// The client fetches this once before opening the AI stream and uses the set as a
// silent dedup backstop in the envelope parser (drops any AI candidate whose URL
// is already known). Keeps the stream itself pure text/plain.
export async function GET() {
  try {
    const { urls } = assembleDedupContext();
    return Response.json({ urls: [...urls] });
  } catch {
    return Response.json({ urls: [] });
  }
}

import { spawnHeadlessCli } from "@/lib/spawn-cli.mjs";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { resolveCli } from "@/lib/clis";
import { careerOpsRoot, readMemory } from "@/lib/career-ops";
import { assembleDedupContext } from "@/lib/core/discover";

// AI search orchestrates modes/discover.md by running the USER'S configured CLI
// headless (CLI-agnostic, like the assistant). Web hunting is slow → generous
// budget. The agent is a PROPOSER: Write/Edit/Bash are disabled so it structurally
// cannot persist; the only writes happen when the user later ADDs a candidate.
export const runtime = "nodejs";
export const dynamic = "force-dynamic";
export const maxDuration = 600;

type CodexCapabilityCacheEntry = {
  mtimeMs: number;
  size: number;
  probe: Promise<boolean>;
};

const codexCapabilityCache = new Map<string, CodexCapabilityCacheEntry>();

function readCodexHelp(binPath: string, args: string[]): Promise<string> {
  return new Promise((resolve) => {
    let stdout = "";
    let stderr = "";
    let settled = false;
    let timeout: ReturnType<typeof setTimeout> | undefined;

    const finish = (output: string) => {
      if (settled) return;
      settled = true;
      if (timeout) clearTimeout(timeout);
      resolve(output);
    };

    const appendBounded = (current: string, chunk: Buffer) =>
      (current + chunk.toString()).slice(-64_000);

    const child = spawnHeadlessCli(binPath, args, {
      env: { ...process.env, NO_COLOR: "1" },
    });

    child.stdout.on("data", (chunk: Buffer) => {
      stdout = appendBounded(stdout, chunk);
    });

    child.stderr.on("data", (chunk: Buffer) => {
      stderr = appendBounded(stderr, chunk);
    });

    child.on("error", () => finish(""));
    child.on("close", () => finish(`${stdout}
${stderr}`));

    timeout = setTimeout(() => {
      try {
        child.kill("SIGTERM");
      } catch {
        /* best-effort capability-probe cleanup */
      }
      finish("");
    }, 5_000);
  });
}

function supportsSafeCodexExec(binPath: string): Promise<boolean> {
  let mtimeMs: number;
  let size: number;

  try {
    ({ mtimeMs, size } = fs.statSync(binPath));
  } catch {
    return Promise.resolve(false);
  }

  const cached = codexCapabilityCache.get(binPath);
  if (cached && cached.mtimeMs === mtimeMs && cached.size === size) {
    return cached.probe;
  }

  let entry: CodexCapabilityCacheEntry;
  const probe = Promise.all([
    readCodexHelp(binPath, ["--help"]),
    readCodexHelp(binPath, ["exec", "--help"]),
  ])
    // Deliberately fail closed: help/flag drift means "unsupported", never a
    // weaker Codex invocation that could bypass the required safety contract.
    .then(([globalHelp, execHelp]) =>
      globalHelp.includes("--ask-for-approval") &&
      globalHelp.includes("--search") &&
      execHelp.includes("--sandbox") &&
      execHelp.includes("read-only") &&
      execHelp.includes("--strict-config") &&
      execHelp.includes("--ignore-user-config") &&
      execHelp.includes("--ephemeral") &&
      execHelp.includes("--skip-git-repo-check") &&
      execHelp.includes("--output-last-message"),
    )
    .catch(() => false)
    .then((supported) => {
      // Only successes stay cached. A transient/negative probe retries next time,
      // but must not delete a newer entry installed after the binary changed.
      if (!supported && codexCapabilityCache.get(binPath) === entry) {
        codexCapabilityCache.delete(binPath);
      }
      return supported;
    });

  // Concurrent cold requests share the same in-flight probe. mtime+size makes a
  // Codex upgrade at the same path invalidate a previously successful result.
  entry = { mtimeMs, size, probe };
  codexCapabilityCache.set(binPath, entry);
  return probe;
}

const OUTPUT_CONTRACT = `

--- OUTPUT CONTRACT (the career-ops WEB is parsing your stream) ---
Follow modes/discover.md exactly. You are running headless for the web:
- You are a PROPOSER — never write a file (Write/Edit/Bash are disabled).
- Emit each candidate as ONE line, never inside a code fence:
  <<offer:{"url":"…","title":"…","company":"…","location":"…","source":"ai-search","why":"…","postedHint":"…","ats":"…","verification":"unconfirmed"}>>
  Valid JSON, one per line, the moment you're confident — stream them as you go.
- Between envelopes, narrate briefly (plain text) what you're searching — shown live as your reasoning.
- Be frugal (~3–6 searches, stop at a strong set). EVERY candidate is UNVERIFIED.
- Be a GENEROUS FINDER, not a judge: when a constraint (location, seniority, stage) can't be confirmed from the shallow signal, INCLUDE + flag the uncertainty in "why" — don't discard. NEVER score or judge fit; the A–F evaluation does that later, with the full JD.
- DEDUP: skip anything already known below; don't re-propose the user's existing companies.
`;

export async function POST(req: Request) {
  let body: { query?: string; cliId?: string };
  try {
    body = await req.json();
  } catch {
    return Response.json({ error: "bad json" }, { status: 400 });
  }
  const query = (body.query || "").trim();
  const cliId = body.cliId;
  if (!query || !cliId) return Response.json({ error: "query and cliId required" }, { status: 400 });

  const resolved = resolveCli(cliId);
  if (!resolved) return Response.json({ error: `CLI '${cliId}' not found on this machine` }, { status: 404 });
  const { spec, binPath } = resolved;

  // Read the CANONICAL mode at request time — single source of truth, never a
  // homegrown prompt. Missing (older core) → graceful 400 so the Scan tab stays usable.
  let mode: string;
  try {
    mode = fs.readFileSync(path.join(careerOpsRoot(), "modes", "discover.md"), "utf8");
  } catch {
    return Response.json({ code: "MODE_MISSING", error: "AI search needs a newer career-ops — update to enable it." }, { status: 400 });
  }

  const { lines } = assembleDedupContext();
  const memory = readMemory();
  const memoryLine = memory.trim() ? `\n\nWHAT YOU KNOW ABOUT THE USER (persistent memory):\n${memory.trim()}` : "";
  const knownBlock = lines.length ? `\n\n--- ALREADY KNOWN (dedup — do NOT propose these) ---\n${lines.join("\n")}` : "";
  const prompt = `${mode}${OUTPUT_CONTRACT}${memoryLine}${knownBlock}\n\n--- USER INTENT ---\n${query}\n`;

  const isClaude = cliId === "claude";
  const isCodex = cliId === "codex";

  if (isCodex && !(await supportsSafeCodexExec(binPath))) {
    return Response.json(
      {
        code: "CODEX_UNSUPPORTED",
        error:
          "Codex CLI does not support the required read-only execution flags. Update Codex and try again.",
      },
      { status: 400 },
    );
  }

  // The complete mode, memory and dedup context are embedded in `prompt`.
  // Codex runs in an empty temporary cwd and writes only its final assistant
  // response to a dedicated file. Its normal console transcript includes the
  // full prompt and must never be forwarded to the Web UI.
  let childCwd: string;

  if (isCodex) {
    try {
      childCwd = fs.mkdtempSync(
        path.join(os.tmpdir(), "career-ops-codex-"),
      );
    } catch {
      return Response.json(
        {
          code: "CODEX_TEMP_DIR_FAILED",
          error: "AI search could not create an isolated Codex workspace.",
        },
        { status: 400 },
      );
    }
  } else {
    childCwd = careerOpsRoot();
  }

  const codexResultFile = isCodex
    ? path.join(childCwd, "final-response.txt")
    : undefined;

  const args = isClaude
    ? [
        "-p",
        prompt,
        "--output-format",
        "stream-json",
        "--verbose",
        "--include-partial-messages",
        "--permission-mode",
        "acceptEdits",
        "--allowedTools",
        "Read,WebFetch,WebSearch,Glob,Grep", // WebSearch ADDED vs the read-only assistant
        "--disallowedTools",
        "Bash,Write,Edit,NotebookEdit,Task", // proposer-not-writer, by construction
      ]
    : isCodex
      ? [
          "--ask-for-approval",
          "never",
          "--search",
          "exec",
          "--strict-config",
          "--ignore-user-config",
          "--sandbox",
          "read-only",
          "--ephemeral",
          "--skip-git-repo-check",
          "--output-last-message",
          codexResultFile!,
          prompt,
        ]
      : spec.args(prompt);

  // POSIX detached children become process-group leaders. Keeping stdio
  // piped means Node still tracks the Codex process normally.
  const useCodexProcessGroup =
    isCodex && process.platform !== "win32";

  const child = spawnHeadlessCli(binPath, args, {
    cwd: childCwd,
    env: process.env,
    detached: useCodexProcessGroup,
  });

  const cleanupChildCwd = () => {
    if (!isCodex) return;
    try {
      fs.rmSync(childCwd, { recursive: true, force: true });
    } catch {
      /* best-effort temporary-directory cleanup */
    }
  };

  const encoder = new TextEncoder();
  // `closed` + kill timer in the OUTER scope so cancel() can flip `closed` before
  // the child's late handlers run — otherwise they enqueue onto an already-closed
  // controller and throw an uncaught "Controller is already closed" (see #1155).
  let closed = false;
  let killer: ReturnType<typeof setTimeout> | undefined;
  let forceKill: ReturnType<typeof setTimeout> | undefined;

  const isCodexProcessGroupAlive = () => {
    if (!useCodexProcessGroup || !child.pid) return false;

    try {
      process.kill(-child.pid, 0);
      return true;
    } catch {
      return false;
    }
  };

  const clearTerminationTimers = () => {
    if (killer) {
      clearTimeout(killer);
      killer = undefined;
    }

    // If the group leader exited but a descendant ignored SIGTERM, retain the
    // SIGKILL fallback until the remaining process group is gone.
    if (forceKill && !isCodexProcessGroupAlive()) {
      clearTimeout(forceKill);
      forceKill = undefined;
    }
  };

  const signalChild = (signal: NodeJS.Signals): boolean => {
    if (useCodexProcessGroup && child.pid) {
      try {
        process.kill(-child.pid, signal);
        return true;
      } catch {
        /* group may already be gone; fall back to the direct child */
      }
    }

    try {
      return child.kill(signal);
    } catch {
      return false;
    }
  };

  const terminateChild = () => {
    const termSent = signalChild("SIGTERM");

    if (!isCodex || !termSent || forceKill) return;

    forceKill = setTimeout(() => {
      signalChild("SIGKILL");
      forceKill = undefined;
    }, 5_000);

    forceKill.unref?.();
  };

  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      let buf = "";
      let emitted = false;
      let codexStderr = "";
      killer = setTimeout(() => {
        terminateChild();
      }, 480_000);
      const safeClose = () => {
        if (!closed) {
          closed = true;
          clearTerminationTimers();
          try {
            controller.close();
          } catch {
            /* already closed */
          }
        }
      };
      const safeEnqueue = (s: string): boolean => {
        if (closed || !s) return false;
        try {
          controller.enqueue(encoder.encode(s));
          return true;
        } catch {
          closed = true; // controller already closed underneath us — stop, never crash
          return false;
        }
      };
      const emit = (s: string) => {
        if (safeEnqueue(s)) emitted = true;
      };

      child.stdout.on("data", (d: Buffer) => {
        if (closed) return;

        // Codex's authoritative response is read from codexResultFile after
        // process completion. Drain but do not forward its console transcript.
        if (isCodex) return;

        if (!isClaude) {
          emit(d.toString());
          return;
        }
        buf += d.toString();
        let nl: number;
        while ((nl = buf.indexOf("\n")) !== -1) {
          const line = buf.slice(0, nl).trim();
          buf = buf.slice(nl + 1);
          if (!line) continue;
          try {
            const obj = JSON.parse(line);
            if (obj.type === "stream_event" && obj.event?.type === "content_block_delta") {
              const text = obj.event.delta?.text;
              if (typeof text === "string") emit(text);
            }
          } catch {
            /* partial / non-json line — skip */
          }
        }
      });
      child.stderr.on("data", (d: Buffer) => {
        const s = d.toString();

        if (isCodex) {
          // Normal Codex stderr contains session metadata and the complete
          // prompt. Retain only a bounded private diagnostic signal and never
          // stream it during a successful request.
          codexStderr = (codexStderr + s).slice(-16_000);
          return;
        }

        if (/error|not found|denied|fatal/i.test(s)) {
          safeEnqueue(`\n[${spec.name}] ${s.trim()}\n`);
        }
      });
      child.on("error", (e) => {
        safeEnqueue(`
[error launching ${spec.name}: ${e.message}]`);
        cleanupChildCwd();
        safeClose();
      });

      child.on("close", (code) => {
        clearTerminationTimers();

        if (closed) {
          cleanupChildCwd();
          return;
        }

        if (isCodex) {
          let finalText = "";

          try {
            if (codexResultFile && fs.existsSync(codexResultFile)) {
              finalText = fs.readFileSync(codexResultFile, "utf8").trim();
            }
          } catch {
            /* handled below as missing final output */
          }

          if (finalText) {
            emit(finalText);
          } else if (code !== 0) {
            const diagnosticText = codexStderr.trim();
            const diagnosticsCaptured = diagnosticText.length > 0;

            if (diagnosticsCaptured) {
              const lowerDiagnostics = diagnosticText.toLowerCase();
              const diagnosticMarkers = [
                "error",
                "fatal",
                "failed",
                "denied",
                "not found",
                "invalid",
                "unsupported",
              ].filter((marker) => lowerDiagnostics.includes(marker));

              // Codex stderr may contain the complete user prompt. Log only
              // bounded metadata and marker categories, never its contents.
              console.error("[Codex AI search exited without a final response]", {
                exitCode: code ?? "unknown",
                stderrBytes: Buffer.byteLength(diagnosticText, "utf8"),
                stderrLines: diagnosticText.split(/\r?\n/).length,
                diagnosticMarkers,
              });
            }

            safeEnqueue(
              `
[Codex exited with code ${code ?? "unknown"}${
                diagnosticsCaptured ? "; diagnostic output captured" : ""
              }]
`,
            );
          } else if (!emitted) {
            safeEnqueue("_(no final output from Codex)_");
          }

          cleanupChildCwd();
          safeClose();
          return;
        }

        if (!emitted) safeEnqueue("_(no output — is the CLI authenticated?)_");
        safeClose();
      });
    },
    cancel() {
      closed = true;

      if (killer) {
        clearTimeout(killer);
        killer = undefined;
      }

      terminateChild();
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "text/plain; charset=utf-8",
      "Cache-Control": "no-cache, no-transform",
      "X-Accel-Buffering": "no",
    },
  });
}

import { NextRequest } from "next/server";
import fs from "node:fs";
import { runDiscovery } from "@/lib/core/scan";
import { rootScript } from "@/lib/career-ops";
import { parseExplorePatch, DEFAULT_FILTERS, type DiscoveredOffer, type ScanEvent } from "@/lib/explore";
import { scannerMissingBody, SCANNER_MISSING_STATUS } from "@/lib/explore-error.mjs";

// Discovery is HTTP-bound across many ATS boards; give it room. It is FREE —
// zero LLM tokens (the scanner only does HTTP + JSON, and --dry-run writes nothing).
export const runtime = "nodejs";
export const maxDuration = 300;
export const dynamic = "force-dynamic";

export async function POST(req: NextRequest) {
  let body: Record<string, unknown> = {};
  try {
    body = (await req.json()) as Record<string, unknown>;
  } catch {
    /* empty body → defaults */
  }

  const filters = parseExplorePatch(body, DEFAULT_FILTERS);

  // Guard: a data-only checkout (or pre-onboarding) has no scanner. Fail soft.
  // The body carries an explicit code because 400 is a shared channel: the
  // client cannot tell this apart from a malformed request by status alone.
  if (!fs.existsSync(rootScript("scan-ats-full"))) {
    return Response.json(scannerMissingBody(), { status: SCANNER_MISSING_STATUS });
  }

  const encoder = new TextEncoder();
  const stream = new ReadableStream({
    async start(controller) {
      const send = (obj: unknown) => {
        try {
          controller.enqueue(encoder.encode(JSON.stringify(obj) + "\n"));
        } catch {
          /* stream closed */
        }
      };
      send({ kind: "start", ats: filters.ats, sinceDays: filters.sinceDays, limit: filters.limitPerAts, free: true } satisfies ScanEvent);
      let offers: DiscoveredOffer[] = [];
      try {
        offers = await runDiscovery(filters, (e: ScanEvent) => send(e));
      } catch (err) {
        send({ kind: "error", message: err instanceof Error ? err.message : "discovery failed" } satisfies ScanEvent);
      }
      send({ kind: "done", count: offers.length, offers, cost: { tokens: 0, usd: 0 } } satisfies ScanEvent);
      controller.close();
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "application/x-ndjson; charset=utf-8",
      "Cache-Control": "no-cache, no-transform",
      "X-Accel-Buffering": "no",
    },
  });
}

import { execFile } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import * as yaml from "js-yaml";
import { careerOpsRoot, rootScript } from "@/lib/career-ops";
import { atomicWriteWithBackup } from "@/lib/core/safe-write";
import { PROFILE_CADENCE_KEYS, type ProfileCadenceKey } from "@/lib/followups";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

// The follow-up cadence knobs live in config/profile.yml → followup_cadence
// (a USER-LAYER file) — the SAME keys the core followup-cadence.mjs reads, so
// tuning them here changes the CLI's verdict too. Reads are live; writes are
// merge-safe + atomic and never clobber the rest of the profile (mirrors the
// /api/profile guards for the malformed-YAML and first-create cases).

function isObj(v: unknown): v is Record<string, unknown> {
  return !!v && typeof v === "object" && !Array.isArray(v);
}

/**
 * PURE defaults, read from the core rather than copied (#2369).
 *
 * `followup-cadence.mjs --json` emits `cadenceDefaults` (DEFAULT_CADENCE) next
 * to `cadenceConfig` (defaults + the user's profile overrides). The form needs
 * the PURE defaults for its placeholders: sourcing them from `cadenceConfig`
 * would render a user's own override as the default they'd be reverting to.
 *
 * Core keys carry no `_days` suffix (`applied_first`); the profile/web keys do
 * (`applied_first_days`), except `applied_max_followups`. That mapping is the
 * only translation here — no values are restated.
 *
 * Returns null when the core is missing or unparseable. Deliberately NOT a
 * hardcoded fallback table: a fallback copy is the same copy in disguise, and
 * that is exactly how states.ts's FALLBACK drifted (#2282).
 */
async function readCoreDefaults(): Promise<Partial<Record<ProfileCadenceKey, number>> | null> {
  const script = rootScript("followup-cadence");
  if (!fs.existsSync(script)) return null;
  const stdout = await new Promise<string>((resolve) => {
    execFile("node", [script, "--json"], { cwd: careerOpsRoot(), timeout: 12_000 }, (_e, out) => resolve(out || ""));
  });
  try {
    const start = stdout.indexOf("{");
    if (start === -1) return null;
    const parsed = JSON.parse(stdout.slice(start)) as { cadenceDefaults?: unknown };
    if (!isObj(parsed.cadenceDefaults)) return null;
    const core = parsed.cadenceDefaults;
    // ALL-OR-NOTHING, and no coercion. Number.parseInt would accept "3.5" as 3
    // and "7days" as 7, and a per-key filter would report defaultsAvailable:
    // true off a single valid key — either way the form would show a baseline
    // the core never emitted. A partial or coerced contract is exactly the
    // silent-wrong-value this whole derivation exists to remove, so a
    // malformed payload degrades to "no defaults" instead.
    const out: Partial<Record<ProfileCadenceKey, number>> = {};
    for (const key of PROFILE_CADENCE_KEYS) {
      const coreKey = key === "applied_max_followups" ? key : key.replace(/_days$/, "");
      const raw = core[coreKey];
      if (typeof raw !== "number" || !Number.isInteger(raw) || raw < 0) return null;
      out[key] = raw;
    }
    return out;
  } catch {
    return null;
  }
}

export async function GET() {
  const file = path.join(careerOpsRoot(), "config", "profile.yml");
  const overrides: Partial<Record<ProfileCadenceKey, number>> = {};
  if (fs.existsSync(file)) {
    let profile: Record<string, unknown> = {};
    try {
      const parsed = yaml.load(fs.readFileSync(file, "utf8"));
      profile = isObj(parsed) ? parsed : {};
    } catch {
      /* unreadable/malformed → show defaults (read is best-effort) */
    }
    const source = isObj(profile.followup_cadence) ? profile.followup_cadence : {};
    for (const key of PROFILE_CADENCE_KEYS) {
      const n = Number.parseInt(String(source[key]), 10);
      if (Number.isFinite(n) && n >= 0) overrides[key] = n;
    }
  }
  const defaults = await readCoreDefaults();
  // `defaultsAvailable: false` tells the form to render its placeholders as
  // unknown rather than inventing a number — an honest gap beats a stale copy.
  const effective = { ...(defaults ?? {}), ...overrides };
  return Response.json({ defaults: defaults ?? {}, defaultsAvailable: defaults !== null, overrides, effective });
}

export async function POST(req: Request) {
  let body: Record<string, unknown>;
  try {
    body = (await req.json()) as Record<string, unknown>;
  } catch {
    return Response.json({ error: "bad json" }, { status: 400 });
  }

  const cadence: Record<string, number> = {};
  for (const key of PROFILE_CADENCE_KEYS) {
    if (body[key] == null) continue;
    const n = Number.parseInt(String(body[key]), 10);
    if (!Number.isInteger(n) || n < 0) {
      return Response.json({ error: `${key} must be a non-negative integer` }, { status: 400 });
    }
    cadence[key] = n;
  }
  if (Object.keys(cadence).length === 0) return Response.json({ error: "nothing to write" }, { status: 400 });

  const root = careerOpsRoot();
  const file = path.join(root, "config", "profile.yml");
  let base: Record<string, unknown> = {};
  if (!fs.existsSync(file)) {
    // First create: seed from the example so we never leave a cadence-only profile.
    try {
      const seeded = yaml.load(fs.readFileSync(path.join(root, "config", "profile.example.yml"), "utf8"));
      base = isObj(seeded) ? seeded : {};
    } catch {
      base = {};
    }
  } else {
    // DATA-LOSS GUARD (mirrors /api/profile): a profile that EXISTS but cannot be
    // read/parsed must never be overwritten with a cadence-only file.
    let parsed: unknown;
    try {
      parsed = yaml.load(fs.readFileSync(file, "utf8"));
    } catch {
      return Response.json({ error: "config/profile.yml exists but could not be read as YAML — refusing to overwrite it." }, { status: 409 });
    }
    base = isObj(parsed) ? parsed : {};
  }

  const merged = {
    ...base,
    followup_cadence: { ...(isObj(base.followup_cadence) ? base.followup_cadence : {}), ...cadence },
  };
  try {
    atomicWriteWithBackup(file, yaml.dump(merged, { lineWidth: 100, noRefs: true }));
  } catch (e) {
    return Response.json({ error: e instanceof Error ? e.message : "write failed" }, { status: 500 });
  }
  return Response.json({ ok: true, followup_cadence: merged.followup_cadence });
}

import fs from "node:fs";
import path from "node:path";
import { atomicWrite } from "@/lib/core/safe-write";
import { CHANNELS, isRealISODate, localISODate } from "@/lib/followups";
import { followupsLogPath, withFollowupsWrite, followupsWriteError } from "@/lib/followups-server";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

// Append-only follow-up log → data/follow-ups.md (NEVER clobber; the cadence
// calculator reads this to advance the schedule). Writes the canonical TABLE row
// the core's followup-cadence.mjs parses:
//   | num | appNum | date | company | role | channel | contact | notes |
// (Earlier builds wrote bullet lines; those stay in place — the core parser now
// reads both formats — but every new log is a full-fidelity table row.)

/** Table cells must stay single-line and pipe-free. `max` optional — notes are
 *  deliberately uncapped (user decision), identity fields keep a sanity cap. */
function cell(v: unknown, max?: number): string {
  const s = String(v ?? "")
    .replace(/[\r\n]+/g, " ")
    .replace(/\|/g, "/")
    .trim();
  return max ? s.slice(0, max) : s;
}

const TABLE_HEADER = "| num | appNum | date | company | role | channel | contact | notes |\n|---|---|---|---|---|---|---|---|\n";

export async function POST(req: Request) {
  let body: {
    appNum?: string | number;
    num?: string | number; // legacy alias for appNum (old home-card payload)
    company?: string;
    role?: string;
    date?: string;
    channel?: string;
    contact?: string;
    notes?: string;
    note?: string; // legacy alias for notes
  };
  try {
    body = (await req.json()) as typeof body;
  } catch {
    return Response.json({ error: "bad json" }, { status: 400 });
  }

  const appNum = Number.parseInt(String(body.appNum ?? body.num ?? ""), 10);
  if (!Number.isInteger(appNum) || appNum < 0) {
    return Response.json({ error: "appNum (application #) required" }, { status: 400 });
  }
  const company = cell(body.company, 80);
  if (!company) return Response.json({ error: "company required" }, { status: 400 });

  // Default to the LOCAL day (local-first app — server clock is the user's
  // clock); validate as a REAL calendar date, not just the shape: one
  // impossible date (2026-13-45) in the log would crash the cadence engine.
  const date = (body.date ?? localISODate()).trim();
  if (!isRealISODate(date)) {
    return Response.json({ error: "date must be a real calendar date (YYYY-MM-DD)" }, { status: 400 });
  }
  const rawChannel = (body.channel ?? "Other").trim();
  const channel = CHANNELS.find((c) => c.toLowerCase() === rawChannel.toLowerCase());
  if (!channel) {
    return Response.json({ error: `channel must be one of: ${CHANNELS.join(", ")}` }, { status: 400 });
  }
  const role = cell(body.role, 80);
  const contact = cell(body.contact, 120);
  const notes = cell(body.notes ?? body.note ?? "");

  const file = followupsLogPath();
  try {
    return await withFollowupsWrite(() => {
      fs.mkdirSync(path.dirname(file), { recursive: true });
      let existing = "";
      if (fs.existsSync(file)) existing = fs.readFileSync(file, "utf8");
      else fs.writeFileSync(file, "# Follow-ups\n\n", "utf8");

      // Auto-increment num = max existing TABLE num + 1 (legacy bullets carry none).
      let maxNum = 0;
      let hasHeader = false;
      for (const line of existing.split("\n")) {
        if (!line.startsWith("|")) continue;
        const first = line.split("|")[1]?.trim() ?? "";
        // Both header spellings exist in the wild: "num" (this writer) and
        // "#" (files created per modes/followup.md) — recognize either, or a
        // second header block gets appended into CLI-created files.
        if (/^(num|#)$/i.test(first)) hasHeader = true;
        const n = Number.parseInt(first, 10);
        if (Number.isInteger(n) && n > maxNum) maxNum = n;
      }
      const num = maxNum + 1;

      let out = "";
      // CLI-created files may lack a trailing newline — guard regardless of
      // whether we're also inserting the header, or the row glues to the last line.
      if (existing && !existing.endsWith("\n")) out += "\n";
      if (!hasHeader) out += TABLE_HEADER;
      out += `| ${num} | ${appNum} | ${date} | ${company} | ${role} | ${channel} | ${contact} | ${notes} |\n`;
      fs.appendFileSync(file, out, "utf8");
      return Response.json({ ok: true, num, appNum, date, channel });
    });
  } catch (e) {
    return followupsWriteError(e, "write failed");
  }
}

// Remove ONE logged follow-up by its `num` (mistake correction — user-initiated
// from the history panel). Only the matching table row is dropped; every other
// byte of the file (header, other rows, legacy bullets) is preserved. Legacy
// bullets carry no num and cannot be deleted here.
export async function DELETE(req: Request) {
  let body: { num?: string | number };
  try {
    body = (await req.json()) as { num?: string | number };
  } catch {
    return Response.json({ error: "bad json" }, { status: 400 });
  }
  const num = Number.parseInt(String(body.num ?? ""), 10);
  if (!Number.isInteger(num) || num <= 0) return Response.json({ error: "num required" }, { status: 400 });

  const file = followupsLogPath();
  if (!fs.existsSync(file)) return Response.json({ error: "no follow-up log" }, { status: 404 });
  try {
    return await withFollowupsWrite(() => {
      const lines = fs.readFileSync(file, "utf8").split("\n");
      const idx = lines.findIndex((line) => {
        if (!line.startsWith("|")) return false;
        const first = line.split("|")[1]?.trim() ?? "";
        return Number.parseInt(first, 10) === num && /^\d+$/.test(first);
      });
      if (idx === -1) return Response.json({ error: `follow-up #${num} not found` }, { status: 404 });
      lines.splice(idx, 1);
      atomicWrite(file, lines.join("\n"));
      return Response.json({ ok: true, num });
    });
  } catch (e) {
    return followupsWriteError(e, "delete failed");
  }
}

import fs from "node:fs";
import path from "node:path";
import { atomicWrite } from "@/lib/core/safe-write";
import { isRealISODate, localISODate } from "@/lib/followups";
import { followupsLogPath, withFollowupsWrite, followupsWriteError } from "@/lib/followups-server";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

// Pin an application's NEXT follow-up date, overriding the computed cadence.
// Stored as a directive line in data/follow-ups.md —
//   - next #42 2026-07-10 (set 2026-07-02)
// — which the core followup-cadence.mjs reads (parseNextOverrides). The pin
// wins over the computed schedule (it even revives a cold application) until a
// follow-up is logged on/after the set-date, which resumes the normal cadence.

const pinRe = (appNum: number) => new RegExp(`^-\\s+next\\s+#${appNum}\\s`, "i");

export async function POST(req: Request) {
  let body: { appNum?: string | number; date?: string };
  try {
    body = (await req.json()) as typeof body;
  } catch {
    return Response.json({ error: "bad json" }, { status: 400 });
  }
  const appNum = Number.parseInt(String(body.appNum ?? ""), 10);
  if (!Number.isInteger(appNum) || appNum < 0) {
    return Response.json({ error: "appNum (application #) required" }, { status: 400 });
  }
  const date = (body.date ?? "").trim();
  if (!isRealISODate(date)) {
    return Response.json({ error: "date must be a real calendar date (YYYY-MM-DD)" }, { status: 400 });
  }

  const file = followupsLogPath();
  try {
    return await withFollowupsWrite(() => {
      fs.mkdirSync(path.dirname(file), { recursive: true });
      let existing = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : "# Follow-ups\n\n";
      // Supersede: drop any previous pin lines for this application (the parser
      // takes the last one anyway; pruning keeps the file tidy).
      const kept = existing.split("\n").filter((line) => !pinRe(appNum).test(line));
      existing = kept.join("\n");
      if (!existing.endsWith("\n")) existing += "\n";
      existing += `- next #${appNum} ${date} (set ${localISODate()})\n`;
      atomicWrite(file, existing);
      return Response.json({ ok: true, appNum, date });
    });
  } catch (e) {
    return followupsWriteError(e, "write failed");
  }
}

// Clear the pin for an application (the computed cadence takes over again).
export async function DELETE(req: Request) {
  let body: { appNum?: string | number };
  try {
    body = (await req.json()) as typeof body;
  } catch {
    return Response.json({ error: "bad json" }, { status: 400 });
  }
  const appNum = Number.parseInt(String(body.appNum ?? ""), 10);
  if (!Number.isInteger(appNum) || appNum < 0) {
    return Response.json({ error: "appNum (application #) required" }, { status: 400 });
  }

  const file = followupsLogPath();
  if (!fs.existsSync(file)) return Response.json({ error: "no follow-up log" }, { status: 404 });
  try {
    return await withFollowupsWrite(() => {
      const lines = fs.readFileSync(file, "utf8").split("\n");
      const kept = lines.filter((line) => !pinRe(appNum).test(line));
      if (kept.length === lines.length) {
        return Response.json({ error: `no pinned next-date for application #${appNum}` }, { status: 404 });
      }
      atomicWrite(file, kept.join("\n"));
      return Response.json({ ok: true, appNum });
    });
  } catch (e) {
    return followupsWriteError(e, "delete failed");
  }
}

import { execFile } from "node:child_process";
import fs from "node:fs";
import { careerOpsRoot, rootScript } from "@/lib/career-ops";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

// The DEMAND loop: surface follow-ups due, via the core's own
// followup-cadence.mjs --json (the SAME calculator the CLI uses) — we never
// reimplement the cadence logic, we read its verdict (mirrors /api/doctor).
// Default: capped list for the home card. `?full=1`: the complete cadence
// (entries + metadata + cadenceConfig) for the /followups tracker page.
export async function GET(req: Request) {
  const full = new URL(req.url).searchParams.get("full") === "1";
  const script = rootScript("followup-cadence");
  if (!fs.existsSync(script)) return Response.json({ available: false, metadata: null, entries: [] });
  const stdout = await new Promise<string>((resolve) => {
    execFile("node", [script, "--json"], { cwd: careerOpsRoot(), timeout: 12_000 }, (_e, out) => resolve(out || ""));
  });
  try {
    const start = stdout.indexOf("{");
    const j = JSON.parse(stdout.slice(start));
    const entries = Array.isArray(j.entries) ? j.entries : [];
    if (full) {
      return Response.json({
        available: true,
        metadata: j.metadata ?? null,
        entries,
        cadenceConfig: j.cadenceConfig ?? null,
      });
    }
    // Overdue first; cap for the home (full list lives in /followups).
    // Check BOTH fields — not urgency-with-status-fallback — so output where
    // either one signals overdue/urgent lands in the priority bucket.
    const overdue = entries.filter((e: { urgency?: string; status?: string }) => /overdue|urgent/i.test(`${e.urgency ?? ""} ${e.status ?? ""}`)).slice(0, 8);
    const top = (overdue.length ? overdue : entries).slice(0, 6);
    return Response.json({ available: true, metadata: j.metadata ?? null, entries: top });
  } catch {
    return Response.json({ available: false, metadata: null, entries: [] });
  }
}

import { NextRequest } from "next/server";
import fs from "node:fs/promises";
import path from "node:path";
import { careerOpsRoot } from "@/lib/career-ops";
import { companyDomain } from "@/lib/company";
import { companyCacheKey } from "@/lib/core/logo-cache-key.mjs";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

// Localhost logo proxy + on-disk cache, FOREVER per key. Honors local-first: the
// browser never talks to Google directly. Accepts `?domain=` (exact) OR
// `?company=` (a name → we guess a handful of likely domains and resolve once).
// Each key is fetched at most once ever, then served from .career-ops-web/logo-cache
// (a hit, or an empty sentinel for a known miss). On any miss → 404 so the
// client's <img onError> falls back to the offline monogram. Because the cache is
// keyed by company, once a company's logo resolves it's instant for that card AND
// every other card (this search or any future one), forever. "Forever" is why
// company keys are versioned — see lib/core/logo-cache-key.

const DOMAIN_RE = /^[a-z0-9.-]{1,253}\.[a-z]{2,}$/i;

function cacheDir(): string {
  return path.join(careerOpsRoot(), ".career-ops-web", "logo-cache");
}

/** Plausible domains for a company name, cheapest/likeliest first.
 *  The curated override map in lib/company wins when it knows the brand (it is
 *  the only source for non-.com marks like notion.so / zoom.us / deepmind.google);
 *  the slug guesses below cover everything else. Keeping both matters because ATS
 *  postings carry legal entity names ("Amazon.com Services LLC") that no single
 *  slug rule resolves — the firstWord stem is what rescues those.
 *  Changing which domains this returns, or their order, means bumping
 *  COMPANY_KEY_VERSION — warm caches would otherwise never see the change. */
function companyDomains(company: string): string[] {
  const paren = company.match(/\(([A-Za-z0-9]{2,12})\)/)?.[1]; // "… (5WPR)"
  // [^()] (not [^)]) keeps the match unambiguous — no polynomial backtracking on
  // adversarial inputs full of unclosed parens (CodeQL js/polynomial-redos).
  const base = company.replace(/\([^()]*\)/g, "").trim();
  const compact = base.toLowerCase().replace(/&/g, "and").replace(/[^a-z0-9]/g, "");
  const firstWord = base.toLowerCase().split(/\s+/)[0].replace(/[^a-z0-9]/g, "");
  const stems = [...new Set([compact, paren?.toLowerCase(), firstWord].filter((s): s is string => !!s && s.length >= 2 && s.length <= 30))];
  const out: string[] = [];
  const curated = companyDomain(base);
  if (curated) out.push(curated);
  for (const t of [".com", ".ai", ".io", ".co"]) for (const s of stems) out.push(s + t);
  return [...new Set(out)].slice(0, 5);
}

/** Fetch a real favicon for one domain (Google's tokenless service). Returns the
 *  bytes, or null for a miss (Google serves a tiny globe placeholder for misses). */
async function fetchFavicon(domain: string): Promise<ArrayBuffer | null> {
  try {
    const res = await fetch(`https://www.google.com/s2/favicons?domain=${encodeURIComponent(domain)}&sz=64`, {
      headers: { Accept: "image/*" },
      signal: AbortSignal.timeout(3500),
      redirect: "follow",
    });
    if (!res.ok) return null;
    const ab = await res.arrayBuffer();
    return ab.byteLength > 220 ? ab : null;
  } catch {
    return null;
  }
}

export async function GET(req: NextRequest) {
  const sp = req.nextUrl.searchParams;
  const domain = (sp.get("domain") ?? "").trim().toLowerCase();
  const company = (sp.get("company") ?? "").trim();

  let key: string;
  let candidates: string[];
  if (domain) {
    if (!DOMAIN_RE.test(domain) || domain.includes("..")) return new Response("bad domain", { status: 400 });
    key = domain.replace(/[^a-z0-9.-]/g, "_");
    candidates = [domain];
  } else if (company) {
    // Versioned + digested (see lib/core/logo-cache-key): the cache never
    // expires, so the key has to carry both the resolver version and enough of
    // the name to keep two companies apart.
    const companyKey = companyCacheKey(company);
    if (!companyKey) return new Response("bad company", { status: 400 });
    key = companyKey;
    candidates = companyDomains(company);
    if (candidates.length === 0) return new Response("no logo", { status: 404 });
  } else {
    return new Response("need domain or company", { status: 400 });
  }

  // `key` is already sanitized above, but enforce containment anyway: a cache
  // path must never resolve outside the cache dir (defense in depth).
  const file = path.resolve(cacheDir(), `${key}.png`);
  if (!file.startsWith(path.resolve(cacheDir()) + path.sep)) return new Response("bad key", { status: 400 });

  // 1) serve from disk cache forever (hit, or empty sentinel = known miss)
  try {
    const buf = await fs.readFile(file);
    if (buf.byteLength > 0) {
      return new Response(new Uint8Array(buf), { status: 200, headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=604800" } });
    }
    return new Response("no logo", { status: 404 });
  } catch {
    /* not cached yet → resolve below */
  }

  // 2) resolve once: first candidate domain that yields a real favicon wins
  let bytes: ArrayBuffer | null = null;
  for (const d of candidates) {
    bytes = await fetchFavicon(d);
    if (bytes) break;
  }

  try {
    await fs.mkdir(cacheDir(), { recursive: true });
    await fs.writeFile(file, bytes ? Buffer.from(bytes) : new Uint8Array(0)); // sentinel on miss → never refetch
  } catch {
    /* best-effort */
  }

  if (!bytes) return new Response("no logo", { status: 404 });
  return new Response(bytes, { status: 200, headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=604800" } });
}

