}
.report-prose pre {
  background: var(--pre-bg);
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  padding: 1rem;
  overflow-x: auto;
  margin: 1rem 0;
}
.report-prose pre code { background: none; color: var(--fg); padding: 0; }
.report-prose ul, .report-prose ol { margin: 0.9rem 0; padding-left: 1.4rem; }
.report-prose ul { list-style: disc; }
.report-prose ol { list-style: decimal; }
.report-prose li { margin: 0.35rem 0; }
.report-prose li::marker { color: var(--faint); }
.report-prose blockquote {
  border-left: 3px solid var(--color-brand);
