"use client";

import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from "react";
import type { ApplyField } from "@/lib/apply/extract";
import type { ApplyIssue, DriveStep } from "@/lib/apply/issue";
import { resolveLateSession } from "@/lib/apply/exit.mjs";

export type FillStep = { fieldId: string; label: string; ok: boolean; thumb?: string };
type Meta = { needsConfirmation?: boolean };
type Status = "idle" | "opening" | "driving" | "prefilling" | "ready" | "filling" | "done" | "error";

type ApplyCtx = {
  status: Status;
  url: string;
  title: string;
  company: string;
  /** Tracker row this session was opened for, "" when opened from a pasted URL. */
  n: string;
  /** Path the session was opened from, so the page has somewhere to go back to. */
  from: string;
  fields: ApplyField[];
  answers: Record<string, string>;
  meta: Record<string, Meta>;
  steps: FillStep[];
  shots: string[];
  prefillLog: string[];
  issues: ApplyIssue[];
  driveSteps: DriveStep[];
  error: string;
  open: (url: string, opts?: { prefill?: boolean; company?: string; n?: string; from?: string }) => Promise<void>;
  prefill: () => Promise<void>;
  setAnswer: (idOrLabel: string, value: string) => void;
  fill: () => Promise<void>;
  agentFill: () => Promise<void>;
  reset: () => void;
};

const Ctx = createContext<ApplyCtx | null>(null);
export function useApply(): ApplyCtx {
  const c = useContext(Ctx);
  if (!c) throw new Error("useApply must be used within <ApplyProvider>");
  return c;
}

/** Release the headless browser behind a session id. Fire-and-forget: the page
 *  is usually navigating away as this goes out, hence keepalive. */
function closeSession(id: string) {
  void fetch("/api/apply/close", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ sessionId: id }), keepalive: true }).catch(() => {});
}

const CONFIG_KEY = "career-ops:config";
function cliId(): string | null {
  try {
    return JSON.parse(localStorage.getItem(CONFIG_KEY) || "{}").cliId || null;
  } catch {
    return null;
  }
}

export function ApplyProvider({ children }: { children: React.ReactNode }) {
  const [status, setStatus] = useState<Status>("idle");
  const [url, setUrl] = useState("");
  const [title, setTitle] = useState("");
  const [company, setCompany] = useState("");
  const [n, setN] = useState("");
  const [from, setFrom] = useState("");
  const [fields, setFields] = useState<ApplyField[]>([]);
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [meta, setMeta] = useState<Record<string, Meta>>({});
  const [steps, setSteps] = useState<FillStep[]>([]);
  const [shots, setShots] = useState<string[]>([]);
  const [prefillLog, setPrefillLog] = useState<string[]>([]);
  const [issues, setIssues] = useState<ApplyIssue[]>([]);
  const [driveSteps, setDriveSteps] = useState<DriveStep[]>([]);
  const [error, setError] = useState("");
  const sessionId = useRef<string | null>(null);
  const companyRef = useRef<string>("");
  const fieldsRef = useRef<ApplyField[]>([]);
  fieldsRef.current = fields;
  const answersRef = useRef<Record<string, string>>({});
  answersRef.current = answers;
  // Bumped every time a session is abandoned or replaced. Leaving the page is
  // reachable while a request or stream is still in flight, and none of them can
  // be recalled, so each one carries the generation it started in and drops its
  // results if that generation is no longer current.
  const generation = useRef(0);
  // When a session opens with {prefill:true}, auto-fire prefill once fields are
  // ready — driven by an effect (not a fragile setTimeout) so it can't race the
  // session response or a navigation.
  const pendingPrefill = useRef(false);

  // Stream the agentic drive (the AI reaching the form live) and finalize the
  // session when it succeeds → fields ready → auto-prefill fires.
  const drive = useCallback(async (id: string) => {
    const gen = generation.current;
    setDriveSteps([]);
    try {
      const r = await fetch("/api/apply/drive", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ sessionId: id, cliId: cliId(), goal: "reach" }) });
      if (generation.current !== gen) return; // left mid-drive
      if (!r.body) {
        setError("The agent couldn't start.");
        setStatus("error");
        return;
      }
      const reader = r.body.getReader();
      const dec = new TextDecoder();
      let buf = "";
      let finished = false;
      for (;;) {
        const { value, done } = await reader.read();
        if (done) break;
        if (generation.current !== gen) return; // left mid-drive
        buf += dec.decode(value, { stream: true });
        let nl: number;
        while ((nl = buf.indexOf("\n")) >= 0) {
          const line = buf.slice(0, nl).trim();
          buf = buf.slice(nl + 1);
          if (!line) continue;
          let ev: { t?: string; message?: string; fields?: ApplyField[]; title?: string; issues?: ApplyIssue[] } & DriveStep;
          try {
            ev = JSON.parse(line);
          } catch {
            continue;
          }
          if (ev.t === "step") setDriveSteps((p) => [...p, ev as DriveStep]);
          else if (ev.t === "done") {
            finished = true;
            setFields(ev.fields ?? []);
            if (ev.title) setTitle(ev.title);
            setIssues(ev.issues ?? []);
            setStatus("ready"); // → the ready-effect auto-prefills if pending
          } else if (ev.t === "error") {
            finished = true;
            setError(ev.message || "The agent couldn't reach a fillable form.");
            setStatus("error");
          }
        }
      }
      if (generation.current !== gen) return; // left mid-drive
      if (!finished) {
        setError("The agent stopped before reaching a form.");
        setStatus("error");
      }
    } catch (e) {
      if (generation.current !== gen) return; // left mid-drive
      setError(`The agent couldn't reach the form: ${e instanceof Error ? e.message : "stream error"}.`);
      setStatus("error");
    }
  }, []);

  const open = useCallback(async (u: string, opts?: { prefill?: boolean; company?: string; n?: string; from?: string }) => {
    const gen = ++generation.current;
    // Opening a second form abandons the first one's browser exactly the way
    // leaving the page does, so it is released here too.
    if (sessionId.current) closeSession(sessionId.current);
    sessionId.current = null;
    setStatus("opening");
    setError("");
    setFields([]);
    setAnswers({});
    setMeta({});
    setSteps([]);
    setShots([]);
    setIssues([]);
    setDriveSteps([]);
    setUrl(u);
    setCompany(opts?.company ?? "");
    companyRef.current = opts?.company ?? "";
    setN(opts?.n ?? "");
    setFrom(opts?.from ?? "");
    pendingPrefill.current = false;
    try {
      const r = await fetch("/api/apply/session", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ url: u, cliId: cliId() }) });
      const d = await r.json();
      // The user can leave while this is in flight, and the request can't be
      // recalled — a session that lands after they left is closed here or its
      // headless browser runs forever, unreferenced.
      const late = resolveLateSession({ stale: generation.current !== gen, sessionId: d.id });
      if (late !== "apply") {
        if (late === "close") closeSession(d.id);
        return;
      }
      if (d.error) {
        setError(d.error);
        setStatus("error");
        return;
      }
      sessionId.current = d.id;
      setTitle(d.title);
      setShots(d.shots ?? []);
      pendingPrefill.current = !!opts?.prefill;
      if (d.needsDrive) {
        // The form is behind navigation → the agent drives to reach it, streamed.
        setStatus("driving");
        await drive(d.id);
        return;
      }
      setFields(d.fields);
      setIssues(d.issues ?? []);
      setStatus("ready");
    } catch {
      if (generation.current !== gen) return; // left while it was opening
      setError("Could not open the form.");
      setStatus("error");
    }
  }, []);

  const prefill = useCallback(async () => {
    if (!sessionId.current) return;
    const gen = generation.current;
    if (!cliId()) {
      setError("Configure a CLI in Config first, then pre-fill from your CV.");
      return;
    }
    setStatus("prefilling");
    setError("");
    setPrefillLog([]);
    const applyAnswers = (raw: Record<string, { value?: string; needs_confirmation?: boolean }>) => {
      const a: Record<string, string> = {};
      const m: Record<string, Meta> = {};
      for (const [id, v] of Object.entries(raw)) {
        a[id] = v?.value ?? "";
        m[id] = { needsConfirmation: !!v?.needs_confirmation };
      }
      setAnswers(a);
      setMeta(m);
    };
    try {
      const r = await fetch("/api/apply/prefill", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ sessionId: sessionId.current, cliId: cliId() }) });
      if (generation.current !== gen) return; // left mid-prefill
      if (!r.body) {
        setError("Couldn't pre-fill — no response stream.");
        setStatus("ready");
        return;
      }
      const reader = r.body.getReader();
      const dec = new TextDecoder();
      let buf = "";
      let got = false;
      let sawError = false;
      for (;;) {
        const { value, done } = await reader.read();
        if (done) break;
        if (generation.current !== gen) return; // left mid-prefill
        buf += dec.decode(value, { stream: true });
        let nl: number;
        while ((nl = buf.indexOf("\n")) >= 0) {
          const line = buf.slice(0, nl).trim();
          buf = buf.slice(nl + 1);
          if (!line) continue;
          let ev: { t?: string; m?: string; el?: number; raw?: string; answers?: Record<string, { value?: string; needs_confirmation?: boolean }>; count?: number; truncated?: boolean };
          try {
            ev = JSON.parse(line);
          } catch {
            continue;
          }
          if (ev.t === "log") {
            setPrefillLog((p) => [...p, `+${((ev.el ?? 0) / 1000).toFixed(1)}s  ${ev.m}`]);
          } else if (ev.t === "done") {
            got = true;
            applyAnswers(ev.answers ?? {});
            if ((ev.count ?? 0) === 0) setError("The planner returned 0 answers — see the diagnostics log below.");
            else if (ev.truncated) setError("The planner was cut off — some fields were recovered, others may be blank. See diagnostics.");
          } else if (ev.t === "error") {
            sawError = true;
            setError(ev.m ? `Couldn't pre-fill: ${ev.m}` : "Couldn't pre-fill from your CV.");
            setPrefillLog((p) => [...p, `✗ ${ev.m ?? "error"}${ev.raw ? ` — raw tail: ${ev.raw.slice(0, 160)}` : ""}`]);
          }
        }
      }
      if (generation.current !== gen) return; // left mid-prefill
      if (!got && !sawError) setError("Pre-fill ended without answers — see the diagnostics log below.");
      setStatus("ready");
    } catch (e) {
      if (generation.current !== gen) return; // left mid-prefill
      setError(`Couldn't pre-fill from your CV: ${e instanceof Error ? e.message : "stream error"}. See diagnostics.`);
      setStatus("ready");
    }
  }, []);

  // Auto-prefill exactly once after the fields are ready.
  useEffect(() => {
    if (status === "ready" && pendingPrefill.current) {
      pendingPrefill.current = false;
      void prefill();
    }
  }, [status, prefill]);

  const setAnswer = useCallback((idOrLabel: string, value: string) => {
    const fs = fieldsRef.current;
    const key = idOrLabel.toLowerCase();
    const f =
      fs.find((x) => x.id === idOrLabel) ||
      fs.find((x) => x.label.toLowerCase().includes(key)) ||
      fs.find((x) => key.includes(x.label.toLowerCase()) && x.label.length > 2);
    if (f) setAnswers((prev) => ({ ...prev, [f.id]: value }));
  }, []);

  const fill = useCallback(async () => {
    if (!sessionId.current) return;
    const gen = generation.current;
    setStatus("filling");
    setSteps([]);
    try {
      const r = await fetch("/api/apply/fill", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ sessionId: sessionId.current, answers, fields, handoff: true, company: companyRef.current }) });
      const d = await r.json();
      // Also stops the escalation below from starting an agent drive on a
      // session the user has already walked away from.
      if (generation.current !== gen) return; // left mid-fill
      if (d.error) {
        setError(d.error);
        setStatus("error");
        return;
      }
      setSteps(d.steps ?? []);
      // merge the verify-after-fill warnings (required-empty / mismatch / validation)
      if (Array.isArray(d.issues) && d.issues.length) {
        setIssues((prev) => {
          const seen = new Set(prev.map((i: ApplyIssue) => i.message));
          return [...prev, ...(d.issues as ApplyIssue[]).filter((i) => !seen.has(i.message))];
        });
      }
      if (d.navigated) setError("Heads up: the form's page changed during fill — review it carefully before submitting (career-ops never submits for you).");
      setStatus("done");
      // ESCALATION ("si no va, full agente"): if deterministic fill clearly
      // didn't land (most fields failed / mismatched), let the agent fill it.
      const okCount = (d.steps ?? []).filter((s: FillStep) => s.ok).length;
      const total = (d.steps ?? []).length;
      const mismatch = (d.issues ?? []).some((i: ApplyIssue) => i.code === "fill-mismatch");
      if (cliId() && total > 0 && (okCount === 0 || (mismatch && okCount < total / 2))) {
        await agentFillRef.current();
      }
    } catch {
      if (generation.current !== gen) return; // left mid-fill
      setError("Fill failed.");
      setStatus("error");
    }
  }, [answers, fields]);

  // FULL-AGENT FILL — the agent fills the real form turn-by-turn from the verified
  // answers, streamed (drive panel), never submits, then hands off. Used as the
  // escalation when deterministic fill fails, or on demand.
  const agentFill = useCallback(async () => {
    if (!sessionId.current) return;
    const gen = generation.current;
    const fs = fieldsRef.current;
    const a = answersRef.current;
    const ans = fs.filter((f) => f.type !== "file" && (a[f.id] || "").trim()).map((f) => ({ label: f.label || f.id, value: a[f.id] }));
    setDriveSteps([]);
    setError("");
    setStatus("filling");
    try {
      const r = await fetch("/api/apply/drive", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ sessionId: sessionId.current, cliId: cliId(), goal: "full", answers: ans }) });
      if (generation.current !== gen) return; // left mid-fill
      if (!r.body) {
        setError("The agent couldn't start filling.");
        setStatus("error");
        return;
      }
      const reader = r.body.getReader();
      const dec = new TextDecoder();
      let buf = "";
      for (;;) {
        const { value, done } = await reader.read();
        if (done) break;
        if (generation.current !== gen) return; // left mid-fill
        buf += dec.decode(value, { stream: true });
        let nl: number;
        while ((nl = buf.indexOf("\n")) >= 0) {
          const line = buf.slice(0, nl).trim();
          buf = buf.slice(nl + 1);
          if (!line) continue;
          let ev: { t?: string; message?: string; filled?: boolean } & DriveStep;
          try {
            ev = JSON.parse(line);
          } catch {
            continue;
          }
          if (ev.t === "step") setDriveSteps((p) => [...p, ev as DriveStep]);
          else if (ev.t === "done") {
            setIssues((prev) => [...prev, { level: "info", code: "ai-filled", message: ev.filled ? "AI filled the form for you — review every answer on the real form, then submit it yourself." : "AI did its best but couldn't finish — check the real form before submitting." }]);
            setStatus("done");
          } else if (ev.t === "error") {
            setError(ev.message || "The agent couldn't fill the form.");
            setStatus("error");
          }
        }
      }
    } catch (e) {
      if (generation.current !== gen) return; // left mid-fill
      setError(`The agent couldn't fill the form: ${e instanceof Error ? e.message : "stream error"}.`);
      setStatus("error");
    }
  }, []);
  const agentFillRef = useRef(agentFill);
  agentFillRef.current = agentFill;

  const reset = useCallback(() => {
    // Invalidate anything still in flight before clearing state, so a response
    // that lands after this can't repopulate the page the user just left.
    generation.current += 1;
    if (sessionId.current) closeSession(sessionId.current);
    sessionId.current = null;
    companyRef.current = "";
    pendingPrefill.current = false;
    setStatus("idle");
    setUrl("");
    setTitle("");
    setCompany("");
    setN("");
    setFrom("");
    setFields([]);
    setAnswers({});
    setMeta({});
    setSteps([]);
    setShots([]);
    setPrefillLog([]);
    setIssues([]);
    setDriveSteps([]);
    setError("");
  }, []);

  const value = useMemo(
    () => ({ status, url, title, company, n, from, fields, answers, meta, steps, shots, prefillLog, issues, driveSteps, error, open, prefill, setAnswer, fill, agentFill, reset }),
    [status, url, title, company, n, from, fields, answers, meta, steps, shots, prefillLog, issues, driveSteps, error, open, prefill, setAnswer, fill, agentFill, reset],
  );
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

"use client";

import { useRouter } from "next/navigation";
import { Send, Lock } from "lucide-react";
import { useJobs } from "@/components/jobs/job-store";
import { useApply } from "@/components/apply/apply-provider";

// The "Apply" CTA — brand orange, paper-plane. Enabled ONLY when the tailored CV
// for THIS offer is ready (the tracker's PDF column is ✅, or a pdf worker for
// this #n just finished). On click it opens the apply form-proxy for the offer
// (where the user reviews and submits it themselves — never auto-submit).
export function ApplyButton({ n, url, company, pdfReady }: { n: string; url?: string; company: string; pdfReady: boolean }) {
  const router = useRouter();
  const { jobs } = useJobs();
  const apply = useApply();

  const pdfJobDone = jobs.some((j) => j.kind === "pdf" && j.input === n && j.status === "done");
  const hasUrl = !!url && /^https?:\/\//i.test(url);
  const ready = (pdfReady || pdfJobDone) && hasUrl;

  if (!ready) {
    return (
      <button
        type="button"
        disabled
        title={!hasUrl ? "No application URL on this report" : "Generate the tailored CV (PDF) first to apply"}
        className="inline-flex cursor-not-allowed items-center justify-center gap-1.5 rounded-full border border-border bg-surface/40 px-3.5 py-1 text-xs font-medium text-faint max-sm:min-h-[44px]"
      >
        <Lock className="size-3.5" /> Apply
      </button>
    );
  }
  return (
    <button
      type="button"
      onClick={() => {
        // n + from ride along so the Apply page can mark this row Applied and
        // return the user to the page they left. Read straight off the handler's
        // own location: usePathname() drops the query and hash, which is where
        // the list filter and the row anchor live.
        const { pathname, search, hash } = window.location;
        apply.open(url!, { prefill: true, company, n, from: `${pathname}${search}${hash}` });
        router.push("/apply");
      }}
      className="inline-flex items-center justify-center gap-1.5 rounded-full bg-brand px-3.5 py-1 text-xs font-medium text-brand-foreground shadow-sm transition-colors hover:bg-brand-200 max-sm:min-h-[44px]"
      title="Apply — opens the form pre-filled, you review and submit yourself"
    >
      <Send className="size-3.5" /> Apply
    </button>
  );
}

"use client";

import { Loader2, Wand2, Asterisk, Paperclip, Sparkles, ArrowUpRight, ShieldCheck, RotateCcw, FileCheck2, AlertTriangle, Terminal, Check, ScanLine, PenLine, CheckCircle2, Info, ExternalLink, MousePointerClick, ArrowLeft, ClipboardCheck } from "lucide-react";
import { useRouter } from "next/navigation";
import type { ApplyIssue, DriveStep } from "@/lib/apply/issue";
import { useApply } from "@/components/apply/apply-provider";
import { needsLeaveConfirmation, resolveReturnPath } from "@/lib/apply/exit.mjs";
import type { ApplyField } from "@/lib/apply/extract";
import { cn } from "@/lib/cn";
import { Fragment, useEffect, useRef, useState } from "react";

// Co-located UI animations (HMR-proof vs Tailwind v4's stale globals.css):
// field cascade-in, per-field "just drafted" flash, skeleton shimmer, hero orb.
const STYLE = `
@keyframes co-rise{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
.co-rise{animation:co-rise .55s cubic-bezier(.22,1,.36,1) both}
@keyframes co-flash{0%{box-shadow:0 0 0 0 hsl(26 82% 55% / 0)}22%{box-shadow:0 0 0 3px hsl(26 82% 55% / .38)}100%{box-shadow:0 0 0 0 hsl(26 82% 55% / 0)}}
.co-flash{animation:co-flash 1.15s ease both;border-radius:.6rem}
@keyframes co-shim{0%{background-position:-200% 0}100%{background-position:200% 0}}
.co-skel{background:linear-gradient(90deg, color-mix(in srgb,var(--fg) 5%, transparent) 25%, color-mix(in srgb,var(--fg) 12%, transparent) 37%, color-mix(in srgb,var(--fg) 5%, transparent) 63%);background-size:200% 100%;animation:co-shim 1.6s linear infinite;border-radius:.5rem}
@keyframes co-orb{0%,100%{transform:scale(1);opacity:.55}50%{transform:scale(1.35);opacity:.9}}
.co-orb{animation:co-orb 2.4s ease-in-out infinite}
@keyframes co-spin{to{transform:rotate(360deg)}}
.co-ring{animation:co-spin 3s linear infinite}
@media (prefers-reduced-motion: reduce){.co-rise,.co-flash,.co-skel,.co-orb,.co-ring{animation:none}}
`;

// The form-proxy UI: the real employer form is opened headlessly on the user's
// machine and re-rendered here in plain language, pre-filled from their CV. The
// user verifies every answer, then we fill the real form behind the scenes and
// bring it to the front for them to submit. We never submit.
export function ApplyView() {
  const a = useApply();
  const [input, setInput] = useState("");

  if (a.status === "idle" || a.status === "error") {
    return (
      <div>
        <div className="flex max-w-2xl items-center gap-2 rounded-full border border-border bg-surface/70 py-1.5 pl-4 pr-1.5 shadow-sm transition focus-within:border-brand/50 focus-within:shadow-md">
          <input
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && a.open(input.trim())}
            placeholder="Paste an application form URL (Ashby, Lever, Greenhouse…)"
            className="min-w-0 flex-1 bg-transparent py-1.5 text-sm outline-none placeholder:text-faint"
          />
          <button
            onClick={() => a.open(input.trim())}
            className="inline-flex shrink-0 items-center gap-1.5 rounded-full bg-brand px-4 py-1.5 text-sm font-medium text-brand-foreground transition-colors hover:bg-brand-200"
          >
            <Wand2 className="size-4" /> Read form
          </button>
        </div>
        {a.error && (
          <div className="mt-4 max-w-2xl rounded-xl border border-amber-500/40 bg-amber-500/10 px-4 py-3.5">
            <div className="flex items-start gap-2.5">
              <AlertTriangle className="mt-0.5 size-4 shrink-0 text-amber-500" />
              <div className="min-w-0">
                <p className="text-sm text-amber-800 dark:text-amber-300">{a.error}</p>
                {a.url && /^https?:\/\//.test(a.url) && (
                  <a href={a.url} target="_blank" rel="noreferrer" className="mt-2 inline-flex items-center gap-1 text-xs font-medium text-brand hover:underline">
                    Open the form directly <ExternalLink className="size-3" />
                  </a>
                )}
              </div>
            </div>
          </div>
        )}
        {/* A session that failed still has a row and an origin behind it, so the
            way back and the way to record it must survive the failure. */}
        {a.status === "error" && <ApplyExitBar />}
      </div>
    );
  }

  const opening = a.status === "opening";
  const driving = a.status === "driving";
  const prefilling = a.status === "prefilling";
  const filling = a.status === "filling";
  const done = a.status === "done";
  const busy = opening || driving;
  const phase = busy ? 0 : prefilling ? 1 : 2;

  return (
    <div className="mx-auto max-w-2xl">
      <style>{STYLE}</style>

      {/* journey: Read → Draft → Review */}
      <PhaseRail phase={phase} />

      {!busy && (
        <div className="co-rise mb-4 flex items-baseline justify-between gap-3">
          <h2 className="font-display text-xl text-landing drop-shadow-sm">{a.title || "Application"}</h2>
          <button onClick={a.reset} className="inline-flex items-center gap-1 text-xs text-faint transition-colors hover:text-foreground">
            <RotateCcw className="size-3" /> new
          </button>
        </div>
      )}

      {/* opening: big magic hero + skeleton fields (no layout jump when real ones arrive) */}
      {opening && (
        <>
          <ProcessingHero title="Reading your form…" subtitle="Opening the real application on your machine and reading every field." />
          <FieldSkeleton />
        </>
      )}

      {/* driving: watch the agent reach the form live (it navigates, never submits) */}
      {driving && <DrivePanel steps={a.driveSteps} />}

      {a.error && (
        <p className="co-rise mb-3 flex items-start gap-1.5 rounded-lg border border-amber-500/40 bg-amber-500/10 px-3 py-2 text-sm text-amber-700 backdrop-blur-sm dark:text-amber-400">
          <AlertTriangle className="mt-0.5 size-4 shrink-0" /> {a.error}
        </p>
      )}

      {!busy && (
        <div className="co-rise">
          <ApplyIssues issues={a.issues} />
          {/* drafting banner while the planner writes the answers */}
          {prefilling && (
            <div className="mb-4 flex items-center gap-3 rounded-xl border border-brand/30 bg-brand-soft/60 px-4 py-3 backdrop-blur-sm">
              <span className="relative grid size-8 shrink-0 place-items-center">
                <span className="co-orb absolute inset-0 rounded-full bg-brand/40 blur-[6px]" />
                <Sparkles className="size-4 text-brand" />
              </span>
              <div className="min-w-0">
                <div className="text-sm font-medium text-foreground">Drafting your answers…</div>
                <RotatingStatus />
              </div>
              <Loader2 className="ml-auto size-4 shrink-0 animate-spin text-brand" />
            </div>
          )}

          <div className="mb-4 flex flex-wrap items-center gap-2">
            <button
              onClick={a.prefill}
              disabled={prefilling || filling}
              className="inline-flex items-center gap-1.5 rounded-full border border-brand/40 bg-brand-soft px-3.5 py-1.5 text-sm font-medium text-brand transition-colors hover:bg-brand/15 disabled:opacity-50"
            >
              {prefilling ? <Loader2 className="size-4 animate-spin" /> : <Sparkles className="size-4" />}
              {prefilling ? "Drafting from your CV…" : "Pre-fill from my CV"}
            </button>
            <span className="text-xs text-muted">…or ask the corner assistant to write/revise any answer.</span>
          </div>

          {(prefilling || a.prefillLog.length > 0) && (
            <details className="mb-4 rounded-lg border border-border bg-surface/60 backdrop-blur-sm" open={false}>
              <summary className="flex cursor-pointer select-none items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-muted">
                <Terminal className="size-3.5" /> Pre-fill diagnostics
                {prefilling && <Loader2 className="size-3 animate-spin text-brand" />}
                <span className="ml-auto text-faint">{a.prefillLog.length} steps</span>
              </summary>
              <div className="max-h-52 overflow-y-auto border-t border-border px-3 py-2">
                <ol className="space-y-0.5 font-mono text-[11px] leading-relaxed text-muted">
                  {a.prefillLog.map((l, i) => (
                    <li key={i} className={l.startsWith("✗") ? "text-amber-600 dark:text-amber-400" : ""}>
                      {l}
                    </li>
                  ))}
                  {prefilling && <li className="text-faint">…</li>}
                </ol>
              </div>
            </details>
          )}

          {/* the questions — float on the blurred form image, cascade in, each
              flashes brand-orange the instant its drafted answer lands */}
          <div className="space-y-1 rounded-2xl border border-border/70 bg-surface/80 p-2 shadow-2xl shadow-black/10 backdrop-blur-md sm:p-3">
            {a.fields.map((f, i) => (
              <div key={f.id} className="co-rise rounded-xl px-3 py-2.5" style={{ animationDelay: `${Math.min(i * 45, 700)}ms` }}>
                <FieldRow
                  field={f}
                  value={a.answers[f.id] ?? ""}
                  needs={!!a.meta[f.id]?.needsConfirmation}
                  index={i}
                  drafting={prefilling}
                  onChange={(v) => a.setAnswer(f.id, v)}
                />
              </div>
            ))}
          </div>

          <div className="mt-5 flex flex-wrap items-center gap-3">
            <button
              onClick={a.fill}
              disabled={filling || prefilling}
              className="inline-flex items-center gap-2 rounded-full bg-brand px-5 py-2.5 text-sm font-medium text-brand-foreground shadow-lg shadow-brand/25 transition-all hover:bg-brand-200 hover:shadow-brand/40 disabled:opacity-50"
            >
              {filling ? <Loader2 className="size-4 animate-spin" /> : <ArrowUpRight className="size-4" />}
              {filling ? "Filling the real form…" : "Fill the real form & review"}
            </button>
            <button
              onClick={a.agentFill}
              disabled={filling || prefilling}
              title="Let the AI drive the real form and fill it field-by-field (for tricky / multi-step forms). It never submits."
              className="inline-flex items-center gap-1.5 rounded-full border border-border px-4 py-2.5 text-sm font-medium text-muted transition-colors hover:border-brand/40 hover:text-brand disabled:opacity-50"
            >
              <MousePointerClick className="size-4" /> Let the AI fill it
            </button>
            <p className="inline-flex items-center gap-1.5 text-xs text-muted">
              <ShieldCheck className="size-3.5 text-emerald-500" /> Never submits — you click Submit yourself.
            </p>
          </div>

          {/* agent filling the form live (full-agent escalation) */}
          {filling && a.driveSteps.length > 0 && <div className="mt-6"><DrivePanel steps={a.driveSteps} filling /></div>}

          {(filling || done) && a.steps.length > 0 && (
            <div className="co-rise mt-6">
              <div className="mb-2 text-xs font-semibold uppercase tracking-[0.14em] text-faint">Behind the scenes</div>
              <div className="flex gap-2 overflow-x-auto pb-2">
                {a.steps.map((s, i) => (
                  <figure key={i} className="shrink-0">
                    {s.thumb ? (
                      // eslint-disable-next-line @next/next/no-img-element
                      <img src={s.thumb} alt="" className="h-24 w-36 rounded-md border border-border object-cover" />
                    ) : (
                      <div className="flex h-24 w-36 items-center justify-center rounded-md border border-dashed border-border text-faint">…</div>
                    )}
                    <figcaption className={cn("mt-1 w-36 truncate text-[10px]", s.ok ? "text-faint" : "text-amber-500")}>{s.label || "field"}</figcaption>
                  </figure>
                ))}
              </div>
            </div>
          )}
          {done && (
            <div className="co-rise mt-4 flex items-start gap-2.5 rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-4 py-3 text-sm backdrop-blur-sm">
              <CheckCircle2 className="mt-0.5 size-5 shrink-0 text-emerald-500" />
              <div>
                <span className="font-medium text-emerald-700 dark:text-emerald-400">The real form is now in front, pre-filled.</span>{" "}
                <span className="text-muted">Review it and click Submit yourself — career-ops never submits for you.</span>
              </div>
            </div>
          )}
        </div>
      )}

      {/* the way out: back out of the form, or record that you sent it */}
      <ApplyExitBar />
    </div>
  );
}

// ── Leaving the page: back out, or record that you applied ─────────────────
// You submit the real form yourself on the employer's site, so the moment you
// apply happens outside career-ops — this is where you tell the tracker about
// it. The write goes through /api/status, the same route the tracker's own
// status control uses, so there is only ever one writer to the table.
function ApplyExitBar() {
  const a = useApply();
  const router = useRouter();
  const [confirming, setConfirming] = useState(false);
  const [marking, setMarking] = useState(false);
  const [error, setError] = useState("");
  // The status write outlives this bar when the user navigates while it is in
  // flight. The write still lands; what must not happen is dragging them back
  // off whatever page they moved on to once it returns.
  // Set on mount as well as cleared on unmount: React re-runs an effect after
  // its cleanup (StrictMode does this on every mount in development), so a
  // cleanup-only flag latches false while the bar is still on screen.
  const onPage = useRef(true);
  useEffect(() => {
    onPage.current = true;
    return () => {
      onPage.current = false;
    };
  }, []);

  // reset() also closes the headless form session on the user's machine —
  // navigating away without it strands the browser this page opened. The
  // destination is read before reset() clears the origin it comes from.
  //
  // The staleness check comes FIRST, before reset(). By the time a late status
  // response gets here the user may have started a different application, and
  // reset() is not addressed to a particular session: it would close whichever
  // one is open now, taking a form the user is in the middle of with it.
  // Leaving that session alone is the same outcome as navigating away from the
  // page by any other route.
  function leave() {
    if (!onPage.current) return;
    const target = resolveReturnPath(a.from);
    a.reset();
    router.push(target);
    router.refresh();
  }

  async function markApplied() {
    setMarking(true);
    setError("");
    try {
      const res = await fetch("/api/status", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ n: a.n, status: "Applied" }),
      });
      if (!res.ok) {
        const d = await res.json().catch(() => ({}));
        if (!onPage.current) return; // moved on already; the row is unchanged
        setError(d.error || "Couldn't mark it applied — the tracker row is unchanged.");
        setMarking(false);
        return;
      }
      leave();
    } catch {
      if (!onPage.current) return; // moved on already
      // The route writes the tracker before it answers, so a connection that
      // drops on the way back leaves the write's fate genuinely unknown —
      // claiming the row is untouched here would be a guess.
      setError("Couldn't confirm the update — check the row in your tracker before relying on it.");
      setMarking(false);
    }
  }

  if (confirming) {
    return (
      <div className="co-rise mt-8 rounded-xl border border-amber-500/40 bg-amber-500/10 p-4 backdrop-blur-sm">
        <p className="text-sm font-medium text-foreground">Leave this application?</p>
        <p className="mt-1 text-xs text-muted">Your drafted answers live only on this page. Going back discards them and closes the form.</p>
        <div className="mt-3 flex flex-wrap gap-2">
          <button
            onClick={leave}
            className="inline-flex items-center gap-1.5 rounded-md bg-amber-500 px-3 py-1.5 text-xs font-medium text-white transition-colors hover:bg-amber-600 max-sm:min-h-[44px]"
          >
            <ArrowLeft className="size-3.5" /> Leave and discard
          </button>
          <button
            onClick={() => setConfirming(false)}
            className="rounded-md border border-border px-3 py-1.5 text-xs text-muted transition-colors hover:text-foreground max-sm:min-h-[44px]"
          >
            Stay here
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="mt-8 border-t border-border/70 pt-5">
      <div className="flex flex-wrap items-center gap-3">
        <button
          onClick={() => (needsLeaveConfirmation({ status: a.status, answers: a.answers }) ? setConfirming(true) : leave())}
          className="inline-flex items-center gap-1.5 rounded-full border border-border px-4 py-2 text-sm font-medium text-muted transition-colors hover:border-brand/40 hover:text-brand max-sm:min-h-[44px]"
        >
          <ArrowLeft className="size-4" /> Back
        </button>
        {a.n && (
          <button
            onClick={markApplied}
            disabled={marking}
            title={`Set tracker row #${a.n} to Applied and go back`}
            className="inline-flex items-center gap-1.5 rounded-full border border-emerald-500/40 bg-emerald-500/10 px-4 py-2 text-sm font-medium text-emerald-700 transition-colors hover:bg-emerald-500/20 disabled:opacity-50 dark:text-emerald-400 max-sm:min-h-[44px]"
          >
            {marking ? <Loader2 className="size-4 animate-spin" /> : <ClipboardCheck className="size-4" />}
            {marking ? "Updating your tracker…" : "Mark applied"}
          </button>
        )}
        {a.n && <span className="text-xs text-muted">Click this once you have submitted the real form yourself.</span>}
      </div>
