        {value}
      </div>
      <div className="mt-2 text-sm text-foreground">{label}</div>
      <div className="text-xs text-faint">{hint}</div>
    </Link>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Gauge } from "lucide-react";
import { cn } from "@/lib/cn";

type Usage = { window5h: { tokens: number }; window7d: { tokens: number } };

// Soft budgets (tunable via localStorage `career-ops:usage-budget`). The bar
// colour is the "brake" signal — set these to your plan's real limits.
const DEFAULT_BUDGET = { w5: 140_000_000, w7: 1_000_000_000 };

function fmt(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1).replace(/\.0$/, "")}M`;
  if (n >= 1_000) return `${Math.round(n / 1_000)}k`;
  return `${n}`;
}
function tone(pct: number): string {
  if (pct >= 85) return "bg-red-400";
  if (pct >= 60) return "bg-amber-400";
  return "bg-emerald-400";
}

export function UsageMeter() {
  const [data, setData] = useState<Usage | null>(null);
  const [cli, setCli] = useState<string | null>(null);
  const [budget, setBudget] = useState(DEFAULT_BUDGET);

  useEffect(() => {
    try {
      const cfg = localStorage.getItem("career-ops:config");
      setCli(cfg ? JSON.parse(cfg).cliId || null : null);
      const b = localStorage.getItem("career-ops:usage-budget");
      if (b) setBudget({ ...DEFAULT_BUDGET, ...JSON.parse(b) });
    } catch {
      /* ignore */
    }
  }, []);

  useEffect(() => {
    let alive = true;
    const load = () =>
      fetch("/api/usage")
        .then((r) => r.json())
        .then((d) => {
          if (alive) setData(d);
        })
        .catch(() => {});
    load();
    const id = setInterval(load, 60_000);
    return () => {
      alive = false;
      clearInterval(id);
    };
  }, []);

  // The usage source is Claude's local logs; only meaningful when Claude is the CLI.
  if (cli && cli !== "claude") return null;
  if (!data) return null;

  const rows = [
    { label: "5h", tokens: data.window5h?.tokens ?? 0, budget: budget.w5 },
    { label: "7d", tokens: data.window7d?.tokens ?? 0, budget: budget.w7 },
  ];

  return (
    <div className="border-t border-border pt-3">
      <div className="mb-1.5 flex items-center gap-1.5 px-1 text-[10px] font-semibold uppercase tracking-[0.18em] text-faint">
        <Gauge className="size-3" /> Usage
      </div>
      <div className="space-y-2 px-1">
        {rows.map((r) => {
          const pct = Math.min(100, Math.round((r.tokens / r.budget) * 100));
          return (
            <div key={r.label} title={`${r.tokens.toLocaleString()} tokens in the last ${r.label}`}>
              <div className="flex items-center justify-between text-[10px] text-faint">
                <span>{r.label}</span>
                <span className="tabular-nums">
                  {fmt(r.tokens)} · {pct}%
                </span>
              </div>
              <div className="mt-0.5 h-1 w-full overflow-hidden rounded-full bg-surface-hover">
                <div
                  className={cn("h-full rounded-full transition-all", tone(pct))}
                  style={{ width: `${Math.max(pct, 2)}%` }}
                />
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// Pure JS helper for the assistant console's <<act:ID {json}>> envelope parser
// (assistant-console.tsx). No TypeScript types so it can be imported by both the
// component and tests/lib/act-envelope.test.mjs (which can't import .tsx
// without a runner).
//
// parseEnvelopes only hides an incomplete envelope once the opener regex
// `<<act:([a-zA-Z]+)[ \t]+` fully matches — i.e. `<<act:`, the id letters, AND
// the trailing space are all present. While a chunk boundary leaves the opener
// short of that (`<<`, `<<act`, `<<act:save` with no space yet), nothing hides
// it, so the half-written marker flickers into the rendered chat bubble on every
// action the assistant takes. This finds where such a trailing partial opener
// begins so the caller can hide it too — the same "buffer a split opener, never
// render garbage" invariant the AI-search parser holds (stream-parse.mjs).

const OPEN = "<<act:";

/**
 * Start index of a trailing partial `<<act:` opener in `acc` that the main
 * `<<act:([a-zA-Z]+)[ \t]+` regex can't match yet, or -1 if none.
 *
 * Anchored to the end of `acc`, so a completed envelope earlier in the string
 * (which is followed by its `>>`, not by end-of-buffer) is never matched.
 *
 * @param {string} acc - Accumulated assistant text so far.
 * @returns {number} Index where the trailing partial opener starts, else -1.
 */
export function pendingActOpenerStart(acc) {
  // `<<act:` plus any id letters, but no trailing space yet → regex can't fire.
  const withColon = /<<act:[a-zA-Z]*$/.exec(acc);
  if (withColon) return withColon.index;
  // A proper prefix of the literal `<<act:` at the very end (`<` … `<<act`).
  for (let k = Math.min(acc.length, OPEN.length - 1); k > 0; k--) {
    if (acc.endsWith(OPEN.slice(0, k))) return acc.length - k;
  }
  return -1;
}

import { spawnHeadlessCli } from "@/lib/spawn-cli.mjs";
import type { Frame } from "playwright-core";
import { resolveCli } from "@/lib/clis";
import { careerOpsRoot } from "@/lib/career-ops";
import type { ApplyField } from "./extract";

// ─────────────────────────────────────────────────────────────────────────────
// AGENTIC FALLBACK — the AI interprets the LIVE form, like a human does with
// Playwright. When deterministic extraction is low-confidence (unknown ATS, 0
// clean fields), we hand the LLM a text snapshot of EVERY interactive control +
// its surrounding context/options (no hardcoded selectors), and it returns the
// form's structure. WE then actuate deterministically (fill/verify/handoff) —
// the LLM interprets, never blind-clicks. Robust to any markup change.
// ─────────────────────────────────────────────────────────────────────────────

type Cand = { n: number; tag: string; type: string; name: string; placeholder: string; aria: string; req: boolean; ctx: string; opts: string[] };

/** Tag + capture every interactive control in the frame as a browser_snapshot-style
 *  text list the LLM can reason over. Radio groups collapse to one candidate. */
async function captureCandidates(frame: Frame): Promise<Cand[]> {
  return frame.evaluate(() => {
    const clean = (s: string | null | undefined) => (s || "").replace(/\s+/g, " ").trim().slice(0, 220);
    const cands: Cand[] = [];
    const seenRadio = new Set<string>();
    const els = Array.from(document.querySelectorAll('input, textarea, select, [role="combobox"], [role="radiogroup"], [contenteditable="true"]'));
    let n = 0;
    for (const el of els) {
      const tag = el.tagName.toLowerCase();
      const itype = ((el as HTMLInputElement).type || "").toLowerCase();
      const role = el.getAttribute("role") || "";
      if (tag === "input" && ["hidden", "submit", "button", "image", "reset"].includes(itype)) continue;
      if ((el as HTMLElement).offsetParent === null && itype !== "radio" && itype !== "checkbox") continue;
      if ((el as Element).closest('[class*="autofill" i]')) continue;

      const cont = el.closest('[class*="field" i], [class*="question" i], fieldset, .form-group, div');
      const ctx = clean((cont as HTMLElement | null)?.innerText);
      const req = (el as HTMLInputElement).required || el.getAttribute("aria-required") === "true" || /\*|\brequired\b/i.test(ctx);
      const name = (el as HTMLInputElement).name || (el as HTMLElement).id || "";
      const aria = el.getAttribute("aria-label") || "";
      const placeholder = (el as HTMLInputElement).placeholder || "";

      if (itype === "radio") {
        const rname = (el as HTMLInputElement).name;
        if (rname && seenRadio.has(rname)) continue;
        if (rname) seenRadio.add(rname);
        const group = Array.from(document.querySelectorAll(`input[type=radio][name="${CSS.escape(rname)}"]`));
        const opts = group.map((r) => clean((document.querySelector(`label[for="${CSS.escape((r as HTMLElement).id)}"]`)?.textContent) || r.closest("label")?.textContent || (r as HTMLInputElement).value)).filter(Boolean);
        group.forEach((r) => r.setAttribute("data-co-cand", String(n)));
        cands.push({ n, tag: "radiogroup", type: "radio", name: rname || "", placeholder, aria, req, ctx, opts });
        n++;
        continue;
      }
      el.setAttribute("data-co-cand", String(n));
      let opts: string[] = [];
      if (tag === "select") opts = Array.from((el as HTMLSelectElement).options).map((o) => clean(o.textContent)).filter((o) => o && !/^(select|choose|--)/i.test(o));
      cands.push({ n, tag, type: itype || role || tag, name, placeholder, aria, req, ctx, opts });
      n++;
    }
    return cands;
  });
}

const VALID_TYPES = new Set(["text", "email", "tel", "url", "number", "date", "textarea", "select", "radio", "checkbox", "file"]);

/** Ask the planner CLI to interpret the captured controls into clean fields. */
function buildPrompt(title: string, cands: Cand[]): string {
  const lines = cands
    .map((c) => `[${c.n}] tag=${c.tag} type=${c.type}${c.req ? " required" : ""}${c.name ? ` name="${c.name}"` : ""}${c.placeholder ? ` placeholder="${c.placeholder}"` : ""}${c.aria ? ` aria="${c.aria}"` : ""}${c.opts.length ? ` options=[${c.opts.slice(0, 12).join(" | ")}]` : ""} | context: "${c.ctx}"`)
    .join("\n");
  return `You are interpreting a LIVE job-application form (${title}) so it can be re-rendered cleanly. Below is EVERY interactive control with its surrounding text. For EACH control decide:
- "skip": true if it is NOT a real application field to fill (a search/filter box, navigation, cookie/consent control, social-login button, or decorative widget).
- otherwise give: "label" (the human question in plain words, cleaned of asterisks/option text), "type" (one of: text, email, tel, url, number, date, textarea, select, radio, checkbox, file), "options" (ONLY for select/radio — the exact visible option texts), "required" (boolean).
Infer the TYPE from meaning (e.g. a "Resume/CV" upload = file; a custom dropdown = select; "Why us?" = textarea). Use the EXACT option texts shown.

CONTROLS:
${lines}

Return ONLY a JSON array, no prose, no code fence:
[{"n":0,"skip":false,"label":"First Name","type":"text","options":[],"required":true}, ...]`;
}

function runPlanner(binPath: string, isClaude: boolean, argsFor: (p: string) => string[], prompt: string): Promise<string> {
  const args = isClaude ? ["-p", prompt, "--permission-mode", "acceptEdits", "--strict-mcp-config", "--allowedTools", "Read", "--disallowedTools", "Bash,Write,Edit,NotebookEdit,Task,WebFetch,WebSearch"] : argsFor(prompt);
  return new Promise((resolve) => {
    const child = spawnHeadlessCli(binPath, args, { cwd: careerOpsRoot(), env: process.env });
    let buf = "";
    child.stdout.on("data", (d: Buffer) => (buf += d.toString()));
    child.stderr.on("data", () => {});
    const killer = setTimeout(() => {
      try {
        child.kill("SIGTERM");
      } catch {
        /* ignore */
      }
    }, 150_000);
    child.on("close", () => {
      clearTimeout(killer);
      resolve(buf);
    });
    child.on("error", () => {
      clearTimeout(killer);
      resolve(buf);
    });
  });
}

type Interpreted = { n: number; skip?: boolean; label?: string; type?: string; options?: string[]; required?: boolean };

/** The agentic interpreter: capture the live form, let the LLM read+classify it,
 *  re-tag the chosen controls with data-co-field, and return clean ApplyField[].
 *  Returns [] if the CLI is missing or interpretation fails (caller falls back). */
export async function agentInterpretForm(frame: Frame, cliId: string, title: string): Promise<ApplyField[]> {
  const resolved = resolveCli(cliId);
  if (!resolved) return [];
  const cands = await captureCandidates(frame).catch(() => [] as Cand[]);
  if (!cands.length) return [];

  const out = await runPlanner(resolved.binPath, cliId === "claude", resolved.spec.args, buildPrompt(title, cands));
  const m = out.match(/\[[\s\S]*\]/);
  if (!m) return [];
  let parsed: Interpreted[];
  try {
    parsed = JSON.parse(m[0]);
  } catch {
    return [];
  }

  const byN = new Map(cands.map((c) => [c.n, c]));
  const fields: ApplyField[] = [];
  const tagMap: { candN: number; fid: string; type: string; options: string[] }[] = [];
  parsed
    .filter((p) => p && !p.skip && typeof p.n === "number" && byN.has(p.n))
    .forEach((p) => {
      const type = VALID_TYPES.has(p.type || "") ? (p.type as ApplyField["type"]) : "text";
      const fid = `co${fields.length}`;
      const cand = byN.get(p.n)!;
      const options = (p.options && p.options.length ? p.options : cand.opts).map((s) => s.trim()).filter(Boolean);
      fields.push({ id: fid, type, label: (p.label || cand.ctx || "").slice(0, 160), required: !!p.required || cand.req, options: options.length ? options : undefined, combobox: type === "select" && cand.tag !== "select" });
      tagMap.push({ candN: p.n, fid, type, options });
    });
  if (!fields.length) return [];

  // Re-tag the live elements: data-co-field on the chosen control (+ per-option
  // data-co-option for radios) so fillSession can locate them deterministically.
  await frame
    .evaluate((tagMap) => {
      for (const t of tagMap) {
        const els = Array.from(document.querySelectorAll(`[data-co-cand="${t.candN}"]`));
        if (t.type === "radio") {
          els.forEach((r, i) => {
            r.setAttribute("data-co-field", t.fid);
            const lbl = (document.querySelector(`label[for="${CSS.escape((r as HTMLElement).id)}"]`)?.textContent || r.closest("label")?.textContent || (r as HTMLInputElement).value || "").replace(/\s+/g, " ").trim();
            r.setAttribute("data-co-option", t.options[i] || lbl || String(i));
          });
        } else {
          els.forEach((e) => e.setAttribute("data-co-field", t.fid));
        }
      }
    }, tagMap)
    .catch(() => {});

  return fields;
}

import fs from "node:fs";
import path from "node:path";
import { careerOpsRoot } from "@/lib/career-ops";

/**
 * Locate the tailored CV PDF the real `pdf` mode wrote to output/ for a given
 * company (newest match wins). STRICT company match — never returns a CV tailored
 * for a different company (we'd rather attach nothing than the wrong CV). Mirrors
 * the matching in /api/cv-pdf so the "View tailored CV" link and the apply
 * file-upload always resolve to the SAME file. Returns an absolute path or null.
 */
export function resolveTailoredCv(company?: string): string | null {
  const c = (company ?? "").trim();
  if (!c) return null;
  const dir = path.join(careerOpsRoot(), "output");
  let files: string[];
  try {
    files = fs.readdirSync(dir).filter((f) => f.toLowerCase().endsWith(".pdf"));
  } catch {
    return null;
  }
  // Token-extract instead of replace-then-trim: same slug, and no `-+$`-style
  // pattern that backtracks polynomially on adversarial input (CodeQL).
  const slug = (c.toLowerCase().match(/[a-z0-9]+/g) ?? []).join("-");
  const first = slug.split("-")[0];
  const matches = files.filter((f) => {
    const l = f.toLowerCase();
    return l.includes(slug) || (first.length > 2 && l.includes(first));
  });
  if (!matches.length) return null;
  matches.sort((a, b) => fs.statSync(path.join(dir, b)).mtimeMs - fs.statSync(path.join(dir, a)).mtimeMs);
  return path.join(dir, matches[0]);
}

/**
 * Best-effort company name from an application form/page title. ATS titles look
 * like "Role - Region @ Company" (Ashby) or "Company — Role" / "Role at Company".
 * Used as a fallback when the apply flow was started by pasting a URL (no offer
 * context) rather than from a report's Apply button.
 */
export function companyFromTitle(title?: string): string {
  const t = (title ?? "").trim();
  if (!t) return "";
  const at = t.match(/@\s*([^|@]+?)\s*$/);
  if (at) return at[1].trim();
  const atWord = t.match(/\bat\s+([A-Z][\w&.\- ]+?)\s*$/);
  if (atWord) return atWord[1].trim();
  return "";
}

import type { Page, Frame } from "playwright-core";
import type { ApplyField } from "./extract";
import type { ApplyIssue } from "./issue";

export type { ApplyIssue };

// ─────────────────────────────────────────────────────────────────────────────
// Robust block/obstacle detection for the local Playwright form-interpreter.
// Through-line guard (from the robustness taxonomy): only ever ABORT when there
// is NO fillable form after settle — a captcha/cookie badge over a populated form
// is NOT a block. Abort-level categories require ≥2 independent signal classes.
// We never auto-solve a challenge; we hand the human a clear, actionable message.
// ─────────────────────────────────────────────────────────────────────────────

/** Cheapest + first check: the navigation Response status/headers. Returns a hard
 *  block for auth/forbidden/geo/rate-limit/server/not-found — before any DOM work. */
export function statusBlock(status: number | null | undefined, headers: Record<string, string>): ApplyIssue | null {
  if (!status) return null;
  const cf = headers["cf-ray"] || headers["cf-mitigated"] || headers["cf-request-id"];
  if (status === 401 || status === 407) return { level: "block", code: "auth-required", message: "This page needs you to sign in first. Open it directly, log in, then paste the application-form URL here." };
  if (status === 451) return { level: "block", code: "geo-block", message: "This page is blocked for legal/region reasons. We can't open the form here." };
  if (status === 403) return { level: "block", code: cf ? "bot-block" : "forbidden", message: cf ? "This page is behind a bot check. Open it directly in your browser, then paste the URL back here." : "This page returned “403 access denied”. Open it directly in your browser to check." };
  if (status === 429) return { level: "block", code: "rate-limited", message: "The site is rate-limiting requests right now. Wait a minute, then try again or open it directly." };
  if (status >= 500) return { level: "block", code: "server-error", message: `The site returned an error (status ${status}). Try again shortly, or open it directly.` };
  if (status === 404 || status === 410) return { level: "block", code: "not-found", message: "This posting is gone (404). It's likely closed, or the link is wrong." };
  return null;
}

const CONSENT_ROOTS =
  '#onetrust-banner-sdk, #CybotCookiebotDialog, #truste-consent-track, .qc-cmp2-container, #usercentrics-root, [id*="cookie" i][class*="banner" i], [class*="cookie-consent" i], [aria-label*="cookie" i]';
const CONSENT_BUTTONS = [
  "#onetrust-accept-btn-handler",
  "#onetrust-button-accept-all",
  "#CybotCookiebotDialogBodyLevelButtonLevelOptinAllowAll",
  "#CybotCookiebotDialogBodyButtonAccept",
  '.qc-cmp2-button[mode="primary"]',
  "#truste-consent-button",
];

/** Auto-dismiss a cookie/consent overlay that covers the form (it only HIDES the
 *  form, it's never a hard block). Tries vendor buttons, then a generic accept. */
export async function dismissConsent(page: Page): Promise<ApplyIssue[]> {
  try {
    const root = page.locator(CONSENT_ROOTS).first();
    if (!(await root.count().catch(() => 0))) return [];
    if (!(await root.isVisible().catch(() => false))) return [];
    for (const sel of CONSENT_BUTTONS) {
      const b = page.locator(sel).first();
      if ((await b.count().catch(() => 0)) && (await b.isVisible().catch(() => false))) {
        await b.click({ timeout: 2000 }).catch(() => {});
        return [{ level: "info", code: "consent-dismissed", message: "Dismissed a cookie banner to reach the form." }];
      }
    }
    const g = page.getByRole("button", { name: /^(accept|allow|agree|got it|i agree|accept all)/i }).first();
    if (await g.count().catch(() => 0)) {
      await g.click({ timeout: 2000 }).catch(() => {});
      return [{ level: "info", code: "consent-dismissed", message: "Dismissed a cookie banner to reach the form." }];
    }
  } catch {
    /* never let consent handling break the open */
  }
  return [];
}

/** Force same-tab navigation: many "Apply" links are <a target="_blank"> (e.g.
 *  openai.com → jobs.ashbyhq.com/…/application). Without this, clicking Apply
 *  opens a NEW tab we don't follow and the loop never reaches the form. We strip
 *  target=_blank in every frame so any click/navigation stays in OUR page. */
export async function dropNewTabs(page: Page): Promise<void> {
  for (const fr of page.frames()) {
    await fr
      .evaluate(() => {
        document.querySelectorAll('a[target="_blank"], a[target="_new"], form[target]').forEach((el) => el.removeAttribute("target"));
        // also neutralise window.open so JS "apply" handlers navigate in-tab
        try {
          (window as unknown as { open: (u?: string) => Window | null }).open = (u?: string) => {
            if (u) location.href = u;
            return null;
          };
        } catch {
          /* ignore */
        }
      })
      .catch(() => {});
  }
}

/** SPA / apply-behind-a-button: if no form yet, click the first visible Apply CTA
 *  (NEVER a submit) to reveal the form. If it's an <a> with an application href,
 *  NAVIGATE there directly (robust vs popups). Returns true if it acted. */
export async function tryApplyTrigger(page: Page): Promise<boolean> {
  try {
    // 1) Most reliable: an <a> linking straight to a known ATS application (e.g.
    //    openai.com → jobs.ashbyhq.com/…/application). Navigate there in-tab.
    const atsLink = page.locator('a[href*="ashbyhq"], a[href*="greenhouse"], a[href*="lever.co"], a[href*="smartrecruiters"], a[href*="workable"], a[href*="recruitee"], a[href*="bamboohr"], a[href*="jobvite"], a[href*="teamtailor"], a[href*="myworkdayjobs"], a[href*="/apply"], a[href*="/application"]').first();
    if (await atsLink.count().catch(() => 0)) {
      const href = await atsLink.getAttribute("href").catch(() => null);
      if (href && /^https?:\/\//i.test(href) && !/submit/i.test(href)) {
        await page.goto(href, { waitUntil: "domcontentloaded", timeout: 30_000 }).catch(() => {});
        return true;
      }
    }
    // 2) Otherwise click a visible Apply CTA (never a submit). dropNewTabs() has
    //    already neutralised target=_blank / window.open so it stays in-tab.
    const t = page
      .getByRole("button", { name: /apply|start application|begin application/i })
      .or(page.getByRole("link", { name: /apply/i }))
      .first();
    if ((await t.count().catch(() => 0)) && (await t.isVisible().catch(() => false))) {
      const label = (await t.innerText().catch(() => "")).toLowerCase();
      if (/submit|applied|withdraw/.test(label)) return false;
      await t.click({ timeout: 3000 }).catch(() => {});
      return true;
    }
  } catch {
    /* ignore */
  }
  return false;
}

/** When extraction yields 0 fields, classify WHY so we abort with the RIGHT
 *  message (bot-challenge vs login wall vs closed posting vs unsupported). */
export async function classifyEmpty(page: Page, url: string): Promise<ApplyIssue> {
  const host = (() => {
    try {
      return new URL(url).hostname;
    } catch {
      return "";
    }
  })();
  const sig = await page
    .evaluate(() => {
      const t = (document.title || "").toLowerCase();
      const body = (document.body?.innerText || "").toLowerCase().slice(0, 6000);
      const hasPassword = !!document.querySelector('input[type="password"]');
      const challengeDom = !!document.querySelector(
        '#challenge-running, #challenge-form, .cf-browser-verification, iframe[src*="challenges.cloudflare.com"], .g-recaptcha, .h-captcha, #px-captcha, [class*="datadome" i], #cf-please-wait',
      );
      return { t, body, hasPassword, challengeDom };
    })
    .catch(() => ({ t: "", body: "", hasPassword: false, challengeDom: false }));

  const u = url.toLowerCase();
  const challTitle = /just a moment|checking your browser|one moment please|verifying you|attention required/.test(sig.t);
  const challUrl = /__cf_chl|challenges\.cloudflare\.com|\/cdn-cgi\/|datadome|px-captcha/.test(u);
  const challText = /(verify (you|that you)|are you human|not a robot|human verification|checking your browser|enable javascript and cookies)/.test(sig.body);
  if ([challTitle, challUrl, sig.challengeDom, challText].filter(Boolean).length >= 2) {
    return { level: "block", code: "bot-challenge", message: "This page is asking you to verify you're human before showing the form. Open it directly in your browser, complete the check, then paste the URL back here." };
  }
  if (sig.hasPassword || /\/(login|sign-?in|register|sign-?up|auth|account|mfa|2fa)(\/|$|\?)/.test(u)) {
    return { level: "block", code: "login-wall", message: "This page wants you to sign in or create an account first. Open it directly, log in, then paste the actual application-form URL here." };
  }
  if (/no longer accepting|position has been filled|posting is closed|no longer available|this (job|position|posting) (is |has )?(closed|expired|been filled)/.test(sig.body) || /not found|no longer|removed|closed/.test(sig.t)) {
    return { level: "block", code: "expired", message: "This job posting is closed or expired — it's no longer accepting applications." };
  }
  if (/myworkdayjobs\.com$/i.test(host)) {
    return { level: "block", code: "workday", message: "Workday forms aren't supported for in-app fill yet (multi-step, account-gated). Open the posting and apply there directly." };
  }
  if (/^(jobs|careers|empleos|empregos|all jobs|open (positions|roles)|search jobs|current openings)/i.test(sig.t) || /\/(jobs|careers|search|positions)\/?(\?|$)/.test(u)) {
    return { level: "block", code: "listing-page", message: "This looks like the careers listing, not a single application — the posting may have moved or closed. Open the specific job and paste its “Apply” URL." };
  }
  return { level: "block", code: "no-form", message: "Couldn't find a fillable form on this page. If it's a job description, open its “Apply” form and paste that URL." };
}

/** An INTERACTIVE captcha (a checkbox/widget the user must click) present on the
 *  form → warn. We deliberately IGNORE invisible reCAPTCHA v3 (the .grecaptcha-
 *  badge that's on nearly every ATS form and needs NO user action) so the warning
 *  isn't constant noise. */
export async function captchaWarning(page: Page): Promise<ApplyIssue | null> {
  const interactive = await page
    .evaluate(() => {
      const vis = (el: Element | null) => {
        if (!el) return false;
        const r = (el as HTMLElement).getBoundingClientRect();
        return (el as HTMLElement).offsetParent !== null && r.width > 40 && r.height > 20;
      };
      const some = (sel: string) => Array.from(document.querySelectorAll(sel)).some(vis);
      // v2 checkbox (anchor iframe / visible widget), hCaptcha checkbox, Turnstile widget.
      // NOT .grecaptcha-badge (invisible v3) and NOT the bare bframe.
      return (
        some('iframe[src*="recaptcha/api2/anchor"]') ||
        some('.g-recaptcha[data-size="normal"]') ||
        some('iframe[src*="hcaptcha.com"][src*="frame=checkbox"], .h-captcha iframe') ||
        some('.cf-turnstile')
      );
    })
    .catch(() => false);
  return interactive ? { level: "warn", code: "captcha-present", message: "This form has a captcha you'll need to tick — do it yourself on the real form at the end." } : null;
}

/** Conservatively detect a multi-STEP form (we only read/fill page 1) so we can
 *  set the user's expectation that they'll continue on the real form. Fires only
 *  on a "Step 1 of N" indicator, or a visible Next/Continue with NO Submit. */
export async function multiStepInfo(page: Page): Promise<ApplyIssue | null> {
  const ms = await page
    .evaluate(() => {
      const txt = (document.body?.innerText || "").toLowerCase();
      const stepText = /\b(step|page|stage)\s*\d+\s*(of|\/)\s*\d+/.test(txt);
      const vis = (el: Element) => (el as HTMLElement).offsetParent !== null;
      const btns = Array.from(document.querySelectorAll("button, a, [role=button]"));
      const label = (b: Element) => (b.textContent || "").replace(/\s+/g, " ").trim();
      const hasNext = btns.some((b) => vis(b) && /^(next|continue|save (and|&) continue|next step|continue to)\b/i.test(label(b)));
      const hasSubmit = btns.some((b) => vis(b) && /^(submit application|submit|send application|apply now)\b/i.test(label(b)));
      return (stepText || hasNext) && !hasSubmit;
    })
    .catch(() => false);
  return ms ? { level: "info", code: "multi-step", message: "This form has more than one step — after this page, you'll continue on the real form." } : null;
}

/** READ THE REAL FORM BACK after filling: did every answer land? required fields
 *  still empty? any validation error visible? — the self-verification a blind
 *  selector script can't do. Returns warnings to show BEFORE the human submits. */
export async function verifyFill(frame: Frame, fields: ApplyField[], answers: Record<string, string>): Promise<ApplyIssue[]> {
  const meta = fields.map((f) => ({ id: f.id, label: f.label || "this field", type: f.type, required: !!f.required, combobox: !!f.combobox }));
  type R = { mismatches: string[]; requiredEmpty: string[]; valErrors: string[] };
  const res = await frame
    .evaluate(
      ({ meta, answers }): R => {
        const norm = (s: string | null | undefined) => (s || "").replace(/\s+/g, " ").trim().toLowerCase();
        const mismatches: string[] = [];
        const requiredEmpty: string[] = [];
        for (const f of meta) {
          const intended = answers[f.id];
          const el = document.querySelector(`[data-co-field="${f.id}"]`) as HTMLElement | null;
          if (!el) continue;
          if (f.type === "file") {
            // confirm a file actually landed on the input (the CV attach can fail
            // silently on a custom dropzone). Only warn if the field is required.
            const filesEl = el as HTMLInputElement;
            const has = !!(filesEl.files && filesEl.files.length > 0);
            if (f.required && !has) requiredEmpty.push(f.label);
            continue;
          }
          let actual = "";
          if (f.type === "checkbox") {
            actual = (el as HTMLInputElement).checked ? "true" : "";
          } else if (f.type === "radio") {
            const grp = Array.from(document.querySelectorAll(`[data-co-field="${f.id}"]`)) as HTMLInputElement[];
            actual = grp.some((r) => r.checked) ? "checked" : "";
          } else if (f.combobox) {
            // react-select keeps the chosen value in a sibling .select__single-value
            // (the tagged input stays empty). Read leniently: only conclude "empty"
            // when a placeholder is visibly shown — otherwise assume OK (never a
            // false "didn't land" warning).
            const shell = el.closest('[class*="select-shell" i], [class*="select__container" i], [class*="select__control" i], [class*="value-container" i]') || el.parentElement?.parentElement || el.parentElement;
            const sv = shell?.querySelector('.select__single-value, [class*="single-value" i], [class*="singleValue" i], [class*="multi-value" i]');
            const ph = shell?.querySelector('.select__placeholder, [class*="placeholder" i]');
            const svText = (sv?.textContent || "").trim();
            if (svText) actual = svText; // a value is shown
            else if (ph && (ph as HTMLElement).offsetParent !== null) actual = ""; // placeholder visible → empty
            else actual = intended || "ok"; // can't read reliably → don't flag
          } else {
            actual = (el as HTMLInputElement).value || "";
          }
          if (intended && intended.trim() && !norm(actual)) mismatches.push(f.label);
          else if (f.required && !norm(actual) && !(intended && intended.trim())) requiredEmpty.push(f.label);
        }
        const errSel = '[aria-invalid="true"], [role="alert"], [class*="error" i]:not([class*="clear" i]):not([class*="error-free" i])';
        const valErrors: string[] = [];
        for (const e of Array.from(document.querySelectorAll(errSel)) as HTMLElement[]) {
          const txt = (e.textContent || "").replace(/\s+/g, " ").trim();
          if (txt && txt.length > 2 && txt.length < 160 && e.offsetParent !== null) valErrors.push(txt);
        }
        return { mismatches, requiredEmpty, valErrors: Array.from(new Set(valErrors)).slice(0, 5) };
      },
      { meta, answers },
    )
    .catch(() => ({ mismatches: [], requiredEmpty: [], valErrors: [] }) as R);

  const out: ApplyIssue[] = [];
  if (res.mismatches.length) out.push({ level: "warn", code: "fill-mismatch", message: `These answers didn't seem to land on the real form — check them: ${res.mismatches.slice(0, 4).join(", ")}${res.mismatches.length > 4 ? "…" : ""}.` });
  if (res.requiredEmpty.length) out.push({ level: "warn", code: "required-empty", message: `Required and still empty — you'll need to fill ${res.requiredEmpty.length > 1 ? "these" : "this"}: ${res.requiredEmpty.slice(0, 4).join(", ")}${res.requiredEmpty.length > 4 ? "…" : ""}.` });
  for (const v of res.valErrors) out.push({ level: "warn", code: "validation", message: `The form flagged: “${v}”.` });
  return out;
}

import { spawnHeadlessCli } from "@/lib/spawn-cli.mjs";
import type { Page, Frame } from "playwright-core";
import { resolveCli } from "@/lib/clis";
import { careerOpsRoot } from "@/lib/career-ops";
import { dropNewTabs } from "./diagnose";
import type { DriveStep } from "./issue";

export type { DriveStep };

// ─────────────────────────────────────────────────────────────────────────────
// AGENTIC DRIVE LOOP — the backend gets "as intelligent as Claude Code + Playwright":
// observe (ref-tagged snapshot) → the LLM picks ONE action → WE execute it on OUR
// headed session → observe again → adapt. We orchestrate the loop (CLI-agnostic in
// principle; Claude-first via --resume) and execute every action ourselves, so:
//   • NEVER-SUBMIT is by CONSTRUCTION — the action vocabulary has no "submit", and
//     we refuse to click any submit/apply-final control. The human submits.
//   • everything stays in OUR session (screenshots, handoff, the streamed UI).
// HYBRID = drive only until a fillable application form is reached, then hand back
// to deterministic fill+verify. FULL = keep driving (fill the fields too).
// ─────────────────────────────────────────────────────────────────────────────

export type DriveResult = { reached: boolean; turns: number; reason: string; steps: DriveStep[] };

const SUBMIT_RX = /\b(submit|send application|finish( application)?|complete application|apply (and|&) submit|enviar|finalizar)\b/i;

/** Ref-tagged snapshot of the interactive page (a browser_snapshot-style view the
 *  LLM reasons over). Tags data-co-ref on each element so actions are unambiguous. */
async function snapshot(frame: Frame): Promise<{ text: string; n: number }> {
  return frame.evaluate(() => {
    const clean = (s: string | null | undefined) => (s || "").replace(/\s+/g, " ").trim().slice(0, 80);
    const vis = (el: Element) => {
      const r = (el as HTMLElement).getBoundingClientRect();
      return (el as HTMLElement).offsetParent !== null && r.width > 2 && r.height > 2;
    };
    const sel = 'a, button, input, textarea, select, [role="button"], [role="link"], [role="combobox"], [role="checkbox"], [role="radio"], [contenteditable="true"]';
    const els = Array.from(document.querySelectorAll(sel)).filter(vis);
    const lines: string[] = [];
    let n = 0;
    for (const el of els.slice(0, 70)) {
      const tag = el.tagName.toLowerCase();
      const itype = ((el as HTMLInputElement).type || "").toLowerCase();
      if (tag === "input" && ["hidden", "submit", "button", "image", "reset"].includes(itype)) {
        // surface submit buttons in the snapshot as read-only context (not actionable)
      }
      const ref = `e${n}`;
      el.setAttribute("data-co-ref", ref);
      const role = el.getAttribute("role") || (tag === "a" ? "link" : tag);
      const label = clean(el.getAttribute("aria-label") || (el as HTMLInputElement).placeholder || el.textContent || (el as HTMLInputElement).value || (el as HTMLInputElement).name);
      const kind = tag === "input" ? itype || "text" : tag === "a" ? "link" : tag === "select" ? "select" : tag === "textarea" ? "textarea" : role;
      lines.push(`[${ref}] ${kind} "${label}"`);
      n++;
    }
    return { text: lines.join("\n"), n };
  });
}

/** One planner turn (Claude-first: --resume keeps the loop's context cheaply). */
function plannerTurn(binPath: string, prompt: string, resumeId: string | null): Promise<{ out: string; sessionId: string | null }> {
  const base = resumeId ? ["-p", "--resume", resumeId, prompt] : ["-p", prompt];
  const args = [...base, "--output-format", "json", "--strict-mcp-config", "--disallowedTools", "Bash,Read,Write,Edit,NotebookEdit,Task,WebFetch,WebSearch,Glob,Grep"];
  return new Promise((resolve) => {
    const child = spawnHeadlessCli(binPath, args, { cwd: careerOpsRoot(), env: process.env });
    let buf = "";
    child.stdout.on("data", (d: Buffer) => (buf += d.toString()));
    child.stderr.on("data", () => {});
    const killer = setTimeout(() => {
      try {
        child.kill("SIGTERM");
      } catch {
        /* ignore */
      }
    }, 90_000);
    child.on("close", () => {
      clearTimeout(killer);
      let out = buf;
      let sessionId: string | null = null;
      try {
        const j = JSON.parse(buf);
        out = j.result ?? buf;
        sessionId = j.session_id ?? null;
      } catch {
        /* non-json (other CLI) → use raw */
      }
      resolve({ out, sessionId });
    });
    child.on("error", () => {
      clearTimeout(killer);
      resolve({ out: buf, sessionId: null });
    });
  });
}

type Action = { action: string; ref?: string; text?: string; value?: string; reason?: string };

function parseAction(out: string): Action | null {
  const m = out.match(/\{[\s\S]*?\}/);
  if (!m) return null;
  try {
    return JSON.parse(m[0]);
  } catch {
    return null;
  }
}

/** Drive the page agentically toward the application form (hybrid) or through it
 *  (full). `isFormReady` lets the caller stop the loop the moment a fillable form
 *  appears (hybrid hand-back). `emit` streams each step to the UI. */
export async function driveSession(
  page: Page,
  cliId: string,
  goal: "reach" | "full",
  isFormReady: () => Promise<boolean>,
  emit: (s: DriveStep) => void,
  budget = 10,
  answers?: { label: string; value: string }[],
): Promise<DriveResult> {
  const resolved = resolveCli(cliId);
  const steps: DriveStep[] = [];
  if (!resolved || cliId !== "claude") {
    return { reached: false, turns: 0, reason: "Agentic drive currently needs Claude Code (browser-driving CLI).", steps };
  }
  const shot = async () => {
    try {
      return `data:image/jpeg;base64,${(await page.screenshot({ type: "jpeg", quality: 38 })).toString("base64")}`;
    } catch {
      return undefined;
    }
  };
  const answersBlock = (answers ?? []).filter((a) => a.value?.trim()).map((a) => `- "${a.label}": ${a.value.replace(/\s+/g, " ").slice(0, 300)}`).join("\n");
  const goalText =
    goal === "reach"
      ? `Your goal: navigate to the actual fillable JOB APPLICATION form (click 'Apply', pass any interstitial/pre-screen, reach the page with the Name/Email/Resume fields). Do NOT fill anything yet. Reply {"action":"reached_form"} once the form with those fields is visible.`
      : `Your goal: FILL this job application with the candidate's answers below, matching each answer to its field by label, across all pages (click 'Next'/'Continue' between pages). Skip any field already correctly filled, and skip file-uploads (handled separately). NEVER submit — when everything is filled and you're on the final page, reply {"action":"done"}.
ANSWERS (match by the field's label):
${answersBlock || "(no answers provided — just reach/observe)"}`;
  let resumeId: string | null = null;
  let lastUrl = page.url();

  const stopVerb = goal === "reach" ? '{"action":"reached_form"}            STOP — the fillable application form is now visible' : '{"action":"done"}                    STOP — every answer is filled (you NEVER submit; the human does)';
  for (let turn = 1; turn <= budget; turn++) {
    if (goal === "reach" && (await isFormReady().catch(() => false))) return { reached: true, turns: turn - 1, reason: "form-reached", steps };
    await dropNewTabs(page); // any "Apply" link/popup navigates in OUR tab, not a new one
    const frame = page.mainFrame();
    const snap = await snapshot(frame).catch(() => ({ text: "", n: 0 }));
    const prompt =
      turn === 1
        ? `You are an agent driving a real web browser for a job seeker (we execute your actions; the human submits at the end). ${goalText}
You NEVER submit a form — there is no submit action; the human does that.
Reply with EXACTLY ONE action as a JSON object, nothing else:
  {"action":"click","ref":"e3"}            click an element
  {"action":"type","ref":"e4","text":"…"}  type into a field
  {"action":"select","ref":"e9","value":"…"} pick an option
  {"action":"scroll"}                        scroll down to reveal more
  ${stopVerb}
  {"action":"stuck","reason":"…"}            you can't proceed (login/captcha/dead-end)

Page: "${await page.title().catch(() => "")}" (${page.url()})
Elements:
${snap.text}`
        : `New page state after your last action.
Page: "${await page.title().catch(() => "")}" (${page.url()})
Elements:
${snap.text}

Reply ONE action JSON.`;

    const { out, sessionId } = await plannerTurn(resolved.binPath, prompt, resumeId);
    if (sessionId) resumeId = sessionId;
    const act = parseAction(out);
    if (!act) {
      const s: DriveStep = { turn, action: "parse-error", detail: out.slice(0, 80), thumb: await shot() };
      steps.push(s);
      emit(s);
      continue;
    }

    if (act.action === "reached_form") return { reached: true, turns: turn, reason: "agent-reached", steps };
    if (act.action === "done") return { reached: true, turns: turn, reason: "agent-done", steps };
    if (act.action === "stuck") {
      const s: DriveStep = { turn, action: "stuck", detail: act.reason || "", thumb: await shot() };
      steps.push(s);
      emit(s);
      return { reached: false, turns: turn, reason: act.reason || "stuck", steps };
    }

    // execute the action on OUR session — NEVER submit.
    let detail = "";
    let note = "";
    try {
      const loc = act.ref ? frame.locator(`[data-co-ref="${act.ref}"]`).first() : null;
      if (act.action === "click" && loc) {
        const txt = (await loc.innerText().catch(() => "")) || (await loc.getAttribute("value").catch(() => "")) || "";
        if (SUBMIT_RX.test(txt)) {
          note = "refused to click a submit control (the human submits)";
          detail = `blocked submit "${txt.slice(0, 40)}"`;
        } else {
          detail = `click "${txt.slice(0, 40)}"`;
          await loc.scrollIntoViewIfNeeded().catch(() => {});
          await Promise.all([page.waitForLoadState("domcontentloaded", { timeout: 8000 }).catch(() => {}), loc.click({ timeout: 6000 })]);
        }
      } else if (act.action === "type" && loc) {
        detail = `type into ${act.ref}`;
        await loc.fill(act.text || "").catch(async () => {
          await loc.click();
          await page.keyboard.type(act.text || "");
        });
      } else if (act.action === "select" && loc) {
        detail = `select "${act.value}"`;
        await loc.selectOption({ label: act.value || "" }).catch(() => loc.selectOption(act.value || ""));
      } else if (act.action === "scroll") {
        detail = "scroll";
        await page.evaluate(() => window.scrollBy(0, 700)).catch(() => {});
      } else {
        detail = `unknown action ${act.action}`;
      }
    } catch (e) {
      detail = `${act.action} failed: ${e instanceof Error ? e.message.slice(0, 50) : "err"}`;
    }
    await page.waitForTimeout(700);
    const s: DriveStep = { turn, action: act.action, detail, thumb: await shot(), note: note || undefined };
    steps.push(s);
    emit(s);
    lastUrl = page.url();
    void lastUrl;
  }
  return { reached: await isFormReady().catch(() => false), turns: budget, reason: "budget-exhausted", steps };
}

// The Apply page's two exit decisions (#2734), kept out of the component so
// every branch is testable: whether leaving would lose work, and where "back"
// actually goes.

/** Where back goes when the session recorded no origin (a pasted form URL). */
export const DEFAULT_RETURN_PATH = "/pipeline";

/** Statuses where a step is running that leaving would interrupt. */
const IN_FLIGHT = new Set(["opening", "driving", "prefilling", "filling"]);

/**
 * Should leaving the Apply page ask first?
 *
 * Yes once there is something to lose: an answer with content, or a step still
 * running. A form that was read but never touched backs out in one click, so
 * the confirm stays meaningful instead of becoming something to click through.
 */
export function needsLeaveConfirmation({ status, answers } = {}) {
  if (IN_FLIGHT.has(status)) return true;
  return Object.values(answers ?? {}).some((v) => typeof v === "string" && v.trim() !== "");
}

/**
 * Resolve where back goes, from the origin the apply session recorded.
 *
 * Only a local app path is honoured. Anything that would leave the app, and the
 * Apply page itself (which would reload rather than exit), falls back to the
 * tracker.
 */
export function resolveReturnPath(from) {
  if (typeof from !== "string") return DEFAULT_RETURN_PATH;
  const path = from.trim();
  if (!path.startsWith("/")) return DEFAULT_RETURN_PATH;
  // "//host" and "/\host" are protocol-relative in browsers, not local paths.
  if (path.startsWith("//") || path.startsWith("/\\")) return DEFAULT_RETURN_PATH;
  // A trailing slash reaches the same route, so it has to be refused too.
  const pathname = path.split(/[?#]/, 1)[0].replace(/\/+$/, "");
  if (pathname === "/apply") return DEFAULT_RETURN_PATH;
  return path;
}

/**
 * What to do with an apply-session result that arrived after the user left.
 *
 * Leaving mid-open is now reachable (Back works while the form is still
 * opening), and the request in flight cannot be recalled. A stale result must
 * not repopulate the page the user walked away from, and if it opened a session
 * anyway that session has to be closed here: nothing else holds its id, so the
 * headless browser behind it would keep running.
 *
 * @returns {"apply"|"close"|"discard"}
 */
export function resolveLateSession({ stale, sessionId } = {}) {
  if (!stale) return "apply";
  return sessionId ? "close" : "discard";
}

import type { Page, Frame } from "playwright-core";

export type ApplyField = {
  id: string; // our stable handle, also set as data-co-field on the live element
  type: "text" | "email" | "tel" | "url" | "number" | "date" | "textarea" | "select" | "checkbox" | "radio" | "file";
  label: string;
  required: boolean;
  options?: string[];
  maxLength?: number;
  value?: string;
  combobox?: boolean; // react-select-style widget → fill via click+type+Enter, not selectOption
  nativeId?: string; // the live element's id/name — used to match ATS API schemas (Greenhouse)
  nativeName?: string;
};

export type ExtractedForm = { title: string; url: string; fields: ApplyField[] };

// Extract the application form's STRUCTURE (not pixels) and TAG each control with
// a stable `data-co-field` id on the LIVE page (which the session keeps open), so
// the later fill phase can locate each field deterministically. Generic DOM/a11y
// introspection — clean ATS (Ashby/Lever/Greenhouse) work well; Workday best-effort.
export async function extractForm(ctx: Page | Frame): Promise<ExtractedForm> {
  const data = await ctx.evaluate(() => {
    const clean = (s: string | null | undefined) => (s || "").replace(/\s+/g, " ").trim().slice(0, 160);
    const isUuid = (s: string) => /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s.trim());
    // generic placeholders that masquerade as labels (Ashby/react-select)
    const isGenericPh = (s: string) => /^(start typing|select\b|choose|search\b|type\b|--|please select|e\.?g\.?)/i.test(s.trim());
    // a usable label: not empty, not a UUID, not a generic placeholder
    const ok = (s: string | null | undefined) => {
      const t = (s || "").trim();
      return t && !isUuid(t) && !isGenericPh(t) ? t : "";
    };
    // Pure label text: a wrapping <label>Gender<select>…</select></label> would
    // otherwise swallow all option text (Lever). Strip controls/options first.
    const pure = (node: Element | null): string => {
      if (!node) return "";
      const c = node.cloneNode(true) as Element;
      c.querySelectorAll?.("input, select, textarea, option, button, [role=option], [class*='menu' i]").forEach((n) => n.remove());
      return clean(c.textContent);
    };

    // The field WRAPPER (Ashby `ashby-application-form-field-entry`, Greenhouse
    // `select__container`/`field`, generic `form-group`/`fieldset`) — deliberately
    // NOT a bare `div` (that matches the immediate parent and misses the real label
    // which lives one wrapper up).
    function fieldGroup(el: Element): Element | null {
      return el.closest(
        '[class*="field-entry" i], [class*="fieldEntry" i], [class*="form-group" i], [class*="question" i], [class*="field__" i], [class*="__field" i], fieldset, [class*="field" i]',
      );
    }

    function labelFor(el: Element): string {
      const aria = el.getAttribute("aria-label");
      if (ok(aria)) return aria!;
      const labelledby = el.getAttribute("aria-labelledby");
      if (labelledby) {
        const t = labelledby.split(/\s+/).map((id) => document.getElementById(id)?.textContent || "").join(" ");
        if (ok(t)) return t;
      }
      const id = (el as HTMLElement).id;
      if (id) {
        const l = document.querySelector(`label[for="${CSS.escape(id)}"]`);
        if (l && ok(pure(l))) return pure(l);
      }
      const parentLabel = el.closest("label");
      if (parentLabel && ok(pure(parentLabel))) return pure(parentLabel);
      // the question title inside the field wrapper (handles Ashby's
      // `ashby-application-form-question-title`, Greenhouse `select__label`, etc.)
      const grp = fieldGroup(el);
      if (grp) {
        const lab = grp.querySelector(
          'label, legend, [class*="question-title" i], [class*="heading" i], [class*="label" i], [class*="title" i]',
        );
        if (lab && ok(pure(lab))) return pure(lab);
      }
      // walk up a few ancestors for a nearby label/heading
      let c: Element | null = el.parentElement;
      for (let i = 0; i < 4 && c; i++, c = c.parentElement) {
        const lab = c.querySelector('label, legend, [class*="label" i], [class*="title" i], h3, h4, h5');
        if (lab && ok(pure(lab))) return pure(lab);
      }
      const ph = (el as HTMLInputElement).placeholder;
      if (ok(ph)) return ph;
      const name = (el as HTMLInputElement).name;
      return ok(name); // never a UUID/placeholder; "" → caller shows "Untitled"
    }

    // The QUESTION of a radio group — NOT the first option's label. Look for a
    // radiogroup/fieldset aria-label/legend, else the first label/heading in the
    // group's container that isn't one of the options.
    function groupLabel(firstRadio: Element, options: string[]): string {
      const rg = firstRadio.closest("[role=radiogroup], fieldset");
      if (rg) {
        const al = rg.getAttribute("aria-label");
        if (al) return al;
        const lb = rg.getAttribute("aria-labelledby");
        if (lb) {
          const t = lb.split(/\s+/).map((id) => document.getElementById(id)?.textContent || "").join(" ");
          if (t.trim()) return t;
        }
        const legend = rg.querySelector("legend");
        if (legend?.textContent?.trim()) return legend.textContent;
      }
      const optSet = new Set(options.map((o) => o.toLowerCase()));
      const container = fieldGroup(firstRadio) || firstRadio.parentElement?.parentElement || firstRadio.parentElement;
      if (container) {
        const cands = container.querySelectorAll(
          'label, legend, h1, h2, h3, h4, h5, h6, [class*="question-title" i], [class*="heading" i], [class*="label" i], [class*="title" i], [class*="question" i]',
        );
        for (const c of Array.from(cands)) {
          const t = pure(c);
          if (t && t.length > 2 && t.length < 160 && !optSet.has(t.toLowerCase()) && !isUuid(t) && !isGenericPh(t)) return t;
        }
      }
      return "";
    }

    const fields: Array<Record<string, unknown>> = [];
    const seenRadio = new Set<string>();
    const els = Array.from(document.querySelectorAll("input, textarea, select"));
    let n = 0;

    for (const el of els) {
      const tag = el.tagName.toLowerCase();
      const itype = ((el as HTMLInputElement).type || "").toLowerCase();
      if (tag === "input" && ["hidden", "submit", "button", "image", "reset"].includes(itype)) continue;
      if ((el as HTMLElement).offsetParent === null && itype !== "radio" && itype !== "checkbox") continue;
      // skip ATS "autofill from resume / parse my CV" helper widgets (Ashby) — these
      // are convenience uploaders, not real application fields.
      if ((el as Element).closest('[class*="autofill" i]')) continue;

      // react-select widgets render an extra internal/autosize <input> next to the
      // real role=combobox input. Keep ONLY the combobox; drop the dummy (it's the
      // "Untitled field" noise). The combobox carries the question's aria label.
      const inReactSelect = (el as Element).closest('[class*="select__"], .select-shell');
      const isCombobox = el.getAttribute("role") === "combobox";
      if (inReactSelect && tag === "input" && !isCombobox) continue;

      const required = (el as HTMLInputElement).required || el.getAttribute("aria-required") === "true";
      const nativeId = (el as HTMLElement).id || undefined;
      const nativeName = (el as HTMLInputElement).name || undefined;
      const fid = `co${n++}`;

      if (isCombobox) {
        el.setAttribute("data-co-field", fid);
        fields.push({ id: fid, type: "select", combobox: true, label: clean(labelFor(el)), required, options: [], nativeId, nativeName });
        continue;
      }

      if (itype === "radio") {
        const name = (el as HTMLInputElement).name;
        if (name && seenRadio.has(name)) {
          n--;
          continue;
        }
        if (name) seenRadio.add(name);
        const group = Array.from(document.querySelectorAll(`input[type=radio][name="${CSS.escape(name)}"]`));
        const options = group.map((r) => clean(labelFor(r) || (r as HTMLInputElement).value)).filter(Boolean);
        group.forEach((r, i) => {
          r.setAttribute("data-co-field", fid);
          r.setAttribute("data-co-option", options[i] ?? String(i));
        });
        fields.push({ id: fid, type: "radio", label: clean(groupLabel(el, options)) || name, required, options });
        continue;
      }

      el.setAttribute("data-co-field", fid);

      if (tag === "select") {
        const options = Array.from((el as HTMLSelectElement).options).map((o) => clean(o.textContent)).filter((o) => o && !/^(select|choose|--)/i.test(o));
        fields.push({ id: fid, type: "select", label: clean(labelFor(el)), required, options, nativeId, nativeName });
        continue;
      }
      const type = tag === "textarea" ? "textarea" : ["email", "tel", "url", "number", "date", "checkbox", "file"].includes(itype) ? itype : "text";
      const ml = (el as HTMLInputElement).maxLength;
      fields.push({
        id: fid,
        type,
        label: clean(labelFor(el)),
        required,
        maxLength: ml && ml > 0 ? ml : undefined,
        value: (el as HTMLInputElement).value || undefined,
        nativeId,
        nativeName,
      });
    }
    return { title: document.title, fields };
  });

  return { title: data.title, url: ctx.url(), fields: data.fields as ApplyField[] };
}

// Greenhouse job-board forms render their select questions as react-select
// comboboxes (no native <select>, options live in a portal) — so generic DOM
// extraction can't read their options. But Greenhouse exposes the full question
// schema publicly, and each question's `name` equals the DOM element id. We use
// it to enrich extraction with clean labels, correct types, and real options.

export type GhField = { label: string; type: string; required: boolean; options: string[] };

/** Parse a Greenhouse job-board URL → {token, jobId}, else null. */
export function parseGreenhouse(url: string): { token: string; jobId: string } | null {
  try {
    const u = new URL(url);
    if (!/(^|\.)greenhouse\.io$/i.test(u.hostname)) return null;
    // .../{token}/jobs/{id}  (job-boards.greenhouse.io or boards.greenhouse.io)
    const m = u.pathname.match(/\/([^/]+)\/jobs\/(\d+)/);
    if (m) return { token: m[1], jobId: m[2] };
    // embed form: boards.greenhouse.io/embed/job_app?for={token}&token={id}
    const forToken = u.searchParams.get("for");
    const jobId = u.searchParams.get("token");
    if (forToken && jobId) return { token: forToken, jobId };
    return null;
  } catch {
    return null;
  }
}

const GH_TYPE: Record<string, GhField["type"]> = {
  input_text: "text",
  textarea: "textarea",
  input_file: "file",
  multi_value_single_select: "select",
  multi_value_multi_select: "select",
  multi_select: "select",
  single_select: "select",
  boolean: "select",
};

/** Fetch the public Greenhouse question schema → map keyed by BOTH the field
 *  `name` (== DOM id, e.g. "question_123") and the human label (lowercased), so
 *  extraction can match whichever it has. Returns null on any failure (we then
 *  just keep the generic DOM extraction). */
export async function fetchGreenhouseSchema(token: string, jobId: string): Promise<Map<string, GhField> | null> {
  try {
    const r = await fetch(`https://boards-api.greenhouse.io/v1/boards/${encodeURIComponent(token)}/jobs/${encodeURIComponent(jobId)}?questions=true`, {
      headers: { Accept: "application/json" },
      signal: AbortSignal.timeout(8000),
    });
    if (!r.ok) return null;
    const data = (await r.json()) as { questions?: Array<{ label?: string; required?: boolean; fields?: Array<{ name?: string; type?: string; values?: Array<{ label?: string }> }> }> };
    const map = new Map<string, GhField>();
    for (const q of data.questions ?? []) {
      const label = (q.label ?? "").replace(/\s*\*+\s*$/, "").trim();
      for (const f of q.fields ?? []) {
        if (!f.name) continue;
        const gf: GhField = {
          label,
          type: GH_TYPE[f.type ?? ""] ?? "text",
          required: !!q.required,
          options: (f.values ?? []).map((v) => (v.label ?? "").trim()).filter(Boolean),
        };
        map.set(f.name, gf);
        if (label) map.set(`label:${label.toLowerCase()}`, gf);
      }
    }
    return map.size ? map : null;
  } catch {
    return null;
  }
}

// Client-safe (no playwright import). A structured, user-facing problem the
// interpreter hit, so the apply UI NEVER fails mute.
//   block = can't proceed (captcha / login wall / expired posting)
//   warn  = proceeded, but the user should look (unread field, validation error)
//   info  = FYI (we auto-dismissed a cookie banner)
export type ApplyIssue = { level: "block" | "warn" | "info"; code: string; message: string; field?: string };

// One step of the agentic drive loop (the AI reaching/filling the form live).
export type DriveStep = { turn: number; action: string; detail: string; thumb?: string; note?: string };

import { chromium, type Browser, type BrowserContext, type Page, type Frame, type Response } from "playwright-core";
import { extractForm, type ApplyField, type ExtractedForm } from "./extract";
import { parseGreenhouse, fetchGreenhouseSchema } from "./greenhouse";
import { statusBlock, dismissConsent, tryApplyTrigger, dropNewTabs, classifyEmpty, captchaWarning, multiStepInfo, verifyFill, type ApplyIssue } from "./diagnose";
import { agentInterpretForm } from "./agent-interpret";

/** The frame with the most interactive controls — where the agentic interpreter
 *  should look when deterministic extraction found nothing usable. */
async function richestControlFrame(page: Page): Promise<Frame> {
  let best = page.mainFrame();
  let bestN = -1;
  for (const fr of page.frames()) {
    const n = await fr.evaluate(() => document.querySelectorAll('input, textarea, select, [role="combobox"], [contenteditable="true"]').length).catch(() => 0);
    if (n > bestN) {
      bestN = n;
      best = fr;
    }
  }
  return best;
}

/** Escape a value for use inside a double-quoted CSS attribute selector.
 *  Backslash FIRST, then quote — escaping only the quote would let a trailing
 *  backslash neutralize the closing quote (CodeQL js/incomplete-sanitization). */
function cssAttr(v: string): string {
  return v.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

/** Navigate resiliently: a transient nav error / slow ATS shouldn't fail the
 *  whole apply. Up to 3 attempts with backoff; returns the navigation Response
 *  (status/headers feed the cheap status-block check). */
async function gotoResilient(page: Page, url: string): Promise<Response | null> {
  let lastErr: unknown;
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      const resp = await page.goto(url, { waitUntil: "domcontentloaded", timeout: 30_000 });
      await page.waitForLoadState("load", { timeout: 8_000 }).catch(() => {});
      return resp;
    } catch (e) {
      lastErr = e;
      await page.waitForTimeout(800 * (attempt + 1));
    }
  }
  throw lastErr instanceof Error ? lastErr : new Error("could not open the page");
}

/** Distinguish a real APPLICATION form from a careers-listing / job-search form
 *  (a closed Greenhouse posting redirects to the board, whose keyword/department
 *  filters would otherwise look like a fillable form). */
function looksLikeApplicationForm(form: ExtractedForm): boolean {
  const fs = form.fields;
  if (fs.length === 0) return false;
  const lab = (f: ApplyField) => (f.label || "").toLowerCase();
  const hasFile = fs.some((f) => f.type === "file");
  const hasEmail = fs.some((f) => f.type === "email" || /e-?mail/.test(lab(f)));
  const hasAppish = fs.some((f) => /first name|last name|full name|resume|résumé|\bcv\b|cover letter|phone|linkedin|github|why |portfolio|sponsorship|relocat/.test(lab(f)));
  if (hasFile || hasEmail || hasAppish) return true; // clearly an application
  const allSearch = fs.every(
    (f) => /search|buscar|filtr|keyword|palabra|department|departa|office|oficina|location|ubicaci|remote|category|categor/.test(lab(f)) || /filter|search|keyword/.test((f.nativeId || "").toLowerCase()),
  );
  if (allSearch) return false; // a job-board search/filter form
  if (fs.length <= 3 && fs.every((f) => !f.required)) return false; // too sparse + all optional = not an app form
  return true;
}

/** ATS forms are often embedded in an <iframe> on a company career site
 *  (greenhouse/lever/smartrecruiters embeds), sometimes cross-origin — the main
 *  frame then has 0 fields. Extract from EVERY frame and keep the richest one. */
async function pickFormFrame(page: Page): Promise<{ frame: Frame; form: ExtractedForm }> {
  let best: { frame: Frame; form: ExtractedForm } = {
    frame: page.mainFrame(),
    form: { title: "", url: page.url(), fields: [] },
  };
  for (const fr of page.frames()) {
    try {
      const form = await extractForm(fr);
      if (form.fields.length > best.form.fields.length) best = { frame: fr, form };
    } catch {
      /* detached / cross-origin restriction → skip */
    }
  }
  // Prefer the main frame's title (the posting title) when an iframe won the form.
  if (best.frame !== page.mainFrame() && !best.form.title) best.form.title = await page.title().catch(() => best.form.title);
  return best;
}

/** Enrich generically-extracted fields with an ATS's published schema (clean
 *  labels, correct types, real options) — Greenhouse renders react-select
 *  widgets whose options aren't in the DOM. Matched by native id/name, then label. */
async function enrichFromAts(url: string, fields: ApplyField[]): Promise<void> {
  const gh = parseGreenhouse(url);
  if (!gh) return;
  const schema = await fetchGreenhouseSchema(gh.token, gh.jobId);
  if (!schema) return;
  for (const f of fields) {
    const hit =
      (f.nativeName && schema.get(f.nativeName)) ||
      (f.nativeId && schema.get(f.nativeId)) ||
      (f.label && schema.get(`label:${f.label.toLowerCase()}`));
    if (!hit) continue;
    if (hit.label) f.label = hit.label;
    if (hit.type) f.type = hit.type as ApplyField["type"];
    if (hit.options.length) f.options = hit.options;
    if (hit.required) f.required = true;
    if (hit.type === "select") f.combobox = true;
  }
}

// A persistent apply SESSION keeps one real-form page open (headed-but-off-screen)
// so we can: extract → (user verifies pre-filled answers) → FILL the real form →
// bringToFront() for the human to submit it themselves. Headed (channel:chrome) =
// the user's own Chrome on their residential IP (best ATS success); never submits.
type Session = { id: string; url: string; title: string; fields: ApplyField[]; context: BrowserContext; page: Page; frame: Frame; createdAt: number; formShot?: string };

declare global {
  // eslint-disable-next-line no-var
  var __coApplySessions: Map<string, Session> | undefined;
  // eslint-disable-next-line no-var
  var __coHeadedBrowser: Browser | undefined;
  // eslint-disable-next-line no-var
  var __coIdleTimer: ReturnType<typeof setTimeout> | undefined;
}
const SESSIONS: Map<string, Session> = (globalThis.__coApplySessions ??= new Map());

async function headedBrowser(): Promise<Browser> {
  const b = globalThis.__coHeadedBrowser;
  if (b && b.isConnected()) return b;
  let nb: Browser;
  try {
    nb = await chromium.launch({
      channel: "chrome",
      headless: false,
      args: ["--window-position=-3200,-3200", "--window-size=1280,940"], // off-screen during fill; moved on-screen at handoff
    });
  } catch {
    // No system Google Chrome → fall back to Playwright's bundled Chromium if
    // present; otherwise a clear, actionable error.
    try {
      nb = await chromium.launch({ headless: false, args: ["--window-position=-3200,-3200", "--window-size=1280,940"] });
    } catch {
      throw new Error("The apply feature needs Google Chrome. Install Chrome (or run: npx playwright install chromium) and try again.");
    }
  }
  globalThis.__coHeadedBrowser = nb;
  return nb;
}

/** Close the headed Chrome once no sessions have been active for a while, so we
 *  don't leak a browser process. Re-armed on every prune/close; cancelled on open. */
function scheduleIdleClose() {
  if (globalThis.__coIdleTimer) clearTimeout(globalThis.__coIdleTimer);
  globalThis.__coIdleTimer = setTimeout(() => {
    if (SESSIONS.size === 0) {
      const b = globalThis.__coHeadedBrowser;
      globalThis.__coHeadedBrowser = undefined;
      void b?.close().catch(() => {});
    }
  }, 5 * 60_000);
}

function prune() {
  const now = Date.now();
  for (const [id, s] of SESSIONS) if (now - s.createdAt > 15 * 60_000) void closeSession(id);
}

/** Bounded scroll pass to trigger lazy/virtualized forms that only render their
 *  fields once scrolled into view, then return to the top. */
async function nudgeScroll(page: Page): Promise<void> {
  for (let i = 1; i <= 3; i++) {
    await page.evaluate((y) => window.scrollTo(0, y), i * 1200).catch(() => {});
    await page.waitForTimeout(250);
  }
  await page.evaluate(() => window.scrollTo(0, 0)).catch(() => {});
}

export async function openSession(url: string, cliId?: string, forceAgent?: boolean, noApplyBtn?: boolean): Promise<{ id: string; title: string; fields: ApplyField[]; shots: string[]; issues: ApplyIssue[]; needsDrive?: boolean }> {
  prune();
  if (globalThis.__coIdleTimer) clearTimeout(globalThis.__coIdleTimer); // someone's active
  const browser = await headedBrowser();
  const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
  context.setDefaultTimeout(8000); // no single action hangs the whole open/fill
  const page = await context.newPage();
  const abort = async (msg: string): Promise<never> => {
    await context.close().catch(() => {});
    if (SESSIONS.size === 0) scheduleIdleClose();
    throw new Error(msg);
  };
  // Capture the real form as we read it → a "behind the scenes" progress strip
  // that proves we genuinely opened + parsed THEIR form (not magic). The last
  // shot doubles as a subtle blurred backdrop behind the clean proxy.
  const shots: string[] = [];
  const snap = async () => {
    try {
      const b = await page.screenshot({ type: "jpeg", quality: 42 });
      shots.push(`data:image/jpeg;base64,${b.toString("base64")}`);
    } catch {
      /* ignore */
    }
  };
  // 1) Navigate (resilient) → cheapest hard-block check on the Response status.
  const resp = await gotoResilient(page, url);
  await snap(); // first paint
  const sBlock = statusBlock(resp?.status(), resp ? resp.headers() : {});
  if (sBlock) return abort(sBlock.message);

  // 2) Clear any cookie/consent overlay that hides the form (never a hard block).
  const consentIssues = await dismissConsent(page);

  // 3) Wait for real form controls to render (SPA hydrate) in ANY frame (embedded
  //    forms), then settle. More reliable than a fixed sleep.
  const formSel = 'form input, form textarea, input[type=file], [role=combobox], [class*="application-form" i], #application_form';
  await Promise.race(page.frames().map((f) => f.waitForSelector(formSel, { timeout: 12_000 }).catch(() => null))).catch(() => {});
  await page.waitForTimeout(1200);
  await dropNewTabs(page); // make any "Apply" link/popup navigate in OUR tab
  await snap(); // settled

  // 4) Extract from the richest frame; if nothing yet, try (a) a scroll pass to
  //    trigger lazy/virtualized fields, then (b) clicking an "Apply" button (SPA;
  //    never a submit) — re-settling and re-extracting after each.
  let { frame, form } = await pickFormFrame(page);
  // "no usable form yet" = 0 fields OR only non-application fields (e.g. a search
  // box on a job-description page) — both should trigger the recovery, not just 0.
  if (!looksLikeApplicationForm(form)) {
    await nudgeScroll(page);
    await page.waitForTimeout(400);
    ({ frame, form } = await pickFormFrame(page));
  }
  if (!noApplyBtn && !looksLikeApplicationForm(form) && (await tryApplyTrigger(page))) {
    await Promise.race(page.frames().map((f) => f.waitForSelector(formSel, { timeout: 6_000 }).catch(() => null))).catch(() => {});
    await page.waitForTimeout(800);
    await dropNewTabs(page);
    ({ frame, form } = await pickFormFrame(page));
    await snap();
  }
  await enrichFromAts(url, form.fields); // clean labels + real options for known ATS (Greenhouse)
  await snap();

  let aiInterpreted = false;
  // Opt-in: ALWAYS interpret with AI (max robustness, ignores the deterministic
  // result) — for users who'd rather pay tokens than risk a heuristic miss.
  if (forceAgent && cliId) {
    const aiFrame = await richestControlFrame(page);
    const aiFields = await agentInterpretForm(aiFrame, cliId, form.title || (await page.title().catch(() => ""))).catch(() => [] as ApplyField[]);
    if (aiFields.length) {
      frame = aiFrame;
      form = { ...form, fields: aiFields };
      aiInterpreted = true;
      await snap();
    }
  }

  // 5) Deterministic extraction found no usable APPLICATION form. Classify WHY
  //    first — then run the AGENTIC FALLBACK only for the genuinely AMBIGUOUS
  //    "no-form" case (controls are present but our heuristics produced nothing).
  //    A challenge/login/listing/expired/Workday page has no form to interpret,
  //    so we abort directly with the right message (no wasted AI run).
  if (!aiInterpreted && !looksLikeApplicationForm(form)) {
    const why = await classifyEmpty(page, url);
    // Driveable (controls present, not a hard block) + we have an agent → KEEP the
    // session open and hand off to the STREAMED drive route, so the user watches
    // the agent reach the form live (/api/apply/drive). Otherwise abort.
    if (cliId && why.code === "no-form") {
      const id = `apply-${crypto.randomUUID()}`;
      const title = form.title || (await page.title().catch(() => "")) || "Application";
      SESSIONS.set(id, { id, url, title, fields: [], context, page, frame, createdAt: Date.now(), formShot: shots[shots.length - 1] });
      return { id, title, fields: [], shots, issues: [], needsDrive: true };
    }
    return abort(why.message);
  }

  // 6) Soft issues the user should know about — surfaced, never silent.
  const [cap, multi] = await Promise.all([captchaWarning(page), multiStepInfo(page)]);
  const unlabeled = form.fields.filter((f) => !(f.label || "").trim()).length;
  const issues: ApplyIssue[] = [...consentIssues];
  if (cap) issues.push(cap);
  if (multi) issues.push(multi);
  if (aiInterpreted) issues.push({ level: "info", code: "ai-interpreted", message: "This form had an uncommon layout, so AI read its fields live — give them an extra check before submitting." });
  if (unlabeled > 0) issues.push({ level: "warn", code: "unlabeled-fields", message: `${unlabeled} field${unlabeled > 1 ? "s" : ""} couldn't be labelled cleanly — double-check ${unlabeled > 1 ? "them" : "it"} before submitting.` });

  const id = `apply-${crypto.randomUUID()}`;
  SESSIONS.set(id, { id, url, title: form.title, fields: form.fields, context, page, frame, createdAt: Date.now(), formShot: shots[shots.length - 1] });
  return { id, title: form.title, fields: form.fields, shots, issues };
}

export function getSession(id: string): Session | undefined {
  return SESSIONS.get(id);
}

/** Open a bare headed page on a URL (for the agentic drive loop / validation),
 *  without the full extract pipeline. Caller must close the context. */
export async function newDrivePage(url: string): Promise<{ page: Page; context: BrowserContext }> {
  if (globalThis.__coIdleTimer) clearTimeout(globalThis.__coIdleTimer);
  const browser = await headedBrowser();
  const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
  context.setDefaultTimeout(8000);
  const page = await context.newPage();
  await gotoResilient(page, url);
  await dismissConsent(page).catch(() => {});
  await page.waitForTimeout(1000);
  return { page, context };
}

/** Extract+enrich the current page (used after the drive loop reaches a form). */
export async function extractCurrent(page: Page, url: string): Promise<{ frame: Frame; form: ExtractedForm }> {
  const r = await pickFormFrame(page);
  await enrichFromAts(url, r.form.fields);
  return r;
}

export function isApplicationFormFn(form: ExtractedForm): boolean {
  return looksLikeApplicationForm(form);
}

/** After the streamed drive loop reaches a form, extract+enrich it (Tier-3
 *  interpret as a last resort), UPDATE the open session, and return the fields +
 *  issues. Returns null if no real application form materialised. */
export async function finalizeDrivenSession(id: string, cliId?: string): Promise<{ title: string; fields: ApplyField[]; issues: ApplyIssue[] } | null> {
  const s = SESSIONS.get(id);
  if (!s) return null;
  let { frame, form } = await pickFormFrame(s.page);
  await enrichFromAts(s.url, form.fields);
  let aiInterpreted = false;
  if (!looksLikeApplicationForm(form) && cliId) {
    const aiFrame = await richestControlFrame(s.page);
    const aiFields = await agentInterpretForm(aiFrame, cliId, form.title || s.title).catch(() => [] as ApplyField[]);
    if (aiFields.length && looksLikeApplicationForm({ title: form.title, url: form.url, fields: aiFields })) {
      frame = aiFrame;
      form = { ...form, fields: aiFields };
      aiInterpreted = true;
    }
  }
  if (!looksLikeApplicationForm(form)) return null;
  s.frame = frame;
  s.fields = form.fields;
  if (form.title) s.title = form.title;
  const issues: ApplyIssue[] = [{ level: "info", code: "ai-navigated", message: "AI navigated to reach this application form on your machine — review the fields before submitting." }];
  if (aiInterpreted) issues.push({ level: "info", code: "ai-interpreted", message: "AI also read the fields live (uncommon layout) — give them an extra check." });
  const cap = await captchaWarning(s.page);
  if (cap) issues.push(cap);
  return { title: s.title, fields: s.fields, issues };
}

export async function closeSession(id: string): Promise<void> {
  const s = SESSIONS.get(id);
  SESSIONS.delete(id);
  await s?.context.close().catch(() => {});
  if (SESSIONS.size === 0) scheduleIdleClose();
}

export type FillStep = { fieldId: string; label: string; ok: boolean; thumb?: string };

/** True for a file field that wants the candidate's résumé/CV (vs. cover letter,
 *  portfolio, or a generic attachment we leave for the user). */
function isResumeField(f: ApplyField): boolean {
  return f.type === "file" && /resume|résumé|\bcv\b|curriculum|lebenslauf|currículum/i.test(f.label || "");
}

/** Fill the real form with verified answers, screenshotting after each field.
 *  Attaches the tailored CV PDF to résumé/CV file fields (cvPath). NEVER clicks a
 *  submit/apply control — only fills/selects/checks/attaches. */
export async function fillSession(
  id: string,
  answers: Record<string, string>,
  fieldsMeta: ApplyField[],
  cvPath?: string,
): Promise<{ steps: FillStep[]; navigated: boolean; issues: ApplyIssue[] }> {
  const s = SESSIONS.get(id);
  if (!s) throw new Error("apply session not found (it may have expired)");
  const byId = new Map(fieldsMeta.map((f) => [f.id, f]));
  const steps: FillStep[] = [];
  // Belt-and-suspenders: if filling ever navigates the page (i.e. something got
  // submitted), the URL path changes. We never submit by construction, but we
  // report it so the caller can flag it instead of silently "succeeding".
  const startPath = (() => {
    try {
      return new URL(s.frame.url()).pathname;
    } catch {
      return s.frame.url();
    }
  })();

  const shoot = async () => {
    try {
      const buf = await s.page.screenshot({ type: "jpeg", quality: 38 });
      return `data:image/jpeg;base64,${buf.toString("base64")}`;
    } catch {
      return undefined;
    }
  };

  // 1) Attach the tailored CV to every résumé/CV file field (even with no text
  //    answer). The real <input type=file> was tagged data-co-field at extract
  //    time; setInputFiles works even when the ATS visually hides it behind a
  //    dropzone. Other file fields (cover letter, portfolio) are left to the user.
  if (cvPath) {
    for (const meta of fieldsMeta) {
      if (!isResumeField(meta)) continue;
      let ok = false;
      try {
        await s.frame.locator(`[data-co-field="${cssAttr(meta.id)}"]`).first().setInputFiles(cvPath);
        ok = true;
      } catch {
        // fallback: any file input inside the same field container
        try {
          await s.frame.locator(`input[type=file]`).first().setInputFiles(cvPath);
          ok = true;
        } catch {
          ok = false;
        }
      }
      steps.push({ fieldId: meta.id, label: `${meta.label || "Resume"} (CV attached)`, ok, thumb: await shoot() });
    }
  }

  for (const [fid, raw] of Object.entries(answers)) {
    const meta = byId.get(fid);
    const value = (raw ?? "").toString();
    if (!meta || value === "") continue;
    if (meta.type === "file") continue; // handled above (CV) — never auto-fill other uploads
    // Defense-in-depth: NEVER auto-tick a legal consent/agreement checkbox — the
    // human must affirmatively accept. (The planner already flags these
    // needs_confirmation; this guarantees it even if it slips.)
    if (meta.type === "checkbox" && /\b(i (have )?read|i agree|i consent|i accept|consent to|privacy notice|terms|gdpr|data protection)\b/i.test(meta.label || "")) {
      steps.push({ fieldId: fid, label: `${meta.label} — you confirm`, ok: false, thumb: undefined });
      continue;
    }
    let ok = false;
    let gaveUp = false;
    try {
      const loc = s.frame.locator(`[data-co-field="${cssAttr(fid)}"]`).first();
      if (meta.combobox) {
        // react-select: open, type to filter, CLICK the matching option. We never
        // press Enter — in a form, Enter can submit. Clicking an option can't.
        await loc.scrollIntoViewIfNeeded().catch(() => {});
        await loc.click();
        await s.page.waitForTimeout(150);
        await loc.pressSequentially(value, { delay: 15 }).catch(async () => {
          await s.page.keyboard.type(value);
        });
        await s.page.waitForTimeout(300);
        const esc = value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        const menu = '.select__menu .select__option, .select__menu-list [role="option"], [class*="menu" i] [role="option"]';
        const exact = s.frame.locator(menu).filter({ hasText: new RegExp(`^\\s*${esc}\\s*$`, "i") }).first();
        if (await exact.count()) {
          await exact.click();
        } else {
          // fall back to the first option that contains the typed text; else give
          // up (Escape closes the menu) — leave it for the human, never submit.
          const partial = s.frame.locator(menu).filter({ hasText: new RegExp(esc, "i") }).first();
          if (await partial.count()) await partial.click();
          else {
            await s.page.keyboard.press("Escape").catch(() => {});
            gaveUp = true;
          }
        }
      } else if (meta.type === "select") {
        await loc.selectOption({ label: value }).catch(async () => {
          await loc.selectOption(value);
        });
      } else if (meta.type === "checkbox") {
        const want = ["true", "1", "yes", "on", "checked"].includes(value.toLowerCase());
        let done = false;
        try {
          await loc.setChecked(want, { timeout: 3000 });
          done = true;
        } catch {
          // custom-styled checkbox with a hidden real <input> → click its label
          // (native toggle + React onChange) or force as a last resort.
          if ((await loc.isChecked().catch(() => false)) === want) {
            done = true;
          } else {
            const cid = await loc.getAttribute("id").catch(() => null);
            const lab = cid ? s.frame.locator(`label[for="${cssAttr(cid)}"]`).first() : null;
            if (lab && (await lab.count())) {
              await lab.click().catch(() => {});
              done = true;
            } else {
              try {
                await loc.check({ force: true });
                done = true;
              } catch {
                /* leave for the user */
              }
            }
          }
        }
        gaveUp = !done;
      } else if (meta.type === "radio") {
        const r = s.frame.locator(`[data-co-field="${cssAttr(fid)}"][data-co-option="${cssAttr(value)}"]`).first();
        await r.check({ timeout: 3000 }).catch(async () => {
          await r.check({ force: true }).catch(async () => {
            const rid = await r.getAttribute("id").catch(() => null);
            if (rid) await s.frame.locator(`label[for="${cssAttr(rid)}"]`).first().click().catch(() => { gaveUp = true; });
            else gaveUp = true;
          });
        });
      } else {
        await loc.fill(value);
      }
      ok = !gaveUp;
    } catch {
      ok = false;
    }
    steps.push({ fieldId: fid, label: meta.label, ok, thumb: await shoot() });
  }
  const endPath = (() => {
    try {
      return new URL(s.frame.url()).pathname;
    } catch {
      return s.frame.url();
    }
  })();
  // Read the real form back: did every answer actually land? any validation
  // error? — so we warn the user about silent divergence before the handoff.
  const issues = await verifyFill(s.frame, fieldsMeta, answers).catch(() => [] as ApplyIssue[]);
  return { steps, navigated: endPath !== startPath, issues };
}

/** Hand the real (now pre-filled) form to the HUMAN to review + submit. The
 *  window was kept OFF-SCREEN during fill, so bringToFront alone wouldn't make it
 *  visible — we reposition it on-screen via CDP first. We never submit. */
export async function handoffSession(id: string): Promise<void> {
  const s = SESSIONS.get(id);
  if (!s) throw new Error("apply session not found");
  try {
    const cdp = await s.context.newCDPSession(s.page);
    const { windowId } = (await cdp.send("Browser.getWindowForTarget")) as { windowId: number };
    await cdp.send("Browser.setWindowBounds", {
      windowId,
      bounds: { left: 80, top: 60, width: 1280, height: 920, windowState: "normal" },
    });
    await cdp.detach().catch(() => {});
  } catch {
    /* CDP unavailable → bringToFront still raises it */
  }
  await s.page.bringToFront().catch(() => {});
}

import fs from "node:fs";
import path from "node:path";
import { atomicWrite } from "@/lib/core/safe-write";
import { parseApplications } from "@/lib/tracker-table.mjs";
// One definition of the `{n}-RESERVED.md` convention, shared with
// run-cli-support.mjs — see report-files.mjs for why it lives there.
import { isReservedReportFile } from "@/lib/report-files.mjs";

/**
 * Resolve the career-ops "home" — the directory holding the user's sibling
 * files (cv.md, data/, reports/). In production the web/ app lives inside the
 * career-ops checkout, so the home is its parent (..). Dev overrides via
 * CAREER_OPS_ROOT to read the user's real (gitignored) data from a separate
 * checkout — see web/.env.local.
 */
export function careerOpsRoot(): string {
  const env = process.env.CAREER_OPS_ROOT?.trim();
  if (env) return env;
  return path.resolve(process.cwd(), "..");
}

/**
 * Absolute path to a core root script (e.g. doctor, verify-portals). The `.mjs`
 * is assembled here from the bare name so the literal never appears as a direct
 * `execFile`/`spawn` argument — Next's bundler statically traces such literals
 * as module imports and fails the production build otherwise.
 */
export function rootScript(nameNoExt: string): string {
  return path.join(careerOpsRoot(), `${nameNoExt}.mjs`);
}

// Feature-detect the core's `tracker.mjs delete --num` row-delete (#1200) by probing
// the local script source — older checkouts lack it, so the delete UI hides itself.
export function trackerCanDelete(): boolean {
  try {
    const src = fs.readFileSync(rootScript("tracker"), "utf8");
    return src.includes("delete") && src.includes("--num");
  } catch {
    return false;
  }
}

function read(rel: string): string | null {
  try {
    return fs.readFileSync(path.join(careerOpsRoot(), rel), "utf8");
  } catch {
    return null;
  }
}

export type InboxJob = { url: string; company: string; role: string; location?: string; compensation?: string; done: boolean; postedAt?: string };

/** A pipeline-row segment like `posted: 2026-07-14`, `trust: 62 stale` or
 *  `note: …` — the core appends these LABELED segments after whatever
 *  positional shape a row has (3/4/5 columns), so a naive positional reader
 *  would misread them as location/compensation on short rows. Any
 *  `word:`-prefixed segment is treated as labeled (forward-compatible with
 *  labels the core hasn't invented yet). */
const LABELED_SEGMENT = /^([a-z][a-z_-]*):\s*(.*)$/i;

/** Parse data/pipeline.md — `- [ ] URL | Company | Role [| Location [| Compensation]] [| label: …]*`.
 *  Positional split for the first columns (the optional 4th `location` #1015
 *  and 5th `compensation` #1017 must NOT bleed into `role`); labeled segments
 *  (posted:/trust:/note:/…) are filtered out of positional assignment wherever
 *  they appear and surfaced when useful (posted: → postedAt). Unknown labels
 *  and further trailing columns are ignored gracefully. */
export function readInbox(): InboxJob[] {
  const md = read("data/pipeline.md");
  if (!md) return [];
  const jobs: InboxJob[] = [];
  for (const line of md.split("\n")) {
    const m = line.match(/^\s*-\s*\[([ xX])\]\s*(.+)$/);
    if (!m) continue;
    const all = m[2].split("|").map((s) => s.trim());
    const labels = new Map<string, string>();
    const parts: string[] = [];
    for (const [i, seg] of all.entries()) {
      // the URL cell can contain a colon-y value but is always position 0
      const lm = i >= 3 ? seg.match(LABELED_SEGMENT) : null;
      if (lm) labels.set(lm[1].toLowerCase(), lm[2].trim());
      else parts.push(seg);
    }
    if (parts.length < 3 || !parts[0]) continue; // need at least url | company | role
    const posted = labels.get("posted");
    jobs.push({
      done: m[1].toLowerCase() === "x",
      url: parts[0],
      company: parts[1],
      role: parts[2],
      location: parts[3] || undefined, // optional 4th column (#1015)
      compensation: parts[4] || undefined, // optional 5th column (#1017); 6th+ ignored
      // the row's own posting date (scan.mjs `posted:` label) — a more direct
      // freshness signal than the scan-history join, which stays as fallback
      postedAt: posted && /^\d{4}-\d{2}-\d{2}$/.test(posted) ? posted : undefined,
    });
  }
  return jobs;
}

/**
 * Read data/scan-history.tsv → Map<url, first_seen(YYYY-MM-DD)>. The scanner
 * already stamps every discovered posting with the date it was first seen
 * (col 2), so we derive the inbox's freshness signal here WITHOUT touching the
 * core (see the inbox-triage build: freshness = option A, no scanner change).
 * Tolerant by construction: no file → empty map (freshness facet just hides);
 * a malformed row is skipped, never thrown (missing ≠ corrupt).
 */
export function readScanDates(): Map<string, string> {
  const tsv = read("data/scan-history.tsv");
  const dates = new Map<string, string>();
  if (!tsv) return dates;
  const lines = tsv.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!line || (i === 0 && line.startsWith("url\t"))) continue; // skip header
    const tab = line.indexOf("\t");
    if (tab < 1) continue;
    const url = line.slice(0, tab);
    const firstSeen = line.slice(tab + 1).split("\t")[0]?.trim();
    // keep the EARLIEST first_seen if a url recurs (it's "first" seen, after all)
    if (/^\d{4}-\d{2}-\d{2}$/.test(firstSeen) && !dates.has(url)) dates.set(url, firstSeen);
  }
  return dates;
}

export type Application = {
  n: string;
  date: string;
  company: string;
  /** Intermediary channel (#1596): agency/recruiter firm, "—" for direct, "" when the tracker has no Via column. */
  via: string;
  role: string;
  score: string;
  status: string;
  pdf: string;
  report: string;
  notes: string;
};

/**
 * Parse data/applications.md — the tracker table (source of truth).
 * The header-aware parsing lives in tracker-table.mjs, which resolves headers
 * through the SAME alias table the Node tooling uses (tracker-aliases.json,
 * exported by tracker-parse.mjs as HEADER_ALIASES) — one shared source, no
 * web-side mirror to drift (#954, PR #1598 review).
 */
export function readApplications(): Application[] {
  const md = read("data/applications.md");
  if (!md) return [];
  return parseApplications(md, careerOpsRoot());
}

/**
 * Server-side lifecycle of the user's setup — mirrors the prerequisite list that
 * doctor.mjs uses (cv.md, config/profile.yml, modes/_profile.md, portals.yml), by
 * plain file-stat (no subprocess). Drives the home branch: first-run (no CV) →
 * the CV takeover; in-between (CV but no profile) → gentle nudges; established.
 */
export type LifecyclePhase = "first-run" | "in-between" | "established";
/**
 * Server-side lifecycle, mirroring the core doctor.mjs prerequisite list with the
 * SAME existsSync semantics (the SSOT the OnboardingBanner already reads via
 * /api/doctor). The 4 user-layer prereqs: cv.md, config/profile.yml,
 * modes/_profile.md, portals.yml.
 *   - first-run  → a TRULY empty install (no cv AND no data): the CV takeover.
 *     CRITICAL back-compat (maintainer): NEVER force onboarding on a user who
 *     already has data (a full pipeline/tracker with no cv.md is valid).
 *   - in-between → has cv/data but setup incomplete: dashboard + the nudge banner.
 *   - established → all 4 prereqs present.
 * onboardingNeeded mirrors doctor.mjs: true if ANY prereq is missing → show banner.
 */
export function doctorState(): {
  phase: LifecyclePhase;
  onboardingNeeded: boolean;
  missing: string[];
  hasCv: boolean;
  hasData: boolean;
} {
  const has = (rel: string) => {
    try {
      return fs.existsSync(path.join(careerOpsRoot(), rel));
    } catch {
      return false;
    }
  };
  const prereqs: [string, string][] = [
    ["cv.md", "cv.md"],
    ["config/profile.yml", "config/profile.yml"],
    ["modes/_profile.md", "modes/_profile.md"],
    ["portals.yml", "portals.yml"],
  ];
  const missing = prereqs.filter(([rel]) => !has(rel)).map(([, label]) => label);
  const hasCv = has("cv.md");
  const hasData = readApplications().length > 0 || readInbox().some((j) => !j.done);
  const onboardingNeeded = missing.length > 0;
  const phase: LifecyclePhase = !hasCv && !hasData ? "first-run" : onboardingNeeded ? "in-between" : "established";
  return { phase, onboardingNeeded, missing, hasCv, hasData };
}

export type PipelineSummary = {
  root: string;
  rootExists: boolean;
  inbox: InboxJob[];
  applications: Application[];
};

export function pipelineSummary(): PipelineSummary {
  const root = careerOpsRoot();
  const scanDates = readScanDates();
  return {
    root,
    rootExists: fs.existsSync(root),
    // join the freshness date (first_seen) onto each raw posting — the inbox's
    // triage view orders/faceted-filters on it entirely client-side.
    inbox: readInbox().map((j) => ({ ...j, postedAt: j.postedAt ?? scanDates.get(j.url) })),
    applications: readApplications(),
  };
}

export type ReportData = { content: string; file: string };

/** Locate the evaluation report for an application number.
 *  The tracker row's own report link is authoritative: report FILE numbers can
 *  differ from application numbers (e.g. app #309 → reports/308-…), so
 *  resolving only by leading filename number misses those. Links are
 *  normalized relative to the tracker file's directory (see #760). Falls back
 *  to the filename scan (reports/{n}-{slug}-{date}.md, possibly zero-padded)
 *  for rows without a parseable link.
 *
 *  Both the linked lookup and the fallback scan skip `{n}-RESERVED.md`
 *  placeholder files.
 *  `reserve-report-num.mjs` writes an empty `NNN-RESERVED.md` sentinel to
 *  claim a report number before a worker has actually written the report;
 *  it's normally deleted once the real report lands (or GC'd after 4h if
 *  abandoned). But "RESERVED" sorts alphabetically before nearly every real
 *  slug (company names start with lowercase/uppercase letters after the
 *  number-dash, "R" often lands mid-alphabet or earlier), so if a sentinel
 *  outlives its report — e.g. a worker was driven directly instead of
 *  through the orchestrator that owns cleanup — `.find()` could return the
 *  empty sentinel instead of the real report, making the report body and the
 *  Apply/PDF-ready checks disappear. */
export function findReportFile(n: string): string | null {
  const target = parseInt(n, 10);
  if (Number.isNaN(target)) return null;
  const root = careerOpsRoot();
  const app = readApplications().find((a) => parseInt(a.n, 10) === target);
  const linked = app?.report.match(/\]\(([^)]+)\)/)?.[1];
  if (linked) {
    const p = path.resolve(root, "data", linked);
    // Containment: a hand-edited link must not resolve outside the project.
    if (p.endsWith(".md") && !isReservedReportFile(p) && containedRealpath(p, root)) return p;
  }
  let files: string[];
  try {
    files = fs.readdirSync(path.join(root, "reports"));
  } catch {
    return null;
  }
  const match = files.find(
    (f) => f.endsWith(".md") && !isReservedReportFile(f) && parseInt(f, 10) === target,
  );
  if (!match) return null;
  const p = path.join(root, "reports", match);
  return containedRealpath(p, root) ? p : null;
}

/** True containment check: resolves symlinks before comparing, so a link
 *  planted under data/ or reports/ can't leak files outside the project. */
function containedRealpath(p: string, root: string): boolean {
  try {
    return fs.realpathSync(p).startsWith(fs.realpathSync(root) + path.sep);
  } catch {
    return false; // missing file or unresolvable link — treat as not found
  }
}

export function readReport(n: string): ReportData | null {
  const file = findReportFile(n);
  if (!file) return null;
  try {
    return { content: fs.readFileSync(file, "utf8"), file: path.basename(file) };
  } catch {
    return null;
  }
}

export function findApplication(n: string): Application | null {
  return readApplications().find((a) => a.n === n) ?? null;
}

/** The CANONICAL user-customization file the CLI/TUI reads. Durable facts the
 *  web assistant learns go HERE (single source of truth) inside a managed marker
 *  block — so the CLI sees them too. No web-only memory store (that would drift). */
export function profilePath(): string {
  return path.join(careerOpsRoot(), "modes", "_profile.md");
}

const NOTES_START = "<!-- co-web-notes:start -->";
const NOTES_END = "<!-- co-web-notes:end -->";

/** Read back ONLY the web-assistant managed notes from modes/_profile.md (small,
 *  focused — the agent reads the rest of the canonical files itself). Falls back
 *  to the legacy web-only memory file for back-compat. */
export function readMemory(): string {
  try {
    const md = fs.readFileSync(profilePath(), "utf8");
    const i = md.indexOf(NOTES_START);
    const j = md.indexOf(NOTES_END);
    if (i !== -1 && j !== -1 && j > i) return md.slice(i + NOTES_START.length, j).trim();
  } catch {
    /* no _profile.md yet */
  }
  try {
    return fs.readFileSync(path.join(careerOpsRoot(), ".career-ops-web", "memory.md"), "utf8").trim();
  } catch {
    return "";
  }
}

/** Append a durable fact to the canonical modes/_profile.md (creating the file +
 *  managed block if needed), PRESERVING existing user content. */
export function rememberFact(fact: string): "ok" | "deduped" | "error" {
  const f = fact.trim().replace(/\s+/g, " ").slice(0, 300);
  if (!f) return "deduped";
  const p = profilePath();
  try {
    fs.mkdirSync(path.dirname(p), { recursive: true });
    let md = "";
    try {
      md = fs.readFileSync(p, "utf8");
    } catch {
      md = "";
    }
    const i = md.indexOf(NOTES_START);
    const j = md.indexOf(NOTES_END);
    if (i !== -1 && j !== -1 && j > i) {
      if (md.slice(i, j).includes(f)) return "deduped";
      atomicWrite(p, md.slice(0, j) + `- ${f}\n` + md.slice(j));
      return "ok";
    }
    if (md.includes(f)) return "deduped";
    const section = `\n\n## Notes from the web assistant\n${NOTES_START}\n- ${f}\n${NOTES_END}\n`;
    const base = md.trim() ? md.replace(/\n*$/, "\n") : "# Profile customization\n";
    atomicWrite(p, base + section);
    return "ok";
  } catch {
    return "error";
  }
}

/**
 * claude-invocation.mjs — how a headless `claude` run is invoked: which tools each
 * web worker kind may use, and the argv that carries that decision (#2185).
 *
 * Everything here is asserted on as VALUES (test-all.mjs §55.6), never by matching
 * route.ts's source: five source-text versions of that guard were each defeated by
 * rewriting the route around them while pdf kept full write access. So the argv is
 * built here — `claudeCliArgs({kind:"pdf"})` IS the command line — and the only
 * rule left on the route is that it may spell no tool flag itself.
 *
 * The transport flags (`--output-format stream-json`, `--include-partial-messages`)
 * live here too, because route.ts's NDJSON parser depends on them and a guard can
 * only be honest if it inspects ONE shipped argv.
 *
 * `disallowedTools` is the hard guardrail; the allow list is the working set. Every
 * write-capable tool a kind does not need is EXPLICITLY denied, never merely
 * omitted: `--permission-mode acceptEdits` exists to auto-approve edit tools, so
 * "unmentioned" is the one status a file-writing tool must never have. The deny
 * lists are derived from the allow lists for that reason — hand-writing them once
 * left MultiEdit unmentioned for the persisting kinds.
 */

/**
 * Tools that can modify the user's files. `Bash` counts: `sh -c '> cv.md'` is a
 * write, which is why pdf lost Bash in #2172 and must never regain it. Anything
 * added here is automatically denied to every read-only kind.
 */
export const WRITE_CAPABLE_TOOLS = Object.freeze(["Write", "Edit", "MultiEdit", "NotebookEdit", "Bash"]);

/** Sub-agents: unbounded fan-out cost, wanted by no kind. */
const ALWAYS_DENIED = ["Task"];

/**
 * Split a comma-separated tool list into bare tool names.
 *
 * Claude Code accepts parameterized specifiers (`Bash(node x.mjs:*)`,
 * `Edit(src/**)`), so the argument is stripped before comparing — otherwise
 * `Bash(...)` reads as a tool nobody has heard of and slips past every check.
 *
 * @param {string} value - A comma-separated --allowedTools/--disallowedTools value.
 * @returns {string[]} Bare tool names, in order.
 */
export function toolNames(value) {
  return String(value ?? "")
    .split(",")
    .map((t) => t.trim().replace(/\(.*$/, "").trim())
    .filter(Boolean);
}

/**
 * @typedef {Object} ToolScope
 * @property {string} allowed - Comma-separated --allowedTools value.
 * @property {string} disallowed - Comma-separated --disallowedTools value.
 */

/**
 * Build a scope from its allow list, denying every write-capable tool it does not
 * name plus everything denied unconditionally. Derived rather than hand-listed so
 * a tool added to WRITE_CAPABLE_TOOLS cannot leave any scope silently permissive.
 *
 * @param {string} allowed - Comma-separated --allowedTools value.
 * @returns {ToolScope}
 */
function scopeFrom(allowed) {
  const granted = toolNames(allowed);
  const denied = [...WRITE_CAPABLE_TOOLS.filter((t) => !granted.includes(t)), ...ALWAYS_DENIED];
  return Object.freeze({ allowed, disallowed: denied.join(",") });
}

/**
 * The two scopes that exist. `persisting` kinds run the REAL mode and write
 * canonical artifacts (reserve-report-num.mjs / merge-tracker.mjs /
 * verify-portals.mjs), so they need Write + Bash. `readOnly` kinds produce their
 * result through the response stream and need no write tool at all — pdf emits
 * its CV in a `<<cv-html>>` envelope the backend persists (#2185), and research
 * only reports.
 *
 * @type {{persisting: ToolScope, readOnly: ToolScope}}
 */
export const TOOL_SCOPES = Object.freeze({
  persisting: scopeFrom("Read,WebFetch,WebSearch,Write,Edit,Bash,Glob,Grep"),
  readOnly: scopeFrom("Read,WebFetch,WebSearch,Glob,Grep"),
});

/** Kinds that legitimately write files. Everything else is read-only. */
const PERSISTING_KINDS = new Set(["evaluate", "fix-portal"]);

/**
 * Every kind /api/run dispatches. Exported so guards iterate this rather than a
 * hand-written list — a list silently stops gating whatever kind is added next.
 * Unknown kinds still resolve (read-only, see toolScopeFor); this is the set a
 * test can enumerate, not a validity check.
 */
export const KNOWN_KINDS = Object.freeze(["pdf", "research", "evaluate", "fix-portal"]);

/**
 * Resolve the tool scope for a worker kind.
 *
 * Unknown kinds get the read-only scope: granting write access to a kind nobody
 * has reviewed is the one unrecoverable default.
 *
 * @param {string} kind - Worker kind ("pdf", "research", "evaluate", …).
 * @returns {ToolScope}
 */
export function toolScopeFor(kind) {
  return PERSISTING_KINDS.has(kind) ? TOOL_SCOPES.persisting : TOOL_SCOPES.readOnly;
}

/**
 * Does this scope hand the agent any way to write?
 *
 * Compares bare tool names, so `MultiEdit` is caught (a `\bEdit\b`-style match is
 * not) and so is `Bash(node x.mjs:*)`, while a longer tool name that merely
 * contains a write tool's name is not a false positive.
 *
 * @param {ToolScope} scope
 * @returns {boolean}
 */
export function grantsWriteCapability(scope) {
  const allowed = toolNames(scope?.allowed);
  return WRITE_CAPABLE_TOOLS.some((tool) => allowed.includes(tool));
}

/**
 * The complete headless `claude` argv for a run.
 *
 * Assembled here, not in the route, so a guard can assert on the command line
 * that actually ships instead of on source text that can be rewritten around it.
 *
 * @param {{kind: string, prompt: string}} args
 * @returns {string[]}
 */
export function claudeCliArgs({ kind, prompt }) {
  const scope = toolScopeFor(kind);
  return [
    "-p", prompt,
    "--output-format", "stream-json",
    "--verbose",
    "--include-partial-messages",
    "--permission-mode", "acceptEdits",
    // pdf only, deliberately. --strict-mcp-config with no --mcp-config loads ZERO
    // MCP servers, so the tool lists below describe everything the agent can
    // reach — without it an MCP server from the user's own config could supply a
    // write tool that appears in neither list. #2185 is about pdf, and applying
    // this to every kind would silently stop a configured MCP server (e.g. the
    // optional Canva server) from loading on evaluate/research runs. The same gap
    // for the other kinds is #2507.
    ...(kind === "pdf" ? ["--strict-mcp-config"] : []),
    "--allowedTools", scope.allowed,
    "--disallowedTools", scope.disallowed,
  ];
}

/**
 * Read a flag's value back out of an argv array.
 *
 * Exists for guards: it lets a test ask "what did pdf actually get?" rather than
 * trusting that the argv was built from the scope it expected.
 *
 * @param {string[]} args
 * @param {string} flag - e.g. "--allowedTools".
 * @returns {string} The value, or "" when the flag is absent.
 */
export function argValue(args, flag) {
  const i = args.indexOf(flag);
  return i === -1 || i + 1 >= args.length ? "" : args[i + 1];
}

// Pure JS implementation of cleanChips — no TypeScript types so it can be
// imported directly by both explore.ts (which re-exports it) and by
// clean-chips.test.mjs (which can't import .ts without a runner).
// This is the single source of truth for the chip-cleaning logic.

/**
 * Upper bound on a keyword list — a sanity rail against a pathological paste
 * (a whole spreadsheet column, a JSON blob), NOT a limit on how many keywords a
 * search may use.
 *
 * It was 16, which is smaller than the config it has to carry:
 *
 * 1. `templates/portals.example.yml` ships **37** `title_filter.positive`
 *    keywords, so the project's own default could not survive a round-trip
 *    through the Explorer. seedExploreFilters() read 37 and handed the scanner
 *    16, with nothing shown to the user. The CLI reads the same portals.yml and
 *    uses all 37 — so `scan` and the web Explorer silently ran different
 *    searches off one config file.
 *
 * 2. Worse, the cap applied to a MERGE. filter-builder's commit() cleans
 *    `[...existing, ...pasted]`, so on any list already over the cap, adding a
 *    single chip kept the first 16 entries, dropped the other 21, and did not
 *    append the new chip either — a keystroke that deletes data.
 *
 * The bound stays because unbounded is not a property worth having on a value
 * that gets serialized into a YAML file and passed to a scanner; it is just
 * sized to bound the process rather than the user.
 */
export const CHIP_CAP = 512;

/** Trim, drop empties, de-dupe case-insensitively, cap length. */
export function cleanChips(v) {
  if (v == null) return [];
  const arr = Array.isArray(v) ? v : [v];
  const seen = new Set();
  const out = [];
  for (const item of arr) {
    if (typeof item !== "string") continue;
    const k = item.trim();
    if (!k) continue;
    if (!/[\p{L}\p{N}]/u.test(k)) continue; // drop punctuation-only junk (e.g. a stray "*")
    const key = k.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(k);
    if (out.length >= CHIP_CAP) break;
  }
  return out;
}

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { codexStreamArgs, isFatalClaudeStderr, isFatalCodexStderr, parseClaudeEvent, parseCodexEvent } from "./run-cli-support.mjs";

// Server-only (node imports). The agnostic runtimes career-ops can delegate to
// in headless mode (AGENTS.md). Install URLs from career-ops-docs.
export type CliSpec = {
  id: string;
  name: string;
  bin: string;
  run: string;
  url: string;
  /** headless invocation args for a single prompt, emitting PLAIN TEXT on stdout.
   * Every caller that reads the output itself (the `<<offer:>>`/`<<cv:>>` envelope
   * routes, the apply planners) uses this, so it must stay unstructured. */
  args: (prompt: string) => string[];
  /** Structured-output CLIs only: args for a run whose stdout the caller parses
   * with `parseEvent` — i.e. /api/run's dashboard stream, the one consumer that
   * understands events. Absent → that caller falls back to `args`.
   *
   * INVARIANT: `parseEvent` only applies to output produced by THIS argv (for
   * claude, by claude-invocation.mjs's `claudeCliArgs`, which spells its own
   * `--output-format stream-json`). Pairing one CLI's parser with a plain-text
   * invocation yields a silent stream of unparseable lines. */
  streamArgs?: (prompt: string) => string[];
  /** Structured-output CLIs only: parse one stdout line into dashboard events.
   * Absent → the route streams stdout as raw text (the default for every CLI
   * without its own structured output format). */
  parseEvent?: (line: string) => import("./run-cli-support.mjs").ParsedEvent | null;
  /** Structured-output CLIs only: decide whether a stderr line is fatal.
   * Absent → the route falls back to the shared generic error regex. */
  stderrIsFatal?: (line: string) => boolean;
};

/**
 * NO RUNTIME HERE MAY GRANT ITSELF MORE PERMISSION THAN THE AUDITED ONE.
 *
 * The permission model is per-worker AND per-CLI, but only one axis is written
 * down: WRITE_CAPABLE_TOOLS and the per-kind deny lists live in
 * claude-invocation.mjs — i.e. on Claude's path. A new CLI arriving with a
 * blanket auto-approve flag (`--always-approve`, `--yolo`,
 * `--dangerously-skip-permissions`, `--yes`) is not breaking that rule; it is
 * entering where the rule does not exist.
 *
 * Concretely: the `pdf` worker has Bash explicitly denied and must never regain
 * it. Pair Grok with `--always-approve` and that same worker gets Write and
 * Bash auto-approved — so the user's choice of runtime silently changes what a
 * worker may do to their files, while both paths look identical in the UI.
 *
 * If a CLI has no per-tool deny list to pair with, the answer is NOT to
 * auto-approve: it is to withhold the workers that write. Needing such a flag
 * to make a runtime work is a core architecture issue, not a line inside a
 * CLI-support PR.
 *
 * Enforced by tests/lib/clis-permissions.test.mjs, because a rule that only
 * lives in a comment is a rule the next contributor may never read.
 */
export const KNOWN: CliSpec[] = [
  { id: "claude", name: "Claude Code", bin: "claude", run: "claude -p", url: "https://claude.ai/code", args: (p) => ["-p", p], parseEvent: parseClaudeEvent, stderrIsFatal: isFatalClaudeStderr },
  { id: "codex", name: "Codex", bin: "codex", run: "codex exec", url: "https://github.com/openai/codex", args: (p) => ["exec", p], streamArgs: codexStreamArgs, parseEvent: parseCodexEvent, stderrIsFatal: isFatalCodexStderr },
  { id: "gemini", name: "Gemini CLI", bin: "gemini", run: "gemini -p", url: "https://github.com/google-gemini/gemini-cli", args: (p) => ["-p", p] },
  { id: "opencode", name: "OpenCode", bin: "opencode", run: "opencode run", url: "https://opencode.ai", args: (p) => ["run", p] },
  { id: "copilot", name: "GitHub Copilot CLI", bin: "copilot", run: "copilot -p", url: "https://docs.github.com/en/copilot/github-copilot-in-the-cli", args: (p) => ["-p", p] },
  { id: "qwen", name: "Qwen CLI", bin: "qwen", run: "qwen -p", url: "https://qwen.ai/qwencode", args: (p) => ["-p", p] },
  { id: "antigravity", name: "Antigravity CLI", bin: "agy", run: "agy -p", url: "https://antigravity.google", args: (p) => ["-p", p] },
  // Grok Build also speaks `--output-format streaming-json`, but that is its own
  // schema, not Claude's `stream-json` — and the run route only parses the
  // latter. Plain `-p` streams text, which is what every other non-Claude entry
  // here does.
  { id: "grok", name: "Grok Build CLI", bin: "grok", run: "grok -p", url: "https://docs.x.ai/build/overview", args: (p) => ["-p", p] },
];

function searchDirs(): string[] {
  const home = os.homedir();
  const extra = [
    path.join(home, ".local/bin"),
    path.join(home, ".npm-global/bin"),
    path.join(home, ".bun/bin"),
    path.join(home, ".deno/bin"),
    path.join(home, ".opencode/bin"),
    "/opt/homebrew/bin",
    "/usr/local/bin",
    "/usr/bin",
  ];
  if (process.platform === "win32") {
    // Windows CLIs frequently install under per-user AppData roots and don't
    // reliably add themselves to PATH (e.g. Antigravity → %LOCALAPPDATA%\agy\bin).
    const localAppData = process.env.LOCALAPPDATA || path.join(home, "AppData", "Local");
    const appData = process.env.APPDATA || path.join(home, "AppData", "Roaming");
    extra.push(
      path.join(localAppData, "agy", "bin"), // Antigravity CLI
      path.join(localAppData, "Microsoft", "WindowsApps"), // winget/Store shims
      path.join(appData, "npm"), // npm global prefix on Windows
    );
  }
  const fromPath = (process.env.PATH || "").split(path.delimiter).filter(Boolean);
  return [...new Set([...fromPath, ...extra])];
}

// On Windows, executables carry an extension (claude.exe, claude.cmd, ...).
// Mirror the shell's PATHEXT resolution so a native-installer claude.exe is
// found, not just an extensionless npm shim. On POSIX, "" keeps the bare name.
function binCandidates(bin: string): string[] {
  if (process.platform !== "win32") return [bin];
  const pathext = process.env.PATHEXT || ".COM;.EXE;.BAT;.CMD";
  const exts = pathext
    .split(";")
    .map((e) => e.trim())
    .filter(Boolean)
    // Only include extensions that `child_process.spawn()` can execute directly.
    .filter((e) => [".com", ".exe", ".bat", ".cmd"].includes(e.toLowerCase()));

  // Try the bare name too (some environments provide an extensionless shim).
  return [bin, ...exts.map((ext) => bin + ext)];
}

export function findBin(bin: string, dirs = searchDirs()): string | null {
  for (const dir of dirs) {
    for (const candidate of binCandidates(bin)) {
      const p = path.join(dir, candidate);
      try {
        fs.accessSync(p, fs.constants.X_OK);
        return p;
      } catch {
        /* not here */
      }
    }
  }
  return null;
}

export function detectClis() {
  const dirs = searchDirs();
  return KNOWN.map((c) => {
    const found = findBin(c.bin, dirs);
    return { id: c.id, name: c.name, run: c.run, url: c.url, installed: !!found, path: found };
  });
}

export function resolveCli(id: string): { spec: CliSpec; binPath: string } | null {
  const spec = KNOWN.find((c) => c.id === id);
  if (!spec) return null;
  const binPath = findBin(spec.bin);
  if (!binPath) return null;
  return { spec, binPath };
}

