/**
 * ACL for the core's follow-ups file lock (`followup-seed.mjs`).
 *
 * WHY A WEB ROUTE NEEDS IT. `data/follow-ups.md` is a read-modify-write from
 * two directions: the web's log/override routes AND the core's cadence seeder
 * (`followup-seed.mjs`, which takes this same lock). `atomicWrite` makes the
 * WRITE atomic, not the read-modify-write around it — two writers each read the
 * whole file, each edit, each rename their full copy back, and one change
 * silently reverts. Same failure family as the tracker (#2900), same cure.
 *
 * NOT `withLogLock` (followups-server.ts): that is an in-process promise queue.
 * It serializes THIS process's own requests and is blind to the user's CLI —
 * "no cross-process lock needed" is true for web-vs-web and false for
 * web-vs-seeder. Two guards, different scopes; they compose (see
 * `withFollowupsWrite`), neither substitutes for the other.
 *
 * WE DO NOT DERIVE THE LOCK DIRECTORY. The core computes it from a sha256 of the
 * resolved path, entirely inside `followup-seed.mjs`. We import `withFollowupsLock`
 * and pass our path; the core resolves the path and the lockDir. Recomputing the
 * hash web-side would birth a second body of the same truth that has to stay in
 * sync forever — the exact class of bug this whole change closes (#3034).
 *
 * THE LOCK IS NOT REENTRANT (no owner/pid self-check in the core). A caller
 * holding it must never orchestrate a core script that also takes it — that
 * self-deadlocks until the timeout. Our two routes write the file DIRECTLY, so
 * this is safe today; it is a rule for any future followups writer that shells
 * out.
 *
 * `finally`-release lives in the core export, so it cannot be forgotten here.
 * The web timeout is deliberately far shorter than the CLI's 60s default: a
 * minute of silence inside an HTTP handler is indistinguishable from a hang, so
 * we fail fast and answer the caller "busy, retry" (→ 409) instead.
 */

type CoreWithFollowupsLock = (
  followupsPath: string,
  fn: () => unknown,
  options?: Record<string, unknown>,
) => Promise<unknown>;

/** Cached per resolved module path; failures are NEVER cached, so a repaired or
 *  newly-installed checkout is picked up on the next request. */
const modCache = new Map<string, CoreWithFollowupsLock>();

/** Resolve the core export, or null when this root has data but no scripts.
 *  A data-only root cannot host the seeder either, so there is nothing to
 *  exclude cross-process and the in-process queue alone is correct — see
 *  `withFollowupsLock` below. */
async function loadCoreLock(): Promise<CoreWithFollowupsLock | null> {
  const file = path.join(careerOpsRoot(), "followup-seed.mjs");
  const cached = modCache.get(file);
  if (cached) return cached;
  if (!fs.existsSync(file)) return null;
  const mod = await import(/* webpackIgnore: true */ pathToFileURL(file).href);
  if (typeof mod.withFollowupsLock !== "function") {
    throw new Error("followup-seed.mjs has no withFollowupsLock export");
  }
  const api = mod.withFollowupsLock as CoreWithFollowupsLock;
  modCache.set(file, api);
  return api;
}

/** Thrown when the lock is held by someone else for longer than we will wait. */
export class FollowupsBusyError extends Error {
  constructor() {
    super("follow-ups file is being written by another process");
    this.name = "FollowupsBusyError";
  }
}

/**
 * Run `fn` holding the core's follow-ups lock, releasing it on EVERY path.
 *
 * When the core scripts are absent (data-only root), runs `fn` with no file
 * lock: without the core there is no seeder to race, and `withLogLock` still
 * serializes this process. When the lock is contended past the web timeout,
 * throws `FollowupsBusyError` so the route can answer 409 rather than hang.
 *
 * @param followupsPath absolute path to data/follow-ups.md (the core resolves
 *   and normalizes it; do not pre-derive anything from it)
 * @param fn the read-modify-write to run under the lock
 */
export async function withFollowupsLock<T>(followupsPath: string, fn: () => T | Promise<T>): Promise<T> {
  const core = await loadCoreLock();
  if (!core) return await fn();
  try {
    return (await core(followupsPath, fn as () => unknown, {
      timeoutMs: Number(process.env.CAREER_OPS_WEB_FOLLOWUPS_LOCK_TIMEOUT_MS) || 5_000,
    })) as T;
  } catch (e) {
    // The core throws SeedError('LOCK_TIMEOUT') only from the lock acquire,
    // which runs BEFORE fn — and our fn does fs I/O, never mints a SeedError —
    // so this match is unambiguous: it means "couldn't get the lock", not "the
    // write failed". Anything else (a real fs error from fn) propagates as-is.
    const err = e as { name?: string; code?: string } | null;
    if (err && err.name === "SeedError" && err.code === "LOCK_TIMEOUT") {
      throw new FollowupsBusyError();
    }
    throw e;
  }
}

import { createHash } from "node:crypto";

// Cache identity for name-resolved company logos (see app/api/logo/route.ts).
//
// The logo cache is written once per key and never revalidated — misses are
// stored as an empty sentinel precisely so a dead company is never refetched.
// That permanence puts two requirements on the key that a bare slug cannot meet:
//
//  1. It must change when candidate generation changes. Otherwise a machine
//     that cached a miss under the old resolver keeps serving that miss forever
//     and the improvement is invisible exactly where it was needed.
//  2. It must not collide. Two different companies sharing a key means one of
//     them wears the other's logo permanently, with no expiry to correct it.

/** Bump whenever `companyDomains()` in app/api/logo/route.ts changes which
 *  domains it tries, or in what order. The version is part of every key, so
 *  bumping it makes entries written by the previous resolver unreachable.
 *  v2: curated brand domains (notion.so, zoom.us, …) now precede slug guesses. */
export const COMPANY_KEY_VERSION = "v2";

/** Cache key for a company name, or null if the name carries nothing to key on.
 *
 *  Normalizing before hashing is deliberate: "Acme, Inc." and "acme inc" are one
 *  brand and should share one cached favicon across every card, this search and
 *  every future one. The digest is taken over the full normalized name so that
 *  truncating the readable prefix to 40 characters — which keeps cache files
 *  greppable by eye — cannot merge two long legal entity names into one entry. */
export function companyCacheKey(company) {
  const normalized = String(company ?? "").toLowerCase().replace(/[^a-z0-9]/g, "");
  if (!normalized) return null;
  const digest = createHash("sha256").update(normalized).digest("hex").slice(0, 10);
  return `co_${COMPANY_KEY_VERSION}_${normalized.slice(0, 40)}_${digest}`;
}

/**
 * Unicode-safe company/role matching key — algorithm mirror of the core's
 * `normalizeTextKey` in tracker-parse.mjs (#2569 / #2666).
 *
 * Plain .mjs (same pattern as clean-chips.mjs) so node:test and client bundles
 * can import it without a TS runner or Node-only deps.
 *
 * WHY A COPY EXISTS AT ALL: the live core lives in the user's career-ops
 * checkout and is resolved at runtime via careerOpsRoot() — unavailable in the
 * browser. Server code prefers the live export through getNormalizeTextKey()
 * in text-key.ts; this file is for (a) client components and (b) the last-resort
 * fallback when the core module can't be loaded.
 *
 * Keep the body byte-for-byte aligned with tracker-parse.mjs `normalizeTextKey`
 * (nullish → '', NFKC, lower, \p{L}\p{M}\p{N}, separator). The parity test in
 * tests/lib/normalize-text-key.test.mjs fails the build if they drift.
 *
 * Never reinstate [^a-z0-9]: that deleted every non-ASCII letter ("Škoda"→"koda",
 * "日本電産"→""), which both suppressed real offers and resurfaced evaluated ones.
 */

/**
 * @param {unknown} value
 * @param {string} [separator='']
 * @returns {string}
 */
export function normalizeTextKey(value, separator = "") {
  return String(value ?? "")
    .normalize("NFKC")
    .toLowerCase()
    // Mirrors the core exactly, including this step: lowercasing a Turkish
    // dotted capital leaves a combining dot behind (`'İ'.toLowerCase()` is
    // `i` + U+0307), so the key drifts from the visually identical plain `i`.
    // NO `NFD`: NFKC leaves ż/ė/ġ as single precomposed code points the strip
    // cannot reach, while `i` + U+0307 has no precomposed form. Decomposing
    // first would collapse Żubr/Zubr and Ėmė/Eme.
    // Kept byte-for-byte in step with tracker-parse.mjs — test-all §55.7
    // compares the two and fails on any divergence.
    .replace(/̇/gu, "")
    .replace(/[^\p{L}\p{M}\p{N}]+/gu, separator)
    .trim();
}

import { spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { careerOpsRoot, rootScript } from "@/lib/career-ops";
import type { DiscoveredOffer } from "./scan";

/**
 * "Add to pipeline" — appends user-selected discovered offers to data/pipeline.md
 * AND records them in data/scan-history.tsv (so future scans dedup them). We reuse
 * the CANONICAL writers exported by the core's scan.mjs (`appendToPipeline`,
 * `appendToScanHistory`) instead of re-implementing the line format / section
 * markers — single source of truth, per the web↔core contract. We invoke them in
 * a short-lived node process (cwd = the user's career-ops root) so the core's own
 * code does the writing; the web never owns a parallel copy of that logic.
 *
 * Discovered-but-not-added offers stay "new" (a dry-run scan writes nothing);
 * only an explicit add records them as seen. No tokens are spent here.
 */
export type AddResult = { added: number; error?: string };

export function addOffersToPipeline(offers: DiscoveredOffer[]): Promise<AddResult> {
  const clean = offers
    .filter((o) => o && typeof o.url === "string" && /^https?:\/\//i.test(o.url))
    .map((o) => ({
      url: o.url,
      company: o.company || "",
      title: o.title || "",
      location: o.location || "",
      source: o.source || o.ats || "explorer",
      // Preserve the optional per-offer signal so it survives to pipeline.md.
      // The core writer treats an empty note as absent (byte-identical output).
      note: o.note || "",
    }));
  if (clean.length === 0) return Promise.resolve({ added: 0 });

  // Data-only / pre-scan-ats checkout has no scan.mjs writers → fail with an
  // actionable message instead of a silent added:0.
  if (!fs.existsSync(rootScript("scan"))) {
    return Promise.resolve({ added: 0, error: "This checkout is data-only — the pipeline writer (scan.mjs) isn't available." });
  }

  const scanUrl = pathToFileURL(rootScript("scan")).href;
  const localTodayUrl = pathToFileURL(path.join(careerOpsRoot(), "lib", "local-today.mjs")).href;
  const code = `
import { appendToPipeline, appendToScanHistory } from ${JSON.stringify(scanUrl)};
import { localToday } from ${JSON.stringify(localTodayUrl)};
let input = "";
process.stdin.setEncoding("utf8");
process.stdin.on("data", (d) => { input += d; });
process.stdin.on("end", async () => {
  try {
    const offers = JSON.parse(input);
    // LOCAL calendar day, not the UTC one — west of Greenwich, an evening
    // add would otherwise stamp scan-history.tsv's first_seen a day ahead,
    // opening scan.mjs's recheck/cooldown gate a day late for this row (#3070).
    const date = localToday();
    await appendToPipeline(offers);
    await appendToScanHistory(offers, date, "added");
    process.stdout.write(JSON.stringify({ added: offers.length }));
  } catch (e) {
    process.stdout.write(JSON.stringify({ added: 0, error: String((e && e.message) || e) }));
  }
});
`;

  return new Promise((resolve) => {
    const child = spawn(process.execPath, ["--input-type=module", "-e", code], {
      cwd: careerOpsRoot(),
      env: process.env,
    });
    let out = "";
    let err = "";
    child.stdout.on("data", (d: Buffer) => (out += d.toString()));
    child.stderr.on("data", (d: Buffer) => (err += d.toString()));
    child.on("error", (e) => resolve({ added: 0, error: e instanceof Error ? e.message : "spawn failed" }));
    child.on("close", () => {
      try {
        const parsed = JSON.parse(out.trim() || "{}") as AddResult;
        resolve({ added: parsed.added ?? 0, error: parsed.error });
      } catch {
        resolve({ added: 0, error: err.trim().slice(0, 200) || "writer returned no result" });
      }
    });
    child.stdin.write(JSON.stringify(clean));
    child.stdin.end();
  });
}

// Pure serializer for the ephemeral Explorer portals.yml — extracted from
// portals.ts so a `node --test` can load it (the web suite is .mjs and cannot
// import a .ts), matching clean-chips.mjs / profile-keywords.mjs.
//
// Kept dependency-free on purpose: it takes a plain filter-lists object and
// returns YAML text, nothing else. The correctness this guards is that NO
// location tier is silently dropped when the Explorer writes the file the
// scanner reads — the bug block_hard hit (#3102): a tier the type carried but
// the serializer never emitted is a filter the user set and the scan ignored.

/** One YAML list block, or "" when empty. Scalars go through JSON.stringify (a
 *  valid YAML double-quoted scalar) so arbitrary keywords — colons, quotes,
 *  leading dashes — can never break the document or inject YAML. */
function block(key, items) {
  return items.length
    ? `  ${key}:\n` + items.map((k) => `    - ${JSON.stringify(k)}`).join("\n") + "\n"
    : "";
}

/**
 * Serialize filters into a minimal, valid portals.yml.
 *
 * location tiers mirror scan.mjs precedence block_hard > always_allow > block >
 * allow. The `location_filter:` header is emitted when ANY tier is non-empty —
 * block_hard included, or a config that hard-blocks and nothing else would write
 * no location_filter at all and the scan would honor none of it (#3102).
 *
 * @param {{positive:string[], negative:string[], allow:string[], block:string[], alwaysAllow:string[], blockHard:string[]}} f
 * @returns {string}
 */
export function serializePortals(f) {
  let out = "# Ephemeral Explorer filters — generated per-search, safe to delete.\n";
  if (f.positive.length || f.negative.length) {
    out += "title_filter:\n";
    out += block("positive", f.positive);
    out += block("negative", f.negative);
  }
  if (f.blockHard.length || f.allow.length || f.block.length || f.alwaysAllow.length) {
    out += "location_filter:\n";
    out += block("block_hard", f.blockHard);
    out += block("always_allow", f.alwaysAllow);
    out += block("allow", f.allow);
    out += block("block", f.block);
  }
  return out;
}

import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { randomUUID } from "node:crypto";
import * as yaml from "js-yaml";
import { careerOpsRoot } from "@/lib/career-ops";
import { DEFAULT_FILTERS, cleanChips, type ExploreFilters } from "@/lib/explore";
import { profileTargetKeywords } from "@/lib/profile-keywords.mjs";

/**
 * ACL for portals.yml — the core's scan-filter config (a CONTRACT entry-point,
 * see reference_web_core_sync_protocol). The Explorer NEVER mutates the user's
 * real portals.yml: it writes an EPHEMERAL filter file and points the scanner at
 * it via CAREER_OPS_PORTALS, so an ad-hoc search can't clobber the curated config.
 * We also read the real portals.yml + config/profile.yml (tolerantly) only to
 * SEED sensible defaults for the first search.
 *
 * Filter semantics mirror scan.mjs::buildTitleFilter / buildLocationFilter:
 *   title positive → substring match (empty = everything matches)
 *   title negative → substring reject
 *   location block_hard > always_allow > block > allow (case-insensitive substring);
 *   block_hard is the one tier always_allow cannot override (scan.mjs, #2956)
 */
type FilterLists = Pick<ExploreFilters, "positive" | "negative" | "allow" | "block" | "alwaysAllow" | "blockHard">;

function listFrom(v: unknown): string[] {
  return cleanChips(v);
}

// serializePortals lives in portals-serialize.mjs (pure, no TS deps) so the web
// `node --test` suite can load it — the block_hard round-trip (#3102) is exactly
// a "don't silently drop a tier" property that has to be asserted, not eyeballed.
export { serializePortals } from "./portals-serialize.mjs";
import { serializePortals } from "./portals-serialize.mjs";

/** Write the ephemeral filter file to a temp path; caller cleans it up. */
export function writeTempPortals(f: FilterLists): string {
  const file = path.join(os.tmpdir(), `career-ops-explore-${randomUUID()}.yml`);
  fs.writeFileSync(file, serializePortals(f), "utf8");
  return file;
}

export function cleanupTempPortals(file: string): void {
  try {
    if (file.startsWith(os.tmpdir()) && file.includes("career-ops-explore-")) fs.unlinkSync(file);
  } catch {
    /* best-effort */
  }
}

function loadYaml(rel: string): Record<string, unknown> | null {
  try {
    const doc = yaml.load(fs.readFileSync(path.join(careerOpsRoot(), rel), "utf8"));
    return doc && typeof doc === "object" ? (doc as Record<string, unknown>) : null;
  } catch {
    return null;
  }
}

/**
 * Tolerantly seed first-search defaults from the user's real config. Reads
 * portals.yml (title_filter / location_filter) and falls back to
 * config/profile.yml (target_roles, location) for the positive keywords when
 * portals has none. Never throws — a bare checkout just yields DEFAULT_FILTERS.
 */
export function seedExploreFilters(): { filters: ExploreFilters; seededFrom: string[] } {
  const filters: ExploreFilters = { ...DEFAULT_FILTERS, ats: [...DEFAULT_FILTERS.ats] };
  const seededFrom: string[] = [];

  const portals = loadYaml("portals.yml");
  if (portals) {
    const tf = (portals.title_filter ?? {}) as Record<string, unknown>;
    const lf = (portals.location_filter ?? {}) as Record<string, unknown>;
    filters.positive = listFrom(tf.positive);
    filters.negative = listFrom(tf.negative);
    filters.allow = listFrom(lf.allow);
    filters.block = listFrom(lf.block);
    filters.alwaysAllow = listFrom(lf.always_allow);
    filters.blockHard = listFrom(lf.block_hard);
    if (filters.positive.length || filters.allow.length || filters.block.length || filters.blockHard.length) seededFrom.push("portals.yml");
  }

  if (filters.positive.length === 0) {
    // Shape-reading lives in profile-keywords.mjs, mirroring the core's
    // providers/_profile-keywords.mjs. Inlined here it had drifted from the
    // core on BOTH fields — `primary` read as a string when it is a list,
    // `archetypes` spread raw when its entries are objects — so this fallback
    // returned nothing for every profile.yml the app itself writes.
    const fromRoles = listFrom(profileTargetKeywords(loadYaml("config/profile.yml")));
    if (fromRoles.length) {
      filters.positive = fromRoles;
      seededFrom.push("profile.yml");
    }
  }

  return { filters, seededFrom };
}

export { listFrom as normalizeKeywords };

// In-memory registry of in-flight runs that WRITE the tracker (kind evaluate/pdf →
// the core runs merge-tracker / updates applications.md). The web is a single local
// Node process, so a module-level set is enough.
//
// Why this exists: `tracker.mjs delete` (#1200) does NOT yet share a file lock with
// merge-tracker (a documented follow-up — merge-tracker isn't import-safe), so a row
// delete must not run while a worker is mid-merge or one of the two writes is lost.
// The delete route serializes against this registry — coarse (the whole run), but
// correct: we never delete while an evaluation is in flight.
//
// WHAT THIS DOES **NOT** PROTECT, and the reason that matters: this is a counter
// in THIS process's memory. It cannot see the user's CLI, a second `career-ops
// web` instance, or anything else on the machine. Cross-process exclusion on
// data/applications.md is the core's FILE lock (tracker-utils.mjs), reached from
// web via lib/core/tracker-lock.ts.
//
// The distinction is not academic: /api/status wrote the tracker with no file
// lock at all while this registry existed one import away, so the route looked
// guarded and lost updates against the CLI in silence (#2900). A reader who sees
// a guard stops looking for the one that is missing — which is exactly why this
// paragraph is here and not in a commit message.
//
// Rule of thumb: in-flight question → this registry. Writing the tracker →
// withTrackerLock. They compose; neither substitutes for the other.

let seq = 0;
const writing = new Set<number>();

/** Mark that a tracker-writing run has started; returns a token to release with. */
export function acquireTrackerWrite(): number {
  const token = ++seq;
  writing.add(token);
  return token;
}

export function releaseTrackerWrite(token: number): void {
  writing.delete(token);
}

/** True while any evaluation/pdf run that mutates applications.md is in flight. */
export function isTrackerWriting(): boolean {
  return writing.size > 0;
}

import fs from "node:fs";
import path from "node:path";
import { randomUUID } from "node:crypto";

// THE one place every user-layer write goes through. The core's #1 historical
// pain was data-loss (#649/#704/#920/#958); these guards make a web write
// crash-safe + non-clobbering by construction:
//   - atomic: write a UNIQUE temp file (pid + uuid → no concurrent-write race on
//     a single long-lived Next pid) in the SAME dir, then rename (atomic on POSIX),
//     so a kill mid-write can never truncate the real file.
//   - backup: optionally snapshot the prior contents to {file}.bak-{ts} before
//     overwriting, so a bad write is recoverable even though user files are gitignored.

export function atomicWrite(file: string, content: string): void {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const tmp = `${file}.tmp-${process.pid}-${randomUUID()}`;
  fs.writeFileSync(tmp, content, "utf8");
  fs.renameSync(tmp, file);
}

/** Snapshot the file (if it has content) to a timestamped .bak before a write. */
export function backup(file: string): string | null {
  try {
    const cur = fs.readFileSync(file, "utf8");
    if (!cur.trim()) return null;
    const ts = new Date().toISOString().replace(/[:.]/g, "-");
    const bak = `${file}.bak-${ts}`;
    fs.writeFileSync(bak, cur, "utf8");
    return bak;
  } catch {
    return null; // no prior file → nothing to back up
  }
}

/** Atomic write that first backs up any existing content. Returns the backup path. */
export function atomicWriteWithBackup(file: string, content: string): string | null {
  const bak = backup(file);
  atomicWrite(file, content);
  return bak;
}

import { spawn } from "node:child_process";
import fs from "node:fs";
import { careerOpsRoot, rootScript } from "@/lib/career-ops";
import { writeTempPortals, cleanupTempPortals } from "./portals";
import { ATS_SOURCES, type DiscoveredOffer, type ExploreFilters, type ScanEvent } from "@/lib/explore";

export type { DiscoveredOffer, ScanEvent, AtsSource } from "@/lib/explore";
export { ATS_SOURCES } from "@/lib/explore";

/**
 * ACL for the discovery engine — orchestrates the REAL core scanner
 * `scan-ats-full.mjs` (reverse ATS discovery, a contract entry-point). We run it
 * with `--dry-run` so it writes NOTHING (the user reviews + chooses), point it at
 * an EPHEMERAL filter file (never the user's portals.yml), and surface its results.
 *
 * DISCOVERY IS FREE — zero LLM tokens (pure HTTP + JSON). Only evaluation costs
 * tokens, and that is triggered explicitly elsewhere.
 *
 * Two parse paths, chosen by probing the local scanner's source:
 *  • `--json` (#1199): stdout = ONE authoritative object (human progress → stderr),
 *    carrying capHit / datasetStatus / postingsDroppedNoDate so we can tell a
 *    DEGRADED scan (capped, stale/unreachable dataset, postings dropped for no date)
 *    from a genuinely EMPTY one. Preferred.
 *  • legacy: older local checkouts lack `--json`; we parse the human stdout text
 *    (convenient but not formally stable) and infer a looser summary.
 */

const OFFER_RE = /^\s*\+\s+\[([^\]]+)\]\s+(\S+)\s+\|\s+(.+)$/;
const ATS_START_RE = /⚙\s+(\S+)\s+—\s+(\d+)\s+companies/;
const PROGRESS_RE = /(\d+)\/(\d+)\s+scanned,\s+(\d+)\s+total matches/;
const ATS_DONE_RE = /done \((\d+) unreachable boards skipped\)/;
const COMPANIES_RE = /Companies scanned:\s+(\d+)/;
const UNREACHABLE_RE = /Unreachable boards:\s+(\d+)/;
const SUMMARY_RE = /New matches:\s+(\d+)/;

function firstMatch(title: string, positives: string[]): string | undefined {
  const lower = title.toLowerCase();
  for (const k of positives) if (k && lower.includes(k.toLowerCase())) return k;
  return undefined;
}

function parseOfferLine(source: string, date: string, rest: string): Omit<DiscoveredOffer, "url"> | null {
  const fields = rest.split(" | ");
  if (fields.length < 2) return null;
  const company = fields[0].trim();
  const title = fields[1].trim();
  const location = fields.slice(2).join(" | ").trim();
  if (!company || !title) return null;
  return {
    company,
    title,
    location: location === "N/A" ? "" : location,
    postedAt: /^\d{4}-\d{2}-\d{2}$/.test(date) ? date : "",
    ats: source.replace(/-full$/, ""),
    source,
  };
}

// Does the user's LOCAL scanner support the --json contract (#1199)? Probe the
// source (cheap, no spawn) so older checkouts fall back instead of breaking on an
// unknown flag — the web is local-first, so the version is whatever they installed.
export function scannerSupportsJson(): boolean {
  try {
    const src = fs.readFileSync(rootScript("scan-ats-full"), "utf8");
    return src.includes("--json") && src.includes("capHit");
  } catch {
    return false;
  }
}

type JsonOffer = { company?: string; title?: string; url?: string; location?: string | null; postedAt?: string | null; source?: string };
type ScanJson = {
  companiesAvailable?: number;
  companiesScanned?: number;
  capHit?: boolean;
  datasetStatus?: Record<string, "ok" | "stale" | "empty">;
  postingsKept?: number;
  postingsDroppedNoDate?: number;
  unreachableBoards?: number;
  offers?: JsonOffer[];
};

export function runDiscovery(filters: ExploreFilters, onEvent: (e: ScanEvent) => void): Promise<DiscoveredOffer[]> {
  return new Promise((resolve) => {
    const tempPortals = writeTempPortals(filters);
    const ats = (filters.ats.length ? filters.ats : [...ATS_SOURCES]).filter((a) => (ATS_SOURCES as readonly string[]).includes(a));
    const useJson = scannerSupportsJson();
    const args = [
      rootScript("scan-ats-full"),
      "--dry-run",
      "--since",
      String(Math.max(1, filters.sinceDays || 7)),
      "--ats",
      ats.join(","),
      "--limit",
      String(Math.max(1, filters.limitPerAts || 150)),
    ];
    if (useJson) args.push("--json");

    const child = spawn(process.execPath, args, {
      cwd: careerOpsRoot(),
      env: { ...process.env, CAREER_OPS_PORTALS: tempPortals },
    });

    const offers: DiscoveredOffer[] = [];
    const seen = new Set<string>();
    let currentAts: string = ats[0] || "";
    let pending: Omit<DiscoveredOffer, "url"> | null = null;
    let companiesScanned = 0;
    let unreachable = 0;
    let outBuf = "";
    let errBuf = "";
    let jsonOut = ""; // --json mode: the single stdout object accumulates here

    const killer = setTimeout(() => {
      try {
        child.kill("SIGTERM");
      } catch {
        /* ignore */
      }
    }, 230_000);

    // Live progress (atsStart / progress / atsDone) — in --json mode these human
    // lines arrive on STDERR; in legacy mode on STDOUT (handled inside handleLine).
    const handleProgressLine = (line: string) => {
      const atsM = line.match(ATS_START_RE);
      if (atsM) {
        currentAts = atsM[1];
        onEvent({ kind: "atsStart", ats: atsM[1], companies: Number(atsM[2]) });
        return;
      }
      const progM = line.match(PROGRESS_RE);
      if (progM) {
        onEvent({ kind: "progress", ats: currentAts, scanned: Number(progM[1]), total: Number(progM[2]), matches: Number(progM[3]) });
        return;
      }
      const doneAtsM = line.match(ATS_DONE_RE);
      if (doneAtsM) {
        onEvent({ kind: "atsDone", ats: currentAts, unreachable: Number(doneAtsM[1]) });
      }
    };

    const handleLine = (line: string) => {
      const trimmed = line.trim();
      if (pending && /^https?:\/\//i.test(trimmed)) {
        const url = trimmed.split(/\s+/)[0];
        if (!seen.has(url)) {
          seen.add(url);
          const offer: DiscoveredOffer = { ...pending, url, matchedKeyword: firstMatch(pending.title, filters.positive) };
          offers.push(offer);
          onEvent({ kind: "offer", offer });
        }
        pending = null;
        return;
      }
      if (pending) pending = null;

      const offerM = line.match(OFFER_RE);
      if (offerM) {
        pending = parseOfferLine(offerM[1], offerM[2], offerM[3]);
        return;
      }
      const atsM = line.match(ATS_START_RE);
      if (atsM) {
        currentAts = atsM[1];
        onEvent({ kind: "atsStart", ats: atsM[1], companies: Number(atsM[2]) });
        return;
      }
      const progM = line.match(PROGRESS_RE);
      if (progM) {
        onEvent({ kind: "progress", ats: currentAts, scanned: Number(progM[1]), total: Number(progM[2]), matches: Number(progM[3]) });
        return;
      }
      const doneAtsM = line.match(ATS_DONE_RE);
      if (doneAtsM) {
        onEvent({ kind: "atsDone", ats: currentAts, unreachable: Number(doneAtsM[1]) });
        return;
      }
      const compM = line.match(COMPANIES_RE);
      if (compM) {
        companiesScanned = Number(compM[1]);
        return;
      }
      const unreachM = line.match(UNREACHABLE_RE);
      if (unreachM) {
        unreachable = Number(unreachM[1]);
        return;
      }
      const sumM = line.match(SUMMARY_RE);
      if (sumM) {
        onEvent({ kind: "summary", companiesScanned, unreachable, matches: Number(sumM[1]) });
        return;
      }
    };

    child.stdout.on("data", (d: Buffer) => {
      if (useJson) {
        jsonOut += d.toString(); // one JSON object — parsed at close
        return;
      }
      outBuf += d.toString();
      const parts = outBuf.split(/\r\n|\r|\n/);
      outBuf = parts.pop() ?? "";
      for (const p of parts) handleLine(p);
    });
    child.stderr.on("data", (d: Buffer) => {
      errBuf += d.toString();
      const parts = errBuf.split(/\r?\n/);
      errBuf = parts.pop() ?? "";
      for (const p of parts) {
        if (!p.trim()) continue;
        if (useJson) handleProgressLine(p); // human progress lives on stderr in --json mode
        onEvent({ kind: "log", line: p.trim() });
      }
    });

    child.on("error", (e) => {
      clearTimeout(killer);
      cleanupTempPortals(tempPortals);
      onEvent({ kind: "error", message: e instanceof Error ? e.message : "scanner failed to start" });
      resolve(offers);
    });
    child.on("close", () => {
      clearTimeout(killer);
      cleanupTempPortals(tempPortals);
      if (useJson) {
        let j: ScanJson | null = null;
        try {
          j = JSON.parse(jsonOut.trim()) as ScanJson;
        } catch {
          j = null;
        }
        if (j && Array.isArray(j.offers)) {
          for (const o of j.offers) {
            const url = (o.url || "").trim();
            if (!url || seen.has(url) || !o.company || !o.title) continue;
            seen.add(url);
            const source = o.source || `${currentAts}-full`;
            const offer: DiscoveredOffer = {
              company: o.company,
              title: o.title,
              location: o.location || "",
              postedAt: o.postedAt || "",
              ats: source.replace(/-full$/, ""),
              source,
              url,
              matchedKeyword: firstMatch(o.title, filters.positive),
            };
            offers.push(offer);
            onEvent({ kind: "offer", offer });
          }
          onEvent({
            kind: "summary",
            companiesScanned: j.companiesScanned ?? 0,
            unreachable: j.unreachableBoards ?? 0,
            matches: j.postingsKept ?? offers.length,
            companiesAvailable: j.companiesAvailable,
            capHit: j.capHit,
            datasetStatus: j.datasetStatus,
            postingsDroppedNoDate: j.postingsDroppedNoDate,
          });
        } else {
          // --json requested but stdout didn't parse — surface honestly rather than
          // silently returning 0 (defensive; shouldn't happen once the probe passed).
          onEvent({ kind: "error", message: "The scanner returned no readable output." });
        }
        resolve(offers);
        return;
      }
      if (outBuf.trim()) handleLine(outBuf);
      resolve(offers);
    });
  });
}

import fs from "node:fs";
import path from "node:path";
import * as yaml from "js-yaml";
import { careerOpsRoot } from "@/lib/career-ops";
import { CANONICAL_STATES } from "@/lib/format";

/**
 * ACL for templates/states.yml — the SINGLE SOURCE OF TRUTH for canonical
 * application states (career-ops writer + dashboard reader both read it). Per the
 * web↔core contract we READ it live and never hardcode the list.
 *
 * The hand-maintained FALLBACK that used to live here is gone. It promised to be
 * "kept identical to the file" and was not: it shipped without `hired` (#2282)
 * and later drifted 31 aliases behind. The core states the rule outright in
 * followup-cadence.mjs — "a fallback copy is the same copy in disguise and drifts
 * the same way" — and two incidents in this file proved it.
 *
 * The degraded path now derives from CANONICAL_STATES, the list CI already
 * freezes against states.yml (test-all §55.3b). So when states.yml is unreadable
 * we accept exactly what the UI is able to offer — labels only, no aliases —
 * and there is no second list that can drift on its own.
 */
export type CanonicalState = {
  id: string;
  label: string;
  aliases: string[];
  description: string;
  group: string;
};

const FALLBACK: CanonicalState[] = CANONICAL_STATES.map((label) => ({
  id: label.toLowerCase(),
  label,
  aliases: [],
  description: "",
  group: label.toLowerCase(),
}));

/**
 * Cached per resolved states.yml path and keyed on the file's mtime+size (one
 * statSync per call, no full read), mirroring loadHeaderAliases in
 * tracker-table.mjs.
 *
 * A bare `if (cache) return cache` made the "READ it live" contract above true
 * only for the first request a server process ever served: a core update that
 * rewrote templates/states.yml (git pull, update-system.mjs apply) was then
 * invisible until restart, so a newly canonical status was rejected by
 * POST /api/status and a removed one kept being accepted.
 *
 * Failures are NEVER cached, so a states.yml that is momentarily unreadable
 * falls back for that call only, instead of pinning FALLBACK for the lifetime
 * of the process.
 */
const statesCache = new Map<string, { mtimeMs: number; size: number; states: CanonicalState[] }>();

export function readCanonicalStates(): CanonicalState[] {
  const file = path.join(careerOpsRoot(), "templates", "states.yml");
  try {
    const { mtimeMs, size } = fs.statSync(file);
    const cached = statesCache.get(file);
    if (cached && cached.mtimeMs === mtimeMs && cached.size === size) return cached.states;
    const raw = fs.readFileSync(file, "utf8");
    const doc = yaml.load(raw) as { states?: unknown };
    const list = Array.isArray(doc?.states) ? doc.states : null;
    if (list && list.length) {
      const parsed: CanonicalState[] = [];
      for (const s of list as Record<string, unknown>[]) {
        if (!s || typeof s.label !== "string") continue;
        parsed.push({
          id: typeof s.id === "string" ? s.id : s.label.toLowerCase(),
          label: s.label,
          aliases: Array.isArray(s.aliases) ? s.aliases.filter((a): a is string => typeof a === "string") : [],
          description: typeof s.description === "string" ? s.description : "",
          group: typeof s.dashboard_group === "string" ? s.dashboard_group : (typeof s.id === "string" ? s.id : s.label.toLowerCase()),
        });
      }
      if (parsed.length) {
        statesCache.set(file, { mtimeMs, size, states: parsed });
        return parsed;
      }
    }
    // Readable but unusable (empty/!states) — drop any stale entry so a
    // repaired file is picked up on the next request rather than after a
    // restart, and fall back for this call only.
    statesCache.delete(file);
  } catch {
    /* unreadable — fall back for this call, never cache the failure */
  }
  return FALLBACK;
}

export function canonicalLabels(): string[] {
  return readCanonicalStates().map((s) => s.label);
}

/**
 * Fold a raw status the SAME way the core's foldStatusInput does
 * (tracker-utils.mjs). A bare toLowerCase() is not enough: JS lowercases the
 * Turkish dotted capital `İ` to `i` + U+0307 and the mark survives, so every
 * all-caps Turkish status ("TEKLİF", "KABUL EDİLDİ") missed every alias here
 * while the CLI resolved it — the web answered HTTP 400 for rows the core
 * considered perfectly canonical.
 *
 * NO `NFD`, and that is the whole safety property (5df43e7): NFKC leaves ż, ė
 * and ġ as single precomposed code points this strip cannot reach, while
 * `i` + U+0307 has no precomposed form and stays exposed. Decomposing first
 * looks equivalent and collapses Żubr/Zubr.
 */
function foldStatusInput(input: string): string {
  return String(input ?? "")
    .replace(/\*\*/g, "")
    .trim()
    .normalize("NFKC")
    .toLowerCase()
    .replace(/̇/gu, "");
}

/** Map any raw status (label/id/alias, case-insensitive) to its canonical label,
 *  or null if unrecognized. */
export function canonicalizeStatus(raw: string): string | null {
  const q = foldStatusInput(raw);
  if (!q) return null;
  for (const s of readCanonicalStates()) {
    if (foldStatusInput(s.label) === q || foldStatusInput(s.id) === q || s.aliases.some((a) => foldStatusInput(a) === q)) {
      return s.label;
    }
  }
  return null;
}

import path from "node:path";
import { pathToFileURL } from "node:url";
import { careerOpsRoot } from "@/lib/career-ops";
import { normalizeTextKey as fallbackKey } from "./normalize-text-key.mjs";

/**
 * ACL for the core's `normalizeTextKey` (tracker-parse.mjs) — the shared
 * matching/dedup key helper that scan.mjs and tracker-parse.mjs use (#2569).
 *
 * DERIVED, NOT COPIED (#2369, #2666). The web used to reimplement this with
 * `[^a-z0-9]`, which deletes every non-ASCII letter: "Nestlé" keyed to "nestl",
 * "Škoda" to "koda" and "日本電産" to the empty string. Two companies could then
 * collide after stripping and a genuinely new offer got suppressed as "already
 * evaluated" — a job the user never saw, with no signal.
 *
 * We can't `import` it statically: the core lives in the USER's checkout,
 * resolved at runtime via careerOpsRoot(), and is not a build dependency of this
 * app. So we import it dynamically per resolved root and cache the module —
 * keyed by path, and NEVER caching a failure (the lesson from #2590, where a
 * cached fallback pinned stale definitions for the process lifetime).
 *
 * Consequence, by design: the web keys with the normalizeTextKey of the user's
 * OWN core, so web dedup always matches their CLI dedup. Version skew is
 * semantic, and that's the correct behaviour — not a bug to paper over.
 *
 * Client components cannot use this ACL (Node-only). They import the Unicode-safe
 * mirror from normalize-text-key.mjs instead — same algorithm, parity-tested
 * against the core so [^a-z0-9] cannot creep back in.
 */

type NormalizeTextKey = (value: unknown, separator?: string) => string;

const modCache = new Map<string, NormalizeTextKey>();

let warned = false;

/** Resolve the core's normalizeTextKey for the current root, or the fallback. */
export async function getNormalizeTextKey(): Promise<NormalizeTextKey> {
  const file = path.join(careerOpsRoot(), "tracker-parse.mjs");
  const hit = modCache.get(file);
  if (hit) return hit;
  try {
    const mod = await import(/* webpackIgnore: true */ pathToFileURL(file).href);
    const fn = mod?.normalizeTextKey;
    if (typeof fn === "function") {
      modCache.set(file, fn); // only successes are cached (#2590)
      return fn;
    }
    if (!warned) {
      warned = true;
      console.warn(
        `[career-ops] ${file} has no normalizeTextKey export — company matching falls back to a local Unicode-safe key. Update career-ops to keep web dedup identical to CLI dedup.`,
      );
    }
  } catch {
    if (!warned) {
      warned = true;
      console.warn(
        `[career-ops] could not load ${file} — company matching falls back to a local Unicode-safe key. Update career-ops to keep web dedup identical to CLI dedup.`,
      );
    }
  }
  return fallbackKey;
}

import path from "node:path";
import { pathToFileURL } from "node:url";
import { careerOpsRoot } from "@/lib/career-ops";

/**
 * ACL for the core's tracker lock (`tracker-utils.mjs`).
 *
 * WHY A WEB ROUTE NEEDS IT. `atomicWrite` makes the WRITE atomic, not the
 * read-modify-write around it. Two writers each read the whole tracker, each
 * edit their own row, each rename their full copy back: the second discards the
 * first's change. Every call succeeds, the file is well-formed at every instant,
 * and one row silently reverts (#2900). Reproduced before fixing:
 *
 *   row 1 → Applied     (wanted Applied)
 *   row 2 → Evaluated   (wanted Interview)   ← lost, no error anywhere
 *
 * The other writer is not hypothetical: the web exists to be used ALONGSIDE the
 * CLI, and `set-status.mjs`, `mark-pdf-ready.mjs` and `reserve-report-num.mjs`
 * all take this lock already.
 *
 * NOT `run-registry`'s acquireTrackerWrite(): that is an in-memory counter which
 * tells this process whether a run is in flight. It cannot see another process.
 * Two guards, different scopes — the reason this survived review is that the
 * route looked protected.
 *
 * THE LOCK IS NOT REENTRANT (checked: no owner/pid self-check in
 * tracker-utils.mjs). So a caller holding it must never invoke a core script
 * that takes it too — that self-deadlocks until the timeout. Direct writers only.
 *
 * A crashed holder does NOT wedge the tracker: `lockCanRecover` reads the
 * owner's pid and recovers when that process is gone. But a LIVE process that
 * leaks the lock (a throw with no `finally`) keeps its pid alive, so recovery
 * waits out staleMs — hence the mandatory `finally` in withTrackerLock.
 */
type CoreLock = { release: () => void | Promise<void> };
type AcquireFn = (lockDir: string, options: Record<string, unknown>) => Promise<CoreLock>;
type LockDirFn = (trackerPath: string) => string;

/** Cached per resolved module path; failures are NEVER cached, so a repaired or
 *  newly-installed checkout is picked up on the next request (#2590). */
const modCache = new Map<string, { acquire: AcquireFn; lockDirFor: LockDirFn }>();

async function loadCoreLock() {
  const file = path.join(careerOpsRoot(), "tracker-utils.mjs");
  const cached = modCache.get(file);
  if (cached) return cached;
  const mod = await import(/* webpackIgnore: true */ pathToFileURL(file).href);
  if (typeof mod.acquireTrackerLock !== "function" || typeof mod.trackerLockDirFor !== "function") {
    throw new Error("tracker-utils.mjs has no acquireTrackerLock/trackerLockDirFor");
  }
  const api = { acquire: mod.acquireTrackerLock as AcquireFn, lockDirFor: mod.trackerLockDirFor as LockDirFn };
  modCache.set(file, api);
  return api;
}

/** Thrown when the lock is held by someone else for longer than we will wait. */
export class TrackerBusyError extends Error {
  constructor() {
    super("tracker is being written by another process");
    this.name = "TrackerBusyError";
  }
}

/**
 * Run `fn` holding the core's tracker lock, and release it on EVERY path.
 *
 * The timeout is deliberately far shorter than the CLI's 60s: this runs inside
 * an HTTP handler, where a minute of silence is indistinguishable from a hang.
 * Failing fast lets the caller answer 409 and the user retry, which is a better
 * experience than a request that eventually succeeds after the user gave up.
 *
 * @param trackerFile absolute path to data/applications.md
 * @param fn the read-modify-write to run under the lock
 */
export async function withTrackerLock<T>(trackerFile: string, fn: () => T | Promise<T>): Promise<T> {
  const { acquire, lockDirFor } = await loadCoreLock();
  let lock: CoreLock;
  try {
    lock = await acquire(lockDirFor(trackerFile), {
      timeoutMs: Number(process.env.CAREER_OPS_WEB_LOCK_TIMEOUT_MS) || 5_000,
      retryMs: 50,
      tracker: trackerFile,
    });
  } catch {
    throw new TrackerBusyError();
  }
  try {
    return await fn();
  } finally {
    // MANDATORY. A leaked lock on a long-lived server process is worse than the
    // bug this fixes: the holder's pid stays alive, so the core's stale-recovery
    // will not reclaim it and the user's own CLI is locked out until staleMs.
    await lock.release();
  }
}

/**
 * Canonical posting-URL key — algorithm mirror of the core's `normalizeUrl`
 * in url-key.mjs (root).
 *
 * Plain .mjs (same pattern as normalize-text-key.mjs) so node:test and client
 * bundles can import it without a TS runner or Node-only deps — this file has
 * none, same as the core it mirrors (only the global `URL`).
 *
 * WHY A COPY EXISTS AT ALL: the live core lives in the user's career-ops
 * checkout and is resolved at runtime via careerOpsRoot() — unavailable to the
 * client bundle. Unlike normalize-text-key.mjs's split (a Node-only live
 * loader server-side, this mirror client-side), the URL key here is used to
 * build ONE Set server-side (assembleDedupContext, from data/scan-history.tsv)
 * that the CLIENT then does membership lookups against on each AI-streamed
 * offer (explore-ai.ts's canon()). Server and client MUST key with the exact
 * same function or `known.has(key)` silently stops matching anything — so both
 * sides import this one mirror rather than the server preferring a live-loaded
 * copy that could drift from what the client bundle was built with.
 *
 * Keep the body byte-for-byte aligned with url-key.mjs `normalizeUrl`. The
 * parity test in tests/lib/url-key.test.mjs fails the build if they drift.
 *
 * UNDER-STRIP ON PURPOSE (see the root file's docstring for the full RFC 3986
 * rationale). Never add path/query lowercasing or a broader strip list here:
 * that is exactly the over-normalization that collapsed two different
 * Greenhouse postings (same host+path, distinct `?gh_jid=`) into one dedup
 * key and silently dropped every opening after the first at that employer —
 * the bug this mirror exists to stop reintroducing.
 */

// Query params that identify a click/campaign, never the posting itself. Keep
// this list literal and board-specific, identical to the core's denylist.
const TRACKING_PARAMS = [
  /^utm_/i, /^gh_src$/i, /^fbclid$/i, /^gclid$/i,
  /^mc_cid$/i, /^mc_eid$/i, /^igshid$/i, /^_hsenc$/i, /^_hsmi$/i, /^trk$/i, /^trackingid$/i,
];

/**
 * Reduce a posting URL to a stable comparison key.
 *
 * @param {string} raw - A posting URL (or any string).
 * @returns {string} A normalized key, or '' when there is nothing to key on.
 *   '' means NO KEY — callers must treat it as unknown, never as a value that
 *   can match another ''.
 */
export function normalizeUrl(raw) {
  if (typeof raw !== "string") return "";
  const s = raw.trim();
  if (!s) return "";

  let u;
  try {
    u = new URL(s);
  } catch {
    return "";
  }

  if (u.protocol !== "http:" && u.protocol !== "https:") return "";

  u.protocol = "https:";
  u.hostname = u.hostname.toLowerCase();
  u.hash = "";

  const keep = [];
  for (const [k, v] of u.searchParams.entries()) {
    if (!TRACKING_PARAMS.some((re) => re.test(k))) keep.push([k, v]);
  }
  keep.sort((x, y) => (x[0] !== y[0] ? (x[0] < y[0] ? -1 : 1) : (x[1] < y[1] ? -1 : x[1] > y[1] ? 1 : 0)));
  u.search = "";
  for (const [k, v] of keep) u.searchParams.append(k, v);

  if (u.pathname.length > 1 && u.pathname.endsWith("/")) {
    u.pathname = u.pathname.slice(0, -1);
  }

  return u.toString();
}

export default normalizeUrl;

// Client-safe (no node). Deterministic "is this CV good enough to score?" signal —
// ZERO tokens. Advisory only: it drives a green-check vs amber hint, NEVER blocks
// saving (the minimal-CV principle: even a rough parse is enough for a first score).

export type CvReadiness = { scoreable: boolean; words: number; hasExperience: boolean; hasSkills: boolean; hint?: string };

export function cvReadiness(md: string): CvReadiness {
  const text = (md || "").trim();
  const words = text ? text.split(/\s+/).length : 0;
  const hasExperience = /(^|\n)#{1,3}\s*(experience|work|employment|empleo|experiencia)/i.test(text) || /\b(20\d\d)\s*[-–—]\s*(20\d\d|present|now|actualidad)/i.test(text);
  const hasSkills = /(^|\n)#{1,3}\s*(skills|technologies|competenc|habilidad)/i.test(text);
  const scoreable = words >= 80 && (hasExperience || hasSkills || words >= 200);
  let hint: string | undefined;
  if (!scoreable) hint = words < 40 ? "That's very short — add your experience for real matches (you can save anyway)." : "Looks thin — add a role or two for better matches (you can save anyway).";
  return { scoreable, words, hasExperience, hasSkills, hint };
}

// ── CV ingest stream markers (parallel to the <<act:>>/<<offer:>> envelopes) ──
export type CvSeed = { title?: string; roles?: string[]; location?: string };
export type CvIngestResult = { markdown: string; seed: CvSeed | null; error: string | null; trace: string };

/** Parse the full accumulated ingest stream text into its parts. Tolerant: a
 *  still-streaming buffer just yields partial markdown + the pre-start trace. */
export function parseCvStream(buf: string): CvIngestResult {
  const errM = buf.match(/<<cv:error>>\s*(\{[^}]*\})/);
  if (errM) {
    let reason = "unreadable";
    try {
      reason = JSON.parse(errM[1]).reason || reason;
    } catch {
      /* keep default */
    }
    return { markdown: "", seed: null, error: reason, trace: buf.split("<<cv:error>>")[0].trim() };
  }

  const start = buf.indexOf("<<cv:start>>");
  const trace = (start === -1 ? buf : buf.slice(0, start)).replace(/<<cv:[a-z]+>>.*$/s, "").trim();
  if (start === -1) return { markdown: "", seed: null, error: null, trace };

  const afterStart = buf.slice(start + "<<cv:start>>".length);
  const end = afterStart.indexOf("<<cv:end>>");
  const markdown = (end === -1 ? afterStart : afterStart.slice(0, end)).replace(/^\s*\n/, "").trimEnd();

  let seed: CvSeed | null = null;
  const seedM = buf.match(/<<cv:seed>>\s*(\{[\s\S]*?\})/);
  if (seedM) {
    try {
      const j = JSON.parse(seedM[1]);
      seed = {
        title: typeof j.title === "string" ? j.title : undefined,
        roles: Array.isArray(j.roles) ? j.roles.filter((r: unknown): r is string => typeof r === "string").slice(0, 6) : undefined,
        location: typeof j.location === "string" ? j.location : undefined,
      };
    } catch {
      /* malformed seed → ignore */
    }
  }
  return { markdown, seed, error: null, trace };
}

/**
 * cv-envelope.mjs — the pdf-mode agent's output channel (#2185).
 *
 * pdf mode used to hand the agent `Write`/`Edit` so it could save the tailored
 * CV itself. Tool grants are tool-name-only, not path-scoped, so a prompt
 * injection in a job posting or an evaluation report — both of which enter that
 * agent's context — could redirect a write to cv.md, data/applications.md or
 * .env. Rather than fence those writes, pdf mode no longer grants them: the
 * agent emits the tailored HTML inline in a `<<cv-html …>>` envelope and the
 * BACKEND persists it. That completes the arc #2182 started, which moved
 * rendering out of the agent for the same reason.
 *
 * Plain .mjs (same pattern as pdf-paths.mjs / pdf-render.mjs) so this can be
 * unit-tested with `node --test`, no TypeScript build step.
 *
 * The envelope's rules are all fail-closed, because the alternative to a clean
 * failure is the backend building from attacker-influenced input and reporting
 * success: markers only count on a line of their own, the FIRST closer wins (an
 * injected closer truncates instead of escaping), and more than one envelope is
 * refused outright rather than guessed at.
 */
import { PAGE_FORMATS, DEFAULT_PAGE_FORMAT } from "./page-formats.mjs";

// Markers must own their line — otherwise an agent merely *mentioning* the
// syntax in its prose (or a CLI echoing the prompt, as `codex exec` does) would
// open or close an envelope.
// The marker spellings are exported so the PROMPT that asks for them, the parser
// that reads them, and any guard that checks them all derive from one string.
// Restating them by hand in the prompt is how you get a rename that breaks every
// pdf run at runtime with the whole suite still green.
export const OPEN_MARK = "<<cv-html";
export const CLOSE_MARK = "<</cv-html>>";

// One pattern source per marker. The closer needs two compiled flavours because
// `exec` on a global regex advances `lastIndex` between calls, so the single-shot
// lookup and the scanning one must not share an object; the opener is only ever
// scanned with `matchAll`, which clones and needs just the one.
const OPENER_SRC = String.raw`^<<cv-html(?:[ \t]+format="([^"\n]*)")?>>[ \t]*$`;
const CLOSER_SRC = String.raw`^<<\/cv-html>>[ \t]*$`;
const OPENER = new RegExp(OPENER_SRC, "gm");
const CLOSER = new RegExp(CLOSER_SRC, "m");
const CLOSER_ALL = new RegExp(CLOSER_SRC, "gm");

/**
 * The envelope contract, as the agent is told it. Lives here beside the parser so
 * the two cannot drift; route.ts interpolates it into the pdf prompt.
 *
 * The markers are deliberately described MID-LINE (inside backticks) rather than
 * shown on their own lines: `codex exec` echoes its prompt to stdout, and a
 * line-start marker in that echo parses as a second envelope, failing the run.
 *
 * The page formats are spelled out literally rather than interpolated from
 * DEFAULT_PAGE_FORMAT: that constant is the parser's fallback for an agent that
 * declares NOTHING, which is a different question from what the agent should
 * choose. Tying them together once produced "choose letter … otherwise letter".
 *
 * It says "do not save" rather than "you have no write tools": that claim is only
 * true on Claude Code. The six CLIs invoked via clis.ts's bare args keep their own
 * default tool access, and telling an agent something false about its own
 * capabilities invites it to test the claim.
 */
export const CV_ENVELOPE_INSTRUCTION =
  `Do NOT save or edit any file — the platform persists your output for you. Instead OUTPUT the finished HTML inline, between two marker lines. The first line contains only the opening marker carrying your chosen page format — \`${OPEN_MARK} format="a4">>\` or \`${OPEN_MARK} format="letter">>\`, and nothing else on that line. Choose letter for a US/Canada company, otherwise a4. Then the complete HTML document, then a final line containing only \`${CLOSE_MARK}\`. Each marker appears exactly once. Emit the WHOLE document from <!DOCTYPE html> to </html> — never abbreviate, summarize, or write "unchanged"; the platform renders exactly these bytes and nothing else.`;

/**
 * @typedef {Object} CvEnvelope
 * @property {true} ok
 * @property {string} html - The tailored CV HTML, byte-exact as emitted.
 * @property {"a4"|"letter"} format - Page format for generate-pdf.mjs.
 * @property {string[]} warnings - Non-fatal issues to surface in the run log.
 */

/**
 * Extract the tailored CV HTML and page format from an agent's full output.
 *
 * Returns a result rather than throwing so the caller (the /api/run close
 * handler) can route the failure through the same honesty gate as every other
 * "this run produced nothing usable" case.
 *
 * @param {string} text - Everything the agent emitted, concatenated.
 * @returns {CvEnvelope | {ok: false, error: string}}
 */
export function parseCvEnvelope(text) {
  if (typeof text !== "string") {
    return { ok: false, error: "No agent output to read a CV envelope from." };
  }
  // Normalize CRLF once so the line-anchored markers match on a Windows stream
  // and no stray \r rides into the HTML handed to the renderer.
  const normalized = text.replace(/\r\n/g, "\n");

  const openers = [...normalized.matchAll(OPENER)];
  if (openers.length === 0) {
    return { ok: false, error: "The agent emitted no <<cv-html>> envelope, so there is no CV to render." };
  }
  if (openers.length > 1) {
    // Choosing one would be choosing blind — an injected envelope looks exactly
    // like the real one from here.
    return { ok: false, error: `Found ${openers.length} <<cv-html>> envelopes; refusing to guess which is the real CV.` };
  }

  const opener = openers[0];
  const afterOpener = normalized.slice(opener.index + opener[0].length);
  const closer = CLOSER.exec(afterOpener);
  if (!closer) {
    return { ok: false, error: "The <<cv-html>> envelope was never closed — the CV output is incomplete." };
  }

  // The opener match stops before its newline and the closer starts on its own
  // line, so exactly one delimiting newline sits on each side of the body.
  const html = afterOpener.slice(0, closer.index).replace(/^\n/, "").replace(/\n$/, "");
  if (!html.trim()) {
    return { ok: false, error: "The <<cv-html>> envelope was empty — no CV was tailored." };
  }
  // A closing </html> is what distinguishes a whole document from one the agent
  // cut off mid-emission — the realistic failure when emitting 15-25 KB inline.
  // This belongs here, not in the caller: the caller reports THIS error string, so
  // splitting the rule out would leave the user with a generic message.
  if (!/<\/html\s*>/i.test(html)) {
    return { ok: false, error: "The CV was cut off before its closing </html> tag — the output is incomplete." };
  }

  const warnings = [];
  const declared = opener[1];
  let format = DEFAULT_PAGE_FORMAT;
  if (declared === undefined) {
    warnings.push(`The agent declared no page format; defaulting to ${DEFAULT_PAGE_FORMAT}.`);
  } else {
    const lower = declared.trim().toLowerCase();
    if (PAGE_FORMATS.has(lower)) format = lower;
    else warnings.push(`Unrecognized page format "${declared}"; defaulting to ${DEFAULT_PAGE_FORMAT}.`);
  }

  return { ok: true, html, format, warnings };
}

/**
 * Could `line` still become a marker once more characters arrive?
 *
 * True both while the text is a prefix of a marker (`<`, `<<c`) and once it has
 * passed one (`<<cv-html format="a4"` is still growing towards `>>`).
 *
 * @param {string} line - The unterminated final line.
 * @returns {boolean}
 */
function couldBecomeMarker(line) {
  return (
    // Still growing into a marker (`<`, `<<c`)...
    OPEN_MARK.startsWith(line) || CLOSE_MARK.startsWith(line) ||
    // ...or already past it and still growing towards `>>`.
    line.startsWith(OPEN_MARK) || line.startsWith(CLOSE_MARK)
  );
}

/**
 * First match of `re` in `s` whose line is terminated by a newline.
 *
 * An unterminated match is deliberately ignored: more characters could still
 * arrive on that line, and acting early is how a half-written marker leaks into
 * the rendered log (the flicker act-envelope.mjs documents).
 *
 * @param {RegExp} re - Line-anchored marker pattern; must carry the `g` flag.
 * @param {string} s
 * @returns {{start: number, end: number} | null} `end` consumes the newline.
 */
function completeMarker(re, s) {
  for (const m of s.matchAll(re)) {
    const after = m.index + m[0].length;
    if (s[after] === "\n") return { start: m.index, end: after + 1 };
  }
  return null;
}

/**
 * Streaming companion to parseCvEnvelope: accumulates the agent's full output
 * for parsing while keeping the envelope body out of the user's run log.
 *
 * Both halves are needed at once. The route must see every byte to reconstruct
 * the CV, but streaming 15-25 KB of raw HTML into the log would bury the agent's
 * actual narration. Chunk boundaries fall wherever the transport likes, so the
 * markers are matched across pushes rather than per chunk.
 *
 * @returns {{push: (chunk: string) => string, flush: () => string, result: () => (CvEnvelope | {ok: false, error: string})}}
 *   `push` returns the text safe to display, `flush` releases anything still
 *   held at end of stream, `result` parses everything pushed so far.
 */
export function createCvEnvelopeFilter() {
  let raw = "";       // everything pushed, verbatim — what result() parses
  let pending = "";   // display work buffer (CRLF-normalized so lines match)
  let carry = "";     // a trailing "\r" whose "\n" may be in the next chunk
  let inBody = false;

  return {
    push(chunk) {
      const text = String(chunk ?? "");
      raw += text;
      // Normalizing per chunk is not enough: a CRLF split across two pushes would
      // leave a lone \r that `[ \t]*$` can never match, so no marker is ever
      // recognized and the ENTIRE body streams into the run log with ok:true and
      // no signal. Hold back a trailing \r until its partner arrives.
      const withCarry = carry + text;
      carry = withCarry.endsWith("\r") ? "\r" : "";
      pending += (carry ? withCarry.slice(0, -1) : withCarry).replace(/\r\n/g, "\n");
      let display = "";
      for (;;) {
        if (!inBody) {
          const opener = completeMarker(OPENER, pending);
          if (opener) {
            display += pending.slice(0, opener.start);
            pending = pending.slice(opener.end);
            inBody = true;
            continue;
          }
          // Everything up to the unterminated final line is settled: a marker in
          // it would already have matched. Hold that line only if it might grow
          // into a marker.
          const tailStart = pending.lastIndexOf("\n") + 1;
          const cut = couldBecomeMarker(pending.slice(tailStart)) ? tailStart : pending.length;
          display += pending.slice(0, cut);
          pending = pending.slice(cut);
          return display;
        }
        const closer = completeMarker(CLOSER_ALL, pending);
        if (closer) {
          // The body itself is never displayed — only skipped past.
          pending = pending.slice(closer.end);
          inBody = false;
          continue;
        }
        // Settled body lines are never displayed, so drop them; keep only the
        // unterminated final line, which may be a closer still being written.
        // (`raw` retains every byte for parsing — this buffer is display-only.)
        const tailStart = pending.lastIndexOf("\n") + 1;
        pending = pending.slice(tailStart);
        return display;
      }
    },

    flush() {
      // Held text that never became a marker is prose, and dropping it would
      // silently lose the tail of the log. Body leftovers are already discarded.
      const held = inBody ? "" : pending + carry;
      pending = "";
      carry = "";
      return held;
    },

    result() {
      return parseCvEnvelope(raw);
    },
  };
}

// Client-safe (NO node imports) tolerant streaming parser for the AI-search
// `<<offer:{...}>>` envelopes emitted by modes/discover.md. Modeled on the
// assistant console's <<act:>> envelope parsing, factored out so the grammar
// can't drift. The load-bearing requirement: an envelope (or its opener) split
// across stream chunk boundaries must BUFFER, never flush as garbage or drop.

import type { DiscoveredOffer } from "./explore";
import { pendingOpenerLen } from "./stream-parse.mjs";
import { normalizeUrl } from "./core/url-key.mjs";

const OPEN = "<<offer:";
const CLOSE = ">>";

export type AiTraceChunk =
  | { kind: "offer"; offer: DiscoveredOffer }
  | { kind: "narration"; text: string }
  | { kind: "malformed"; raw: string };

/**
 * Normalize a URL for dedup. Delegates to the parity-tested normalizeUrl
 * mirror (url-key.mjs) instead of host+pathname — a bare host+path key
 * discarded the query string unconditionally, so two DIFFERENT postings that
 * share a path and differ only by a functional query id (e.g. Greenhouse's
 * `?gh_jid=`) collapsed onto one key and every opening after the first at
 * that host+path was silently dropped from AI Discover results.
 *
 * Can return '' for an unparseable / non-http(s) input — callers must treat
 * that as NO KEY, never as a value that matches another ''.
 */
export function canon(u: string): string {
  return normalizeUrl(u);
}

function toOffer(raw: unknown): DiscoveredOffer | null {
  if (!raw || typeof raw !== "object") return null;
  const o = raw as Record<string, unknown>;
  const url = typeof o.url === "string" ? o.url.trim() : "";
  if (!/^https?:\/\//i.test(url)) return null;
  const str = (v: unknown) => (typeof v === "string" ? v.trim() : "");
  const conf = o.confidence;
  return {
    url,
    company: str(o.company),
    title: str(o.title),
    location: str(o.location),
    postedAt: "", // AI gives only a human postedHint, never a trustworthy date
    ats: str(o.ats) || "other",
    source: "ai-search",
    verification: "unconfirmed",
    why: str(o.why) || undefined,
    postedHint: str(o.postedHint) || undefined,
    confidence: conf === "low" || conf === "medium" || conf === "high" ? conf : undefined,
  };
}

export function makeAiStreamParser(opts?: { knownUrls?: Set<string> }) {
  const known = opts?.knownUrls ?? new Set<string>();
  const seen = new Set<string>();
  let buf = "";

  return {
    feed(delta: string): AiTraceChunk[] {
      buf += delta;
      const out: AiTraceChunk[] = [];
      for (;;) {
        const open = buf.indexOf(OPEN);
        if (open === -1) {
          // No opener in view. Flush as narration — but hold back the longest
          // trailing run that could be the start of a split opener ("<<offe…"),
          // so an offer whose marker straddles a chunk boundary is never dropped
          // as garbage (#2290). A fixed-length tail check missed the shorter
          // partial openers ("<<", "<<off") preceded by other text.
          const hold = pendingOpenerLen(buf, OPEN);
          const text = hold ? buf.slice(0, buf.length - hold) : buf;
          if (text.trim()) out.push({ kind: "narration", text });
          buf = hold ? buf.slice(buf.length - hold) : "";
          break;
        }
        const before = buf.slice(0, open);
        if (before.trim()) out.push({ kind: "narration", text: before });
        const close = buf.indexOf(CLOSE, open + OPEN.length);
        if (close === -1) {
          // Envelope still streaming — keep from the opener onward and wait.
          buf = buf.slice(open);
          break;
        }
        const json = buf.slice(open + OPEN.length, close);
        buf = buf.slice(close + CLOSE.length);
        let offer: DiscoveredOffer | null = null;
        try {
          offer = toOffer(JSON.parse(json));
        } catch {
          offer = null;
        }
        if (!offer) {
          out.push({ kind: "malformed", raw: json.slice(0, 120) });
          continue;
        }
        const key = canon(offer.url);
        // '' means NO KEY (an unparseable-but-regex-passing url) — never treat
        // two such offers as duplicates of EACH OTHER just because both are ''.
        if (key && (seen.has(key) || known.has(key))) continue; // intra-run + known dedup
        if (key) seen.add(key);
        out.push({ kind: "offer", offer });
      }
      return out;
    },
    /** Emit any trailing buffered narration when the stream ends. */
    flush(): AiTraceChunk[] {
      const text = buf;
      buf = "";
      return text.trim() ? [{ kind: "narration" as const, text }] : [];
    },
  };
}

// The cost-honesty taxonomy — a single source for the FREE vs $ boundary that the
// Explorer teaches by repetition. Discovery (finding roles) is structurally free:
// it calls no LLM. Only evaluation (scoring a role against your CV) spends tokens,
// and only when the user chooses it. The framing is always local-first: "your key,
// your AI, your machine."

export type CostClass = "free" | "free-network" | "spend" | "free-gemini";

export const COST_META: Record<CostClass, { label: string; tip: string }> = {
  "free-network": {
    label: "Free",
    tip: "Scans the public ATS network over HTTP. No AI, no tokens, nothing sent — and it writes nothing until you choose to add a role.",
  },
  free: {
    label: "Free",
    tip: "No tokens. Reads or writes local files only.",
  },
  spend: {
    label: "Uses tokens",
    tip: "Runs a real A–F evaluation on your own AI. This is the only thing that spends tokens — and only when you pick a role.",
  },
  "free-gemini": {
    label: "Free · Gemini",
    tip: "Evaluate with Google's free Gemini tier — no token cost.",
  },
};

// Classifies how a discovery run failed. Plain .mjs (same pattern as
// clean-chips.mjs) so tests/lib/explore-error.test.mjs can import it without a
// TS runner, and so the API route and the client classify from ONE definition.
//
// A run fails in two structurally different ways, and the Explore UI must tell
// them apart:
//
//   1. The scanner is ABSENT from this checkout: a data-only or pre-onboarding
//      install. /api/explore reports this BEFORE any stream starts. This is the
//      only failure the "Discovery needs the full toolkit" panel should cover,
//      because its call to action is "update career-ops".
//
//   2. The scanner RAN but errored: a transient/runtime failure surfaced through
//      the response stream after a 200 (e.g. "The scanner returned no readable
//      output."). The checkout is fine; the right next step is a retry.
//
// Decide on an explicit CODE in the response body, never on the free text of the
// error message and never on the HTTP status alone.
//
// Not the text, because runtime errors routinely contain the word "scanner" (and
// phrases like "isn't available"), so matching their text misreports a transient
// failure as a broken checkout and tells the user to update when nothing is
// wrong. That was the original defect.
//
// Not the status, because 400 is a SHARED channel and reading it as one meaning
// reintroduces the same misdiagnosis one layer up. /api/explore/ai alone returns
// three different 400s — malformed JSON, missing parameters, and MODE_MISSING —
// and a status-keyed check classified every one of them as "this checkout has no
// scanner". MODE_MISSING is the sharpest case: a real missing-capability error
// with its own copy, replaced by the scanner panel's. A code is a channel of its
// own, so a new 400 added tomorrow is a plain failure by default rather than
// silently inheriting the panel.
//
// This mirrors { code: "MODE_MISSING" } in app/api/explore/ai/route.ts, which is
// the established pattern for this in the app.

/** Machine-readable marker for "the scanner is absent from this checkout". */
export const SCANNER_MISSING_CODE = "SCANNER_MISSING";

/** HTTP status the route pairs with the code. Kept for the route; not a classifier. */
export const SCANNER_MISSING_STATUS = 400;

/** Default copy for the panel. Lives here so the route and its test share one string. */
export const SCANNER_MISSING_MESSAGE = "The discovery scanner isn't available in this checkout yet.";

/**
 * The exact JSON body the route returns for case 1.
 *
 * The route builds its response from this rather than an inline literal so the
 * producer and the classifier below cannot drift apart — a code the client
 * matches but the server never sends fails silently and looks like a UI bug.
 *
 * @param {string} [message] Override copy; defaults to SCANNER_MISSING_MESSAGE.
 */
export function scannerMissingBody(message = SCANNER_MISSING_MESSAGE) {
  return { code: SCANNER_MISSING_CODE, error: message };
}

/**
 * True only for the "scanner absent from this checkout" failure (case 1).
 *
 * Takes the PARSED RESPONSE BODY, not the HTTP status. Callers reach this on a
 * failure path where the body is whatever the server actually sent, so a missing,
 * null, or non-object body is a plain failure rather than an error — anything
 * unrecognised must fall through to the retry path, never to "update your
 * install".
 *
 * @param {unknown} body Parsed JSON response body.
 */
export function isScannerMissing(body) {
  return (
    typeof body === "object" &&
    body !== null &&
    /** @type {{code?: unknown}} */ (body).code === SCANNER_MISSING_CODE
  );
}

// Client-safe types + codec for the Explorer (job discovery). NO node imports —
// both client components and server routes import this for the shared shapes, so
// the filter contract, the discovered-offer shape, and the stream-event grammar
// can never drift between the two halves. Server-only logic (spawning the scanner,
// writing temp files) lives in lib/core/{scan,portals,pipeline}.ts.

export type AtsSource = "greenhouse" | "lever" | "ashby" | "workday";
export const ATS_SOURCES: AtsSource[] = ["greenhouse", "lever", "ashby", "workday"];
export const ATS_LABEL: Record<AtsSource, string> = {
  greenhouse: "Greenhouse",
  lever: "Lever",
  ashby: "Ashby",
  workday: "Workday",
};

/** The full UI filter state. The keyword/location lists mirror scan.mjs's
 *  buildTitleFilter / buildLocationFilter semantics; sinceDays/ats/limitPerAts map
 *  to scan-ats-full.mjs's --since / --ats / --limit. */
export type ExploreFilters = {
  positive: string[];
  negative: string[];
  allow: string[];
  block: string[];
  blockHard: string[];
  alwaysAllow: string[];
  sinceDays: number;
  ats: AtsSource[];
  limitPerAts: number;
};

export const DEFAULT_FILTERS: ExploreFilters = {
  positive: [],
  negative: [],
  allow: [],
  block: [],
  blockHard: [],
  alwaysAllow: [],
  sinceDays: 7,
  ats: [...ATS_SOURCES],
  limitPerAts: 150,
};

export type DiscoveredOffer = {
  url: string;
  company: string;
  title: string;
  location: string;
  /** YYYY-MM-DD, or "" when the engine reported n/a (AI offers always "") */
  postedAt: string;
  ats: string;
  source: string;
  /** which positive keyword matched the title (transparency, e.g. "ai" in "Nail") */
  matchedKeyword?: string;
  /** optional free-text ranking signal preserved to pipeline.md by the canonical
   *  writer (scan.mjs formatPipelineOffer). Generic and source-agnostic — an
   *  importer can attach a note; the deterministic scan omits it. */
  note?: string;
  // ── AI-search (modes/discover.md) additions — all optional, so the
  //    deterministic scan offer is unaffected (fields simply absent). ──
  /** present ONLY on AI offers → drives the "unverified" badge. AI finds can't be
   *  liveness-confirmed (AGENTS.md); the scan hits a live ATS API so it omits this. */
  verification?: "unconfirmed";
  /** one-line "why it matched" judgment (the thing a deterministic scan can't give) */
  why?: string;
  /** human freshness ("~5d ago", "unknown") shown when postedAt is "" */
  postedHint?: string;
  confidence?: "low" | "medium" | "high";
};

/** The two discovery surfaces: free deterministic Scan vs token-spending AI search. */
export type ExploreMode = "scan" | "ai";

/** Stream event grammar (NDJSON). `kind` discriminates. Discovery is FREE — the
 *  terminal `done` always carries cost {tokens:0, usd:0}. */
export type ScanEvent =
  | { kind: "start"; ats: string[]; sinceDays: number; limit: number; free: true }
  | { kind: "atsStart"; ats: string; companies: number }
  | { kind: "progress"; ats: string; scanned: number; total: number; matches: number }
  | { kind: "atsDone"; ats: string; unreachable: number }
  | { kind: "offer"; offer: DiscoveredOffer }
  | {
      kind: "summary";
      companiesScanned: number;
      unreachable: number;
      matches: number;
      // Authoritative degraded-vs-empty signals from the scanner's --json mode (#1199).
      // Absent on older local checkouts (the legacy human-stdout parse can't supply them).
      companiesAvailable?: number;
      capHit?: boolean;
      datasetStatus?: Record<string, "ok" | "stale" | "empty">;
      postingsDroppedNoDate?: number;
    }
  | { kind: "log"; line: string }
  | { kind: "error"; message: string }
  | { kind: "done"; count: number; offers: DiscoveredOffer[]; cost?: { tokens: number; usd: number } };

// cleanChips is defined in clean-chips.mjs (plain JS) so it can be shared
// with the test suite without a TypeScript runner. Import for internal use
// and re-export for external consumers (filter-builder.tsx, etc.).
import { cleanChips } from "./clean-chips.mjs";
export { cleanChips };

function clampNum(v: unknown, lo: number, hi: number, fallback: number): number {
  const n = Number(v);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(hi, Math.max(lo, Math.round(n)));
}

function cleanAts(v: unknown): AtsSource[] {
  if (!Array.isArray(v)) return [...ATS_SOURCES];
  const out = v
    .map((a) => String(a).toLowerCase())
    .filter((a): a is AtsSource => (ATS_SOURCES as string[]).includes(a));
  return out.length ? Array.from(new Set(out)) : [...ATS_SOURCES];
}

/** Apply a (possibly partial) action/assistant patch onto a base. The assistant
 *  emits {positive,negative,allow,block,alwaysAllow,since,ats,limit}. With
 *  merge=true, list fields are ADDED to the base; otherwise the given fields
 *  REPLACE. Unspecified fields are left as-is. */
export function parseExplorePatch(
  raw: Record<string, unknown>,
  base: ExploreFilters = DEFAULT_FILTERS,
  merge = false,
): ExploreFilters {
  const next: ExploreFilters = { ...base, ats: [...base.ats] };
  const lists: [keyof ExploreFilters, string][] = [
    ["positive", "positive"],
    ["negative", "negative"],
    ["allow", "allow"],
    ["block", "block"],
    ["blockHard", "blockHard"],
    ["alwaysAllow", "alwaysAllow"],
  ];
  for (const [field, key] of lists) {
    if (raw[key] === undefined) continue;
    const incoming = cleanChips(raw[key]);
    next[field] = (merge ? cleanChips([...(base[field] as string[]), ...incoming]) : incoming) as never;
  }
  if (raw.since !== undefined) next.sinceDays = clampNum(raw.since, 1, 60, base.sinceDays);
  if (raw.sinceDays !== undefined) next.sinceDays = clampNum(raw.sinceDays, 1, 60, base.sinceDays);
  if (raw.limit !== undefined) next.limitPerAts = clampNum(raw.limit, 50, 500, base.limitPerAts);
  if (raw.limitPerAts !== undefined) next.limitPerAts = clampNum(raw.limitPerAts, 50, 500, base.limitPerAts);
  if (raw.ats !== undefined) next.ats = cleanAts(raw.ats);
  return next;
}

/** URL <-> filters codec (so a search is shareable/restorable). */
export function filtersToParams(f: ExploreFilters): string {
  const sp = new URLSearchParams();
  if (f.positive.length) sp.set("q", f.positive.join(","));
  if (f.negative.length) sp.set("not", f.negative.join(","));
  if (f.allow.length) sp.set("loc", f.allow.join(","));
  if (f.block.length) sp.set("noloc", f.block.join(","));
  if (f.blockHard.length) sp.set("hardno", f.blockHard.join(","));
  if (f.alwaysAllow.length) sp.set("home", f.alwaysAllow.join(","));
  if (f.sinceDays !== DEFAULT_FILTERS.sinceDays) sp.set("since", String(f.sinceDays));
  if (f.ats.length !== ATS_SOURCES.length) sp.set("ats", f.ats.join(","));
  if (f.limitPerAts !== DEFAULT_FILTERS.limitPerAts) sp.set("limit", String(f.limitPerAts));
  return sp.toString();
}

export function paramsToFilters(sp: URLSearchParams, base: ExploreFilters = DEFAULT_FILTERS): ExploreFilters {
  const split = (s: string | null) => (s ? s.split(",") : undefined);
  return parseExplorePatch(
    {
      positive: split(sp.get("q")),
      negative: split(sp.get("not")),
      allow: split(sp.get("loc")),
      block: split(sp.get("noloc")),
      blockHard: split(sp.get("hardno")),
      alwaysAllow: split(sp.get("home")),
      since: sp.get("since") ?? undefined,
      ats: split(sp.get("ats")),
      limit: sp.get("limit") ?? undefined,
    },
    base,
  );
}

/** AI-search URL codec (so an AI hunt is shareable/restorable). */
export function aiToParams(intent: string): string {
  const sp = new URLSearchParams();
  sp.set("mode", "ai");
  if (intent.trim()) sp.set("intent", intent.trim());
  return sp.toString();
}

export function paramsToAi(sp: URLSearchParams): string | null {
  if (sp.get("mode") !== "ai") return null;
  return sp.get("intent") ?? "";
}

/** Is the search broad enough that "nothing found" means "you're current"
 *  (good news) rather than "loosen your filters" (actionable)? */
export function isBroadSearch(f: ExploreFilters): boolean {
  return f.positive.length <= 1 && f.block.length === 0 && f.allow.length === 0;
}

import path from "node:path";
import { careerOpsRoot } from "@/lib/career-ops";
import { withFollowupsLock, FollowupsBusyError } from "@/lib/core/followups-lock";

export { FollowupsBusyError };

// Server-only helpers shared by the follow-ups API routes (log + override).

/** data/follow-ups.md — the follow-up log + next-date pins (user layer). */
export function followupsLogPath(): string {
  return path.join(careerOpsRoot(), "data", "follow-ups.md");
}

// In-process serialization of follow-up mutations: POST log derives the next
// num from a read of the file, DELETE and the override routes do read-modify-
// write — unserialized, concurrent requests in THIS process could mint
// duplicate nums or drop lines. The web app is a single local server process,
// so a promise queue serializes them.
//
// WHAT THIS DOES **NOT** PROTECT: this queue only sees THIS process. It cannot
// see the user's CLI or the core's cadence seeder (followup-seed.mjs), which
// read-modify-write the SAME data/follow-ups.md. Its old comment claimed "no
// cross-process lock needed", and that false comfort is exactly why the gap
// survived — a reader who sees a guard stops looking for the one that is
// missing (the same shape as /api/status before #2903). Cross-process exclusion
// is the core FILE lock, reached via withFollowupsLock; this queue and that
// lock COMPOSE (see withFollowupsWrite) — neither replaces the other.
let queue: Promise<unknown> = Promise.resolve();
export function withLogLock<T>(fn: () => T | Promise<T>): Promise<T> {
  const run = queue.then(fn, fn);
  queue = run.then(
    () => undefined,
    () => undefined,
  );
  return run;
}

// The full guard for any data/follow-ups.md mutation. Order is load-bearing and
// agreed with the core maintainer (#3034): the in-process queue OUTSIDE, the
// cross-process file lock INSIDE.
//
//   withLogLock(() => withFollowupsLock(path, fn))
//
// Why this order: the queue reduces this process's N concurrent requests to ONE
// before the file lock is touched, so the file lock only ever arbitrates "the
// one active web request vs the user's CLI". Reversed, two of the user's own
// browser tabs would contend on the cross-process lock — one wins, the other
// eats the timeout and a 409 — for a race the free in-process queue already
// resolves. Every followups writer goes through here so no call site can get
// the nesting wrong.
export function withFollowupsWrite<T>(fn: () => T | Promise<T>): Promise<T> {
  return withLogLock(() => withFollowupsLock(followupsLogPath(), fn));
}

// Map a throw from withFollowupsWrite onto an HTTP response, consistently across
// the four followups mutation handlers. A contended lock is transient (someone
// else — the CLI, the seeder, another tab — holds it right now), so it is 409 +
// Retry-After, not a 500: the caller should retry, not treat the write as
// rejected. Anything else is a real failure on this machine → 500.
export function followupsWriteError(e: unknown, fallback = "write failed"): Response {
  if (e instanceof FollowupsBusyError) {
    return Response.json(
      { error: "follow-ups file is busy — try again in a moment" },
      { status: 409, headers: { "Retry-After": "1" } },
    );
  }
  return Response.json({ error: e instanceof Error ? e.message : fallback }, { status: 500 });
}

