];

export function isActivePath(href: string, pathname: string): boolean {
  return href === "/" ? pathname === "/" : pathname.startsWith(href);
}

// Same-origin / loopback guard for the local dashboard's API surface.
//
// The dashboard is local-first: its /api routes spawn child processes and read
// and write the user's files. A route that answers an unauthenticated request
// is therefore a remote-code-execution primitive, reachable two ways:
//
//   F1 — drive-by: any web page the user visits can POST to
//        http://localhost:3000/api/... in the background (classic CSRF).
//   F2 — LAN: if the dev server is bound to 0.0.0.0, anyone on the same
//        network can hit those routes directly.
//
// This module is the pure decision logic behind `middleware.ts`. It is kept
// free of node/next imports so it runs on the edge runtime and is unit
// testable in isolation. Two independent layers, both must pass:
//
//   Origin layer (F1): trust Sec-Fetch-Site when the browser sends it, fall
//     back to comparing Origin against Host for older/non-browser clients.
//   Host layer (F2): only answer on a loopback Host by default; extra hosts
//     require an explicit opt-in (CAREER_OPS_WEB_ALLOWED_HOSTS).

/** Lowercase a Host/authority, drop the port, unwrap a bracketed IPv6 literal. */
export function normalizeHost(hostHeader) {
  if (!hostHeader) return "";
  const host = String(hostHeader).trim().toLowerCase();
  if (host.startsWith("[")) {
    const end = host.indexOf("]");
    return end === -1 ? host.slice(1) : host.slice(1, end);
  }
  // A single colon is host:port; two or more is a bare IPv6 literal (no port).
  const colon = host.indexOf(":");
  if (colon === -1 || host.indexOf(":", colon + 1) !== -1) return host;
  return host.slice(0, colon);
}

/** True for localhost, the whole 127.0.0.0/8 range, and the IPv6 loopback. */
export function isLoopbackHost(host) {
  const h = normalizeHost(host);
  if (h === "localhost" || h === "::1") return true;
  return /^127\.\d{1,3}\.\d{1,3}\.\d{1,3}$/.test(h);
}

/** Parse the opt-in env value ("host1, host2:port host3") into a Set of hosts. */
export function parseAllowedHosts(envValue) {
  const out = new Set();
  if (!envValue) return out;
  for (const token of String(envValue).split(/[\s,]+/)) {
    const h = normalizeHost(token);
    if (h) out.add(h);
  }
  return out;
}

function block(reason) {
  return { ok: false, status: 403, reason };
}

/**
 * Decide whether an /api request may proceed.
 * @param {object} req
 * @param {string|null} req.secFetchSite  Sec-Fetch-Site header, if any
 * @param {string|null} req.origin        Origin header, if any
 * @param {string|null} req.host          Host header
 * @param {Set<string>} req.allowedHosts  extra non-loopback hosts opted in
 * @returns {{ok: true} | {ok: false, status: number, reason: string}}
 */
export function checkRequest({ secFetchSite, origin, host, allowedHosts }) {
  // Host layer (F2): must be loopback, or an explicitly opted-in host.
  const normalizedHost = normalizeHost(host);
  if (!normalizedHost) return block("missing Host header");
  const hostAllowed = isLoopbackHost(normalizedHost) || (allowedHosts && allowedHosts.has(normalizedHost));
  if (!hostAllowed) {
    return block(
      "this host is not allowed; the dashboard serves loopback only unless CAREER_OPS_WEB_ALLOWED_HOSTS opts it in",
    );
  }

  // Origin layer (F1), primary: the Fetch Metadata signal, when present.
  //   same-origin — the app's own fetch()          → allow
  //   none         — a direct navigation/bookmark   → allow (not attacker-forgeable)
  //   same-site / cross-site — another origin        → block
  if (secFetchSite) {
    if (secFetchSite === "same-origin" || secFetchSite === "none") return { ok: true };
    return block(`cross-origin request refused (Sec-Fetch-Site: ${secFetchSite})`);
  }

  // Origin layer, fallback: no Fetch Metadata (old browser / non-browser).
  // If an Origin is present it must match Host; absent Origin (curl, server
  // fetch) cannot be a browser CSRF, so allow it.
  if (origin == null) return { ok: true };
  let originHost;
  try {
    originHost = new URL(origin).host.toLowerCase();
  } catch {
    return block("invalid Origin header"); // includes the opaque "null" origin
  }
  if (originHost !== String(host).trim().toLowerCase()) {
    return block("cross-origin request refused (Origin does not match Host)");
  }
  return { ok: true };
}

/**
 * pdf-paths.mjs — deterministic scratch + final paths for a web "pdf" run (#2172).
 *
 * Plain .mjs (same pattern as clean-chips.mjs / tracker-table.mjs) so this can
 * be unit-tested with `node --test`, no TypeScript build step. `careerOpsRoot`
 * and `findReportFile` are passed in rather than imported from career-ops.ts,
 * keeping this module free of TypeScript dependencies.
 */
import fs from "node:fs";
import path from "node:path";
import * as yaml from "js-yaml";

/**
 * Lowercase, non-alphanumeric runs -> single hyphen, trimmed.
 * @param {string} s
 * @returns {string}
 */
export function slugify(s) {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
}

/**
 * @typedef {Object} PdfPaths
 * @property {string} html - Where the backend writes the tailored HTML it parsed out of the agent's envelope (#2185).
 * @property {string} finalPdf - Where the backend renders the final PDF (output/cv-{candidate}-{company}-{date}.pdf).
 */

/**
 * Precompute the scratch HTML and final PDF paths for a
 * "pdf" run, so the agent never chooses its own filenames — the backend owns
 * naming, writing (#2185) and rendering. Resolves the report (for the company slug)
 * and config/profile.yml (for the candidate slug) — same naming convention
 * modes/pdf.md documents, so web and CLI output stay byte-identical.
 *
 * Framework-agnostic: returns a result instead of constructing a Response, so
 * the caller (a Next.js route today) decides how to surface `ok: false`.
 *
 * Side effect: creates `.career-ops-web/pdf-tmp/` under `root` if it doesn't
 * exist yet (the backend writes the parsed envelope there, #2185) — this is
 * NOT a pure path computation, despite the name.
 *
 * @param {string} input - The report number (e.g. "018").
 * @param {string} today - YYYY-MM-DD.
 * @param {string} root - careerOpsRoot().
 * @param {(input: string) => string | null} findReportFile - career-ops.ts's findReportFile.
 * @returns {{ok: true, paths: PdfPaths} | {ok: false, error: string}}
 */
export function resolvePdfPaths(input, today, root, findReportFile) {
  // Reject anything but a bare report number before it ever reaches a path.
  // findReportFile()'s parseInt-based matching can still resolve a crafted
  // selector like "123/../../etc/passwd" to a legitimate report file, but the
  // raw string is also used verbatim below to build cv-web-${input}.html —
  // path.join would then honor those ".." segments and escape scratchDir.
  if (!/^\d+$/.test(input)) {
    return { ok: false, error: `Invalid report selector: "${input}"` };
  }
  const reportFile = findReportFile(input);
  if (!reportFile) {
    return { ok: false, error: `No report #${input} found — evaluate this posting first.` };
  }
  const companyMatch = path.basename(reportFile).match(/^\d+-(.+)-\d{4}-\d{2}-\d{2}\.md$/);
  const companySlug = companyMatch ? companyMatch[1] : "company";
  let candidateSlug = "candidate";
  try {
    // js-yaml v4's load() uses the safe default schema (no arbitrary type
    // construction, unlike Python's PyYAML) — same pattern already used in
    // web/src/app/api/profile/route.ts and portals/route.ts.
    const profile = yaml.load(fs.readFileSync(path.join(root, "config", "profile.yml"), "utf8"));
    if (profile?.candidate?.full_name) candidateSlug = slugify(profile.candidate.full_name);
  } catch (err) {
    // A missing profile.yml is expected (not every checkout has one yet) and
    // falls back silently. Anything else — a real YAML syntax error in the
    // user's own file — should not fail silently forever; it would otherwise
    // produce a wrong-but-plausible-looking filename with zero signal.
    if (err?.code !== "ENOENT") {
      console.warn(`resolvePdfPaths: could not read/parse config/profile.yml, defaulting candidate slug: ${err.message}`);
    }
  }
  const scratchDir = path.join(root, ".career-ops-web", "pdf-tmp");
  fs.mkdirSync(scratchDir, { recursive: true });
  return {
    ok: true,
    paths: {
      html: path.join(scratchDir, `cv-web-${input}.html`),
      finalPdf: path.join(root, "output", `cv-${candidateSlug}-${companySlug}-${today}.pdf`),
    },
  };
}

/**
 * pdf-render.mjs — render a tailored CV to PDF and mark the tracker (#2172).
 *
 * Plain .mjs (same pattern as pdf-paths.mjs / clean-chips.mjs) so this can be
 * unit-tested with `node --test`, no TypeScript build step. `spawnFn`,
 * `execPath`, and `root` are injected rather than importing node:child_process
 * or career-ops.ts directly, keeping this module free of TypeScript
 * dependencies and letting tests substitute a fake child process.
 *
 * Runs generate-pdf.mjs and mark-pdf-ready.mjs as plain Node child processes
 * — no agent CLI or its sandbox involved — so a browser launch never depends
 * on an interactive sandbox-escalation approval nobody is present to grant in
 * a headless/web-triggered run. The tracker is marked ✅ only after a
 * CONFIRMED successful render, never optimistically.
 */
import fs from "node:fs";
import path from "node:path";

/**
 * @typedef {Object} PdfRunSignals
 * @property {object|undefined} envelope - parseCvEnvelope's result for this run.
 * @property {string|null} noOutputMessage - The route's verdict on "did the CLI
 *   produce any output at all", or null when it did. That question is about the
 *   transport, not this module, so the route owns the wording and passes it in
 *   rather than both places carrying the same two strings.
 * @property {boolean} sawError - Anything error-shaped on stderr.
 * @property {boolean} cleanExit - Exit code 0 (not killed, not non-zero).
 * @property {boolean} hasPaths - The backend resolved its scratch/final paths.
 */

/**
 * Did this pdf run produce a CV worth rendering?
 *
 * Pure, and here rather than in the route, because it is the decision point for
 * the backend pdf pipeline this module implements: nothing is written, rendered or
 * marked unless this says yes, and the route is a transport layer the repo leaves
 * untested by design.
 *
 * The envelope's own error is preferred over the generic message: "never closed"
 * and "emitted no envelope" are different bugs and the user can act on the
 * difference.
 *
 * @param {PdfRunSignals} signals
 * @returns {{ok: true} | {ok: false, message: string}}
 */
export function pdfRunOutcome({ envelope, noOutputMessage, sawError, cleanExit, hasPaths }) {
  // A CLI that produced nothing at all is a different failure from one that ran
  // and fell short — usually "not installed" or "not authenticated".
  if (noOutputMessage) return { ok: false, message: noOutputMessage };
  if (envelope?.ok !== true || !cleanExit || sawError || !hasPaths) {
    const why = envelope && envelope.ok === false ? ` (${envelope.error})` : "";
    return {
      ok: false,
      message: `This run didn't produce a tailored CV to render, so no PDF was generated — re-run it to verify.${why}`,
    };
  }
  return { ok: true };
}

/**
 * Persist the CV the agent emitted through its <<cv-html>> envelope (#2185).
 *
 * The agent emits the tailored HTML inline and the backend saves it here. The
 * chosen page format is NOT written to disk: it is already in memory and goes
 * straight to renderAndMarkPdf. A sidecar written and re-read inside one request
 * bought only a fallback branch for a state that could not occur, plus an
 * undeclared ordering dependency between these two functions.
 *
 * The scratch directory is created by resolvePdfPaths earlier in the same
 * request, so this deliberately does not mkdir — a missing directory here means
 * something is wrong upstream and should surface, not be papered over.
 *
 * @param {{pdfPaths: {html: string}, html: string}} args
 * @returns {{ok: true} | {ok: false, error: string}} Never throws: the caller
 *   routes the failure through the same honesty gate as every other pdf failure.
 */
export function writeCvHtml({ pdfPaths, html }) {
  try {
    fs.writeFileSync(pdfPaths.html, html, "utf8");
    return { ok: true };
  } catch (err) {
    // err.path when the platform gives it: a non-fs throw (an oversized-content
    // RangeError, a bad argument type) carries none, and "could not save to
    // undefined" tells the user nothing.
    return { ok: false, error: `Could not save the tailored CV to ${err.path ?? pdfPaths.html}: ${err.message}` };
  }
}

/**
 * Spawn generate-pdf.mjs as a plain child process and resolve once it exits.
 * @param {{spawnFn: Function, execPath: string, root: string, html: string, finalPdf: string, format: "letter"|"a4", reportNum: string}} args
 * @returns {Promise<{ok: boolean, stderr: string}>}
 */
export function spawnGeneratePdf({ spawnFn, execPath, root, html, finalPdf, format, reportNum }) {
  return new Promise((resolve) => {
    const child = spawnFn(
      execPath,
      // --allow-reorder: a real cv.md's section order can legitimately diverge
      // from the template's fixed markup order, so this guard would otherwise
      // hard-fail every web-triggered render — same bypass a human already
      // applies manually via the CLI when this diverges.
      [path.join(root, "generate-pdf.mjs"), html, finalPdf, `--format=${format}`, `--report=${reportNum}`, "--allow-reorder"],
      { cwd: root },
    );
    let stderr = "";
    child.stderr.on("data", (d) => { stderr += d.toString(); });
    child.on("close", (code) => resolve({ ok: code === 0, stderr: stderr.trim() }));
    child.on("error", (e) => resolve({ ok: false, stderr: `PDF rendering failed to start: ${e.message}` }));
  });
}

/**
 * Spawn mark-pdf-ready.mjs (--json) and resolve once it exits, parsing its
 * JSON stdout when present (mark-pdf-ready.mjs prints a JSON payload even on
 * a failure exit when --json is passed) so a caller can surface the specific
 * reason (not-found / ambiguous / lock-timeout / ...) rather than raw stderr.
 * @param {{spawnFn: Function, execPath: string, root: string, reportNum: string}} args
 * @returns {Promise<{ok: boolean, data: object | null, stderr: string}>}
 */
export function markTrackerReady({ spawnFn, execPath, root, reportNum }) {
  return new Promise((resolve) => {
    const child = spawnFn(execPath, [path.join(root, "mark-pdf-ready.mjs"), reportNum, "--json"], { cwd: root });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (d) => { stdout += d.toString(); });
    child.stderr.on("data", (d) => { stderr += d.toString(); });
    child.on("close", (code) => {
      let data = null;
      try { data = JSON.parse(stdout); } catch { /* not JSON, or exited before printing any */ }
      resolve({ ok: code === 0, data, stderr: stderr.trim() });
    });
    child.on("error", (e) => resolve({ ok: false, data: null, stderr: `mark-pdf-ready.mjs failed to start: ${e.message}` }));
  });
}

/**
 * Glob-clean every scratch file for this run rather than the one known filename.
 * The agent is not told these paths, and on Claude Code holds no write tool — but
 * the BACKEND writes here and generate-pdf.mjs may leave its own intermediates, so
 * matching the run's prefix stays the right sweep. Logs rather than silently
 * swallowing failures, so a systemic permissions problem doesn't grow
 * `.career-ops-web/pdf-tmp/` forever with no trace anywhere.
 * @param {string} scratchDir
 * @param {string} prefix
 * @returns {void}
 */
export function cleanupPdfScratch(scratchDir, prefix) {
  let entries;
  try {
    entries = fs.readdirSync(scratchDir);
  } catch (err) {
    console.error(`pdf scratch cleanup: could not list ${scratchDir}: ${err.message}`);
    return;
  }
  for (const f of entries) {
    if (!f.startsWith(prefix)) continue;
    try {
      fs.rmSync(path.join(scratchDir, f), { force: true });
    } catch (err) {
      console.error(`pdf scratch cleanup: could not remove ${f}: ${err.message}`);
    }
  }
}

/**
 * @typedef {Object} RenderFailedResult
 * @property {"render-failed"} kind
 * @property {string} error
 */
/**
 * @typedef {Object} RenderedResult
 * @property {"rendered"} kind
 * @property {string[]} warnings - Non-fatal issues to surface to the user (e.g. a tracker row that was not marked).
 */
/** @typedef {RenderFailedResult | RenderedResult} RenderResult */

/**
 * Render the tailored HTML to a PDF, then mark the tracker's PDF column
 * ready — only after the render is CONFIRMED successful, never
 * optimistically. Always cleans up scratch files, whether the render
 * succeeds or fails.
 *
 * Call after writeCvHtml for the same pdfPaths — this reads the HTML that
 * function wrote. `format` is passed in rather than read back off disk, so the two
 * no longer share a file and the only coupling left is the HTML itself.
 * @param {{spawnFn: Function, execPath: string, root: string, pdfPaths: {html: string, finalPdf: string}, format: "letter"|"a4", reportNum: string}} args
 * @returns {Promise<RenderResult>}
 */
export async function renderAndMarkPdf({ spawnFn, execPath, root, pdfPaths, format, reportNum }) {
  const warnings = [];

  const render = await spawnGeneratePdf({ spawnFn, execPath, root, html: pdfPaths.html, finalPdf: pdfPaths.finalPdf, format, reportNum });
  cleanupPdfScratch(path.dirname(pdfPaths.html), `cv-web-${reportNum}.`);

  if (!render.ok) {
    return { kind: "render-failed", error: render.stderr || "PDF rendering failed." };
  }

  // The PDF is the real deliverable and it already rendered successfully — a
  // tracker-sync miss (e.g. the row was edited away mid-flight) doesn't fail
  // the whole job, but it must still be visible to whoever is watching this
  // run, not just a server-side log nobody sees.
  const mark = await markTrackerReady({ spawnFn, execPath, root, reportNum });
  if (!mark.ok) {
    console.error(`mark-pdf-ready.mjs failed for report #${reportNum}: ${mark.data?.error ?? mark.stderr}`);
    warnings.push(
      mark.data?.error
        ? `PDF rendered, but the tracker wasn't updated: ${mark.data.error}`
        : `PDF rendered, but the tracker's PDF column wasn't updated automatically — run \`node mark-pdf-ready.mjs ${reportNum}\` manually.`,
    );
  }

  return { kind: "rendered", warnings };
}

// A tiny client-side ring buffer of recent ERRORS (not arbitrary logs → far less
// PII surface) for the in-app bug reporter. Installed once on first import.
const MAX = 20;
const BUF: string[] = [];

function push(s: string) {
  BUF.push(s.replace(/\s+/g, " ").slice(0, 300));
  if (BUF.length > MAX) BUF.shift();
}

declare global {
  interface Window {
    __coLogBufInstalled?: boolean;
  }
}

if (typeof window !== "undefined" && !window.__coLogBufInstalled) {
  window.__coLogBufInstalled = true;
  const orig = console.error.bind(console);
  console.error = (...args: unknown[]) => {
    try {
      push("[error] " + args.map((a) => (a instanceof Error ? `${a.message}` : String(a))).join(" "));
    } catch {
      /* never break logging */
    }
    orig(...args);
  };
  window.addEventListener("error", (e) => push(`[onerror] ${e.message || ""} @ ${e.filename || ""}:${e.lineno || ""}`));
  // Server-side failures are invisible to console.error — wrap fetch so a
  // degraded API (500, or a route that answered but couldn't do its job) lands
  // in the ring too. Pathname only: query strings can carry company names.
  const origFetch = window.fetch.bind(window);
  window.fetch = async (...args: Parameters<typeof fetch>) => {
    const res = await origFetch(...args);
    try {
      const u = new URL(typeof args[0] === "string" ? args[0] : (args[0] as Request).url, location.origin);
      if (u.pathname.startsWith("/api/") && !res.ok) push(`[api] ${u.pathname} → ${res.status}`);
    } catch {
      /* never break fetch */
    }
    return res;
  };
  window.addEventListener("unhandledrejection", (e) => push(`[rejection] ${String((e as PromiseRejectionEvent).reason)}`));
}

export function recentLogs(): string[] {
  return BUF.slice();
}

import { recentLogs } from "./logbuf";

const REPO = "santifer/career-ops";

/** Strip PII / secrets that could ride in error text, paths or logs BEFORE anything
 *  leaves the machine. Defence-in-depth — the user also reviews the full payload
 *  (preview-then-confirm) before the issue opens. */
export function scrub(s: string): string {
  return (s || "")
    .replace(/\/Users\/[^/\s"']+/g, "~")
    .replace(/\/home\/[^/\s"']+/g, "~")
    .replace(/(sk|key|token|secret|bearer|api[-_]?key)([-_=:\s"']+)[A-Za-z0-9._-]{8,}/gi, "$1$2[redacted]");
}

/** Structural fingerprint from /api/report/shape — shapes/counts, never contents. */
export type Shape = {
  runtime?: { node?: string; platform?: string; arch?: string };
  setup?: { phase?: string; missing?: string[]; hasCv?: boolean; hasData?: boolean };
  data?: {
    inbox?: { candidates?: number; parsed?: number };
    tracker?: { candidates?: number; parsed?: number };
    reports?: number;
    pdfs?: number;
    followupsFile?: boolean;
  };
  capabilities?: { scanJson?: boolean; trackerDelete?: boolean };
};

export type Diag = {
  version: string;
  coreVersion: string;
  channel: string;
  sha: string;
  route: string;
  cli: string;
  ua: string;
  viewport: string;
  logs: string[];
  shape: Shape | null;
  /** Whether the core follow-up cadence engine answered — false = engine degraded. */
  followupsAvailable: boolean | null;
};

/** Gather a STRUCTURAL diagnostic snapshot. Deliberately excludes anything personal:
 *  no cv.md, no profile, no application answers, no job URLs, no report content. */
export async function collect(): Promise<Diag> {
  let version = "";
  let coreVersion = "";
  let channel = "stable";
  let sha = "";
  try {
    const d = await (await fetch("/api/version")).json();
    version = d.version || "";
    coreVersion = d.coreVersion || "";
    channel = d.channel || "stable";
    sha = d.sha || "";
  } catch {
    /* keep defaults */
  }
  let shape: Shape | null = null;
  try {
    shape = (await (await fetch("/api/report/shape")).json()) as Shape;
  } catch {
    /* structural snapshot is best-effort */
  }
  let followupsAvailable: boolean | null = null;
  try {
    followupsAvailable = Boolean((await (await fetch("/api/followups")).json()).available);
  } catch {
    /* best-effort */
  }
  let cli = "";
  try {
    cli = JSON.parse(localStorage.getItem("career-ops:config") || "{}").cliId || "";
  } catch {
    /* none */
  }
  return {
    version,
    coreVersion,
    channel,
    sha,
    route: scrub(location.pathname + location.search),
    cli,
    ua: navigator.userAgent,
    viewport: `${window.innerWidth}×${window.innerHeight}`,
    logs: recentLogs().map(scrub),
    shape,
    followupsAvailable,
  };
}

/** Stable error CLASS from a ring entry: strip the volatile bits (urls, ids,
 *  numbers, quoted values) so the same underlying bug yields the same class
 *  across sessions and machines. */
function errorClass(log: string): string {
  return (log || "")
    .replace(/https?:\/\/\S+/g, "<url>")
    .replace(/["'`][^"'`]{0,80}["'`]/g, "<v>")
    .replace(/\d+/g, "<n>")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 120);
}

/** Deterministic short fingerprint (djb2 → base36) of route + newest error
 *  class + structural degradation flags. Same bug → same fingerprint, across
 *  sessions and users — the dedupe key for issue search, the glow, and the
 *  maintainer's triage Action. Contract: web/src/lib/report/FORMAT.md (v1). */
export function fingerprint(d: Diag): string {
  const route = d.route.split("?")[0];
  const err = errorClass(d.logs[d.logs.length - 1] || "");
  const flags = [
    d.followupsAvailable === false ? "fu-degraded" : "",
    (d.shape?.data?.inbox?.parsed ?? 0) < (d.shape?.data?.inbox?.candidates ?? 0) ? "inbox-gap" : "",
    (d.shape?.data?.tracker?.parsed ?? 0) < (d.shape?.data?.tracker?.candidates ?? 0) ? "tracker-gap" : "",
  ]
    .filter(Boolean)
    .join(",");
  const s = `${route}|${err}|${flags}`;
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
  return `co-web-${h.toString(36)}`;
}

/** The EXACT markdown body the user reviews and that becomes the GitHub issue. */
export function issueBody(d: Diag, description: string): string {
  const s = d.shape;
  const fmt = (n?: number) => (typeof n === "number" ? String(n) : "?");
  const shapeLines = s
    ? [
        "## Data shape (counts only — no contents)",
        `- **Setup:** ${s.setup?.phase || "?"}${s.setup?.missing?.length ? ` · missing: ${s.setup.missing.join(", ")}` : ""}`,
        `- **Inbox:** ${fmt(s.data?.inbox?.parsed)}/${fmt(s.data?.inbox?.candidates)} rows parsed · **Tracker:** ${fmt(s.data?.tracker?.parsed)}/${fmt(s.data?.tracker?.candidates)} rows parsed`,
        `- **Reports:** ${fmt(s.data?.reports)} · **PDFs:** ${fmt(s.data?.pdfs)} · **Follow-ups engine:** ${d.followupsAvailable === null ? "?" : d.followupsAvailable ? "ok" : "DEGRADED"}`,
        `- **Core capabilities:** scan --json ${s.capabilities?.scanJson ? "yes" : "no"} · tracker delete ${s.capabilities?.trackerDelete ? "yes" : "no"}`,
        `- **Server:** node ${s.runtime?.node || "?"} · ${s.runtime?.platform || "?"}/${s.runtime?.arch || "?"}`,
        "",
      ]
    : [];
  return [
    "## What happened",
    scrub(description).trim() || "_(describe what you were doing and what went wrong)_",
    "",
    "## Environment",
    `- **Version:** \`${d.version || "?"}\`${d.coreVersion ? ` · core \`${d.coreVersion}\`` : ""} · ${d.channel}${d.sha ? ` · \`${d.sha}\`` : ""}`,
    `- **CLI:** ${d.cli || "—"}`,
    `- **Screen:** \`${d.route}\``,
    `- **Browser:** ${scrub(d.ua)}`,
    `- **Viewport:** ${d.viewport}`,
    `- **Fingerprint:** \`${fingerprint(d)}\``,
    "",
    ...shapeLines,
    "## Recent errors",
    d.logs.length ? "```\n" + d.logs.join("\n") + "\n```" : "_(none captured)_",
    "",
    "---",
    "_Filed from the in-app bug reporter (report-format: v1). Contains NO CV, profile, application answers, or job URLs._",
  ]
    .join("\n")
    .slice(0, 6000);
}

export function issueUrl(d: Diag, description: string): string {
  const title = `[web ${d.channel}] ${(scrub(description) || "bug report").replace(/\s+/g, " ").trim().slice(0, 70)}`;
  const params = new URLSearchParams({ title, body: issueBody(d, description), labels: "web-alpha,area:web" });
  return `https://github.com/${REPO}/issues/new?${params.toString()}`;
}

import path from "node:path";

// Plain .mjs (same pattern as tracker-table.mjs/pdf-paths.mjs) so both the
// TypeScript side (career-ops.ts) and the Node-run test suites can import it.
// A .ts home would have been unreachable from `node --test`, which is why this
// convention had drifted into two copies before landing here.

/**
 * True for a `{n}-RESERVED.md` placeholder sentinel — never a real report.
 *
 * THE definition of that convention for `web/`. `reserve-report-num.mjs` writes
 * an empty `NNN-RESERVED.md` to claim a report number before a worker has
 * written the report; it is deleted once the real report lands (or GC'd after
 * 4h if abandoned). Two consumers must agree on what that looks like:
 *
 * - `findReportFile` (career-ops.ts) — "RESERVED" sorts before nearly every real
 *   slug, so a surviving sentinel could be returned INSTEAD of the real report,
 *   making the report body and the Apply/PDF-ready checks disappear.
 * - `completedReportNames` (run-cli-support.mjs) — a sentinel must not count as
 *   persistence, or an evaluation that wrote nothing passes the honesty gate.
 *
 * They previously carried separate predicates that already disagreed on
 * `notes-RESERVED.md`; one definition is the point of this module.
 *
 * The number prefix is required: only a numbered sentinel comes from the
 * reservation path, so a hypothetical `notes-RESERVED.md` is a real report.
 *
 * @param {string} file - A filename or path; only the basename is examined.
 * @returns {boolean}
 */
export function isReservedReportFile(file) {
  return /^\d+-RESERVED\.md$/.test(path.basename(file));
}

/**
 * report-sections.mjs — splitting a report body into its author-lettered
 * sections, and cleaning those headings for display.
 *
 * Plain .mjs (same pattern as clean-chips.mjs) so test-report-sections.mjs can
 * import it directly under Node, and so the two places that used to hard-code
 * the author-letter range can no longer drift apart: they were written as
 * `[A-G]` in report-view.tsx, which silently mis-handled `## H) Draft
 * Application Answers` — the heading rendered with its letter still attached
 * while every other section rendered clean, and splitSections reported
 * `letter: null` for it (#2324).
 *
 * The range is now any single letter. The `)` / `.` / `:` delimiter is what
 * keeps this from eating ordinary prose ("A Recommendation Was Requested"),
 * not the narrowness of the range — so widening it costs no safety, and a
 * block added past H is handled the day the core writes it.
 */

/**
 * Strips the prefix for display. A BARE letter needs a real delimiter, never a
 * bare space, or ordinary prose loses its first word ("A Recommendation Was
 * Requested" → "Recommendation Was Requested").
 *
 * After `Block` the whitespace form is allowed, because the word itself is the
 * disambiguator: "## Block A — Role Summary" (oferta.md:47) is unmistakably a
 * lettered heading. HEADING_LETTER below already reads that grammar as section
 * A, so leaving the prefix in the rendered heading made this file classify a
 * heading one way and display it another (CodeRabbit review).
 *
 * The separator is a RUN of dashes, not one character: modes/ja/kyujin.md and
 * modes/hi/naukri.md write the ASCII "## Block A -- Role Summary", which left a
 * stray "- " on every block of every report those modes produce.
 */
const HEADING_PREFIX = /^\s*(?:Block\s+([A-Z])(?:[).:]\s*|\s+(?:[—–-]+\s*)?)|([A-Z])[).:]\s*)/i;

/**
 * Reads the letter. A bare letter needs a delimiter, exactly like the display
 * form above — otherwise "A Recommendation Was Requested" is read as section A
 * and ReportView expands ordinary prose as if it were Block A.
 *
 * The whitespace form is kept for the spelled-out grammar only: oferta.md
 * writes "## Block A — Role Summary", where nothing follows the letter but a
 * space. Requiring a delimiter there would lose the F verdict callout and the
 * A/B expansion on those reports.
 */
const HEADING_LETTER = /^(?:Block\s+([A-Z])(?:[).:]|\s)|([A-Z])[).:])/i;

/**
 * @typedef {{ heading: string, letter: string | null, content: string }} Section
 */

/**
 * Display form of a section heading: author-letter prefix and the trailing
 * "(lead)" / "(verdict)" marker removed. Falls back to the original when
 * stripping would leave nothing.
 * @param {string} h
 * @returns {string}
 */
export function cleanHeading(h) {
  const stripped = h
    .replace(HEADING_PREFIX, "")
    .replace(/\s*\((?:lead|verdict)\)\s*$/i, "")
    .trim();
  return stripped || h.trim();
}

/**
 * The author letter of a heading, uppercased, or null when it carries none.
 * @param {string} heading
 * @returns {string | null}
 */
export function authorLetter(heading) {
  const match = heading.match(HEADING_LETTER);
  return (match?.[1] ?? match?.[2])?.toUpperCase() ?? null;
}

/**
 * Split a report body on `## ` headings. Everything before the first one is
 * the intro.
 * @param {string} body
 * @returns {{ intro: string, sections: Section[] }}
 */
export function splitSections(body) {
  /** @type {string[]} */
  const intro = [];
  /** @type {Section[]} */
  const sections = [];
  /** @type {{ heading: string, letter: string | null, lines: string[] } | null} */
  let cur = null;
  for (const line of body.split("\n")) {
    const h = line.match(/^##\s+(.*)$/);
    if (h) {
      if (cur) sections.push({ heading: cur.heading, letter: cur.letter, content: cur.lines.join("\n").trim() });
      const heading = h[1].trim();
      cur = { heading, letter: authorLetter(heading), lines: [] };
    } else if (cur) {
      cur.lines.push(line);
    } else {
      intro.push(line);
    }
  }
  if (cur) sections.push({ heading: cur.heading, letter: cur.letter, content: cur.lines.join("\n").trim() });
  return { intro: intro.join("\n").trim(), sections };
}

// Plain .mjs (same pattern as tracker-table.mjs/clean-chips.mjs/spawn-cli.mjs)
// so tests/lib/run-cli-support.test.mjs can import it directly under Node. Import it
// with the .mjs extension included (e.g. "@/lib/run-cli-support.mjs" or
// "./run-cli-support.mjs") — unlike .ts files, which TypeScript resolves
// without an extension, ESM specifiers for plain JS modules must be fully
// specified.
import { isReservedReportFile } from "./report-files.mjs";

/**
 * Dashboard-friendly shape both `parseCodexEvent` and `parseClaudeEvent` return.
 * Usually at most one payload field (`tool`/`text`/`tokens`/`costUsd`/`error`) is
 * set per event; `status` may accompany any of them, and `tokens`/`costUsd` may
 * co-occur on a Claude `result` event.
 * `costUsd` is `number | null`: null is a REPORTED absence, not a missing field —
 * Codex sends usage with no cost, and callers must not fill that in with a rate.
 * @typedef {{status?: string, tool?: string, text?: string, tokens?: number, costUsd?: number | null, error?: string}} ParsedEvent
 */

const STATUS_READY = "Agent ready";
const STATUS_RECONNECTING = "Reconnecting…";

/**
 * Token accounting across CLIs — the two conventions are OPPOSITE, and the
 * formula is the only place that difference is visible (adapted from #2689,
 * which reached this from the accounting side).
 *
 * The dashboard's metric is TOKENS BILLED AT FULL RATE — `/api/usage/route.ts`
 * defines it as input + output + cache-creation, deliberately omitting
 * discounted cache reads.
 *
 *   Claude  `input_tokens` EXCLUDES cache reads (they live in
 *           `cache_read_input_tokens`), and cache writes are a separate pool
 *           billed at full rate. → input + output + cache_creation
 *   Codex   `input_tokens` INCLUDES `cached_input_tokens` (OpenAI's
 *           convention), so adding is double-counting and the cached portion
 *           must be SUBTRACTED. → (input − cached) + output
 *
 * Getting this wrong throws nothing and reddens no test — it silently inflates
 * one runtime against another (~4.7× on a real run) in the very comparison
 * people use to control cost.
 */

/**
 * A usage figure, or 0 — guards nulls and junk in a partial usage block.
 *
 * `isSafeInteger`, not `isFinite`: a token count is a whole number, so a
 * fractional value from a malformed event is junk and must not reach the total
 * (CodeRabbit's finding on #2689's `n`, whose shape this shares).
 */
function tokenCount(value) {
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0 ? value : 0;
}

/** Auth failures, in wording shared across agent CLIs. Deliberately narrow: a
 * structured-output CLI's own event stream + exit code are authoritative for
 * everything else, so a stderr classifier only needs to catch the failures that
 * produce no usable stream at all. */
const FATAL_AUTH_STDERR_RE =
  /unauthorized|forbidden|not authenticated|please log in|sign[ -]?in required|credential.*missing/i;

/** Quota/rate-limit failures — fatal like auth, EXCEPT when the line announces
 * its own retry: the CLI is handling it, and the run can still complete
 * cleanly. Same reasoning as CODEX_TRANSIENT_ERROR_RE, for the stderr channel —
 * flagging a self-retrying 429 fatal re-creates the false-red #2085 exists to
 * remove (sawError fails the honesty gate even on exit 0 with a written
 * report). Auth gets no such carve-out: it never heals by retrying. */
const FATAL_QUOTA_STDERR_RE = /quota|rate limit/i;
// Only a retry the CLI ANNOUNCES AS IN PROGRESS ("retrying", "retry in 5s",
// "will retry") — a bare /retry/ would also match terminal wording like
// "do not retry" or "retry limit exhausted" and silence a genuine failure.
const RETRYING_STDERR_RE = /retrying|retry\s+in\b|will\s+retry/i;
const isFatalQuotaStderr = (line) => FATAL_QUOTA_STDERR_RE.test(line) && !RETRYING_STDERR_RE.test(line);

/** Claude Code's own wording for the same class of failure. */
const CLAUDE_FATAL_STDERR_RE = /invalid api key|please run \/login|credit balance|usage limit reached/i;

/** Codex `error` events that it recovers from on its own (see parseCodexEvent). */
const CODEX_TRANSIENT_ERROR_RE = /reconnect/i;

/**
 * Whether one Codex stderr chunk should be treated as a fatal error.
 *
 * Codex can emit benign ERROR-level diagnostics (e.g. a stale local model-cache
 * schema) and still complete successfully, so anything outside the auth/quota
 * set is left to its JSONL stream and exit code — and even a quota/rate-limit
 * line is non-fatal while it says the CLI is retrying.
 *
 * @param {string} line
 * @returns {boolean}
 */
export function isFatalCodexStderr(line) {
  return FATAL_AUTH_STDERR_RE.test(line) || isFatalQuotaStderr(line);
}

/**
 * Whether one Claude Code stderr chunk should be treated as a fatal error.
 *
 * Same reasoning as `isFatalCodexStderr`: Claude also has a structured stream
 * and a meaningful exit code, so the generic "contains the word error" fallback
 * would fail runs that actually succeeded — and a self-retrying rate limit gets
 * the same transient carve-out. Claude's own wording (invalid key, /login,
 * credit/usage limits) is always hard: none of those heal by retrying.
 *
 * @param {string} line
 * @returns {boolean}
 */
export function isFatalClaudeStderr(line) {
  return FATAL_AUTH_STDERR_RE.test(line) || CLAUDE_FATAL_STDERR_RE.test(line) || isFatalQuotaStderr(line);
}

/**
 * Fallback classifier for a CLI with no `stderrIsFatal` of its own.
 *
 * Only claude and codex define one, so SIX of the eight entries in KNOWN reach
 * this path — including every runtime people pick to spend less than they would
 * on those two.
 *
 * The terms are ANCHORED. Unanchored, `auth` matched inside ordinary words and a
 * successful run got reported as failed because a word appeared:
 *
 *   "Authentication successful"   → fatal    ← a SUCCESS message
 *   "warning: no author found"    → fatal    ← "auth" inside "author"
 *   "fetching author metadata"    → fatal
 *   "Errors: 0"                   → fatal
 *
 * That is the same failure #2085 exists to remove, on the path #2102 left
 * untouched. Found by @gregaro in #1974.
 *
 * Anchoring, NOT narrowing: `not authenticated` and `authentication failed`
 * still match, and the multi-word phrases keep no `\b` because they cannot
 * collide with prose. Lives here rather than inline in route.ts so it can be
 * tested — the reason the drift went unnoticed is that a regex in a .ts closure
 * had no reachable test.
 *
 * @param {string} line
 * @returns {boolean}
 */
export function isFatalGenericStderr(line) {
  return GENERIC_FATAL_STDERR_RE.test(line);
}

const GENERIC_FATAL_STDERR_RE =
  /\berror\b|\bdenied\b|\bfatal\b|not found|\bunauthorized\b|\bforbidden\b|not authenticated|authentication failed|\blogin\b|log in|\bcredentials?\b|api[ -]?key|\bquota\b|rate limit/i;

/**
 * The argv that makes `codex exec` emit the JSONL `parseCodexEvent` reads.
 *
 * Lives beside that parser rather than inline in clis.ts because the two are one
 * contract: `--json` is what produces the events, and `--color never` keeps ANSI
 * escapes out of the JSON strings. A caller that wants plain text must use
 * `CliSpec.args` instead — every non-dashboard surface reads codex's stdout
 * directly (`<<offer:>>`/`<<cv:>>` envelopes, the apply planners' JSON array).
 *
 * @param {string} prompt
 * @returns {string[]}
 */
export function codexStreamArgs(prompt) {
  return ["exec", "--json", "--color", "never", prompt];
}

/**
 * Convert one `codex exec --json` JSONL event into dashboard-friendly data.
 * @param {string} line
 * @returns {ParsedEvent | null}
 */
export function parseCodexEvent(line) {
  let event;
  try {
    event = JSON.parse(line);
  } catch {
    return null;
  }
  // JSON.parse("null") SUCCEEDS and yields null, and a bare scalar line yields a
  // number or string — none of which the try above rejects, so reading `.type`
  // off them throws past this function into the stdout handler. A parser written
  // to survive hostile input has to survive its own success cases too.
  if (!event || typeof event !== "object") return null;

  if (event.type === "thread.started") return { status: STATUS_READY };
  // Kind-agnostic on purpose: this parser serves every run kind (evaluate, pdf,
  // research, fix-portal), so the status must not claim one of them.
  if (event.type === "turn.started") return { status: "Agent working" };

  if (event.type === "item.started") {
    const type = event.item?.type;
    if (type === "command_execution") return { tool: "Bash" };
    if (type === "web_search") return { tool: "WebSearch" };
    if (type === "mcp_tool_call") return { tool: event.item?.tool || "Working" };
  }

  if (event.type === "item.completed" && event.item?.type === "agent_message") {
    // Empty text carries nothing: emitting it would put a blank line in the run
    // log and an extra newline inside pdf mode's line-anchored envelope stream.
    if (typeof event.item.text !== "string" || event.item.text === "") return null;
    // Newline-terminate each message: Codex sends complete messages with NO
    // trailing newline ("hello", not "hello\n"), so consecutive messages would
    // otherwise concatenate mid-line downstream. That glued narration into one
    // run-on log line AND broke pdf mode outright — the <<cv-html>> markers are
    // line-anchored by design (cv-envelope.mjs, fail-closed), so an envelope
    // message following unterminated narration parsed as "no envelope" and the
    // honesty gate failed a run whose CV was fully emitted.
    const text = event.item.text;
    return { text: text.endsWith("\n") ? text : text + "\n" };
  }

  if (event.type === "turn.completed") {
    // No `usage` block means nothing to report — return null rather than a
    // {tokens: 0}, so the caller's `typeof === "number"` guard skips it instead
    // of clobbering a correct running total from an earlier turn.
    if (!event.usage) return null;
    const usage = event.usage;
    // Subtraction, not addition: see the header note on the two conventions.
    // Clamped at 0 so a malformed usage block can never report negative tokens.
    const fresh = Math.max(0, tokenCount(usage.input_tokens) - tokenCount(usage.cached_input_tokens));
    // costUsd stays null rather than being invented from a token count and a
    // guessed rate — Codex reports no cost, and a fabricated one reads as real.
    return { tokens: fresh + tokenCount(usage.output_tokens), costUsd: null };
  }

  if (event.type === "turn.failed" || event.type === "error") {
    const message = String(event.error?.message || event.message || "Codex failed before finishing");
    // `turn.failed` is terminal by definition, but a bare `error` event also
    // carries transient conditions Codex recovers from — a "Reconnecting..."
    // notice mid-run would otherwise flag the whole run as failed even though
    // the turn goes on to complete. Report it as progress, not as an error.
    if (event.type === "error" && CODEX_TRANSIENT_ERROR_RE.test(message)) return { status: STATUS_RECONNECTING };
    return { error: message };
  }

  return null;
}

/**
 * Convert one Claude Code `--output-format stream-json` line into the same
 * dashboard-friendly shape `parseCodexEvent` produces.
 * @param {string} line
 * @returns {ParsedEvent | null}
 */
export function parseClaudeEvent(line) {
  let ev;
  try {
    ev = JSON.parse(line);
  } catch {
    return null;
  }
  // Same reason as parseCodexEvent's guard: JSON.parse("null") succeeds.
  if (!ev || typeof ev !== "object") return null;

  if (ev.type === "stream_event") {
    const e = ev.event;
    if (e?.type === "content_block_start" && e.content_block?.type === "tool_use") {
      return { tool: e.content_block.name };
    }
    if (e?.type === "content_block_delta" && e.delta?.text) {
      return { text: e.delta.text };
    }
    return null;
  }

  if (ev.type === "system" && ev.subtype === "init") {
    return { status: STATUS_READY };
  }

  if (ev.type === "result") {
    // Usage first, so a FAILED result still reports what it burned — the tokens
    // were spent either way, and dropping them undercounts exactly the runs a
    // user most wants to see the cost of.
    const result = {};
    if (ev.usage) {
      // Addition here, subtraction for Codex — see the header note. Claude's
      // input_tokens excludes cache reads, so cache writes must be added back
      // in; this is the same formula /api/usage uses.
      const u = ev.usage;
      result.tokens = tokenCount(u.input_tokens) + tokenCount(u.output_tokens) + tokenCount(u.cache_creation_input_tokens);
      if (typeof ev.total_cost_usd === "number") result.costUsd = ev.total_cost_usd;
    }
    // A terminal failure, the counterpart of parseCodexEvent's turn.failed. The
    // route's gate would otherwise have to infer this from the exit code alone,
    // and a non-zero exit is not guaranteed — a run that failed while exiting 0
    // would be banked as a confident score, the dishonest-success case this
    // whole file exists to prevent. `is_error` is the authoritative flag;
    // subtype is checked by PREFIX because the real values are
    // `error_max_turns` / `error_during_execution`, never a bare "error".
    if (ev.is_error === true || (typeof ev.subtype === "string" && ev.subtype.startsWith("error"))) {
      // `result` carries the final text and is empty on failure, so it is only a
      // fallback; the subtype names the failure when no diagnostic is supplied.
      const diagnostic =
        (typeof ev.error === "string" && ev.error) ||
        (typeof ev.result === "string" && ev.result) ||
        (typeof ev.subtype === "string" && ev.subtype) ||
        "Claude failed before finishing";
      result.error = String(diagnostic);
    }
    // Null over an empty object: nothing to report must not look like an event.
    return Object.keys(result).length > 0 ? result : null;
  }

  return null;
}

/**
 * Fold one parsed event's token count into a running total. `turn.completed`
 * (Codex) and `result` (Claude) usage is per-event, not cumulative-since-start,
 * so callers must accumulate across multiple events in one run rather than
 * overwrite — otherwise a multi-turn run silently undercounts.
 *
 * @param {number} current
 * @param {ParsedEvent | null | undefined} ev
 * @returns {number}
 */
export function accumulateTokens(current, ev) {
  return typeof ev?.tokens === "number" ? current + ev.tokens : current;
}

/**
 * Completed report filenames from a raw `reports/` listing.
 * Reservation sentinels are not completed reports — `isReservedReportFile` is
 * the single definition of that convention, shared with career-ops.ts.
 *
 * @param {string[]} entries
 * @returns {Set<string>}
 */
export function completedReportNames(entries) {
  return new Set(entries.filter((name) => name.endsWith(".md") && !isReservedReportFile(name)));
}

/**
 * Whether `afterEntries` contains a completed report name absent from
 * `beforeEntries` — i.e. persistence actually happened, as opposed to a
 * `NNN-RESERVED.md` sentinel merely being replaced or churned.
 * @param {string[]} beforeEntries
 * @param {string[]} afterEntries
 * @returns {boolean}
 */
export function hasNewCompletedReport(beforeEntries, afterEntries) {
  const before = completedReportNames(beforeEntries);
  const after = completedReportNames(afterEntries);
  for (const name of after) {
    if (!before.has(name)) return true;
  }
  return false;
}

/**
 * run-prompts.mjs — the prompts /api/run sends each worker kind (#2185).
 *
 * The web ORCHESTRATES the real career-ops engine — it does NOT reimplement it.
 * kind "evaluate" runs the REAL modes/oferta.md and persists the canonical
 * artifacts (A–F report + tracker row) via the SAME scripts the CLI uses
 * (reserve-report-num.mjs → reports/ → batch/tracker-additions/ → merge-tracker.mjs),
 * so a web evaluation is byte-identical to a CLI one (single source of truth, no
 * drift). kind "research" stays read-only.
 */
import { CV_ENVELOPE_INSTRUCTION } from "./cv-envelope.mjs";

/**
 * Is this company name safe to interpolate into a shell command inside a prompt?
 *
 * The fix-portal prompt tells the agent to run
 * `node verify-portals.mjs --add "<company>"`, and fix-portal is one of the kinds
 * that still holds Bash. Company names are not always the user's own typing — they
 * reach the dashboard from public ATS listings — so a crafted one could close the
 * quote and append a command. Allow the characters real company names use and
 * refuse the rest. The caller turns a refusal into a 400 rather than sanitizing,
 * because a silently rewritten name would resolve the wrong portal.
 *
 * @param {string} name
 * @returns {boolean}
 */
export function isShellSafeCompanyName(name) {
  return typeof name === "string"
    && name.length > 0
    && name.length <= 80
    && SAFE_COMPANY_NAME.test(name)
    // A single & is needed (AT&T, Marks & Spencer); && is a command separator and
    // appears in no real company name. Every other chaining character — ; | $ `
    // quotes, newline — is already outside the character class.
    && !name.includes("&&");
}

const SAFE_COMPANY_NAME = /^[\p{L}\p{N} .,&'()+/-]+$/u;

/**
 * The exact prompt each worker kind is sent.
 *
 * Lives in a plain .mjs so it can be asserted on as a VALUE: the pdf prompt is
 * the load-bearing half of #2185 (it is what tells the agent to emit the CV
 * inline instead of writing it), and a guard that greps route.ts for the marker
 * text matched the route's own comments instead. See test-all.mjs §55.6.
 *
 * @param {{kind: string, input: string, memory: string, today: string}} args
 * @returns {string}
 */
/** ISO calendar date, the only form the dashboard's POSTED column parses. */
const ISO_DATE_RE = /^20\d{2}-\d{2}-\d{2}$/;

export function buildPrompt({ kind, input, memory, today, postedAt }) {
  const mem = memory.trim() ? `\n\nDurable notes about the user (from their profile):\n${memory.trim()}\n` : "";
  if (kind === "research") {
    return `You are investigating the user's OWN work / portfolio to surface job-search-relevant strengths, headless. Investigate the target (use WebFetch for URLs; read local files if referenced) and report: what it is, why it is impressive, and how to leverage it in their job search — which roles/claims it supports and how to frame it on a CV. Be specific, honest, and encouraging. Report only: never submit, send, or click Apply anywhere, and contact no one — you are investigating the user's own work, not acting on it.${mem}

End with EXACTLY one final line: VERDICT: {0-5 signal strength}/5 — {why it helps their search, ≤12 words}

Target: ${input}`;
  }
  if (kind === "pdf") {
    // The agent tailors content only — it neither renders the PDF nor saves it.
    // Rendering moved to the backend because launching a real browser can hit a
    // sandbox escalation nobody is present to approve (#2172); SAVING moved for a
    // different reason (#2185): tool grants are tool-name-only, so the Write/Edit
    // this step used to need was unscoped, and a prompt injection in the posting
    // or the report — both of which land in this agent's context — could aim it at
    // cv.md or data/applications.md. The agent now emits the CV inline and the
    // backend (a plain Node process, no CLI sandbox) writes and renders it, so
    // pdf mode runs with no write tool at all.
    return `You are tailoring the user's ATS-optimized CV for application #${input}, headless, on their machine. Run the REAL career-ops "pdf" mode's CONTENT step: follow modes/pdf.md's TAILORING rules exactly (do not improvise your own scoring or format). Apply its CONTENT rules — keyword injection, ordering, the competency grid, project selection, and its never-invent-a-skill rule. Its steps that shell out (the jd-skill-gap.mjs check, template resolution) and its build/save/render steps are NOT performed on web runs; the platform handles output itself.
1. Read modes/pdf.md, cv.md, config/profile.yml, and the evaluation report at reports/${input}-*.md (for the JD keywords + analysis).
2. Tailor the CV per modes/pdf.md: inject the JD's keywords into the summary + first bullets, reorder experience by relevance, build the competency grid, pick the top 3–4 projects. NEVER invent skills — only reword REAL experience using the JD's vocabulary.
3. Fill templates/cv-template.html's {{...}} placeholders with the tailored content. Use that template even though modes/pdf.md resolves one via cv-templates.mjs: web runs always use the base template. ${CV_ENVELOPE_INSTRUCTION}
4. Emit the envelope EXACTLY ONCE. The platform writes the HTML, renders the PDF, and updates the tracker's PDF column itself, only after a confirmed successful render. Do not submit anything anywhere.

After the envelope, end with EXACTLY one final line: VERDICT: {5 if the complete HTML envelope was emitted, else 1}/5 — {a one-line summary, ≤12 words}`;
  }
  if (kind === "fix-portal") {
    return `A company's job-portal ATS slug is BROKEN — career-ops can no longer scan it, so it silently disappears from every future scan. Repair it (headless, on the user's machine):
1. Run \`node verify-portals.mjs --add "${input}"\` — it probes Greenhouse/Ashby/Lever for the company's correct ATS slug and prints the suggested ats + slug.
2. Open portals.yml, find the "${input}" entry under tracked_companies, and update its careers_url (and any api/slug field) to the suggested WORKING ATS URL. Change ONLY this one company; preserve all other YAML structure, comments and formatting exactly.
3. Re-run \`node verify-portals.mjs\` and confirm "${input}" now shows ✅ live (not ❌).
If NO slug variant resolves, say so clearly and leave portals.yml unchanged. Never touch any other company. This is a config repair: do not submit, send, or click Apply anywhere, and edit no file other than portals.yml.

End with EXACTLY one final line: VERDICT: {5 if now live, else 1}/5 — {what you changed, ≤12 words}`;
  }
  // The posting date is INTERPOLATED, not asked for. The scanner wrote it into
  // pipeline.md from the provider's own `offer.postedAt`; the server already has
  // it (readScanDates/readInbox) and passes it here, so the agent copies a value
  // rather than deriving one. modes/oferta.md is explicit that a guessed date is
  // worse than none — the dashboard's POSTED column renders an absent date as
  // `—`, and an invented one reports a months-old req as fresh.
  //
  // Canonical form, taken from the regex that CONSUMES it (dashboard's
  // rePostedOn) rather than from prose: its own trailing segment after `; `,
  // anchored to a separator, ISO `YYYY-MM-DD`. Mid-sentence mentions are
  // deliberately not metadata there, so this must be a segment or nothing.
  //
  // Absent → the empty string, so the row is byte-identical to today's. Same
  // reason the url field is always written but may be empty: the shape an agent
  // reliably follows is one unconditional template, and here the CONTENT is
  // conditional precisely because "write nothing" is the required behaviour.
  const postedSegment = ISO_DATE_RE.test(String(postedAt ?? "")) ? `; posted: ${postedAt}` : "";

  // evaluate (default) — run the REAL oferta mode + persist canonically
  //
  // The TSV row carries 10 fields, the 10th being the posting URL that
  // merge-tracker dedupes on (#1298). The web is a WRITER of that file, not only
  // a reader: emitting 9 fields stays valid forever, so nothing would ever go
  // red — every job evaluated from the web would simply sit outside the
  // URL dedup. Compatible and half-dead at once, which is the failure mode with
  // no symptom.
  //
  // ALWAYS 10 fields, empty when there is no URL, deliberately: an
  // unconditional template is one an agent follows, "emit 9 or 10 depending"
  // is one it sometimes forgets. Empty and absent are byte-identical in the
  // written row (verified against merge-tracker), so the robust instruction
  // costs nothing. Not "N/A" either — parseTsvExtras drops placeholders
  // precisely so they can't be misread as the row's LOCATION.
  return `You are running the OFFICIAL career-ops job evaluation, HEADLESS, on the user's own machine. Today is ${today}. Run the REAL career-ops evaluation — do NOT improvise your own scoring.

1. Read modes/oferta.md and follow it EXACTLY (blocks A–F, G posting-legitimacy, and the Machine Summary). Ground the fit in THIS person: read cv.md, config/profile.yml and modes/_profile.md. Use WebFetch to read the posting (you are headless — Playwright is unavailable, so use WebFetch and mark the report header "Verification: unconfirmed (batch mode)").

2. Persist the result CANONICALLY so the web and the CLI share ONE source of truth:
   a. Reserve a report number: run \`node reserve-report-num.mjs\` — its stdout is a 3-digit number (e.g. 035).
   b. Write the full report to reports/{num}-{company-slug}-${today}.md  (company-slug = company lowercased, non-alphanumerics → hyphens).
   c. Append ONE row of 10 TAB-separated columns to batch/tracker-additions/{num}-{company-slug}.tsv, in THIS exact order (real \\t tabs, status BEFORE score). ALWAYS write all 10 fields — leave the last one EMPTY if there is no posting URL, never "N/A" or "-":
      {num}\t${today}\t{Company}\t{Role}\t{CanonicalStatus e.g. Evaluated}\t{score}/5\t❌\t[{num}](reports/{num}-{company-slug}-${today}.md)\t{one-line note}${postedSegment}\t{posting URL, or empty}
   d. Merge into the tracker: run \`node merge-tracker.mjs\` (it dedupes by company+role+report-num, validates the status, and writes data/applications.md — NEVER edit applications.md by hand).

3. NEVER submit an application, fill no forms, contact no one. This is evaluation + persistence ONLY.${mem}

After everything above is written and merged, output EXACTLY one final line, nothing after it:
VERDICT: {score}/5 — {reason in 12 words or fewer}

Posting URL: ${input}`;
}

export const CONFIG_KEY = "career-ops:config";

export function readSavedCliId(): string | null {
  try {
    const raw = localStorage.getItem(CONFIG_KEY);
    const id = raw ? JSON.parse(raw).cliId : "";
    return typeof id === "string" && id ? id : null;
  } catch {
    return null;
  }
}

export function persistCliId(cliId: string) {
  try {
    const raw = localStorage.getItem(CONFIG_KEY);
    const prev = raw ? JSON.parse(raw) : {};
    localStorage.setItem(
      CONFIG_KEY,
      JSON.stringify({ ...prev, mode: prev.mode || "cli", cliId }),
    );
  } catch {
    /* quota / private mode */
  }
}

export function pickSoleInstalled(
  clis: { id: string; installed?: boolean }[] | undefined,
): string | null {
  const installed = (clis || []).filter((c) => c.installed);
  return installed.length === 1 ? installed[0].id : null;
}

/** Saved Config cliId, or the only installed CLI (and persist that pick). */
export async function resolveCliId(): Promise<string | null> {
  const saved = readSavedCliId();
  if (saved) return saved;
  try {
    const r = await fetch("/api/clis");
    const d = (await r.json()) as { clis?: { id: string; installed?: boolean }[] };
    const sole = pickSoleInstalled(d.clis);
    if (!sole) return null;
    persistCliId(sole);
    return sole;
  } catch {
    return null;
  }
}

import { spawn } from "node:child_process";

// Plain .mjs (same pattern as tracker-table.mjs/clean-chips.mjs) so
// tests/lib/spawn-cli.test.mjs can import it directly under Node. Import it with the
// .mjs extension included (e.g. "@/lib/spawn-cli.mjs") — unlike .ts files,
// which TypeScript resolves without an extension, ESM specifiers for plain
// JS modules must be fully specified.

/**
 * Spawn a headless agent CLI with stdin closed.
 *
 * CLIs such as `codex exec` read additional prompt text from stdin when a pipe
 * is left open. A web request never supplies that extra input, so leaving the
 * default pipe open makes Codex wait forever without producing stdout. This is
 * the ONLY spawn path for CLI-invoking routes — every call site should use it
 * instead of `node:child_process`'s `spawn` directly, so the fix can't drift.
 *
 * It also replaces the `stdio: ["ignore", ...]` the apply planners used to spell
 * for the same reason — one mechanism means one place for this to be right.
 * The options type omits `stdio` on purpose: stdout/stderr must stay pipes for
 * every caller's stream handlers, and TypeScript keeps `child.stdout` non-null
 * only under that contract. `stdin` is still optional-chained so an untyped
 * caller passing `stdio` anyway degrades safely (null stdin) instead of throwing.
 *
 * @param {string} binPath
 * @param {string[]} args
 * @param {import("node:child_process").SpawnOptionsWithoutStdio} options
 */
export function spawnHeadlessCli(binPath, args, options) {
  const child = spawn(binPath, args, options);
  child.stdin?.end();
  return child;
}

