/**
 * Fold raw status text to a lookup key.
 *
 * Mirrors foldStatusInput() in tracker-utils.mjs (#2705). The `\u0307` strip is
 * what makes a capitalised Turkish status resolve: JS lowercases `İ` to `i` +
 * U+0307 COMBINING DOT ABOVE, so "İşe alındı" keys as "i̇şe alındı" and misses
 * the "işe alındı" entry. Real tracker rows are capitalised, so without this
 * the alias table is only reachable by input that is already lowercase.
 *
 * NFKC and NOT NFD, deliberately: NFD decomposes precomposed letters too, so
 * the same strip would reach the dots of ż / ė / ġ and collapse Żubr onto
 * Zubr, Ėmė onto Eme, Ġenerali onto Generali.
 *
 * Markdown bold is stripped because AGENTS.md forbids it in the status field —
 * which is exactly why it turns up there.
 *
 * @param {string} s - Raw status text from the tracker.
 * @returns {string} Lookup key.
 */
function foldStatus(s) {
  return String(s ?? "")
    .replace(/\*\*/g, "")
    .trim()
    .normalize("NFKC")
    .toLowerCase()
    .replace(/\u0307/gu, "");
}

/**
 * Normalize a raw tracker status to a canonical stage token.
 *
 * Unknown input is passed through uppercased rather than rejected, so a status
 * this map has never seen still renders as itself. Consumers substring-test the
 * result, which is why an alias missing from the map above resolves to no stage
 * at all — see tests/lib/status-alias.test.mjs.
 *
 * @param {string} s - Raw status text from the tracker.
 * @returns {string} Canonical stage token, or the uppercased input.
 */
export function canonStatus(s) {
  const k = foldStatus(s);
  if (k === "" || k === "—" || k === "-") return "DISCARDED";
  return STATUS_ALIAS[k] ?? String(s ?? "").toUpperCase();
}

// The decisions /api/status makes around its set-status.mjs child, kept here so
// they are testable without spawning anything.

// What the caller is told when the CLI supplied no usable message of its own.
const GENERIC_FAILURE = "status update failed";

/**
 * The CLI's JSON document, or null when stdout carries none.
 *
 * `--json` prints one JSON object, but diagnostics can precede it — a ledger
 * append warning, say. Scanning forward to the first `{` finds a brace inside
 * that diagnostic just as readily as the document, and the resulting slice does
 * not parse. The route then reports 500 for a write the CLI already committed,
 * losing `changed` and `statusLogged` with it.
 *
 * So the document is read from the end: the last line that parses as a plain
 * object is the result. A diagnostic that happens to be valid JSON cannot shadow
 * it, because the result is printed last.
 *
 * @param {string} stdout
 * @returns {Record<string, unknown> | null}
 */
export function parseCliJson(stdout) {
  const lines = String(stdout ?? "").split("\n");
  for (let i = lines.length - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (!line.startsWith("{")) continue;
    try {
      const parsed = JSON.parse(line);
      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        return /** @type {Record<string, unknown>} */ (parsed);
      }
    } catch {
      // Not the document line. Keep scanning earlier lines.
    }
  }
  return null;
}

/**
 * The message that goes in the response body for a failed run.
 *
 * Only the CLI's own `error` string is passed through. Child stderr never is:
 * on the exit-1 crash path it is a Node stack trace carrying absolute server
 * paths, which is exactly the content the spawn-failure path already refuses to
 * echo. Guarding one of the two and not the other left the disclosure open on
 * the path most likely to produce a stack trace in the first place.
 *
 * stderr still belongs in the server log — the caller just never sees it, which
 * is why this takes it and ignores it rather than letting a caller forget it
 * exists.
 *
 * @param {Record<string, unknown> | null} parsed
 * @param {string} [_stderr] Deliberately unused; log it at the call site.
 * @returns {string}
 */
export function clientErrorMessage(parsed, _stderr) {
  return typeof parsed?.error === "string" ? parsed.error : GENERIC_FAILURE;
}

/**
 * The `--row` argument for a request's row selector, or null when it names none.
 *
 * `n` arrives from untrusted JSON and is only typed as a string, so it can be an
 * array, an object, or a non-numeric string. `String(n)` turns those into
 * `"[object Object]"` and similar, which costs a process spawn and a tracker
 * lock acquisition to learn what a check here answers for free — and returns the
 * CLI's usage text rather than a message about the field.
 *
 * Not an injection concern: execFile takes an argv array and `--row` consumes
 * the next token as its value, so a flag-shaped value cannot introduce an
 * option. This is about cost and about answering the caller specifically.
 *
 * @param {unknown} n
 * @returns {string | null}
 */
export function trackerRowArg(n) {
  if (typeof n !== "string" && typeof n !== "number") return null;
  const row = String(n).trim();
  return /^\d+$/.test(row) ? row : null;
}

// Pure JS helper for the AI-search <<offer:>> stream parser — no TypeScript
// types so it can be imported directly by both explore-ai.ts (which uses it)
// and tests/lib/stream-parse.test.mjs (which can't import .ts without a
// runner). This is the single source of truth for the "how much of a
// possibly-split opener do we hold back?" logic — the load-bearing part of
// never dropping an offer whose `<<offer:` marker straddles a stream chunk
// boundary (#2290).

/**
 * Length of the trailing run of `buf` that is a proper prefix of `opener` —
 * i.e. a possibly-split opener to buffer rather than flush as narration.
 *
 * Returns the LONGEST such suffix length (0 if none). The previous code checked
 * only whether the fixed last `opener.length - 1` characters formed a prefix,
 * which missed shorter partial openers (`<<`, `<<off`) preceded by other text
 * and dropped the offer once the rest of the marker arrived (#2290).
 *
 * @param {string} buf - Current parse buffer with no full `opener` in view.
 * @param {string} opener - The envelope opener, e.g. "<<offer:".
 * @returns {number} Number of trailing chars to keep buffered (0 = flush all).
 */
export function pendingOpenerLen(buf, opener) {
  const max = Math.min(buf.length, opener.length - 1);
  for (let k = max; k > 0; k--) {
    if (buf.endsWith(opener.slice(0, k))) return k;
  }
  return 0;
}

/**
 * tracker-table.mjs — header-aware parsing of the `data/applications.md` table
 * for the web read path.
 *
 * The header-alias table is NOT mirrored here: it is loaded at runtime from
 * `tracker-aliases.json` in the career-ops root — the same single source
 * tracker-parse.mjs exports as HEADER_ALIASES — so the web reader and the Node
 * tracker tooling can never drift (PR #1598 review). A build-time import of the
 * core module is impossible: Turbopack's root is pinned to web/ (see
 * next.config.mjs) and refuses modules outside it, so the shared source is a
 * JSON file read with fs, like every other career-ops file this app consumes.
 *
 * Plain .mjs (same pattern as clean-chips.mjs) so tracker-columns-tests.mjs can
 * import it directly under Node and regression-test the REAL alias chain.
 */
import fs from "node:fs";
import path from "node:path";

/**
 * Canonical tracker-parse field name → web Application field. The web type
 * names the number column `n` (tracker-parse calls it `num`); every other
 * field maps 1:1. This maps FIELDS (a fixed schema, changing only with the
 * Application type itself), not header aliases — the alias table lives only
 * in tracker-aliases.json.
 * @type {Record<string, string>}
 */
const WEB_FIELD = {
  num: "n", date: "date", company: "company", via: "via", role: "role", location: "location",
  score: "score", status: "status", pdf: "pdf", report: "report", notes: "notes",
};

/** @type {Map<string, {mtimeMs: number, size: number, aliases: Record<string, string>}>} */
const aliasCache = new Map();

/**
 * Load the shared header-alias table (lowercased header text → canonical field)
 * from `{rootDir}/tracker-aliases.json`. Cached per resolved file path so the
 * request-time read path (readApplications runs on every API route / page
 * render) doesn't re-read and re-parse the JSON each call — but the cache is
 * keyed on the file's mtime+size (one statSync per call, no full read), so a
 * system update that rewrites the alias table is picked up on the next request
 * instead of after a server restart. Failures are NEVER cached: a
 * missing/corrupt file (core checkout predating the JSON) yields an empty
 * table — no header row is then detected and parseApplications falls back to
 * the legacy fixed column order — and the cache entry is cleared so a later
 * recovered file is loaded immediately.
 * @param {string} rootDir - career-ops root (careerOpsRoot() on the web side).
 * @returns {Record<string, string>}
 */
export function loadHeaderAliases(rootDir) {
  const file = path.resolve(rootDir, "tracker-aliases.json");
  try {
    const { mtimeMs, size } = fs.statSync(file);
    const cached = aliasCache.get(file);
    if (cached && cached.mtimeMs === mtimeMs && cached.size === size) return cached.aliases;
    const parsed = JSON.parse(fs.readFileSync(file, "utf8"));
    // Guard non-object JSON (null, arrays, scalars) — treat like corrupt.
    /** @type {Record<string, string>} */
    const aliases = parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
    aliasCache.set(file, { mtimeMs, size, aliases });
    return aliases;
  } catch {
    aliasCache.delete(file); // never cache failure — recovery must not need a restart
    return {};
  }
}

/**
 * Split a tracker line into trimmed cells (outer pipes removed).
 *
 * The trailing empty part is dropped only when the row actually ENDS with a
 * pipe. Hand-edited rows without it are one part narrower but still complete —
 * tracker-utils rebuildRow supports them and parseTrackerRow reads their last
 * cell — so an unconditional `slice(1, -1)` silently ate real data (Notes read
 * as empty). Same rule as parseTrackerRow's width computation (#2369).
 * @param {string} line
 * @returns {string[]}
 */
function trackerCells(line) {
  const parts = line.split("|").map((c) => c.trim());
  return parts.slice(1, line.trimEnd().endsWith("|") ? -1 : undefined);
}

/**
 * Pre-scan for the header row and build the column map, exactly like
 * detectColumns in tracker-parse.mjs: ANY row whose cells resolve the essential
 * columns counts as the header (so alias headers like "Num" work too, not just
 * "#"). Returns null when no recognizable header exists.
 * @param {string[]} lines
 * @param {Record<string, string>} aliases - from loadHeaderAliases().
 * @returns {Record<string, number> | null}
 */
export function detectColumnMap(lines, aliases) {
  for (const raw of lines) {
    const line = raw.trim();
    if (!line.startsWith("|")) continue;
    const cells = trackerCells(line);
    /** @type {Record<string, number>} */
    const m = {};
    cells.forEach((c, i) => {
      const k = WEB_FIELD[aliases[c.toLowerCase()]];
      if (k) m[k] = i; // unconditional: last occurrence wins, same as detectColumns
    });
    if (["n", "company", "role", "score", "status"].every((k) => m[k] != null)) return m;
  }
  return null;
}

/**
 * Parse the tracker markdown (source of truth) into application rows.
 * Columns are mapped by header name via the shared alias table in
 * `{rootDir}/tracker-aliases.json`; the legacy fixed order
 * (# | Date | Company | Role | Score | Status | PDF | Report | Notes)
 * is the fallback when no recognizable header row is present.
 * Rows without a numeric # cell (header, separator, stray pipes) are skipped,
 * mirroring parseTrackerRow in tracker-parse.mjs.
 * @param {string} md - content of data/applications.md.
 * @param {string} rootDir - career-ops root holding tracker-aliases.json.
 * @returns {{n: string, date: string, company: string, via: string, role: string, score: string, status: string, pdf: string, report: string, notes: string}[]}
 */
export function parseApplications(md, rootDir) {
  const lines = md.split("\n");
  const map = detectColumnMap(lines, loadHeaderAliases(rootDir));
  const mappedWidth = map ? Math.max(...Object.values(map)) + 1 : 0;
  const rows = [];
  for (const raw of lines) {
    const line = raw.trim();
    if (!line.startsWith("|")) continue;
    const cells = trackerCells(line);
    if (cells.length < 8) continue;
    if (map) {
      // Width guard, mirroring parseTrackerRow: a row missing an INTERIOR cell
      // shifts every later column one left, so requiring merely that the
      // highest mapped index EXISTS is not enough — the row must carry a cell
      // for every mapped column. Without this the reader rendered a
      // pre-`--migrate-via` row with Score in Role and Status in Score (#2369).
      if (cells.length < mappedWidth) continue;
      const at = (/** @type {string} */ k) => cells[map[k]] ?? "";
      if (!/^\d+$/.test(at("n"))) continue; // header / separator / malformed
      rows.push({
        n: at("n"), date: at("date"), company: at("company"), via: at("via"), role: at("role"),
        score: at("score"), status: at("status"), pdf: at("pdf"), report: at("report"),
        notes: at("notes"),
      });
    } else {
      // Legacy fixed order; tolerate the 8-cell variant where Notes is absent.
      if (!/^\d+$/.test(cells[0])) continue; // header / separator / malformed
      const [n, date, company, role, score, status, pdf, report, ...rest] = cells;
      rows.push({ n, date, company, via: "", role, score, status, pdf, report, notes: rest.join(" | ") });
    }
  }
  return rows;
}

/** Cards the home dashboard renders when no explicit limit is asked for. */
export const DEFAULT_OFFER_LIMIT = 24;

/**
 * Ceiling for a caller-requested limit, and what Explore's "See all" hand-off
 * asks for. The payload stays bounded on purpose: explorer-view renders every
 * offer it receives (no virtualisation, no pagination), and a default
 * portals.yml — ~120 companies against a catch-all title_filter — can leave
 * thousands of un-evaluated rows inside a 7-day window. `count` is complete
 * regardless, so the UI shows an honest total without an unbounded render.
 */
export const MAX_OFFER_LIMIT = 200;

/**
 * Resolve the `?limit=` query value into a finite render ceiling. Anything
 * missing, malformed or out of range degrades to a bounded default rather than
 * to an unbounded list.
 *
 * The whole trimmed value has to be an integer — `Number`, not `parseInt`,
 * because parseInt accepts a numeric *prefix*: it would read "24junk" as 24 and
 * "1e9" as 1, letting a malformed limit silently under-fetch instead of falling
 * back. `Number.isInteger` also rejects Infinity, so the unbounded sentinel
 * cannot slip back in through the query string.
 */
export function resolveOfferLimit(raw) {
  if (raw == null) return DEFAULT_OFFER_LIMIT;
  const text = String(raw).trim();
  if (text === "") return DEFAULT_OFFER_LIMIT;
  const requested = Number(text);
  if (!Number.isInteger(requested)) return DEFAULT_OFFER_LIMIT;
  return Math.min(MAX_OFFER_LIMIT, Math.max(1, requested));
}

/**
 * Collect fresh, unique offers while keeping the response payload bounded.
 * `count` always represents the full result set; `offers` is only the slice the
 * caller asked to render. This prevents a UI card limit from masquerading as
 * the number of matches found.
 */
export function collectWhatsNew(rows, { cutoff, toOffer, offerLimit = DEFAULT_OFFER_LIMIT, fallbackLimit = 12 }) {
  const seen = new Set();
  const offers = [];
  let count = 0;
  let anyDated = false;

  const add = (columns, limit) => {
    const offer = toOffer(columns);
    if (!offer || seen.has(offer.url)) return;
    seen.add(offer.url);
    count += 1;
    if (offers.length < limit) offers.push(offer);
  };

  // Recent-by-date supply loop. Walk every row so `count` is not capped by the
  // number of cards returned to the client.
  for (let i = rows.length - 1; i >= 1; i--) {
    const columns = rows[i].split("\t");
    const timestamp = Date.parse(columns[1] || "");
    if (Number.isFinite(timestamp)) anyDated = true;
    if (!Number.isFinite(timestamp) || timestamp < cutoff) continue;
    add(columns, offerLimit);
  }

  // Legacy histories may have no parseable first_seen values. Preserve the
  // append-order fallback while still returning its full unique count.
  if (count === 0 && !anyDated) {
    for (let i = rows.length - 1; i >= 1; i--) {
      add(rows[i].split("\t"), fallbackLimit);
    }
  }

  return { offers, count };
}

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { checkRequest, parseAllowedHosts } from "@/lib/origin-guard.mjs";

// Single choke point over the API surface. Every /api request is gated on the
// same-origin + loopback guard before it can reach a route handler (which may
// spawn a child process or write the user's files). See origin-guard.mjs for
// the two-layer rationale (F1 drive-by CSRF, F2 LAN reachability).
//
// Opt in to extra hosts (e.g. a trusted LAN box) with a comma/space separated
// CAREER_OPS_WEB_ALLOWED_HOSTS; unset means loopback only.
export function proxy(req: NextRequest) {
  const decision = checkRequest({
    secFetchSite: req.headers.get("sec-fetch-site"),
    origin: req.headers.get("origin"),
    host: req.headers.get("host"),
    allowedHosts: parseAllowedHosts(process.env.CAREER_OPS_WEB_ALLOWED_HOSTS),
  });
  if (!decision.ok) {
    return NextResponse.json({ error: decision.reason }, { status: decision.status });
  }
  return NextResponse.next();
}

