// Executes the REAL makeAiStreamParser / canon() from explore-ai.ts — the file
// has no `@/` alias imports and no Node-only deps ("Client-safe (NO node
// imports)" per its own header), so unlike pipeline.ts it can be imported
// directly here rather than needing source-text extraction.
//
// Covers the silent-drop bug: canon() used to key on host+pathname only,
// discarding the query string, so two DIFFERENT Greenhouse postings sharing a
// path (distinct only by `?gh_jid=`) collapsed onto one dedup key and every
// opening after the first was silently absent from AI Discover results.
//
// Run:  node --test tests/lib/explore-ai-dedup.test.mjs

import { test } from "node:test";
import assert from "node:assert/strict";
import { makeAiStreamParser, canon } from "../../src/lib/explore-ai.ts";

const envelope = (offer) => `<<offer:${JSON.stringify(offer)}>>`;

test("two distinct postings that share host+path but differ by a functional query id are BOTH kept", () => {
  const parser = makeAiStreamParser();
  const jobA = "https://boards.greenhouse.io/acme/jobs/apply?gh_jid=4471829005";
  const jobB = "https://boards.greenhouse.io/acme/jobs/apply?gh_jid=5501203417";
  const chunks = [
    ...parser.feed(envelope({ url: jobA, company: "Acme", title: "Backend Engineer" })),
    ...parser.feed(envelope({ url: jobB, company: "Acme", title: "Frontend Engineer" })),
  ];
  const offers = chunks.filter((c) => c.kind === "offer");
  assert.equal(offers.length, 2, "the second, genuinely different posting was silently dropped");
  assert.equal(offers[0].offer.url, jobA);
  assert.equal(offers[1].offer.url, jobB);
});

test("a TRUE duplicate (same posting, tracking param added) is still deduped within a run", () => {
  const parser = makeAiStreamParser();
  const base = "https://boards.greenhouse.io/acme/jobs/apply?gh_jid=4471829005";
  const tracked = base + "&utm_source=linkedin";
  const chunks = [
    ...parser.feed(envelope({ url: base, company: "Acme", title: "Backend Engineer" })),
    ...parser.feed(envelope({ url: tracked, company: "Acme", title: "Backend Engineer" })),
  ];
  const offers = chunks.filter((c) => c.kind === "offer");
  assert.equal(offers.length, 1, "the same posting with a tracking param appended should dedup, not double-post");
});

test("knownUrls filters an already-seen posting by its exact gh_jid, not by host+path alone", () => {
  const known = new Set([canon("https://boards.greenhouse.io/acme/jobs/apply?gh_jid=4471829005")]);
  const parser = makeAiStreamParser({ knownUrls: known });
  const sameJob = "https://boards.greenhouse.io/acme/jobs/apply?gh_jid=4471829005";
  const differentJob = "https://boards.greenhouse.io/acme/jobs/apply?gh_jid=9999999999";
  const chunks = [
    ...parser.feed(envelope({ url: sameJob, company: "Acme", title: "Already known" })),
    ...parser.feed(envelope({ url: differentJob, company: "Acme", title: "New opening" })),
  ];
  const offers = chunks.filter((c) => c.kind === "offer");
  assert.equal(offers.length, 1, "a genuinely new posting at the same host+path was filtered as if already known");
  assert.equal(offers[0].offer.url, differentJob);
});

test("two scheme-valid but URL-unparseable offers BOTH survive — an empty key must not dedup against itself", () => {
  // Both pass toOffer()'s /^https?:\/\// gate (so they reach canon()) but throw
  // in `new URL(...)`, so canon() returns '' for each. Without the `key &&`
  // guard, the second offer's '' would match the first's '' in `seen` and get
  // silently dropped — two UNRELATED malformed entries treated as duplicates
  // of each other purely because neither could be keyed.
  const parser = makeAiStreamParser();
  const unparseableA = "https://[bad";
  const unparseableB = "http:// space.example.com";
  assert.equal(canon(unparseableA), "", "test premise: A must canonicalize to the empty key");
  assert.equal(canon(unparseableB), "", "test premise: B must canonicalize to the empty key");
  const chunks = [
    ...parser.feed(envelope({ url: unparseableA, company: "Acme", title: "Role A" })),
    ...parser.feed(envelope({ url: unparseableB, company: "Acme", title: "Role B" })),
  ];
  const offers = chunks.filter((c) => c.kind === "offer");
  assert.equal(offers.length, 2, "an empty canonical key deduped against another empty key");
  assert.equal(offers[0].offer.url, unparseableA);
  assert.equal(offers[1].offer.url, unparseableB);
});

// Tests for isScannerMissing() using Node's built-in test runner.
// Imports directly from explore-error.mjs (the single source of truth) so the
// test and production code can never drift out of sync.
//
// Run:  node --test tests/lib/explore-error.test.mjs

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  isScannerMissing,
  scannerMissingBody,
  SCANNER_MISSING_CODE,
  SCANNER_MISSING_STATUS,
} from "../../src/lib/explore-error.mjs";

// The data-only / pre-onboarding checkout has no scanner. /api/explore signals it
// with an explicit code in the response body. This is the only failure the
// "Discovery needs the full toolkit" panel (call to action: update career-ops)
// should ever cover.
test("the scanner-missing code is scanner-missing", () => {
  assert.equal(isScannerMissing({ code: SCANNER_MISSING_CODE }), true);
  assert.equal(isScannerMissing(scannerMissingBody()), true);
});

// The reason this keys on a code and not on HTTP 400.
//
// 400 is a SHARED channel. /api/explore/ai returns three structurally different
// 400s, and the AI call site in explore-provider.tsx classified all of them as
// "your checkout has no scanner":
//
//   { error: "bad json" }
//   { error: "query and cliId required" }
//   { code: "MODE_MISSING", error: "AI search needs a newer career-ops — …" }
//
// So a malformed request rendered the "Discovery needs the full toolkit" panel
// and told the user to update career-ops when nothing was wrong with their
// checkout. MODE_MISSING is the sharpest case: it is a real, DIFFERENT missing
// -capability error with its own copy, and it was overwritten by the scanner
// panel's.
test("the other 400s on the shared channel are NOT scanner-missing", () => {
  assert.equal(isScannerMissing({ code: "MODE_MISSING", error: "AI search needs a newer career-ops — update to enable it." }), false);
  assert.equal(isScannerMissing({ error: "bad json" }), false);
  assert.equal(isScannerMissing({ error: "query and cliId required" }), false);
});

// Regression guard from the original defect. A runtime scan error streams back
// AFTER a 200 response and carries no code. Its real message, "The scanner
// returned no readable output.", contains the word "scanner", which is what used
// to trip the panel via text matching. Neither the text nor the absence of a code
// may classify it as a broken checkout.
test("a runtime stream error is NOT scanner-missing", () => {
  assert.equal(isScannerMissing({ error: "The scanner returned no readable output." }), false);
  assert.equal(isScannerMissing({ error: "The scanner isn't available." }), false);
});

// Never throws and never guesses: this runs on a failure path, where the body is
// whatever the server actually sent — possibly nothing, possibly not JSON. The
// call sites use `.catch(() => ({}))`, so `{}` is the common real input.
test("a missing or non-object body is NOT scanner-missing", () => {
  assert.equal(isScannerMissing({}), false);
  assert.equal(isScannerMissing(undefined), false);
  assert.equal(isScannerMissing(null), false);
  assert.equal(isScannerMissing("SCANNER_MISSING"), false);
  assert.equal(isScannerMissing(400), false);
});

// The old signature took an HTTP status. Passing one now must NOT match, or a
// call site left un-migrated would keep the exact bug this change removes while
// still type-checking.
test("the old status-based call does not silently keep working", () => {
  assert.equal(isScannerMissing(SCANNER_MISSING_STATUS), false);
});

// Both ends of the contract are built from the same constant, so the route and
// the classifier cannot drift apart — the failure mode this whole module exists
// to prevent.
test("the response body the route sends is classified by the client", () => {
  const body = scannerMissingBody();
  assert.equal(body.code, SCANNER_MISSING_CODE);
  assert.equal(typeof body.error, "string");
  assert.ok(body.error.length > 0, "the panel renders body.error, so it must carry copy");
  assert.equal(isScannerMissing(body), true);
});

