// The follow-ups lock exists to stop a LOST UPDATE, so the test has to produce one.
//
// data/follow-ups.md is read-modify-written from two directions: the web's
// log/override routes and the core's cadence seeder (followup-seed.mjs). Each
// writer reads the whole file, adds its own line, and writes the whole file
// back. Unserialized, two overlapping writers each start from the same snapshot
// and the second's full-file write discards the first's line — no error, a
// well-formed file, one pin silently gone (the same shape as the tracker, #2900).
//
// This asserts the failure FIRST (unlocked writers lose data) and then that the
// core lock removes it. Without the negative half, a lock that never engaged
// would pass just as happily. Verified red by hand: swap withFollowupsLock for a
// passthrough and the "both survive" assertion fails.
//
// Run:  node --test tests/lib/followups-lock.test.mjs

import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

// Resolved from this file, not the cwd: test-all.mjs runs these suites from the
// repo root, where `cwd/..` points outside the checkout and every core case
// would skip as "not resolvable" while reporting green.
const CORE =
  process.env.CAREER_OPS_ROOT ||
  path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const coreSeed = path.join(CORE, "followup-seed.mjs");

// The guard has to answer "can this be imported", not "is the file there".
// followup-seed.mjs imports js-yaml, so a web-only install (web-ci.yml runs
// `npm ci` in web/ alone) has the file and not its dependencies; existsSync
// would call that runnable and the cases would fail on ERR_MODULE_NOT_FOUND
// instead of skipping (mirrors tracker-lock.test.mjs / #2922).
let core = null;
let skipCore = false;
try {
  core = await import(pathToFileURL(coreSeed).href);
} catch (err) {
  const coreAbsent = !fs.existsSync(coreSeed);
  const packageUnresolvable = err.url == null;
  const depsAbsent = !fs.existsSync(path.join(CORE, "node_modules"));
  if (err.code !== "ERR_MODULE_NOT_FOUND") throw err;
  if (coreAbsent) skipCore = `no core checkout at ${CORE}`;
  else if (packageUnresolvable && depsAbsent) skipCore = `core dependencies are not installed at ${CORE} (web-only checkout)`;
  else throw err;
}

function makeFollowups() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "flwlock-"));
  const file = path.join(root, "follow-ups.md");
  fs.writeFileSync(file, "# Follow-ups\n\n");
  return { root, file };
}

/** The override route's read-modify-write, verbatim in shape: read the whole
 *  file, add THIS app's pin, write the whole file back. The pause widens the
 *  read→write window so two callers reliably overlap. */
function addPin(file, appNum, date, pauseMs) {
  const existing = fs.readFileSync(file, "utf8");
  return new Promise((resolve) => setTimeout(() => {
    const base = existing.endsWith("\n") ? existing : existing + "\n";
    const tmp = `${file}.tmp`;
    fs.writeFileSync(tmp, base + `- next #${appNum} ${date} (set ${date})\n`);
    fs.renameSync(tmp, file);
    resolve();
  }, pauseMs));
}

const pinCount = (file) =>
  fs.readFileSync(file, "utf8").split("\n").filter((l) => /^- next #\d+ /.test(l)).length;

test("WITHOUT a lock, two concurrent pin writers lose one update silently", async () => {
  const { root, file } = makeFollowups();
  try {
    await Promise.all([addPin(file, 1, "2026-07-10", 60), addPin(file, 2, "2026-07-11", 10)]);
    // The bug: no error, file well-formed, only the last writer's pin remains.
    assert.equal(pinCount(file), 1, "expected the classic lost update to reproduce");
  } finally {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

test("WITH the core lock, both pins survive", { skip: skipCore }, async () => {
  const { root, file } = makeFollowups();
  const guarded = (appNum, date, pauseMs) =>
    core.withFollowupsLock(file, () => addPin(file, appNum, date, pauseMs), { timeoutMs: 5_000, retryMs: 25 });
  try {
    await Promise.all([guarded(1, "2026-07-10", 60), guarded(2, "2026-07-11", 10)]);
    assert.equal(pinCount(file), 2, "a pin was lost even under the lock");
  } finally {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

test("the lock is released on a throwing path, not just the happy one", { skip: skipCore }, async () => {
  // A leaked lock on a long-lived server is worse than the bug: the holder's pid
  // stays alive, so the core's stale-recovery will not reclaim it and the user's
  // own CLI is locked out until staleMs.
  const { root, file } = makeFollowups();
  try {
    await assert.rejects(
      core.withFollowupsLock(file, () => { throw new Error("boom"); }, { timeoutMs: 5_000, retryMs: 25 }),
      /boom/,
    );
    // If the lock had leaked, this second acquire would time out.
    await core.withFollowupsLock(file, () => addPin(file, 9, "2026-07-12", 0), { timeoutMs: 2_000, retryMs: 25 });
    assert.equal(pinCount(file), 1, "second acquire after a throw should have written");
  } finally {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

// Tests for the analytics headline tiles' cumulative counters.
// Imports directly from funnel-tiles.mjs (the single source of truth) so the
// test and production code can never drift out of sync.
//
// Run:  node --test tests/lib/funnel-tiles.test.mjs

import { test } from "node:test";
import assert from "node:assert/strict";
import { cumulativeTiles } from "../../src/lib/funnel-tiles.mjs";

test("an offer-holder has already interviewed", () => {
  // The bug: a snapshot count reported interviews=0 here, so the tile showed
  // the "Interviews follow replies — keep follow-ups warm" nudge to someone
  // holding an offer.
  const t = cumulativeTiles(["OFFER"]);
  assert.equal(t.interviews, 1);
  assert.equal(t.offers, 1);
});

test("a hire counts as both an interview and an offer", () => {
  // Landing the job proves the offer and everything before it (stats.mjs
  // computeFunnel: everOffer = Offer + Hired). Previously BOTH tiles read 0
  // and BOTH nudges fired at a candidate who had just been hired.
  const t = cumulativeTiles(["HIRED"]);
  assert.equal(t.interviews, 1);
  assert.equal(t.offers, 1);
});

test("stages accumulate across a realistic pipeline", () => {
  const t = cumulativeTiles(["HIRED", "OFFER", "INTERVIEW", "APPLIED", "APPLIED", "EVALUATED"]);
  assert.equal(t.interviews, 3); // interview + offer + hired
  assert.equal(t.offers, 2); // offer + hired
});

test("stages that never reached an interview are not counted", () => {
  const t = cumulativeTiles(["EVALUATED", "APPLIED", "RESPONDED", "DISCARDED", "SKIP"]);
  assert.equal(t.interviews, 0);
  assert.equal(t.offers, 0);
});

test("a rejection is not folded in — its stage is unknowable from a snapshot", () => {
  // stats.mjs calls the middle stages lower bounds for exactly this reason: a
  // Rejected row that never got a reply is indistinguishable from one rejected
  // after onsites, so counting it would overstate the funnel.
  const t = cumulativeTiles(["REJECTED", "REJECTED"]);
  assert.equal(t.interviews, 0);
  assert.equal(t.offers, 0);
});

test("an empty or absent pipeline is zero, not a crash", () => {
  assert.deepEqual(cumulativeTiles([]), { interviews: 0, offers: 0 });
  assert.deepEqual(cumulativeTiles(undefined), { interviews: 0, offers: 0 });
});

// Cache-key tests for the company logo proxy (/api/logo).
//
// The on-disk logo cache is permanent — a hit and a miss are both written once
// and never revalidated — so the key carries the whole burden of correctness:
// it must fold brand-name variants together, must never fold two different
// companies together, and must change whenever candidate generation changes.
//
// Run:  node --test tests/lib/logo-cache-key.test.mjs

import { test } from "node:test";
import assert from "node:assert/strict";
import { COMPANY_KEY_VERSION, companyCacheKey } from "../../src/lib/core/logo-cache-key.mjs";

test("punctuation, case and spacing variants of one brand share a key", () => {
  const variants = ["Acme, Inc.", "acme inc", "ACME   Inc", "A.C.M.E. Inc!"];
  const keys = new Set(variants.map(companyCacheKey));
  assert.equal(keys.size, 1, `expected one key, got ${[...keys].join(", ")}`);
});

test("distinct companies sharing their first 40 characters do not collide", () => {
  // Both normalize to the same 40-character prefix; only the digest separates
  // them. This is the truncation collision the digest exists to prevent.
  const a = "International Business Machines Corporation Holdings Alpha";
  const b = "International Business Machines Corporation Holdings Beta";
  assert.notEqual(companyCacheKey(a), companyCacheKey(b));
});

test("different companies get different keys", () => {
  assert.notEqual(companyCacheKey("Notion"), companyCacheKey("Zoom"));
});

test("keys are stable across calls", () => {
  assert.equal(companyCacheKey("Amazon.com Services LLC"), companyCacheKey("Amazon.com Services LLC"));
});

test("names with no alphanumeric content are rejected", () => {
  for (const bad of ["", "   ", "---", "!!!", null, undefined]) {
    assert.equal(companyCacheKey(bad), null, `expected null for ${JSON.stringify(bad)}`);
  }
});

test("keys are filesystem-safe and cannot escape the cache directory", () => {
  // A company name arrives from tracker data, so it is untrusted as a path
  // component. The NUL case is written as an escape, never embedded: a raw NUL
  // makes this file binary to grep and every future search of it silently
  // returns nothing (tests/source-no-nul-bytes.test.mjs).
  const hostile = ["../../etc/passwd", "..\\..\\windows\\system32", "a/b/c", "x y", "x\u0000y", "café/../../root"];
  for (const name of hostile) {
    const key = companyCacheKey(name);
    if (key === null) continue;
    assert.match(key, /^co_v\d+_[a-z0-9]{1,40}_[0-9a-f]{10}$/, `unsafe key for ${JSON.stringify(name)}: ${key}`);
  }
});

test("the version prefix is part of every key", () => {
  assert.match(COMPANY_KEY_VERSION, /^v\d+$/);
  assert.ok(companyCacheKey("Notion").startsWith(`co_${COMPANY_KEY_VERSION}_`));
});

test("bumping the version changes every key", () => {
  // Guards the invalidation contract: entries cached under an older resolver
  // must become unreachable, not merely stale. If this ever fails, a candidate
  // generation fix would be invisible on any machine with a warm cache.
  const key = companyCacheKey("Notion");
  assert.ok(!key.includes("_v0_"), "keys must not carry a stale version token");
  assert.equal(key.split("_")[1], COMPANY_KEY_VERSION);
});

// Parity + regression tests for the web's Unicode-safe normalizeTextKey mirror.
// Imports the core and the web copy side-by-side so they can never drift (#2369/#2666).
//
// Run:  node --test tests/lib/normalize-text-key.test.mjs

import { test } from "node:test";
import assert from "node:assert/strict";
import { pathToFileURL } from "node:url";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { normalizeTextKey as webKey } from "../../src/lib/core/normalize-text-key.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const { normalizeTextKey: coreKey } = await import(
  pathToFileURL(join(ROOT, "tracker-parse.mjs")).href
);

const CASES = [
  ["Nestlé", "nestlé"],
  ["Zürich Re", "zürich re"],
  ["Ação Digital", "ação digital"],
  ["Škoda", "škoda"],
  ["日本電産", "日本電産"],
  ["Acme, Inc.", "acme inc"],
  ["Koda", "koda"],
];

test("web mirror matches core for accented / CJK / punctuation cases", () => {
  for (const [input, expected] of CASES) {
    assert.equal(webKey(input, " "), expected, `web: ${input}`);
    assert.equal(coreKey(input, " "), expected, `core: ${input}`);
    assert.equal(webKey(input, " "), coreKey(input, " "), `parity: ${input}`);
  }
});

test("Škoda does not collide with Koda (the silent-suppression bug)", () => {
  assert.notEqual(webKey("Škoda", " "), webKey("Koda", " "));
  assert.equal(webKey("Škoda", " "), coreKey("Škoda", " "));
});

test("CJK company names stay non-empty (the forever-duplicate bug)", () => {
  assert.ok(webKey("日本電産", " "));
  assert.equal(webKey("日本電産", " "), "日本電産");
});

test("null/undefined key to empty string (not 'null'/'undefined')", () => {
  assert.equal(webKey(null, " "), "");
  assert.equal(webKey(undefined, " "), "");
  assert.equal(webKey(null, " "), coreKey(null, " "));
  assert.equal(webKey(undefined), coreKey(undefined));
});

test("default separator stays solid-key (opt-in space only)", () => {
  assert.equal(webKey("Acme, Inc."), "acmeinc");
  assert.equal(webKey("Acme, Inc."), coreKey("Acme, Inc."));
  assert.equal(webKey("Acme, Inc.", " "), "acme inc");
});

test("ASCII-only [^a-z0-9] shape must not return (regression lock)", () => {
  // The pre-#2666 web norm produced these broken keys. If anyone reintroduces
  // that regex, these assertions fail loudly.
  assert.notEqual(webKey("Nestlé", " "), "nestl");
  assert.notEqual(webKey("Zürich Re", " "), "z rich re");
  assert.notEqual(webKey("Ação Digital", " "), "a o digital");
  assert.notEqual(webKey("Škoda", " "), "koda");
  assert.notEqual(webKey("日本電産", " "), "");
});

