    // goes straight to renderAndMarkPdf, so there is no sidecar to keep in sync.
    assert.equal(result.ok, true);
    assert.equal(readFileSync(paths.html, "utf8"), html);
    assert.deepEqual(readdirSync(dir), ["cv-web-018.html"]);
  } finally {
