// ── pdfRunOutcome (#2185) ──
//
// The honesty gate. It decides both whether anything is written and whether the
// run is reported as success, so it must never call a run good on thin evidence.

const OK_ENVELOPE = { ok: true, html: "<html></html>", format: "a4", warnings: [] };
const GOOD = { envelope: OK_ENVELOPE, noOutputMessage: null, sawError: false, cleanExit: true, hasPaths: true };

test("pdfRunOutcome: a clean run with a parsed envelope is the only success", () => {
  // Given every signal healthy
  // Then the run proceeds to write and render
  assert.deepEqual(pdfRunOutcome(GOOD), { ok: true });
});

test("pdfRunOutcome: each degraded signal on its own blocks the render", () => {
  // Given one thing wrong at a time — no single failure may be shrugged off
  const degraded = {
    "unparsed envelope": { envelope: { ok: false, error: "never closed" } },
    "missing envelope": { envelope: undefined },
    "dirty exit": { cleanExit: false },
    "stderr error": { sawError: true },
    "no scratch paths": { hasPaths: false },
  };
  for (const [label, override] of Object.entries(degraded)) {
    // When deciding the outcome
    const outcome = pdfRunOutcome({ ...GOOD, ...override });

    // Then it fails with a message, never silently
    assert.equal(outcome.ok, false, `${label} must block the render`);
    assert.ok(outcome.message.length > 0, `${label} must explain itself`);
  }
});

test("pdfRunOutcome: the parser's reason is surfaced, not swallowed", () => {
  // Given the envelope failed for a specific, actionable reason
  const outcome = pdfRunOutcome({ ...GOOD, envelope: { ok: false, error: "the envelope was never closed" } });

  // Then that reason reaches the user — "never closed" and "no envelope at all"
  // are different bugs and the difference is what tells them what to do
  assert.equal(outcome.ok, false);
  assert.match(outcome.message, /never closed/);
});

test("pdfRunOutcome: the route's no-output verdict wins over the generic message", () => {
  // Given the caller already decided the CLI produced nothing usable. That is a
  // transport question, so the route owns the wording and passes it in — this
  // module must not carry a second copy of those strings.
  const outcome = pdfRunOutcome({
    ...GOOD,
    envelope: undefined,
    noOutputMessage: "The CLI produced no output — is it installed and authenticated?",
  });

  // Then that message is surfaced verbatim, not replaced by "didn't produce a CV",
  // because "nothing ran" and "ran but fell short" need different advice
  assert.equal(outcome.ok, false);
  assert.match(outcome.message, /installed and authenticated/);
});

test("pdfRunOutcome: a no-output verdict outranks an otherwise healthy envelope", () => {
  // Given contradictory signals — a parsed envelope but the route saw no output
  const outcome = pdfRunOutcome({ ...GOOD, noOutputMessage: "nothing came back" });

  // Then it fails closed rather than rendering on the strength of the envelope
  assert.equal(outcome.ok, false);
  assert.equal(outcome.message, "nothing came back");
});

test("writeCvHtml: a shorter re-render leaves no trailing bytes", () => {
  // Given the same report rendered twice, the second CV shorter than the first.
  // route.ts clears no stale scratch file because this function is documented to
  // rewrite the HTML before any render — a claim that rests entirely on
  // writeFileSync truncating. Switch to an append flag, or to a write-then-rename
  // helper, and every other test here stays green while the renderer reads the tail
  // of a previous run's CV.
  const dir = makeScratchDir();
  const paths = { html: join(dir, "cv-web-018.html"), finalPdf: join(dir, "out.pdf") };
  const long = `<!DOCTYPE html><html><body>${"X".repeat(4000)}</body></html>`;
  const short = "<!DOCTYPE html><html><body>short</body></html>";
  try {
    // When the long document is written and then the short one to the same path
    assert.equal(writeCvHtml({ pdfPaths: paths, html: long }).ok, true);
    assert.equal(writeCvHtml({ pdfPaths: paths, html: short }).ok, true);

    // Then the file is exactly the short document, with nothing left over
    const onDisk = readFileSync(paths.html, "utf8");
    assert.equal(onDisk, short);
    assert.ok(!onDisk.includes("XXXX"), "trailing bytes from the earlier write survived");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

// Guards the date computed by the child-process snippet in
// src/lib/core/pipeline.ts (`addOffersToPipeline`) — the "Add to pipeline"
// writer that stamps data/scan-history.tsv's first_seen column (#3070).
//
// `new Date().toISOString().slice(0, 10)` is the UTC day. West of Greenwich,
// an evening "Add to pipeline" click stamped first_seen one day ahead of the
// user's own clock, so scan.mjs's shouldDedupScanHistoryRow recheck/cooldown
// window opened a day late for that row. #3071 fixed the same pattern in six
// core .mjs call sites (including scan.mjs's own DEFAULT for this argument),
// but pipeline.ts always passes an explicit `date` argument, which overrides
// that default — so this call site needed its own fix and its own guard.
//
// pipeline.ts is TypeScript, imports via the `@/` path alias (which plain
// `node --test` cannot resolve without the Next.js build), and computes the
// date inside a template-literal string executed in a SEPARATE spawned
// process — so, same as tests/lib/core-writer-await.test.mjs, it cannot be
// imported and exercised here. This reads the source and asserts the shape.
// The fix itself was verified by execution in a frozen-clock scratch child
// (see the PR description) before this guard was written.
//
// Run (from web/, as `npm test` does):  node --test tests/lib/pipeline-local-today.test.mjs
// From the repo root:                   node --test web/tests/lib/pipeline-local-today.test.mjs

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const SRC = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "src", "lib", "core", "pipeline.ts");
const src = readFileSync(SRC, "utf8");

// The generated child-process code lives inside the backtick template
// assigned to `code`. Isolating it keeps the assertions below from also
// matching an unrelated `new Date()` elsewhere in the (TypeScript) file.
function extractChildProcessCode() {
  const m = src.match(/const code = `([\s\S]*?)`;/);
  assert.ok(m, `${SRC}: could not find the \`const code = \`...\`;\` template — the writer snippet was restructured. Update this extractor.`);
  return m[1];
}

test("the child-process snippet still exists at the shape this test extracts", () => {
  assert.ok(extractChildProcessCode().length > 0);
});

test("the legacy UTC-day pattern is gone from the child-process snippet", () => {
  const code = extractChildProcessCode();
  assert.doesNotMatch(
    code,
    /new Date\(\)\.toISOString\(\)\.slice\(0,\s*10\)/,
    `${SRC}: the child-process snippet resolves "today" with the UTC day again. ` +
      `West of Greenwich this stamps scan-history.tsv's first_seen a day ahead of the ` +
      `user's own clock (#3070) — use localToday() from lib/local-today.mjs instead.`,
  );
});

test("the date handed to appendToScanHistory comes from localToday()", () => {
  const code = extractChildProcessCode();
  assert.match(
    code,
    /const\s+date\s*=\s*localToday\(\)\s*;/,
    `${SRC}: expected \`const date = localToday();\` in the child-process snippet.`,
  );
  // The assertion above only proves `date` is ASSIGNED from localToday() — not
  // that the call site actually passes it on. A rename at the call (e.g. back
  // to an inline `new Date()...`, or a stray second variable) would leave the
  // `date` assignment unused and this bug's actual symptom would resurface.
  assert.match(
    code,
    /appendToScanHistory\(\s*offers\s*,\s*date\s*,\s*["']added["']\s*\)/,
    `${SRC}: expected appendToScanHistory(offers, date, "added") — the local-day ` +
      `value must reach the writer, not just get computed and discarded.`,
  );
});

test("localToday is imported into the spawned child from lib/local-today.mjs", () => {
  const code = extractChildProcessCode();
  assert.match(
    code,
    /import\s*{\s*localToday\s*}\s*from\s+\$\{JSON\.stringify\(localTodayUrl\)\}\s*;/,
    `${SRC}: the child process resolves imports independently of the TypeScript module's own ` +
      `cwd, so localToday must be imported via an interpolated absolute file:// URL — the same ` +
      `pattern already used for scanUrl — not a bare relative specifier that would only resolve ` +
      `by coincidence of the spawn's cwd.`,
  );
});

test("localTodayUrl is built the same way scanUrl is: an absolute file:// URL under careerOpsRoot()", () => {
  assert.match(
    src,
    /const localTodayUrl = pathToFileURL\(path\.join\(careerOpsRoot\(\),\s*["']lib["'],\s*["']local-today\.mjs["']\)\)\.href;/,
    `${SRC}: localTodayUrl must resolve lib/local-today.mjs under careerOpsRoot(), so the import ` +
      `works regardless of the checkout the web dashboard is pointed at.`,
  );
});

// The Explorer writes an ephemeral portals.yml and points the scanner at it. If
// the serializer omits a location tier the type carries, that filter is silently
// dropped — the user set it, the scan ignores it. block_hard (#2956/#3102) is the
// tier this test exists to protect: it is the ONE tier always_allow cannot
// override, so dropping it doesn't loosen results, it lets through jobs the user
// hard-rejected.
//
// Run:  node --test tests/lib/portals-serialize.test.mjs

import { test } from "node:test";
import assert from "node:assert/strict";
import * as yaml from "js-yaml";
import { serializePortals } from "../../src/lib/core/portals-serialize.mjs";

const empty = { positive: [], negative: [], allow: [], block: [], alwaysAllow: [], blockHard: [] };

test("block_hard is written under location_filter", () => {
  const doc = yaml.load(serializePortals({ ...empty, blockHard: ["usa", "brazil"] }));
  assert.deepEqual(doc.location_filter.block_hard, ["usa", "brazil"]);
});

test("a hard-block-ONLY config still emits location_filter (the #3102 drop)", () => {
  // The bug the guard fixes: the location_filter header used to be gated on
  // allow/block/always_allow only, so a config that hard-blocks and nothing else
  // wrote no location_filter at all and the scan honored none of it.
  const doc = yaml.load(serializePortals({ ...empty, blockHard: ["usa"] }));
  assert.ok(doc.location_filter, "location_filter must be present for a block_hard-only config");
  assert.deepEqual(doc.location_filter.block_hard, ["usa"]);
});

test("all location tiers round-trip through YAML", () => {
  const f = { ...empty, allow: ["remote"], block: ["india"], alwaysAllow: ["london"], blockHard: ["usa"] };
  const lf = yaml.load(serializePortals(f)).location_filter;
  assert.deepEqual(lf.block_hard, ["usa"]);
  assert.deepEqual(lf.always_allow, ["london"]);
  assert.deepEqual(lf.allow, ["remote"]);
  assert.deepEqual(lf.block, ["india"]);
});

test("no location tiers → no location_filter section", () => {
  const doc = yaml.load(serializePortals({ ...empty, positive: ["engineer"] }));
  assert.equal(doc.location_filter, undefined);
  assert.deepEqual(doc.title_filter.positive, ["engineer"]);
});

test("a keyword that could break YAML is quoted, not injected", () => {
  // A hard-block keyword is user input; a bare `- key: value` or a leading dash
  // would corrupt the document or smuggle structure. JSON.stringify makes each a
  // double-quoted scalar.
  const doc = yaml.load(serializePortals({ ...empty, blockHard: ["a: b", "- x", '"q"'] }));
  assert.deepEqual(doc.location_filter.block_hard, ["a: b", "- x", '"q"']);
});

// Tests for profileTargetKeywords() — reading `target_roles` out of a parsed
// config/profile.yml.
//
// The bug this module was extracted for was not a crash: the inline version
// read both fields with the wrong shape and returned [], so the Explorer's
// profile.yml fallback looked implemented and had never once produced a
// keyword. So the tests that matter here are the SHAPE tests, driven by the
// two shapes that actually exist on disk — the shipped example, and what the
// app's own writer emits.
//
// Run:  node --test tests/lib/profile-keywords.test.mjs

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import * as yaml from "js-yaml";
import { profileTargetKeywords } from "../../src/lib/profile-keywords.mjs";

// ── the shapes that exist on disk ────────────────────────────────────────────

test("the shipped config/profile.example.yml yields its roles", () => {
  // Not a synthetic fixture: if the template's shape changes, this fails here
  // rather than silently emptying the fallback again.
  const doc = yaml.load(readFileSync(new URL("../../../config/profile.example.yml", import.meta.url), "utf8"));
  const kws = profileTargetKeywords(doc);
  assert.ok(kws.length >= 2, `expected the template's roles, got ${JSON.stringify(kws)}`);
  for (const k of kws) assert.equal(typeof k, "string");
  // primary[] must be represented — the field the inline version read as a string.
  for (const p of doc.target_roles.primary) assert.ok(kws.includes(p), `missing primary role: ${p}`);
  // …and archetypes must contribute their NAME, not the object.
  for (const a of doc.target_roles.archetypes) assert.ok(kws.includes(a.name), `missing archetype: ${a.name}`);
});

test("primary is a LIST, not a string — the regression", () => {
  // api/profile/route.ts writes `{ primary: roles.slice(0, 6) }`. The inline
  // version tested `typeof roles.primary === "string"`, so the app could not
  // read back the profile it had just written.
  const kws = profileTargetKeywords({ target_roles: { primary: ["ML Engineer", "Inference Engineer"] } });
  assert.deepEqual(kws, ["ML Engineer", "Inference Engineer"]);
});

test("archetypes contribute .name, not the whole object", () => {
  const kws = profileTargetKeywords({
    target_roles: { archetypes: [{ name: "Edge AI Engineer", level: "Senior", fit: "primary" }] },
  });
  assert.deepEqual(kws, ["Edge AI Engineer"]);
});

test("primary and archetypes combine, primary first", () => {
  const kws = profileTargetKeywords({
    target_roles: { primary: ["A"], archetypes: [{ name: "B" }] },
  });
  assert.deepEqual(kws, ["A", "B"]);
});

// ── never throws: this is a tolerant seeding path, not a validator ───────────

test("malformed or missing input yields [] rather than throwing", () => {
  for (const bad of [
    null,
    undefined,
    {},
    "a string",
    42,
    { target_roles: null },
    { target_roles: "roles" },
    { target_roles: [] }, // an array IS an object — must not blow up on .primary
    { target_roles: { primary: "Senior AI Engineer" } }, // scalar, not the documented list
    { target_roles: { primary: null, archetypes: null } },
  ]) {
    assert.deepEqual(profileTargetKeywords(bad), [], `not [] for ${JSON.stringify(bad)}`);
  }
});

test("non-string entries are dropped, not passed through", () => {
  // An archetype with no name, or a primary list someone hand-edited into
  // objects, must not put `undefined`/`{}` into a keyword list that gets
  // serialized into YAML and handed to the scanner.
  const kws = profileTargetKeywords({
    target_roles: {
      primary: ["Good", null, 42, { name: "nope" }],
      archetypes: [{ name: "Also Good" }, { level: "Senior" }, null, "bare string"],
    },
  });
  assert.deepEqual(kws, ["Good", "Also Good"]);
});

// ── parity with the core helper lives in the ROOT suite ──────────────────────
//
// tests/profile-keywords-parity.test.mjs asserts this module against
// providers/_profile-keywords.mjs — the drift it was extracted to stop.
//
// It cannot live here. web-ci.yml runs `npm ci` inside web/ only, so importing
// a core module — which resolves js-yaml from the repo ROOT's node_modules —
// fails with ERR_MODULE_NOT_FOUND. Suites under web/tests/ must be runnable on
// web/'s dependencies alone; the root suite is where a cross-boundary invariant
// belongs, and is the required check besides. Same direction of reach, and the
// same reasoning, as tests/web-test-layout.test.mjs.
//
// Reading a root FILE stays fine and is used above: readFileSync needs no
// package resolution.

// Tests for the shared `{n}-RESERVED.md` predicate. Imports report-files.mjs
// directly — it is THE definition for web/, consumed by both career-ops.ts
// (report lookup) and run-cli-support.mjs (the persistence gate), so a change
// here moves both consumers at once. That is the point: the two used to carry
// separate copies that already disagreed.
//
// Run:  node --test tests/lib/report-files.test.mjs

import { test } from "node:test";
import assert from "node:assert/strict";
import { isReservedReportFile } from "../../src/lib/report-files.mjs";

test("a numbered sentinel is reserved", () => {
  // Given: what reserve-report-num.mjs actually writes to claim a number.
  assert.equal(isReservedReportFile("041-RESERVED.md"), true);
  assert.equal(isReservedReportFile("7-RESERVED.md"), true);
});

test("a real report is never reserved", () => {
  assert.equal(isReservedReportFile("027-cd-invest-2026-08-11.md"), false);
});

test("only a NUMBERED sentinel counts — the case the two old copies disagreed on", () => {
  // Given: nothing produces this today, but the predicates differed on it, which
  // is exactly the drift one definition exists to prevent.
  assert.equal(isReservedReportFile("notes-RESERVED.md"), false);
  assert.equal(isReservedReportFile("RESERVED.md"), false);
});

test("the match is anchored, so a lookalike name is not reserved", () => {
  assert.equal(isReservedReportFile("041-RESERVED.md.bak"), false);
  assert.equal(isReservedReportFile("041-RESERVED-notes.md"), false);
  assert.equal(isReservedReportFile("x041-RESERVED.md"), false);
});

test("only the basename is examined, so a full path works", () => {
  // Given: career-ops.ts passes a resolved path, run-cli-support.mjs a bare name.
  assert.equal(isReservedReportFile("/root/reports/041-RESERVED.md"), true);
  assert.equal(isReservedReportFile("/root/reports/027-acme-2026-08-11.md"), false);
});

// Tests for the report section splitter using Node's built-in test runner.
// Imports directly from report-sections.mjs (the single source of truth) so the
// test and production code can never drift out of sync.
//
// Run:  node --test tests/lib/report-sections.test.mjs

import { test } from "node:test";
import assert from "node:assert/strict";
import { cleanHeading, authorLetter, splitSections } from "../../src/lib/report-sections.mjs";

test("strips the author letter from the blocks the core has always written", () => {
  assert.equal(cleanHeading("A) Role Summary"), "Role Summary");
  assert.equal(cleanHeading("G) Posting Legitimacy"), "Posting Legitimacy");
});

test("H) is stripped too — the #2324 regression", () => {
  // oferta.md and auto-pipeline.md write "## H) Draft Application Answers";
  // the old [A-G] range left this one heading showing its letter.
  assert.equal(cleanHeading("H) Draft Application Answers"), "Draft Application Answers");
  assert.equal(authorLetter("H) Draft Application Answers"), "H");
});

test("a block added past H needs no code change", () => {
  assert.equal(cleanHeading("I) Something New"), "Something New");
  assert.equal(authorLetter("Z. Last One"), "Z");
});

test("the (lead) / (verdict) marker is dropped with the letter", () => {
  assert.equal(cleanHeading("F) Verdict (lead)"), "Verdict");
  assert.equal(cleanHeading("F) Verdict (verdict)"), "Verdict");
});

test("all three delimiters and the spelled-out Block form", () => {
  assert.equal(cleanHeading("B) Match with CV"), "Match with CV");
  assert.equal(cleanHeading("B. Match with CV"), "Match with CV");
  assert.equal(cleanHeading("B: Match with CV"), "Match with CV");
  assert.equal(cleanHeading("Block H: Draft Application Answers"), "Draft Application Answers");
  assert.equal(authorLetter("Block C) Red Flags"), "C");
});

test("prose is not eaten: both reads need a real delimiter", () => {
  // The delimiter, not the narrowness of the letter range, is the safety —
  // which is why widening the range costs nothing. A bare letter followed by a
  // space is prose: reading it as a section would make ReportView expand it as
  // if it were Block A.
  assert.equal(cleanHeading("A Recommendation Was Requested"), "A Recommendation Was Requested");
  assert.equal(authorLetter("A Recommendation Was Requested"), null);
  assert.equal(cleanHeading("Machine Summary"), "Machine Summary");
  assert.equal(authorLetter("Machine Summary"), null);
  assert.equal(authorLetter("Risk Summary"), null);
});

test("the spelled-out Block form is stripped for display too", () => {
  // authorLetter reads "Block A — Role Summary" as section A, so cleanHeading
  // must not leave "Block A —" in the rendered heading: classifying a heading
  // one way and displaying it another is the same inconsistency #2324 is about.
  assert.equal(cleanHeading("Block A — Role Summary"), "Role Summary");
  assert.equal(cleanHeading("Block A – Role Summary"), "Role Summary");
  assert.equal(cleanHeading("Block A - Role Summary"), "Role Summary");
  assert.equal(cleanHeading("Block A Role Summary"), "Role Summary");
  assert.equal(cleanHeading("Block C) Red Flags"), "Red Flags");
  // The word Block is what licenses the whitespace form. A bare letter still
  // needs a delimiter, or prose loses its first word.
  assert.equal(cleanHeading("A Recommendation Was Requested"), "A Recommendation Was Requested");
});

test("the spelled-out Block form keeps its letter without a delimiter", () => {
  // oferta.md:47 writes "## Block A — Role Summary": nothing follows the letter
  // but a space. Losing the letter here would drop the F verdict callout and
  // the A/B expansion on those reports.
  assert.equal(authorLetter("Block A — Role Summary"), "A");
  assert.equal(authorLetter("Block F -- Interview Plan"), "F");
  assert.equal(authorLetter("Block G Posting Legitimacy"), "G");
});

test("a heading that is only a letter keeps its original text", () => {
  assert.equal(cleanHeading("H)"), "H)");
});

test("case is normalized on the way out", () => {
  assert.equal(authorLetter("h) draft application answers"), "H");
});

test("splitSections keeps the intro and letters every section", () => {
  const body = [
    "**Score:** 4.2/5",
    "",
    "## F) Verdict (lead)",
    "Apply.",
    "",
    "## A) Role Summary",
    "Senior role.",
    "",
    "## H) Draft Application Answers",
    "Q1: ...",
  ].join("\n");

  const { intro, sections } = splitSections(body);
  assert.equal(intro, "**Score:** 4.2/5");
  assert.deepEqual(
    sections.map((s) => [s.letter, cleanHeading(s.heading)]),
    [
      ["F", "Verdict"],
      ["A", "Role Summary"],
      ["H", "Draft Application Answers"],
    ],
  );
  assert.equal(sections[2].content, "Q1: ...");
});

test("a body with no headings is all intro", () => {
  const { intro, sections } = splitSections("just prose\nand more");
  assert.equal(intro, "just prose\nand more");
  assert.deepEqual(sections, []);
});

test("the ASCII double-hyphen Block form is stripped whole", () => {
  // modes/ja/kyujin.md and modes/hi/naukri.md write "## Block A -- Role Summary"
  // for every block. The separator matched a SINGLE dash character, so each of
  // those headings rendered with a stray leading hyphen ("- Role Summary") —
  // every block of every report produced by the Japanese or Hindi mode.
  assert.equal(cleanHeading("Block A -- Role Summary"), "Role Summary");
  assert.equal(cleanHeading("Block F -- Interview Plan"), "Interview Plan");
  assert.equal(cleanHeading("Block G -- Posting Legitimacy"), "Posting Legitimacy");
  assert.equal(authorLetter("Block F -- Interview Plan"), "F");
  // A heading whose text legitimately starts with a hyphen keeps it: only the
  // separator run is consumed, and it must be attached to the letter.
  assert.equal(cleanHeading("Block A) -- keep this"), "-- keep this");
});

// Tests for the per-CLI stream parsers and run bookkeeping helpers, using
// Node's built-in test runner. Imports directly from run-cli-support.mjs (the
// single source of truth) so the test and production code can never drift.
//
// Each case reads Given (the raw CLI line / listing) → When (parse it) → Then
// (the dashboard event it must become).
//
// Run:  node --test tests/lib/run-cli-support.test.mjs

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  accumulateTokens,
  codexStreamArgs,
  completedReportNames,
  hasNewCompletedReport,
  isFatalClaudeStderr,
  isFatalCodexStderr,
  isFatalGenericStderr,
  parseClaudeEvent,
  parseCodexEvent,
} from "../../src/lib/run-cli-support.mjs";
import { createCvEnvelopeFilter } from "../../src/lib/cv-envelope.mjs";

test("Codex agent message becomes dashboard text, newline-terminated", () => {
  // Given: Codex sends complete messages with NO trailing newline ("hello", not
  // "hello\n"), so without termination consecutive messages glue mid-line —
  // which runs narration together in the log and breaks the line-anchored
  // <<cv-html>> markers in pdf mode.
  const event = parseCodexEvent(JSON.stringify({
    type: "item.completed",
    item: { type: "agent_message", text: "VERDICT: 4.2/5 — strong fit" },
  }));
  assert.deepEqual(event, { text: "VERDICT: 4.2/5 — strong fit\n" });
});

test("an already newline-terminated Codex message gains no second newline", () => {
  const event = parseCodexEvent(JSON.stringify({
    type: "item.completed",
    item: { type: "agent_message", text: "done\n" },
  }));
  assert.deepEqual(event, { text: "done\n" });
});

test("a cv envelope in its own Codex message survives preceding narration", () => {
  // Given: the real pdf-mode failure — narration in one agent_message (no
  // trailing newline), the envelope in the next. Unterminated, the opener lands
  // mid-line and the fail-closed parser reports "no envelope" for a run whose
  // CV was fully emitted.
  const narration = parseCodexEvent(JSON.stringify({
    type: "item.completed",
    item: { type: "agent_message", text: "Tailoring done, emitting the envelope." },
  }));
  const envelope = parseCodexEvent(JSON.stringify({
    type: "item.completed",
    item: { type: "agent_message", text: '<<cv-html format="a4">>\n<!DOCTYPE html><html><body>CV</body></html>\n<</cv-html>>' },
  }));

  // When: both flow through the same filter the route feeds via sendAgentText.
  const filter = createCvEnvelopeFilter();
  filter.push(narration.text);
  filter.push(envelope.text);
  filter.flush();

  // Then: the envelope parses — the run's CV is recovered, not refused.
  const result = filter.result();
  assert.equal(result.ok, true);
  assert.equal(result.format, "a4");
  assert.match(result.html, /<\/html>/);
});

test("Codex turn.started maps to a kind-agnostic working status", () => {
  // Given: the parser serves every run kind (evaluate, pdf, research), so the
  // status must not claim one of them — "Evaluating the role" showed on CV PDF runs.
  const event = parseCodexEvent(JSON.stringify({ type: "turn.started" }));
  assert.deepEqual(event, { status: "Agent working" });
});

test("Codex usage subtracts cached input, the opposite of Claude's formula", () => {
  // Given: OpenAI's convention puts cached_input_tokens INSIDE input_tokens, so
  // input + output folds discounted cache reads back into a metric defined as
  // tokens billed at FULL rate — inflating Codex ~4.7x against Claude in the
  // very comparison people use to control cost (formula adapted from #2689).
  const event = parseCodexEvent(JSON.stringify({
    type: "turn.completed",
    usage: { input_tokens: 120, cached_input_tokens: 80, output_tokens: 30 },
  }));
  // Then: (120 − 80) + 30, and no invented cost — Codex reports none.
  assert.deepEqual(event, { tokens: 70, costUsd: null });
});

test("a real captured Codex turn reports full-rate tokens, not the raw input", () => {
  // Given: an actual codex-cli 0.146.0 turn (input 13956 / cached 11008 / output 44).
  const event = parseCodexEvent(JSON.stringify({
    type: "turn.completed",
    usage: { input_tokens: 13956, cached_input_tokens: 11008, output_tokens: 44 },
  }));
  assert.equal(event.tokens, 2992); // not 14000
});

test("fractional and non-finite usage figures are ignored, not counted", () => {
  // Given: a token count is a whole number, so anything else in a usage block is
  // junk from a malformed event and must not reach the running total.
  const event = parseCodexEvent(JSON.stringify({
    type: "turn.completed",
    usage: { input_tokens: 1.5, cached_input_tokens: 0, output_tokens: 10 },
  }));
  assert.deepEqual(event, { tokens: 10, costUsd: null });

  const claude = parseClaudeEvent(JSON.stringify({
    type: "result",
    usage: { input_tokens: 2.7, output_tokens: 10, cache_creation_input_tokens: 5 },
  }));
  assert.deepEqual(claude, { tokens: 15 });

  // And a non-finite figure, which needs RAW JSONL to construct: JSON.stringify
  // turns Infinity into null, so a fixture built the usual way silently tests
  // something else. `1e400` is how an overflow actually arrives on the wire.
  assert.deepEqual(
    parseCodexEvent('{"type":"turn.completed","usage":{"input_tokens":1e400,"output_tokens":10}}'),
    { tokens: 10, costUsd: null },
  );
  assert.deepEqual(
    parseClaudeEvent('{"type":"result","usage":{"input_tokens":1e400,"output_tokens":10}}'),
    { tokens: 10 },
  );
});

test("malformed Codex usage never reports negative tokens", () => {
  // Given: cached exceeding input can only come from a malformed block — the
  // clamp keeps a nonsense figure from becoming a negative one.
  const event = parseCodexEvent(JSON.stringify({
    type: "turn.completed",
    usage: { input_tokens: 10, cached_input_tokens: 999, output_tokens: 5 },
  }));
  assert.deepEqual(event, { tokens: 5, costUsd: null });
});

test("Codex turn.completed without usage is ignored, not zeroed", () => {
  const event = parseCodexEvent(JSON.stringify({ type: "turn.completed" }));
  assert.equal(event, null);
});

test("invalid and irrelevant Codex lines are ignored", () => {
  assert.equal(parseCodexEvent("not json"), null);
  assert.equal(parseCodexEvent('{"type":"item.completed","item":{"type":"command_execution"}}'), null);
});

test("a line that parses to a non-object is ignored, not thrown on", () => {
  // Given: JSON.parse("null") SUCCEEDS and yields null, so the try/catch around
  // the parse never fires and reading .type off it would throw out of the
  // parser and into the route's stdout handler. Same for bare scalars.
  for (const line of ["null", "42", '"a string"', "true", "[]"]) {
    assert.equal(parseCodexEvent(line), null, `codex: ${line}`);
    assert.equal(parseClaudeEvent(line), null, `claude: ${line}`);
  }
});

test("a null nested payload is survived, not thrown on", () => {
  // Given: the root guard above only covers a non-object ROOT. A well-formed
  // event can still carry a null where an object belongs, and reading through it
  // would throw past the parser into the route's stdout handler just the same.
  // The optional chaining that prevents this has no other coverage, so a
  // regression removing one `?.` would go unnoticed.
  assert.equal(parseCodexEvent('{"type":"item.started","item":null}'), null);
  assert.equal(parseCodexEvent('{"type":"item.completed","item":null}'), null);
  assert.equal(parseCodexEvent('{"type":"turn.completed","usage":null}'), null);
  assert.equal(parseClaudeEvent('{"type":"stream_event","event":null}'), null);
  assert.equal(parseClaudeEvent('{"type":"result","usage":null}'), null);

  // A null `error` still yields the default diagnostic rather than throwing —
  // the event announced a failure, so it must not be silently dropped.
  assert.deepEqual(parseCodexEvent('{"type":"error","error":null}'), { error: "Codex failed before finishing" });
});

test("an empty Codex agent message emits nothing", () => {
  // Given: emitting it would put a blank line in the run log and an extra
  // newline inside pdf mode's line-anchored envelope stream.
  const event = parseCodexEvent(JSON.stringify({
    type: "item.completed",
    item: { type: "agent_message", text: "" },
  }));
  assert.equal(event, null);
});

test("a syntactically-valid but unrecognized Codex event type is ignored", () => {
  assert.equal(parseCodexEvent(JSON.stringify({ type: "session.diff" })), null);
});

test("Codex item.started maps command_execution to the Bash tool", () => {
  const event = parseCodexEvent(JSON.stringify({ type: "item.started", item: { type: "command_execution" } }));
  assert.deepEqual(event, { tool: "Bash" });
});

test("Codex item.started maps web_search to the WebSearch tool", () => {
  const event = parseCodexEvent(JSON.stringify({ type: "item.started", item: { type: "web_search" } }));
  assert.deepEqual(event, { tool: "WebSearch" });
});

test("Codex item.started maps a named mcp_tool_call to its tool name", () => {
  const event = parseCodexEvent(JSON.stringify({ type: "item.started", item: { type: "mcp_tool_call", tool: "reserve-report-num" } }));
  assert.deepEqual(event, { tool: "reserve-report-num" });
});

test("Codex item.started falls back to Working for an unnamed mcp_tool_call", () => {
  const event = parseCodexEvent(JSON.stringify({ type: "item.started", item: { type: "mcp_tool_call" } }));
  assert.deepEqual(event, { tool: "Working" });
});

test("Codex turn.failed extracts the error.message", () => {
  const event = parseCodexEvent(JSON.stringify({ type: "turn.failed", error: { message: "model unavailable" } }));
  assert.deepEqual(event, { error: "model unavailable" });
});

test("Codex error event falls back to a top-level message", () => {
  const event = parseCodexEvent(JSON.stringify({ type: "error", message: "connection reset" }));
  assert.deepEqual(event, { error: "connection reset" });
});

test("Codex error event with no message uses the default fallback", () => {
  const event = parseCodexEvent(JSON.stringify({ type: "error" }));
  assert.deepEqual(event, { error: "Codex failed before finishing" });
});

test("a transient Codex reconnect notice is progress, not a run failure", () => {
  // Given: Codex emits `error`-type events for conditions it recovers from, then
  // completes the turn — treating one as fatal fails a run that actually worked.
  const event = parseCodexEvent(JSON.stringify({ type: "error", message: "Reconnecting... (attempt 1)" }));
  // Then: reported as a status, so the caller never sets sawError.
  assert.deepEqual(event, { status: "Reconnecting…" });
});

test("a terminal turn.failed stays an error even when it mentions reconnecting", () => {
  // Given: turn.failed is terminal by definition — the reconnect wording must not
  // launder a genuine failure into a status.
  const event = parseCodexEvent(JSON.stringify({ type: "turn.failed", error: { message: "gave up reconnecting" } }));
  assert.deepEqual(event, { error: "gave up reconnecting" });
});

test("benign Codex stderr diagnostics are not fatal", () => {
  assert.equal(isFatalCodexStderr("ERROR codex_models_manager::cache: failed to load models cache: schema mismatch"), false);
});

test("Codex auth-failure stderr phrases are fatal", () => {
  assert.equal(isFatalCodexStderr("Error: unauthorized"), true);
  assert.equal(isFatalCodexStderr("please log in to continue"), true);
  assert.equal(isFatalCodexStderr("credential file missing"), true);
  assert.equal(isFatalCodexStderr("403 forbidden"), true);
  assert.equal(isFatalCodexStderr("not authenticated"), true);
  assert.equal(isFatalCodexStderr("sign in required"), true);
});

test("Codex quota/rate-limit stderr is fatal", () => {
  assert.equal(isFatalCodexStderr("Error: quota exceeded"), true);
  assert.equal(isFatalCodexStderr("429 rate limit hit"), true);
});

test("a self-retrying rate-limit stderr line is transient, not fatal", () => {
  // Given: the CLI announces it is handling the 429 itself — the run can still
  // complete cleanly, and flagging it fatal re-creates the false-red the
  // narrow classifier exists to remove (#2085).
  assert.equal(isFatalCodexStderr("429 rate limit hit, retrying in 2s..."), false);
  assert.equal(isFatalClaudeStderr("rate limited, will retry"), false);
});

test("an auth failure stays fatal even when it mentions retrying", () => {
  // Given: auth never heals by retrying, so the transient carve-out must not
  // apply to it.
  assert.equal(isFatalCodexStderr("unauthorized — please log in and retry"), true);
  assert.equal(isFatalClaudeStderr("Invalid API key · Please run /login and retry"), true);
});

test("terminal retry wording does not trigger the transient carve-out", () => {
  // Given: only a retry the CLI announces as IN PROGRESS is transient — wording
  // that says retrying is over or pointless is a real failure.
  assert.equal(isFatalCodexStderr("quota exceeded — do not retry"), true);
  assert.equal(isFatalCodexStderr("rate limit: retry limit exhausted"), true);
});

test("a benign Claude stderr line mentioning an error is not fatal", () => {
  // Given: the generic fallback regex matches a bare "error", which fails a run
  // over any diagnostic that merely says the word — the same false positive the
  // Codex classifier exists to avoid.
  assert.equal(isFatalClaudeStderr("(node:5) Warning: error handler already attached"), false);
});

test("Claude auth and quota stderr phrases are fatal", () => {
  assert.equal(isFatalClaudeStderr("Invalid API key · Please run /login"), true);
  assert.equal(isFatalClaudeStderr("Credit balance is too low"), true);
  assert.equal(isFatalClaudeStderr("Usage limit reached — resets at 4pm"), true);
  // The auth/quota vocabulary shared with every other CLI still applies.
