// The tracker lock exists to stop a LOST UPDATE, so the test has to produce one.
//
// `atomicWrite` makes the write atomic, not the read-modify-write around it: two
// writers read the same snapshot, each edits its own row, each renames its full
// copy back, and the second discards the first's change. Every call succeeds and
// the file is well-formed throughout — the only symptom is a row that silently
// reverts (#2900).
//
// This asserts the failure FIRST (unlocked writers lose data) and then that the
// lock removes it. Without the negative half, a lock that never engaged would
// pass just as happily.
//
// Run:  node --test tests/lib/tracker-lock.test.mjs

import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

// Resolved from this file, not from the cwd: test-all.mjs runs these suites from
// the repo root, where `cwd/..` points outside the checkout and every core case
// skipped as "not resolvable" while reporting green.
const CORE =
  process.env.CAREER_OPS_ROOT ||
  path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const coreLock = path.join(CORE, "tracker-utils.mjs");

// The guard has to answer "can this be imported", not "is the file there".
// tracker-utils.mjs imports js-yaml, so a web-only install (web-ci.yml runs
// `npm ci` in web/ alone) has the file and not its dependencies, and existsSync
// called that runnable: the cases failed on ERR_MODULE_NOT_FOUND instead of
// skipping (#2922).
let core = null;
let skipCore = false;
try {
  core = await import(pathToFileURL(coreLock).href);
} catch (err) {
  // Skipping is only correct where the core genuinely is not installed: no core
  // file here at all, or an unresolvable package in a checkout whose root deps
  // were never installed, which is what a web-only install looks like.
  //
  // Node names the missing path in err.url when a FILE is unresolvable and
  // leaves it unset when a bare package is, which separates "js-yaml was never
  // installed" from "tracker-parse.mjs is missing from this core". The second is
  // a broken checkout, and skipping it would report a real break as an
  // uninstalled dependency, which is the failure this guard exists to stop.
  // Anything unrecognized rethrows for the same reason: a loud failure here is
  // recoverable, a silent skip is not.
  const coreAbsent = !fs.existsSync(coreLock);
  const packageUnresolvable = err.url == null;
  const depsAbsent = !fs.existsSync(path.join(CORE, "node_modules"));

  if (err.code !== "ERR_MODULE_NOT_FOUND") throw err;
  if (coreAbsent) skipCore = `no core checkout at ${CORE}`;
  else if (packageUnresolvable && depsAbsent) skipCore = `core dependencies are not installed at ${CORE} (web-only checkout)`;
  else throw err;
}

function makeTracker() {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "trklock-"));
  const file = path.join(root, "applications.md");
  fs.writeFileSync(file, [
    "| # | Date | Company | Role | Score | Status | PDF | Report | Notes |",
    "|---|---|---|---|---|---|---|---|---|",
    "| 1 | 2026-01-01 | Acme | Eng | 4/5 | Evaluated | ❌ | — | a |",
    "| 2 | 2026-01-01 | Beta | SRE | 3/5 | Evaluated | ❌ | — | b |",
  ].join("\n") + "\n");
  return { root, file };
}

/** The route's read-modify-write, verbatim in shape: read all, edit one, write all. */
function setStatus(file, rowNum, status, pauseMs) {
  const lines = fs.readFileSync(file, "utf8").split("\n");
  return new Promise((resolve) => setTimeout(() => {
    for (let i = 0; i < lines.length; i++) {
      const parts = lines[i].split("|");
      if (parts.length < 8 || parts[1].trim() !== String(rowNum)) continue;
      parts[6] = ` ${status} `;
      lines[i] = parts.join("|");
    }
    const tmp = `${file}.tmp`;
    fs.writeFileSync(tmp, lines.join("\n"));
    fs.renameSync(tmp, file);
    resolve();
  }, pauseMs));
}

const statusOf = (file, n) =>
  fs.readFileSync(file, "utf8").split("\n").find((l) => l.split("|")[1]?.trim() === String(n))?.split("|")[6]?.trim();

test("WITHOUT a lock, two concurrent writers lose one update silently", async () => {
  const { root, file } = makeTracker();
  try {
    await Promise.all([setStatus(file, 1, "Applied", 60), setStatus(file, 2, "Interview", 10)]);
    // The bug: no error, file well-formed, one row back to its old value.
    assert.equal(statusOf(file, 1), "Applied");
    assert.equal(statusOf(file, 2), "Evaluated", "expected the classic lost update to reproduce");
    assert.equal(fs.readFileSync(file, "utf8").split("\n").filter(Boolean).length, 4, "file stayed well-formed");
  } finally {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

test("WITH the core lock, both updates survive", { skip: skipCore }, async () => {
  const { acquireTrackerLock, trackerLockDirFor } = core;
  const { root, file } = makeTracker();
  const guarded = async (rowNum, status, pauseMs) => {
    const lock = await acquireTrackerLock(trackerLockDirFor(file), { timeoutMs: 5_000, retryMs: 25, tracker: file });
    try {
      await setStatus(file, rowNum, status, pauseMs);
    } finally {
      await lock.release();
    }
  };
  try {
    await Promise.all([guarded(1, "Applied", 60), guarded(2, "Interview", 10)]);
    assert.equal(statusOf(file, 1), "Applied");
    assert.equal(statusOf(file, 2), "Interview", "the second update was lost even under the lock");
  } finally {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

test("the lock is released on a throwing path, not just the happy one", { skip: skipCore }, async () => {
  // A leaked lock on a long-lived server is worse than the bug: the holder's pid
  // stays alive, so the core's stale-recovery will not reclaim it.
  const { acquireTrackerLock, trackerLockDirFor } = core;
  const { root, file } = makeTracker();
  try {
    const lock = await acquireTrackerLock(trackerLockDirFor(file), { timeoutMs: 5_000, retryMs: 25, tracker: file });
    try {
      throw new Error("boom");
    } catch {
      /* the route's catch */
    } finally {
      await lock.release();
    }
    // If the lock had leaked, this second acquire would time out.
    const again = await acquireTrackerLock(trackerLockDirFor(file), { timeoutMs: 2_000, retryMs: 25, tracker: file });
    await again.release();
  } finally {
    fs.rmSync(root, { recursive: true, force: true });
  }
});

// Parity + regression tests for the web's normalizeUrl (posting-key) mirror.
// Imports the core and the web copy side-by-side so they can never drift, same
// pattern as normalize-text-key.test.mjs (#2369/#2666).
//
// Run:  node --test tests/lib/url-key.test.mjs

import { test } from "node:test";
import assert from "node:assert/strict";
import { pathToFileURL } from "node:url";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { normalizeUrl as webKey } from "../../src/lib/core/url-key.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
const { normalizeUrl: coreKey } = await import(pathToFileURL(join(ROOT, "url-key.mjs")).href);

test("web mirror matches core on ordinary postings (https upgrade, hostname lowercase, trailing slash)", () => {
  const CASES = [
    "http://Boards.Greenhouse.io/acme/jobs/apply",
    "https://boards.greenhouse.io/acme/jobs/apply/",
    "https://jobs.example.com/role#applyNow",
  ];
  for (const input of CASES) {
    assert.equal(webKey(input), coreKey(input), `parity: ${input}`);
  }
});

test("web mirror strips the same tracking-param denylist as core, in the same sorted order", () => {
  const url = "https://boards.greenhouse.io/acme/jobs/apply?utm_source=li&gh_jid=4471829005&fbclid=xyz";
  assert.equal(
    webKey(url),
    "https://boards.greenhouse.io/acme/jobs/apply?gh_jid=4471829005",
  );
  assert.equal(webKey(url), coreKey(url));
});

test("two RETAINED (non-tracking) params in opposite input order sort to the same key, on both sides", () => {
  // A single retained param (the test above) never exercises keep.sort() —
  // there is nothing to order. This pins order-independence with two.
  const orderA = "https://boards.greenhouse.io/acme/jobs/apply?location=paris&gh_jid=4471829005&utm_source=li";
  const orderB = "https://boards.greenhouse.io/acme/jobs/apply?utm_source=li&gh_jid=4471829005&location=paris";
  const expected = "https://boards.greenhouse.io/acme/jobs/apply?gh_jid=4471829005&location=paris";
  assert.equal(webKey(orderA), expected);
  assert.equal(webKey(orderB), expected, "opposite input order must sort to the identical key");
  assert.equal(webKey(orderA), coreKey(orderA));
  assert.equal(webKey(orderB), coreKey(orderB));
});

test("the reported bug: two DIFFERENT Greenhouse postings (same host+path, distinct gh_jid) key DIFFERENTLY", () => {
  const jobA = "https://boards.greenhouse.io/acme/jobs/apply?gh_jid=4471829005";
  const jobB = "https://boards.greenhouse.io/acme/jobs/apply?gh_jid=5501203417";
  assert.notEqual(webKey(jobA), webKey(jobB), "two distinct openings collapsed to one dedup key");
  assert.equal(webKey(jobA), coreKey(jobA));
  assert.equal(webKey(jobB), coreKey(jobB));
});

test("host+pathname-only shape must not return (regression lock on the pre-fix canon())", () => {
  // The pre-fix canon() discarded the ENTIRE query string, so both of these
  // collapsed to "boards.greenhouse.io/acme/jobs/apply". If that shape comes
  // back, this fails loudly.
  const jobA = "https://boards.greenhouse.io/acme/jobs/apply?gh_jid=4471829005";
  const jobB = "https://boards.greenhouse.io/acme/jobs/apply?gh_jid=5501203417";
  assert.notEqual(webKey(jobA), "boards.greenhouse.io/acme/jobs/apply");
  assert.notEqual(webKey(jobB), "boards.greenhouse.io/acme/jobs/apply");
});

test("unparseable / non-http(s) input keys to '' on both sides (NO KEY IS NOT A KEY)", () => {
  for (const bad of ["not a url", "ftp://example.com/x", "", "   "]) {
    assert.equal(webKey(bad), "", `web: ${JSON.stringify(bad)}`);
    assert.equal(coreKey(bad), "", `core: ${JSON.stringify(bad)}`);
  }
  assert.equal(webKey(null), "");
  assert.equal(webKey(undefined), "");
});

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  DEFAULT_OFFER_LIMIT,
  MAX_OFFER_LIMIT,
  collectWhatsNew,
  resolveOfferLimit,
} from "../../src/lib/whats-new.mjs";

const header = "url\tfirst_seen\tportal\ttitle\tcompany\tstatus\tlocation";
const toOffer = ([url, , , title, company]) => (url ? { url, title, company } : null);

test("count is not capped by the card payload limit", () => {
  const rows = [
    header,
    ...Array.from({ length: 30 }, (_, i) =>
      `https://example.com/${i}\t2026-08-10\ttest\tRole ${i}\tCompany ${i}\tadded\tRemote`,
    ),
  ];
  const result = collectWhatsNew(rows, {
    cutoff: Date.parse("2026-08-03"),
    toOffer,
    offerLimit: 24,
  });

  assert.equal(result.offers.length, 24);
  assert.equal(result.count, 30);
});

test("duplicate URLs count once even when walking the full history", () => {
  const rows = [
    header,
    "https://example.com/1\t2026-08-09\ttest\tOld title\tAcme\tadded\tRemote",
    "https://example.com/1\t2026-08-10\ttest\tNew title\tAcme\tadded\tRemote",
  ];
  const result = collectWhatsNew(rows, {
    cutoff: Date.parse("2026-08-03"),
    toOffer,
  });

  assert.equal(result.offers.length, 1);
  assert.equal(result.count, 1);
  assert.equal(result.offers[0].title, "New title");
});

test("legacy append-order fallback also reports the complete count", () => {
  const rows = [
    header,
    ...Array.from({ length: 15 }, (_, i) =>
      `https://example.com/legacy-${i}\t\ttest\tRole ${i}\tCompany ${i}\tadded\tRemote`,
    ),
  ];
  const result = collectWhatsNew(rows, {
    cutoff: Date.parse("2026-08-03"),
    toOffer,
    fallbackLimit: 12,
  });

  assert.equal(result.offers.length, 12);
  assert.equal(result.count, 15);
});

test("a missing or blank limit falls back to the card default", () => {
  assert.equal(resolveOfferLimit(null), DEFAULT_OFFER_LIMIT);
  assert.equal(resolveOfferLimit(undefined), DEFAULT_OFFER_LIMIT);
  assert.equal(resolveOfferLimit(""), DEFAULT_OFFER_LIMIT);
  assert.equal(resolveOfferLimit("   "), DEFAULT_OFFER_LIMIT);
});

test("the render ceiling is always finite, whatever the caller asks for", () => {
  // explorer-view has no virtualisation, so an unbounded list is an unbounded
  // DOM. The legacy `all` sentinel must degrade to a bounded default, never to
  // Infinity.
  assert.equal(resolveOfferLimit("all"), DEFAULT_OFFER_LIMIT);
  assert.equal(resolveOfferLimit("Infinity"), DEFAULT_OFFER_LIMIT);
  assert.equal(resolveOfferLimit("-Infinity"), DEFAULT_OFFER_LIMIT);
  assert.equal(resolveOfferLimit("NaN"), DEFAULT_OFFER_LIMIT);
  assert.equal(resolveOfferLimit("100000"), MAX_OFFER_LIMIT);
  assert.equal(resolveOfferLimit("1e9"), MAX_OFFER_LIMIT);
  assert.equal(resolveOfferLimit(String(MAX_OFFER_LIMIT)), MAX_OFFER_LIMIT);
});

test("a partially numeric limit falls back instead of under-fetching", () => {
  // parseInt would read a numeric *prefix* — "24junk" as 24, "1e9" as 1 — so a
  // malformed limit would quietly become a real one (and "1e9" would return a
  // single offer, the opposite of what it asks for).
  assert.equal(resolveOfferLimit("24junk"), DEFAULT_OFFER_LIMIT);
  assert.equal(resolveOfferLimit("200px"), DEFAULT_OFFER_LIMIT);
  assert.equal(resolveOfferLimit("12 34"), DEFAULT_OFFER_LIMIT);
  assert.equal(resolveOfferLimit("24.7"), DEFAULT_OFFER_LIMIT);
});

test("surrounding whitespace is tolerated, not treated as malformed", () => {
  assert.equal(resolveOfferLimit(" 50 "), 50);
  assert.equal(resolveOfferLimit("\t200\n"), MAX_OFFER_LIMIT);
});

test("in-range limits pass through and degenerate ones clamp up to 1", () => {
  assert.equal(resolveOfferLimit("1"), 1);
  assert.equal(resolveOfferLimit("50"), 50);
  assert.equal(resolveOfferLimit("0"), 1);
  assert.equal(resolveOfferLimit("-10"), 1);
});

test("the Explore limit still returns the complete count", () => {
  const rows = [
    header,
    ...Array.from({ length: MAX_OFFER_LIMIT + 40 }, (_, i) =>
      `https://example.com/${i}\t2026-08-10\ttest\tRole ${i}\tCompany ${i}\tadded\tRemote`,
    ),
  ];
  const result = collectWhatsNew(rows, {
    cutoff: Date.parse("2026-08-03"),
    toOffer,
    offerLimit: resolveOfferLimit(String(MAX_OFFER_LIMIT)),
  });

  assert.equal(result.offers.length, MAX_OFFER_LIMIT);
  assert.equal(result.count, MAX_OFFER_LIMIT + 40);
});

